fn content_workspace_files(image_kind: FixedImageKind) -> &'static [&'static str] {
    match image_kind {
        FixedImageKind::Standalone => &CONTENT_WORKSPACE_FILES,
        FixedImageKind::Detcore => &CONTENT_DETCORE_WORKSPACE_FILES,
    }
}
