// Native Detcore's fixed-gate publication ordering is a separately declared
// source premise. The ordinary Standalone cohort and Location roles stay frozen.
const CONTENT_DETCORE_FIXED_GATE: (&str, u64, &str) = (
    "reverie-inguest/src/trap/fixed_gates.rs",
    28338,
    "5d062d8cedd22d5e1d29674a358fcee6eccba24a46540cc2ada193c052f4e4b3",
);
fn content_catalog_matches(relative: &str, size: u64, digest: &str) -> Result<()> {
    require(
        CONTENT_REVERIE_CATALOG
            .iter()
            .any(|&(path, expected_size, expected_digest)| {
                relative == path && size == expected_size && digest == expected_digest
            }),
        format!("declared Reverie source differs from reviewed catalog: {relative}"),
    )
}
fn declared_inventory(
    root: &Path,
    relatives: &[&str],
) -> Result<(Vec<DeclaredSourceFile>, BTreeMap<String, FileIdentity>)> {
    let mut inventory = BTreeMap::new();
    let mut files = BTreeMap::new();
    for &relative in relatives {
        let file = exact_source_file(root, relative)?;
        let size = fs::metadata(&file.path).map_err(|e| e.to_string())?.len();
        file.verify()?;
        require(
            inventory
                .insert(
                    relative,
                    DeclaredSourceFile {
                        relative: relative.into(),
                        size,
                        sha256: file.sha256.clone(),
                    },
                )
                .is_none(),
            "duplicate declared source filename",
        )?;
        files.insert(relative.into(), file);
    }
    Ok((inventory.into_values().collect(), files))
}
fn declared_inventory_sha256(inventory: &[DeclaredSourceFile]) -> Result<String> {
    // Serde emits these fixed fields and ordered relative entries. No absolute
    // pathname is part of this location-independent content identity.
    Ok(sha256(
        &serde_json::to_vec(inventory).map_err(|e| e.to_string())?,
    ))
}
fn content_reverie_inventory_for_image(
    root: &Path,
    image_kind: FixedImageKind,
) -> Result<(Vec<DeclaredSourceFile>, BTreeMap<String, FileIdentity>)> {
    let mut relatives: Vec<_> = CONTENT_REVERIE_CATALOG
        .iter()
        .map(|entry| entry.0)
        .collect();
    if image_kind == FixedImageKind::Detcore {
        relatives.push(CONTENT_DETCORE_FIXED_GATE.0);
    }
    relatives.push("scripts/m1_artifact.rs");
    let (inventory, files) = declared_inventory(root, &relatives)?;
    for entry in &inventory {
        if entry.relative == "scripts/m1_artifact.rs" {
            require(
                entry.sha256 == qualifier_source_sha256(),
                "declared qualifier source differs from compiled host qualifier",
            )?;
        } else if entry.relative == CONTENT_DETCORE_FIXED_GATE.0 {
            require(
                image_kind == FixedImageKind::Detcore
                    && entry.size == CONTENT_DETCORE_FIXED_GATE.1
                    && entry.sha256 == CONTENT_DETCORE_FIXED_GATE.2,
                "declared Detcore fixed-gate source differs from reviewed catalog",
            )?;
        } else {
            content_catalog_matches(&entry.relative, entry.size, &entry.sha256)?;
        }
    }
    Ok((inventory, files))
}
#[cfg(test)]
fn content_reverie_inventory(
    root: &Path,
) -> Result<(Vec<DeclaredSourceFile>, BTreeMap<String, FileIdentity>)> {
    content_reverie_inventory_for_image(root, FixedImageKind::Standalone)
}
fn clean_absolute_source_root(root: &Path) -> Result<()> {
    let normalized: PathBuf = root.components().collect();
    require(
        root.is_absolute() && normalized.as_os_str() == root.as_os_str(),
        "compiled source root has a lexical alias",
    )
}
impl CompilerRootBinding {
    fn resolve(logical_root: &Path, pin: &str) -> Result<Self> {
        clean_absolute_source_root(logical_root)?;
        let canonical_root = fs::canonicalize(logical_root).map_err(|e| e.to_string())?;
        if canonical_root.as_os_str() == logical_root.as_os_str() {
            return Ok(Self {
                logical_root: logical_root.into(),
                canonical_root,
                cargo_home: None,
            });
        }
        // The one observed alias is the CARGO_HOME root. No checkout/package/
        // source subdirectory may supply a second alias or change the suffix.
        let cargo_home = std::env::var_os("CARGO_HOME")
            .ok_or("compiler source alias is not an explicit Cargo home root")?;
        Self::resolve_cargo_home(logical_root, pin, Path::new(&cargo_home))
    }
    fn resolve_cargo_home(logical_root: &Path, pin: &str, cargo_home: &Path) -> Result<Self> {
        require(source_pin_is_full(pin), "compiler root requires a full pin")?;
        clean_absolute_source_root(logical_root)?;
        clean_absolute_source_root(cargo_home)?;
        let canonical_home = fs::canonicalize(cargo_home).map_err(|e| e.to_string())?;
        let suffix = format!("git/checkouts/reverie-2fc770f7a9c80803/{}", &pin[..7]);
        require(
            logical_root.as_os_str() == cargo_home.join(&suffix).as_os_str(),
            "compiler alias is not the observed Cargo checkout root",
        )?;
        let canonical_root = fs::canonicalize(logical_root).map_err(|e| e.to_string())?;
        require(
            canonical_root.as_os_str() == canonical_home.join(suffix).as_os_str(),
            "compiler Cargo root contains an internal alias",
        )?;
        Ok(Self {
            logical_root: logical_root.into(),
            canonical_root,
            cargo_home: Some((cargo_home.into(), canonical_home)),
        })
    }
    fn verify(&self) -> Result<()> {
        require(
            fs::canonicalize(&self.logical_root)
                .map_err(|e| e.to_string())?
                .as_os_str()
                == self.canonical_root.as_os_str(),
            "compiler root mapping changed during use",
        )?;
        if let Some((logical, canonical)) = &self.cargo_home {
            require(
                fs::canonicalize(logical)
                    .map_err(|e| e.to_string())?
                    .as_os_str()
                    == canonical.as_os_str(),
                "compiler Cargo home mapping changed during use",
            )?;
        }
        Ok(())
    }
    fn source_path(&self, relative: &str) -> Result<PathBuf> {
        self.verify()?;
        let file = exact_source_file(&self.canonical_root, relative)?;
        let logical = self.logical_root.join(relative);
        require(
            real_file(&logical)?.as_os_str() == file.path.as_os_str(),
            "compiler source mapping does not reach its exact declared file",
        )?;
        Ok(logical)
    }
}
fn verify_declared_content(
    image_kind: FixedImageKind,
    (workspace_root, workspace_inventory, workspace_sha256): (&Path, &[DeclaredSourceFile], &str),
    (reverie_root, reverie_inventory, reverie_sha256): (&Path, &[DeclaredSourceFile], &str),
    compiler_root: &CompilerRootBinding,
) -> Result<()> {
    compiler_root.verify()?;
    require(
        compiler_root.canonical_root.as_os_str() == reverie_root.as_os_str(),
        "declared compiler root differs from Reverie inventory root",
    )?;
    let (current_workspace, _) =
        declared_inventory(workspace_root, content_workspace_files(image_kind))?;
    let (current_reverie, _) = content_reverie_inventory_for_image(reverie_root, image_kind)?;
    require(
        current_workspace == workspace_inventory
            && declared_inventory_sha256(&current_workspace)? == workspace_sha256,
        "declared workspace content changed during use",
    )?;
    require(
        current_reverie == reverie_inventory
            && declared_inventory_sha256(&current_reverie)? == reverie_sha256,
        "declared Reverie content changed during use",
    )?;
    Ok(())
}
fn source_pin_is_full(pin: &str) -> bool {
    pin.len() == 40
        && pin
            .bytes()
            .all(|b| b.is_ascii_digit() || (b'a'..=b'f').contains(&b))
}
fn exact_source_file(root: &Path, relative: &str) -> Result<FileIdentity> {
    let path = root.join(relative);
    let file = FileIdentity::read(&path)?;
    require(
        file.path.as_os_str() == path.as_os_str(),
        "compiled source filename has a symlink or lexical alias",
    )?;
    Ok(file)
}
fn compiled_git_identity(root: &Path, runner: &mut Runner) -> Result<(String, String)> {
    let top = runner.text(
        "git",
        &["--no-replace-objects", "rev-parse", "--show-toplevel"],
        root,
    )?;
    require(
        Path::new(top.trim_end_matches('\n')).as_os_str() == root.as_os_str(),
        "compiled source Git root differs",
    )?;
    let status = runner.text(
        "git",
        &[
            "--no-replace-objects",
            "status",
            "--porcelain",
            "--untracked-files=no",
        ],
        root,
    )?;
    require(status.is_empty(), "compiled source has dirty tracked files")?;
    let head = runner
        .text("git", &["--no-replace-objects", "rev-parse", "HEAD"], root)?
        .trim()
        .to_owned();
    let tree = runner
        .text(
            "git",
            &["--no-replace-objects", "rev-parse", "HEAD^{tree}"],
            root,
        )?
        .trim()
        .to_owned();
    require(
        source_pin_is_full(&head) && source_pin_is_full(&tree),
        "compiled source Git identity is incomplete",
    )?;
    Ok((head, tree))
}
// Called only with bytes freshly returned by the independently pinned Git show.
// A test can refute this comparison without manufacturing VerifiedCompiledSources.
fn compiled_source_matches_blob(file: &FileIdentity, blob: &[u8]) -> Result<()> {
    require(
        file.sha256 == sha256(blob),
        "compiled source differs from the expected Git blob",
    )
}
fn compiled_blob_file(
    root: &Path,
    pin: &str,
    relative: &str,
    runner: &mut Runner,
) -> Result<FileIdentity> {
    let file = exact_source_file(root, relative)?;
    let object = format!("{pin}:{relative}");
    let bytes = runner.run(
        "git",
        &["--no-replace-objects".into(), "show".into(), object],
        root,
    )?;
    compiled_source_matches_blob(&file, &bytes)?;
    file.verify()?;
    Ok(file)
}
fn compiled_library_package(
    metadata: &Value,
    name: &str,
    target: &str,
    kind: &[&str],
    root: &Path,
    source: Option<&str>,
) -> Result<PackageIdentity> {
    let packages = metadata["packages"]
        .as_array()
        .ok_or("compiled metadata packages missing")?;
    let candidates: Vec<_> = packages.iter().filter(|p| p["name"] == name).collect();
    require(
        candidates.len() == 1,
        format!("compiled source needs one package {name}"),
    )?;
    let p = candidates[0];
    let manifest = exact_source_file(root, &format!("{name}/Cargo.toml"))?.path;
    require(
        p["manifest_path"].as_str() == manifest.to_str(),
        "compiled metadata manifest is not the exact source file",
    )?;
    require(
        p["source"].as_str() == source && (source.is_some() || p["source"].is_null()),
        "compiled metadata source differs from full pin",
    )?;
    require(
        p["version"] == "0.4.1",
        "compiled Reverie package version differs",
    )?;
    let id = match source {
        Some(source) => format!(
            "{}#{name}@0.4.1",
            source
                .rsplit_once('#')
                .ok_or("compiled Git source lacks revision")?
                .0
        ),
        None => format!("path+file://{}#0.4.1", root.join(name).display()),
    };
    require(
        p["id"] == id,
        "compiled package ID differs from exact source",
    )?;
    let targets: Vec<_> = p["targets"]
        .as_array()
        .ok_or("compiled package targets missing")?
        .iter()
        .filter(|t| t["name"] == target)
        .collect();
    require(targets.len() == 1, "compiled library target is ambiguous")?;
    let t = targets[0];
    let target_source = exact_source_file(root, &format!("{name}/src/lib.rs"))?.path;
    require(
        t["src_path"].as_str() == target_source.to_str()
            && strings(&t["kind"])? == kind
            && strings(&t["crate_types"])? == kind,
        "compiled library target/source/type differs",
    )?;
    Ok(PackageIdentity {
        id,
        name: name.into(),
        manifest,
        source: source.map(str::to_owned),
        target: target.into(),
        kind: kind.iter().map(|s| (*s).into()).collect(),
        crate_types: kind.iter().map(|s| (*s).into()).collect(),
        target_source,
    })
}
fn compiled_leaf_package(
    metadata: &Value,
    root: &Path,
    rv_root: &Path,
    source: Option<&str>,
    image_kind: FixedImageKind,
) -> Result<PackageIdentity> {
    let (name, target, leaf_manifest, leaf_source) = match image_kind {
        FixedImageKind::Standalone => (
            "reverie-liteinst-preload",
            "reverie_liteinst_preload",
            rv_root.join("reverie-liteinst-preload/Cargo.toml"),
            source,
        ),
        FixedImageKind::Detcore => (
            "detcore-liteinst",
            "detcore_liteinst",
            root.join("detcore-liteinst/Cargo.toml"),
            None,
        ),
    };
    let candidates: Vec<_> = metadata["packages"]
        .as_array()
        .ok_or("compiled leaf packages missing")?
        .iter()
        .filter(|p| p["name"] == name)
        .collect();
    require(candidates.len() == 1, "compiled leaf package is ambiguous")?;
    let raw = candidates[0];
    require(
        raw["manifest_path"].as_str() == leaf_manifest.to_str(),
        "compiled leaf manifest has an alias or wrong root",
    )?;
    let expected_target_source = leaf_manifest
        .parent()
        .ok_or("compiled leaf parent missing")?
        .join("src/lib.rs");
    let raw_targets: Vec<_> = raw["targets"]
        .as_array()
        .ok_or("compiled leaf targets missing")?
        .iter()
        .filter(|t| t["name"] == target)
        .collect();
    require(
        raw_targets.len() == 1
            && raw_targets[0]["src_path"].as_str() == expected_target_source.to_str(),
        "compiled leaf target has an alias or wrong root",
    )?;
    let leaf = select_package(metadata, name, target, &leaf_manifest, leaf_source)?;
    require(
        leaf.manifest.as_os_str() == leaf_manifest.as_os_str()
            && leaf.target_source
                == leaf_manifest
                    .parent()
                    .ok_or("compiled leaf parent missing")?
                    .join("src/lib.rs"),
        "compiled leaf target is outside its expected source",
    )?;
    let expected_id = match image_kind {
        FixedImageKind::Standalone => match source {
            Some(source) => format!(
                "{}#reverie-liteinst-preload@0.4.1",
                source.rsplit_once('#').unwrap().0
            ),
            None => format!("path+file://{}#0.4.1", rv_root.join(name).display()),
        },
        FixedImageKind::Detcore => format!("path+file://{}#0.4.0", root.join(name).display()),
    };
    require(
        leaf.id == expected_id,
        "compiled leaf ID differs from the independent package expectation",
    )?;
    Ok(leaf)
}
fn content_package(
    metadata: &Value,
    name: &str,
    target: &str,
    kind: &[&str],
    binding: &CompilerRootBinding,
    source: &str,
) -> Result<PackageIdentity> {
    let candidates: Vec<_> = metadata["packages"]
        .as_array()
        .ok_or("content metadata packages missing")?
        .iter()
        .filter(|p| p["name"] == name)
        .collect();
    require(
        candidates.len() == 1,
        format!("content source needs one package {name}"),
    )?;
    let raw = candidates[0];
    let manifest_relative = format!("{name}/Cargo.toml");
    let compiler_manifest = binding.source_path(&manifest_relative)?;
    require(
        raw["manifest_path"].as_str() == compiler_manifest.to_str(),
        "content metadata manifest differs from exact compiler spelling",
    )?;
    require(
        raw["source"].as_str() == Some(source) && raw["version"] == "0.4.1",
        "content metadata source/version differs from full pin",
    )?;
    let id = format!(
        "{}#{name}@0.4.1",
        source
            .rsplit_once('#')
            .ok_or("content Git source lacks revision")?
            .0
    );
    require(
        raw["id"] == id,
        "content package ID differs from independent full pin",
    )?;
    let targets: Vec<_> = raw["targets"]
        .as_array()
        .ok_or("content package targets missing")?
        .iter()
        .filter(|t| t["name"] == target)
        .collect();
    require(targets.len() == 1, "content library target is ambiguous")?;
    let t = targets[0];
    let (compiler_target, canonical_target) = if name == "reverie-liteinst-artifact" {
        // Cargo retains this exact declared host-only target spelling. This
        // single manifest declaration is not permission for source aliases.
        (
            binding
                .logical_root
                .join("reverie-liteinst-artifact/../scripts/m1_artifact.rs"),
            binding.source_path("scripts/m1_artifact.rs")?,
        )
    } else {
        let relative = format!("{name}/src/lib.rs");
        let path = binding.source_path(&relative)?;
        (path.clone(), path)
    };
    require(
        t["src_path"].as_str() == compiler_target.to_str()
            && strings(&t["kind"])? == kind
            && strings(&t["crate_types"])? == kind,
        "content library target/source/type differs",
    )?;
    let target_source = real_file(&compiler_target)?;
    require(
        target_source.as_os_str() == real_file(&canonical_target)?.as_os_str(),
        "content target does not reach exact declared file",
    )?;
    let manifest = exact_source_file(&binding.canonical_root, &manifest_relative)?.path;
    Ok(PackageIdentity {
        id,
        name: name.into(),
        manifest,
        source: Some(source.into()),
        target: target.into(),
        kind: kind.iter().map(|s| (*s).into()).collect(),
        crate_types: kind.iter().map(|s| (*s).into()).collect(),
        target_source,
    })
}
fn content_manifest_and_lock_pin(metadata: &Value, root: &Path, source: &str) -> Result<()> {
    let packages = metadata["packages"]
        .as_array()
        .ok_or("content metadata packages missing")?;
    for (name, relative, dependency, kind) in [
        (
            "hermit-liteinst-runtime-build",
            "liteinst-runtime-build/Cargo.toml",
            "reverie-liteinst-artifact",
            Some("build"),
        ),
        (
            "hermit-liteinst-runtime-artifact",
            "liteinst-runtime-build/runtime/Cargo.toml",
            "reverie-liteinst-preload",
            None,
        ),
    ] {
        let selected: Vec<_> = packages.iter().filter(|p| p["name"] == name).collect();
        require(
            selected.len() == 1
                && selected[0]["manifest_path"].as_str() == root.join(relative).to_str(),
            "content build package does not match declared manifest",
        )?;
        let dependencies: Vec<_> = selected[0]["dependencies"]
            .as_array()
            .ok_or("content build dependencies missing")?
            .iter()
            .filter(|d| d["name"] == dependency)
            .collect();
        require(
            dependencies.len() == 1
                && dependencies[0]["source"].as_str() == source.rsplit_once('#').map(|s| s.0)
                && dependencies[0]["kind"].as_str() == kind
                && (kind.is_some() || dependencies[0]["kind"].is_null())
                && dependencies[0]["rename"].is_null()
                && dependencies[0]["path"].is_null(),
            "content manifest dependency differs from independent full pin",
        )?;
    }
    let lock = fs::read_to_string(root.join("liteinst-runtime-build/Cargo.lock"))
        .map_err(|e| e.to_string())?;
    for name in [
        "reverie-inguest",
        "reverie-liteinst",
        "reverie-liteinst-preload",
        "reverie-liteinst-artifact",
    ] {
        let name_line = format!("name = \"{name}\"");
        let entries: Vec<_> = lock
            .split("[[package]]")
            .filter(|entry| entry.lines().any(|line| line == name_line))
            .collect();
        let source_line = format!("source = \"{source}\"");
        require(
            entries.len() == 1
                && entries[0]
                    .lines()
                    .filter(|line| line.starts_with("source = "))
                    .collect::<Vec<_>>()
                    == [source_line.as_str()],
            "content lock source differs from independent full pin",
        )?;
    }
    Ok(())
}
// Runtime and producer are separate locked Cargo graphs. Neither may stand
// in for the other, and they must identify the same actual compiler checkout.
fn content_root_binding(metadata: &Value, pin: &str) -> Result<CompilerRootBinding> {
    let selected: Vec<_> = metadata["packages"]
        .as_array()
        .ok_or("content metadata packages missing")?
        .iter()
        .filter(|p| p["name"] == "reverie-inguest")
        .collect();
    require(
        selected.len() == 1,
        "one compiled reverie-inguest source required",
    )?;
    let raw_manifest = selected[0]["manifest_path"]
        .as_str()
        .ok_or("content dependency manifest missing")?;
    let logical_root = raw_manifest
        .strip_suffix("/reverie-inguest/Cargo.toml")
        .ok_or("content dependency manifest has wrong suffix")?;
    CompilerRootBinding::resolve(Path::new(logical_root), pin)
}
fn content_same_root(runtime: &CompilerRootBinding, producer: &CompilerRootBinding) -> Result<()> {
    runtime.verify()?;
    producer.verify()?;
    require(
        runtime == producer,
        "runtime and producer compiler roots differ",
    )
}
fn content_detcore_manifest_and_lock_pin(
    metadata: &Value,
    root: &Path,
    source: &str,
) -> Result<()> {
    require(
        metadata["workspace_root"].as_str() == root.to_str(),
        "content Detcore workspace root differs",
    )?;
    let selected: Vec<_> = metadata["packages"]
        .as_array()
        .ok_or("content Detcore metadata packages missing")?
        .iter()
        .filter(|p| p["name"] == "detcore-liteinst")
        .collect();
    require(
        selected.len() == 1
            && selected[0]["manifest_path"].as_str()
                == root.join("detcore-liteinst/Cargo.toml").to_str()
            && selected[0]["version"] == "0.4.0"
            && selected[0]["source"].is_null(),
        "content Detcore leaf manifest/version/source differs",
    )?;
    for (name, rename, optional) in [
        ("reverie-core", Some("reverie"), false),
        ("reverie-inguest", None, false),
        ("reverie-liteinst", None, false),
        ("reverie-rpc-transport", None, true),
    ] {
        let dependencies: Vec<_> = selected[0]["dependencies"]
            .as_array()
            .ok_or("content Detcore dependencies missing")?
            .iter()
            .filter(|d| d["name"] == name)
            .collect();
        require(
            dependencies.len() == 1
                && dependencies[0]["source"].as_str() == source.rsplit_once('#').map(|s| s.0)
                && dependencies[0]["kind"].is_null()
                && dependencies[0]["rename"].as_str() == rename
                && (rename.is_some() || dependencies[0]["rename"].is_null())
                && dependencies[0]["path"].is_null()
                && dependencies[0]["target"].is_null()
                && dependencies[0]["optional"].as_bool() == Some(optional),
            format!("content Detcore dependency differs from independent full pin: {name}"),
        )?;
    }
    let lock = fs::read_to_string(root.join("Cargo.lock")).map_err(|e| e.to_string())?;
    for name in [
        "reverie-core",
        "reverie-inguest",
        "reverie-liteinst",
        "reverie-rpc-transport",
    ] {
        let name_line = format!("name = \"{name}\"");
        let entries: Vec<_> = lock
            .split("[[package]]")
            .filter(|entry| entry.lines().any(|line| line == name_line))
            .collect();
        let source_line = format!("source = \"{source}\"");
        require(
            entries.len() == 1
                && entries[0]
                    .lines()
                    .filter(|line| line.starts_with("source = "))
                    .collect::<Vec<_>>()
                    == [source_line.as_str()]
                && entries[0]
                    .lines()
                    .filter(|line| line.starts_with("version = "))
                    .collect::<Vec<_>>()
                    == ["version = \"0.4.1\""],
            format!("content Detcore lock source/version differs: {name}"),
        )?;
    }
    let local: Vec<_> = lock
        .split("[[package]]")
        .filter(|entry| {
            entry
                .lines()
                .any(|line| line == "name = \"detcore-liteinst\"")
        })
        .collect();
    require(
        local.len() == 1
            && !local[0].lines().any(|line| line.starts_with("source = "))
            && local[0]
                .lines()
                .filter(|line| line.starts_with("version = "))
                .collect::<Vec<_>>()
                == ["version = \"0.4.0\""],
        "content Detcore local lock entry differs",
    )
}
fn content_compiler_manifest_path(
    image_kind: FixedImageKind,
    workspace_root: &Path,
    leaf_manifest: &Path,
    compiler_root: &CompilerRootBinding,
) -> Result<PathBuf> {
    let logical = match image_kind {
        FixedImageKind::Standalone => {
            compiler_root.source_path("reverie-liteinst-preload/Cargo.toml")?
        }
        FixedImageKind::Detcore => {
            exact_source_file(workspace_root, "detcore-liteinst/Cargo.toml")?.path
        }
    };
    require(
        real_file(&logical)?.as_os_str() == leaf_manifest.as_os_str(),
        "compiler manifest does not match verified canonical package",
    )?;
    Ok(logical)
}
// Only filename() supplies this helper's identity from its private verified record.
fn compiled_role_filename(
    layout: CompiledSourceLayout,
    relative: &str,
    file: &FileIdentity,
) -> Result<Vec<u8>> {
    require(
        COMPILED_RV_LOCATION_FILES.contains(&relative),
        "compiled source filename role is unsupported",
    )?;
    file.verify()?;
    Ok(match layout {
        CompiledSourceLayout::ReverieWorkspace => relative.as_bytes().to_vec(),
        CompiledSourceLayout::HermitGit => file
            .path
            .to_str()
            .ok_or("compiled source filename is not UTF-8")?
            .as_bytes()
            .to_vec(),
    })
}
impl VerifiedCompiledSources {
    pub fn resolve(expected: &CompiledSourceExpectation<'_>, runner: &mut Runner) -> Result<Self> {
        require(
            source_pin_is_full(expected.reverie_pin),
            "compiled source requires an independent full Reverie pin",
        )?;
        for name in ["RUSTFLAGS", "CARGO_ENCODED_RUSTFLAGS"] {
            if let Some(flags) = std::env::var_os(name) {
                let flags = flags.to_str().ok_or("compiler flags are not UTF-8")?;
                require(
                    !flags.contains("--remap-path-prefix"),
                    "caller compiler filename remapping is unsupported",
                )?;
            }
        }
        let root = fs::canonicalize(expected.workspace_root).map_err(|e| e.to_string())?;
        require(
            root.as_os_str() == expected.workspace_root.as_os_str(),
            "compiled source workspace is not canonical",
        )?;
        require(
            expected.layout != CompiledSourceLayout::ReverieWorkspace
                || expected.image_kind == FixedImageKind::Standalone,
            "Detcore cannot claim Reverie workspace source layout",
        )?;
        let manifest_relative = match (expected.layout, expected.image_kind) {
            (CompiledSourceLayout::HermitGit, FixedImageKind::Standalone) => {
                "liteinst-runtime-build/Cargo.toml"
            }
            _ => "Cargo.toml",
        };
        let manifest = exact_source_file(&root, manifest_relative)?;
        require(
            manifest.path.as_os_str() == expected.manifest.as_os_str(),
            "compiled source manifest differs from the explicit build root",
        )?;
        let (workspace_head, workspace_tree) = compiled_git_identity(&root, runner)?;
        if expected.layout == CompiledSourceLayout::ReverieWorkspace {
            require(
                workspace_head == expected.reverie_pin,
                "workspace source differs from expected Reverie pin",
            )?;
        } else {
            // The full pin is caller-owned, and must also be the actual recorded
            // submodule object of this independently clean Hermit source tree.
            let gitlink = runner.text(
                "git",
                &["--no-replace-objects", "ls-tree", "HEAD", "--", "reverie"],
                &root,
            )?;
            require(
                gitlink == format!("160000 commit {}\treverie\n", expected.reverie_pin),
                "Hermit Git link differs from the expected Reverie pin",
            )?;
        }
        let output = runner.run(
            "cargo",
            &[
                "metadata".into(),
                "--locked".into(),
                "--offline".into(),
                "--format-version=1".into(),
                "--manifest-path".into(),
                manifest
                    .path
                    .to_str()
                    .ok_or("compiled manifest is not UTF-8")?
                    .into(),
            ],
            &root,
        )?;
        let metadata: Value = serde_json::from_slice(&output)
            .map_err(|e| format!("fresh compiled source metadata: {e}"))?;
        let source = format!(
            "git+https://github.com/rrnewton/reverie.git?rev={0}#{0}",
            expected.reverie_pin
        );
        let source = (expected.layout == CompiledSourceLayout::HermitGit).then_some(source);
        let rv_root = if source.is_some() {
            let packages = metadata["packages"]
                .as_array()
                .ok_or("compiled metadata packages missing")?;
            let candidates: Vec<_> = packages
                .iter()
                .filter(|p| p["name"] == "reverie-inguest")
                .collect();
            require(
                candidates.len() == 1,
                "one compiled reverie-inguest source required",
            )?;
            require(
                candidates[0]["source"].as_str() == source.as_deref(),
                "compiled dependency differs from expected full Git source",
            )?;
            let raw = Path::new(
                candidates[0]["manifest_path"]
                    .as_str()
                    .ok_or("compiled dependency manifest missing")?,
            );
            let real = real_file(raw)?;
            require(
                real.as_os_str() == raw.as_os_str()
                    && real.file_name().is_some_and(|p| p == "Cargo.toml")
                    && real
                        .parent()
                        .and_then(Path::file_name)
                        .is_some_and(|p| p == "reverie-inguest"),
                "compiled dependency manifest has an alias or wrong suffix",
            )?;
            real.parent()
                .and_then(Path::parent)
                .ok_or("compiled dependency checkout root missing")?
                .to_owned()
        } else {
            root.clone()
        };
        let (rv_head, rv_tree) = compiled_git_identity(&rv_root, runner)?;
        require(
            rv_head == expected.reverie_pin,
            "compiled checkout HEAD differs from independent full pin",
        )?;
        let mut packages = BTreeMap::new();
        for (name, target, kind) in [
            (
                "reverie-inguest",
                "reverie_inguest",
                &["cdylib", "rlib"][..],
            ),
            ("reverie-liteinst", "reverie_liteinst", &["rlib"][..]),
        ] {
            packages.insert(
                name.into(),
                compiled_library_package(
                    &metadata,
                    name,
                    target,
                    kind,
                    &rv_root,
                    source.as_deref(),
                )?,
            );
        }
        let leaf = compiled_leaf_package(
            &metadata,
            &root,
            &rv_root,
            source.as_deref(),
            expected.image_kind,
        )?;
        let name = leaf.name.clone();
        packages.insert(name, leaf.clone());
        let mut files = BTreeMap::new();
        let mut relatives: BTreeSet<String> = COMPILED_RV_LOCATION_FILES
            .into_iter()
            .map(str::to_owned)
            .collect();
        if expected.image_kind == FixedImageKind::Detcore {
            relatives.insert(CONTENT_DETCORE_FIXED_GATE.0.to_owned());
        }
        for package in packages
            .values()
            .filter(|p| p.manifest.starts_with(&rv_root))
        {
            for path in [&package.manifest, &package.target_source] {
                relatives.insert(
                    path.strip_prefix(&rv_root)
                        .map_err(|e| e.to_string())?
                        .to_str()
                        .ok_or("compiled relative source is not UTF-8")?
                        .to_owned(),
                );
            }
        }
        for relative in relatives {
            files.insert(
                format!("rv:{relative}"),
                compiled_blob_file(&rv_root, expected.reverie_pin, &relative, runner)?,
            );
        }
        if expected.image_kind == FixedImageKind::Detcore {
            for relative in ["detcore-liteinst/Cargo.toml", "detcore-liteinst/src/lib.rs"] {
                files.insert(
                    format!("workspace:{relative}"),
                    compiled_blob_file(&root, &workspace_head, relative, runner)?,
                );
            }
        }
        let observed_manifest =
            compiled_blob_file(&root, &workspace_head, manifest_relative, runner)?;
        require(
            observed_manifest == manifest,
            "compiled build manifest changed during metadata",
        )?;
        let record = CompiledSources {
            layout: expected.layout,
            image_kind: expected.image_kind,
            workspace_root: root,
            authority: CompiledSourceAuthority::Git {
                workspace_head,
                workspace_tree,
                reverie_tree: rv_tree,
            },
            manifest,
            reverie_pin: expected.reverie_pin.into(),
            reverie_root: rv_root,
            packages,
            files,
            leaf,
        };
        let verified = Self { record };
        verified.verify_unchanged(runner)?;
        Ok(verified)
    }
    /// Explicit closed-profile Hermit source-copy authority. It never catches a Git error
    /// or accepts caller-supplied metadata, inventories or compiler mappings.
    pub fn resolve_content(
        expected: &CompiledSourceExpectation<'_>,
        runner: &mut Runner,
    ) -> Result<Self> {
        require(
            expected.layout == CompiledSourceLayout::HermitGit,
            "declared content factory supports only closed Hermit image profiles",
        )?;
        require(
            source_pin_is_full(expected.reverie_pin),
            "compiled source requires an independent full Reverie pin",
        )?;
        for name in ["RUSTFLAGS", "CARGO_ENCODED_RUSTFLAGS"] {
            if let Some(flags) = std::env::var_os(name) {
                require(
                    !flags
                        .to_str()
                        .ok_or("compiler flags are not UTF-8")?
                        .contains("--remap-path-prefix"),
                    "caller compiler filename remapping is unsupported",
                )?;
            }
        }
        let root = fs::canonicalize(expected.workspace_root).map_err(|e| e.to_string())?;
        require(
            root.as_os_str() == expected.workspace_root.as_os_str(),
            "compiled source workspace is not canonical",
        )?;
        let (workspace_inventory, workspace_files) =
            declared_inventory(&root, content_workspace_files(expected.image_kind))?;
        let manifest = workspace_files
            .get(content_manifest_relative(expected.image_kind))
            .ok_or("declared build manifest missing")?
            .clone();
        require(
            manifest.path.as_os_str() == expected.manifest.as_os_str(),
            "compiled source manifest differs from the explicit build root",
        )?;
        let output = runner.run(
            "cargo",
            &[
                "metadata".into(),
                "--locked".into(),
                "--offline".into(),
                "--format-version=1".into(),
                "--manifest-path".into(),
                manifest
                    .path
                    .to_str()
                    .ok_or("compiled manifest is not UTF-8")?
                    .into(),
            ],
            &root,
        )?;
        let metadata: Value = serde_json::from_slice(&output)
            .map_err(|e| format!("fresh compiled source metadata: {e}"))?;
        let source = format!(
            "git+https://github.com/rrnewton/reverie.git?rev={0}#{0}",
            expected.reverie_pin
        );
        let binding = content_root_binding(&metadata, expected.reverie_pin)?;
        let producer_metadata = match expected.image_kind {
            FixedImageKind::Standalone => None,
            FixedImageKind::Detcore => {
                content_detcore_manifest_and_lock_pin(&metadata, &root, &source)?;
                let producer_manifest = workspace_files
                    .get("liteinst-runtime-build/Cargo.toml")
                    .ok_or("declared producer manifest missing")?;
                let output = runner.run(
                    "cargo",
                    &[
                        "metadata".into(),
                        "--locked".into(),
                        "--offline".into(),
                        "--format-version=1".into(),
                        "--manifest-path".into(),
                        producer_manifest
                            .path
                            .to_str()
                            .ok_or("producer manifest is not UTF-8")?
                            .into(),
                    ],
                    &root,
                )?;
                let producer: Value = serde_json::from_slice(&output)
                    .map_err(|e| format!("fresh producer source metadata: {e}"))?;
                content_same_root(
                    &binding,
                    &content_root_binding(&producer, expected.reverie_pin)?,
                )?;
                Some(producer)
            }
        };
        let producer_metadata = producer_metadata.as_ref().unwrap_or(&metadata);
        content_manifest_and_lock_pin(producer_metadata, &root, &source)?;
        let (reverie_inventory, reverie_files) =
            content_reverie_inventory_for_image(&binding.canonical_root, expected.image_kind)?;
        let mut packages = BTreeMap::new();
        for (name, target, kind) in [
            (
                "reverie-inguest",
                "reverie_inguest",
                &["cdylib", "rlib"][..],
            ),
            ("reverie-liteinst", "reverie_liteinst", &["rlib"][..]),
            (
                "reverie-liteinst-preload",
                "reverie_liteinst_preload",
                &["cdylib"][..],
            ),
            (
                "reverie-liteinst-artifact",
                "reverie_liteinst_artifact",
                &["lib"][..],
            ),
        ] {
            packages.insert(
                name.into(),
                content_package(
                    if name == "reverie-liteinst-preload" || name == "reverie-liteinst-artifact" {
                        producer_metadata
                    } else {
                        &metadata
                    },
                    name,
                    target,
                    kind,
                    &binding,
                    &source,
                )?,
            );
        }
        let leaf = match expected.image_kind {
            FixedImageKind::Standalone => packages
                .get("reverie-liteinst-preload")
                .ok_or("content leaf missing")?
                .clone(),
            FixedImageKind::Detcore => {
                let leaf = compiled_leaf_package(
                    &metadata,
                    &root,
                    &binding.canonical_root,
                    Some(&source),
                    FixedImageKind::Detcore,
                )?;
                packages.insert(leaf.name.clone(), leaf.clone());
                leaf
            }
        };
        let files = workspace_files
            .into_iter()
            .map(|(path, file)| (format!("workspace:{path}"), file))
            .chain(
                reverie_files
                    .into_iter()
                    .map(|(path, file)| (format!("rv:{path}"), file)),
            )
            .collect();
        let authority = CompiledSourceAuthority::DeclaredContent {
            workspace_sha256: declared_inventory_sha256(&workspace_inventory)?,
            workspace_inventory,
            reverie_sha256: declared_inventory_sha256(&reverie_inventory)?,
            reverie_inventory,
            compiler_root: binding.clone(),
        };
        let verified = Self {
            record: CompiledSources {
                layout: expected.layout,
                image_kind: expected.image_kind,
                workspace_root: root,
                authority,
                manifest,
                reverie_pin: expected.reverie_pin.into(),
                reverie_root: binding.canonical_root,
                packages,
                files,
                leaf,
            },
        };
        verified.verify_unchanged(runner)?;
        Ok(verified)
    }
    pub fn record(&self) -> &CompiledSources {
        &self.record
    }
    pub fn package(&self) -> &PackageIdentity {
        &self.record.leaf
    }
    /// Exact retained Cargo compiler spelling; canonical PackageIdentity remains
    /// unchanged for artifact selection. Consumers compare this raw path exactly.
    pub fn compiler_manifest_path(&self) -> Result<PathBuf> {
        self.verify_files()?;
        match &self.record.authority {
            CompiledSourceAuthority::Git { .. } => Ok(self.record.leaf.manifest.clone()),
            CompiledSourceAuthority::DeclaredContent { compiler_root, .. } => {
                content_compiler_manifest_path(
                    self.record.image_kind,
                    &self.record.workspace_root,
                    &self.record.leaf.manifest,
                    compiler_root,
                )
            }
        }
    }
    pub fn verify_unchanged(&self, runner: &mut Runner) -> Result<()> {
        let r = &self.record;
        if let CompiledSourceAuthority::Git {
            workspace_head,
            workspace_tree,
            reverie_tree,
        } = &r.authority
        {
            require(
                compiled_git_identity(&r.workspace_root, runner)?
                    == (workspace_head.clone(), workspace_tree.clone()),
                "compiled workspace changed during use",
            )?;
            require(
                compiled_git_identity(&r.reverie_root, runner)?
                    == (r.reverie_pin.clone(), reverie_tree.clone()),
                "compiled Reverie checkout changed during use",
            )?;
        }
        r.manifest.verify()?;
        self.verify_files()
    }
    fn verify_files(&self) -> Result<()> {
        if let CompiledSourceAuthority::DeclaredContent {
            workspace_inventory,
            workspace_sha256,
            reverie_inventory,
            reverie_sha256,
            compiler_root,
        } = &self.record.authority
        {
            verify_declared_content(
                self.record.image_kind,
                (
                    &self.record.workspace_root,
                    workspace_inventory,
                    workspace_sha256,
                ),
                (&self.record.reverie_root, reverie_inventory, reverie_sha256),
                compiler_root,
            )?;
        }
        self.record.manifest.verify()?;
        for file in self.record.files.values() {
            file.verify()?;
        }
        Ok(())
    }
    fn require_image(&self, initializer: &str) -> Result<()> {
        require(
            self.record.image_kind.initializer() == initializer,
            "compiled source context belongs to a different final image",
        )?;
        self.verify_files()
    }
    fn filename(&self, relative: &[u8]) -> Result<Vec<u8>> {
        let relative = std::str::from_utf8(relative).map_err(|e| e.to_string())?;
        if !COMPILED_RV_LOCATION_FILES.contains(&relative) {
            return Ok(relative.as_bytes().to_vec());
        }
        let file = self
            .record
            .files
            .get(&format!("rv:{relative}"))
            .ok_or("verified source context lacks exact filename role")?;
        if let CompiledSourceAuthority::DeclaredContent { compiler_root, .. } =
            &self.record.authority
        {
            self.verify_files()?;
            let logical = compiler_root.source_path(relative)?;
            require(
                real_file(&logical)?.as_os_str() == file.path.as_os_str(),
                "compiler filename does not match verified role",
            )?;
            return Ok(logical
                .to_str()
                .ok_or("compiled source filename is not UTF-8")?
                .as_bytes()
                .to_vec());
        }
        compiled_role_filename(self.record.layout, relative, file)
    }
}

/// Explicit expected manifest/source prevents selecting a lookalike workspace
/// package or wrong Cargo Git checkout with the same name. H passes the resolved
/// exact-pin Git package manifest and full metadata source string here.
pub fn select_package(
    metadata: &Value,
    name: &str,
    target_name: &str,
    expected_manifest: &Path,
    expected_source: Option<&str>,
) -> Result<PackageIdentity> {
    let packages = metadata["packages"]
        .as_array()
        .ok_or("metadata has no packages")?;
    let candidates: Vec<_> = packages.iter().filter(|p| p["name"] == name).collect();
    require(
        candidates.len() == 1,
        format!("expected exactly one metadata package {name}"),
    )?;
    let p = candidates[0];
    let manifest = real_file(Path::new(
        p["manifest_path"]
            .as_str()
            .ok_or("package manifest missing")?,
    ))?;
    require(
        manifest == real_file(expected_manifest)?,
        "selected package manifest differs from required checkout",
    )?;
    let source = p["source"].as_str().map(str::to_owned);
    require(
        source.as_deref() == expected_source,
        "selected Cargo package source differs from expected exact pin",
    )?;
    let targets = p["targets"]
        .as_array()
        .ok_or("metadata package has no targets")?;
    let targets: Vec<_> = targets
        .iter()
        .filter(|t| t["name"] == target_name)
        .collect();
    require(targets.len() == 1, "expected exactly one named leaf target")?;
    let t = targets[0];
    let kind = strings(&t["kind"])?;
    let crate_types = strings(&t["crate_types"])?;
    require(
        kind == ["cdylib"] && crate_types == ["cdylib"],
        "real preload target must be cdylib-only",
    )?;
    Ok(PackageIdentity {
        id: p["id"]
            .as_str()
            .ok_or("metadata package ID missing")?
            .to_owned(),
        name: name.to_owned(),
        manifest,
        source,
        target: target_name.to_owned(),
        kind,
        crate_types,
        target_source: real_file(Path::new(
            t["src_path"].as_str().ok_or("target src_path missing")?,
        ))?,
    })
}

fn strings(value: &Value) -> Result<Vec<String>> {
    value
        .as_array()
        .ok_or_else(|| "expected string array".to_owned())?
        .iter()
        .map(|v| {
            v.as_str()
                .map(str::to_owned)
                .ok_or_else(|| "non-string array entry".to_owned())
        })
        .collect()
}

#[derive(Clone, Debug, PartialEq, Serialize, Deserialize)]
#[serde(deny_unknown_fields)]
pub struct CargoArtifact {
    pub package: PackageIdentity,
    pub features: Vec<String>,
    /// Exact Cargo message profile. Custom profiles cannot be inferred from
    /// its fields alone; receipt separately records the explicit command name.
    pub profile: Value,
    pub fresh: bool,
    pub reported_path: PathBuf,
}

pub fn select_artifact(
    messages: &str,
    package: &PackageIdentity,
    expected_features: &[String],
    expected_profile: &Value,
    target_dir: &Path,
) -> Result<CargoArtifact> {
    let mut candidates = Vec::new();
    let mut finished = Vec::new();
    let mut expected_features = expected_features.to_vec();
    expected_features.sort();
    expected_features.dedup();
    for (index, line) in messages.lines().filter(|line| !line.is_empty()).enumerate() {
        let m: Value = serde_json::from_str(line)
            .map_err(|e| format!("Cargo JSON line {}: {e}", index + 1))?;
        if m["reason"] == "build-finished" {
            finished.push(m["success"].as_bool());
        }
        if m["reason"] != "compiler-artifact"
            || m["package_id"] != package.id
            || m["target"]["name"] != package.target
        {
            continue;
        }
        require(
            real_file(Path::new(
                m["manifest_path"]
                    .as_str()
                    .ok_or("artifact manifest_path missing")?,
            ))? == package.manifest,
            "artifact manifest mismatch",
        )?;
        require(
            strings(&m["target"]["kind"])? == package.kind
                && strings(&m["target"]["crate_types"])? == package.crate_types,
            "artifact target kind/crate-types mismatch",
        )?;
        require(
            real_file(Path::new(
                m["target"]["src_path"]
                    .as_str()
                    .ok_or("artifact target source missing")?,
            ))? == package.target_source,
            "artifact target source mismatch",
        )?;
        let mut features = strings(&m["features"])?;
        features.sort();
        require(
            features == expected_features,
            format!("artifact feature set differs: {features:?}, expected {expected_features:?}"),
        )?;
        require(
            &m["profile"] == expected_profile,
            format!("artifact profile differs: {}", m["profile"]),
        )?;
        let outputs: Vec<_> = strings(&m["filenames"])?
            .into_iter()
            .map(PathBuf::from)
            .filter(|p| p.extension().is_some_and(|e| e == "so"))
            .collect();
        require(
            outputs.len() == 1,
            "leaf compiler-artifact must report exactly one shared object",
        )?;
        let reported_path = real_file(&outputs[0])?;
        let target_dir = fs::canonicalize(target_dir).map_err(|e| e.to_string())?;
        require(
            reported_path.starts_with(target_dir),
            "artifact output is outside explicit separate target directory",
        )?;
        candidates.push(CargoArtifact {
            package: package.clone(),
            features,
            profile: m["profile"].clone(),
            fresh: m["fresh"].as_bool().ok_or("artifact freshness missing")?,
            reported_path,
        });
    }
    require(
        finished == [Some(true)],
        "Cargo must report exactly one successful build-finished message",
    )?;
    require(
        candidates.len() == 1,
        format!(
            "expected one current compiler-artifact; found {}",
            candidates.len()
        ),
    )?;
    Ok(candidates.remove(0))
}

