fn descriptor_mode(payload: &[u8]) -> Result<(u64, AllocatorBackingMode)> {
    require(
        payload.len() == 16,
        "allocator descriptor is not exactly sixteen bytes",
    )?;
    let version = u64::from_le_bytes(payload[..8].try_into().unwrap());
    let mode = match u64::from_le_bytes(payload[8..].try_into().unwrap()) {
        1 => AllocatorBackingMode::Legacy,
        2 => AllocatorBackingMode::Fixed,
        _ => return Err("unknown allocator descriptor mode".to_owned()),
    };
    require(version == 1, "unknown allocator descriptor version")?;
    Ok((version, mode))
}

fn descriptor_binding(binding: u8, visibility: u8) -> bool {
    binding == sym::STB_LOCAL || (binding == sym::STB_GLOBAL && visibility == sym::STV_HIDDEN)
}

fn descriptor_relocation_width(elf: &Elf<'_>, relocation: &reloc::Reloc) -> Result<u64> {
    Ok(match relocation.r_type {
        reloc::R_X86_64_NONE => 0,
        reloc::R_X86_64_COPY => elf
            .dynsyms
            .get(relocation.r_sym)
            .map(|symbol| symbol.st_size)
            .filter(|size| *size != 0)
            .ok_or("allocator descriptor COPY relocation size is unavailable")?,
        reloc::R_X86_64_TLSDESC => 16,
        reloc::R_X86_64_8 | reloc::R_X86_64_PC8 => 1,
        reloc::R_X86_64_16 | reloc::R_X86_64_PC16 => 2,
        reloc::R_X86_64_32
        | reloc::R_X86_64_32S
        | reloc::R_X86_64_PC32
        | reloc::R_X86_64_PLT32
        | reloc::R_X86_64_GOT32 => 4,
        reloc::R_X86_64_64
        | reloc::R_X86_64_RELATIVE
        | reloc::R_X86_64_IRELATIVE
        | reloc::R_X86_64_GLOB_DAT
        | reloc::R_X86_64_JUMP_SLOT
        | reloc::R_X86_64_DTPMOD64
        | reloc::R_X86_64_DTPOFF64
        | reloc::R_X86_64_TPOFF64 => 8,
        _ => {
            return Err(
                "unsupported runtime relocation width for descriptor immutability".to_owned(),
            );
        }
    })
}

// A relocation owns an interval, not only its starting address. The loader can
// write a selected pointer/code byte through a record beginning before it.
struct LoaderWriter {
    relocation: reloc::Reloc,
    end: u64,
}

fn loader_writers(elf: &Elf<'_>) -> Result<Vec<LoaderWriter>> {
    require(
        elf.dynamic.as_ref().is_none_or(|dynamic| {
            dynamic
                .dyns
                .iter()
                .all(|entry| !matches!(entry.d_tag, 35..=37))
        }),
        "packed DT_RELR writes are not decoded for loaded-byte authentication",
    )?;
    let mut writers = Vec::new();
    for relocation in elf
        .dynrelas
        .iter()
        .chain(elf.dynrels.iter())
        .chain(elf.pltrelocs.iter())
    {
        let width = descriptor_relocation_width(elf, &relocation)?;
        if width == 0 {
            continue;
        }
        let end = relocation
            .r_offset
            .checked_add(width)
            .ok_or("runtime relocation writer extent overflows")?;
        writers.push(LoaderWriter { relocation, end });
    }
    writers.sort_by_key(|writer| (writer.relocation.r_offset, writer.end));
    require(
        writers
            .windows(2)
            .all(|pair| pair[0].end <= pair[1].relocation.r_offset),
        "runtime relocation writer intervals overlap",
    )?;
    Ok(writers)
}

fn loader_meta_usize(value: u64) -> Result<usize> {
    usize::try_from(value).map_err(|_| "canonical loader metadata size overflows".to_owned())
}

fn loader_meta_slice(bytes: &[u8], offset: usize, length: usize) -> Result<&[u8]> {
    let end = offset
        .checked_add(length)
        .ok_or("canonical loader metadata extent overflows")?;
    bytes
        .get(offset..end)
        .ok_or_else(|| "canonical loader metadata is truncated".to_owned())
}

fn loader_meta_u16(bytes: &[u8], offset: usize) -> Result<u16> {
    Ok(u16::from_le_bytes(
        loader_meta_slice(bytes, offset, 2)?.try_into().unwrap(),
    ))
}

fn loader_meta_u32(bytes: &[u8], offset: usize) -> Result<u32> {
    Ok(u32::from_le_bytes(
        loader_meta_slice(bytes, offset, 4)?.try_into().unwrap(),
    ))
}

fn loader_meta_u64(bytes: &[u8], offset: usize) -> Result<u64> {
    Ok(u64::from_le_bytes(
        loader_meta_slice(bytes, offset, 8)?.try_into().unwrap(),
    ))
}

// This is an explicit canonical-format admission cut. Complete sections are
// mandatory, even though the platform loader can support sectionless images.
struct CanonicalLoaderMetadata<'a, 'e, 'b, 'w> {
    elf: &'e Elf<'a>,
    bytes: &'b [u8],
    writers: &'w [LoaderWriter],
    extents: Vec<(u64, u64)>,
}

impl<'a, 'e, 'b, 'w> CanonicalLoaderMetadata<'a, 'e, 'b, 'w> {
    fn extent(&mut self, address: u64, length: u64) -> Result<(usize, &'b [u8])> {
        require(address != 0, "canonical loader metadata address is zero")?;
        let length = loader_meta_usize(length)?;
        let (_, offset) = unique_file_mapping(self.elf, self.bytes, address, length)?;
        let end = address
            .checked_add(length as u64)
            .ok_or("loader metadata address overflows")?;
        require(
            self.writers
                .iter()
                .all(|writer| writer.relocation.r_offset >= end || writer.end <= address),
            "runtime writer intersects canonical loader-input metadata",
        )?;
        // The cut also refuses overlapping table representations/subtables.
        require(
            self.extents
                .iter()
                .all(|&(start, stop)| start >= end || stop <= address),
            "canonical loader metadata extents overlap",
        )?;
        let payload = readonly_loaded_bytes(self.elf, self.bytes, address, length)?;
        self.extents.push((address, end));
        Ok((offset, payload))
    }

    fn section(
        &self,
        kind: u32,
        address: u64,
        length: u64,
        entry: Option<u64>,
        link: Option<usize>,
    ) -> Result<(usize, u64)> {
        let sections: Vec<_> = self
            .elf
            .section_headers
            .iter()
            .enumerate()
            .filter(|(_, s)| s.sh_type == kind && s.sh_addr == address)
            .collect();
        require(
            sections.len() == 1,
            "canonical loader table lacks one section view",
        )?;
        let (index, section) = sections[0];
        require(
            section.sh_size == length
                && length != 0
                && section.sh_flags & goblin::elf::section_header::SHF_ALLOC as u64 != 0
                && entry.is_none_or(|value| section.sh_entsize == value)
                && link.is_none_or(|value| section.sh_link as usize == value),
            "canonical loader table section shape/link disagrees with dynamic view",
        )?;
        let (_, offset) =
            unique_file_mapping(self.elf, self.bytes, address, loader_meta_usize(length)?)?;
        require(
            offset as u64 == section.sh_offset,
            "canonical loader section/file mapping disagrees",
        )?;
        Ok((index, section.sh_info as u64))
    }

    fn only_section(&self, kind: u32) -> Result<usize> {
        let sections: Vec<_> = self
            .elf
            .section_headers
            .iter()
            .enumerate()
            .filter(|(_, section)| section.sh_type == kind)
            .collect();
        require(
            sections.len() == 1,
            "canonical loader table section is absent/ambiguous",
        )?;
        Ok(sections[0].0)
    }
}

fn loader_meta_required(tags: &BTreeMap<u64, u64>, tag: u64) -> Result<u64> {
    tags.get(&tag)
        .copied()
        .ok_or_else(|| format!("canonical loader tag {tag:#x} is absent"))
}

fn loader_meta_string(strings: &[u8], offset: u64) -> Result<&[u8]> {
    let suffix = strings
        .get(loader_meta_usize(offset)?..)
        .ok_or("canonical loader string offset is out of bounds")?;
    let end = suffix
        .iter()
        .position(|&byte| byte == 0)
        .ok_or("canonical loader string is unterminated")?;
    Ok(&suffix[..end])
}

struct LoaderRelocationSpec {
    addr_tag: u64,
    size_tag: u64,
    entry_tag: Option<u64>,
    fast_tag: Option<u64>,
    is_rela: bool,
}

fn loader_meta_relocations(
    context: &mut CanonicalLoaderMetadata<'_, '_, '_, '_>,
    tags: &BTreeMap<u64, u64>,
    LoaderRelocationSpec {
        addr_tag,
        size_tag,
        entry_tag,
        fast_tag,
        is_rela,
    }: LoaderRelocationSpec,
    parsed: &goblin::elf::reloc::RelocSection<'_>,
    parsed_offset: usize,
    parsed_size: usize,
    dynsym_index: usize,
) -> Result<()> {
    let present = tags.contains_key(&addr_tag)
        || tags.contains_key(&size_tag)
        || entry_tag.is_some_and(|tag| tags.contains_key(&tag));
    if !present {
        require(
            parsed.is_empty() && parsed_offset == 0 && parsed_size == 0,
            "absent relocation tags have nonempty decoded table",
        )?;
        require(
            fast_tag.is_none_or(|tag| !tags.contains_key(&tag)),
            "relative fast count has no relocation table",
        )?;
        return Ok(());
    }
    let address = loader_meta_required(tags, addr_tag)?;
    let length = loader_meta_required(tags, size_tag)?;
    let entry = if is_rela { 24 } else { 16 };
    if let Some(tag) = entry_tag {
        require(
            loader_meta_required(tags, tag)? == entry,
            "canonical relocation entry width differs",
        )?;
    }
    require(
        address != 0 && length != 0 && length % entry == 0,
        "canonical relocation table is empty/partial",
    )?;
    context.section(
        if is_rela {
            goblin::elf::section_header::SHT_RELA
        } else {
            goblin::elf::section_header::SHT_REL
        },
        address,
        length,
        Some(entry),
        Some(dynsym_index),
    )?;
    let (offset, table) = context.extent(address, length)?;
    require(
        offset == parsed_offset
            && table.len() == parsed_size
            && parsed.len() as u64 == length / entry,
        "relocation mapped offset/length disagrees with Goblin decoded table",
    )?;
    for (index, relocation) in parsed.iter().enumerate() {
        let record = loader_meta_slice(table, index * entry as usize, entry as usize)?;
        let info = loader_meta_u64(record, 8)?;
        require(
            (info >> 32) < context.elf.dynsyms.len() as u64,
            "relocation symbol index leaves the complete symbol table",
        )?;
        require(
            relocation.r_offset == loader_meta_u64(record, 0)?
                && relocation.r_type == info as u32
                && relocation.r_sym as u64 == info >> 32
                && relocation.r_addend
                    == if is_rela {
                        Some(loader_meta_u64(record, 16)? as i64)
                    } else {
                        None
                    },
            "raw relocation and Goblin decoded record disagree",
        )?;
    }
    if let Some(tag) = fast_tag {
        let count = tags.get(&tag).copied().unwrap_or(0);
        require(
            count <= length / entry,
            "relative fast count exceeds whole table",
        )?;
        for record in table
            .chunks_exact(entry as usize)
            .take(loader_meta_usize(count)?)
        {
            let info = loader_meta_u64(record, 8)?;
            require(
                info as u32 == reloc::R_X86_64_RELATIVE && info >> 32 == 0,
                "relative fast path record is not exactly RELATIVE/symbol-zero",
            )?;
        }
    }
    Ok(())
}

fn loader_meta_gnu_hash(name: &[u8]) -> u32 {
    name.iter().fold(5381_u32, |h, &byte| {
        h.wrapping_mul(33).wrapping_add(byte as u32)
    })
}

fn loader_meta_elf_hash(name: &[u8]) -> u32 {
    name.iter().fold(0_u32, |hash, &byte| {
        let h = hash.wrapping_shl(4).wrapping_add(byte as u32);
        let high = h & 0xf0000000;
        (h ^ (high >> 24)) & !high
    })
}

// Validate whole hash structures against the same complete dynsym count.
// The GNU bounded chain partitions ensure Goblin's last-bucket scan cannot
// produce a shorter count or read beyond the authenticated section.
fn loader_meta_hashes(
    context: &mut CanonicalLoaderMetadata<'_, '_, '_, '_>,
    tags: &BTreeMap<u64, u64>,
    symbol_count: usize,
    dynsym_index: usize,
    strings: &[u8],
) -> Result<()> {
    use goblin::elf::dynamic as d;
    use goblin::elf::section_header as sh;
    require(
        tags.contains_key(&d::DT_HASH) || tags.contains_key(&d::DT_GNU_HASH),
        "canonical dynamic symbol count lacks a complete hash table",
    )?;
    for (tag, kind) in [
        (d::DT_HASH, sh::SHT_HASH),
        (d::DT_GNU_HASH, sh::SHT_GNU_HASH),
    ] {
        let Some(&address) = tags.get(&tag) else {
            require(
                !context
                    .elf
                    .section_headers
                    .iter()
                    .any(|s| s.sh_type == kind),
                "hash section has no matching dynamic tag",
            )?;
            continue;
        };
        let index = context.only_section(kind)?;
        let section = &context.elf.section_headers[index];
        let length = section.sh_size;
        context.section(kind, address, length, None, Some(dynsym_index))?;
        let (offset, hash) = context.extent(address, length)?;
        let dynamic = context
            .elf
            .dynamic
            .as_ref()
            .ok_or("dynamic view disappeared")?;
        require(
            if tag == d::DT_HASH {
                dynamic.info.hash == Some(offset as u64)
            } else {
                dynamic.info.gnu_hash == Some(offset as u64)
            },
            "hash mapped offset differs from Goblin input",
        )?;
        let buckets = loader_meta_u32(hash, 0)? as usize;
        require(buckets != 0, "canonical hash has no buckets")?;
        if tag == d::DT_HASH {
            let chains = loader_meta_u32(hash, 4)? as usize;
            require(
                chains == symbol_count
                    && Some(hash.len())
                        == buckets
                            .checked_add(chains)
                            .and_then(|n| n.checked_mul(4))
                            .and_then(|n| n.checked_add(8)),
                "SYSV hash extent/count disagrees with complete symbols",
            )?;
            for chunk in hash[8..].as_chunks::<4>().0 {
                require(
                    (u32::from_le_bytes(*chunk) as usize) < chains,
                    "SYSV hash index leaves complete table",
                )?;
            }
            // No cycle or shared node is canonical; symbol zero is the terminator.
            let mut seen = vec![false; chains];
            for bucket in 0..buckets {
                let mut index = loader_meta_u32(hash, 8 + bucket * 4)? as usize;
                while index != 0 {
                    require(!seen[index], "SYSV hash chain cycles or shares a node")?;
                    seen[index] = true;
                    let symbol = context
                        .elf
                        .dynsyms
                        .get(index)
                        .ok_or("hash symbol is absent")?;
                    let name = loader_meta_string(strings, symbol.st_name as u64)?;
                    require(
                        loader_meta_elf_hash(name) as usize % buckets == bucket,
                        "SYSV hash bucket disagrees with symbol name",
                    )?;
                    index = loader_meta_u32(hash, 8 + buckets * 4 + index * 4)? as usize;
                }
            }
            require(
                seen.iter().skip(1).all(|&v| v),
                "SYSV hash omits dynamic symbols",
            )?;
        } else {
            let first = loader_meta_u32(hash, 4)? as usize;
            let bloom = loader_meta_u32(hash, 8)? as usize;
            let shift = loader_meta_u32(hash, 12)?;
            require(
                first != 0 && first < symbol_count && bloom.is_power_of_two() && shift < 32,
                "GNU hash header is outside canonical bounds",
            )?;
            let bucket_start = bloom
                .checked_mul(8)
                .and_then(|n| n.checked_add(16))
                .ok_or("GNU hash bloom extent overflows")?;
            let chain_start = buckets
                .checked_mul(4)
                .and_then(|n| n.checked_add(bucket_start))
                .ok_or("GNU hash bucket extent overflows")?;
            let chains = symbol_count - first;
            require(
                Some(hash.len())
                    == chains
                        .checked_mul(4)
                        .and_then(|n| n.checked_add(chain_start)),
                "GNU hash extent/count disagrees with complete symbols",
            )?;
            let mut seen = vec![false; chains];
            for bucket in 0..buckets {
                let index = loader_meta_u32(hash, bucket_start + bucket * 4)? as usize;
                if index == 0 {
                    continue;
                }
                require(
                    index >= first && index < symbol_count,
                    "GNU hash bucket leaves complete symbols",
                )?;
                let mut chain = index - first;
                loop {
                    require(
                        chain < chains && !seen[chain],
                        "GNU hash chain is truncated/overlapping",
                    )?;
                    seen[chain] = true;
                    let value = loader_meta_u32(hash, chain_start + chain * 4)?;
                    let symbol = context
                        .elf
                        .dynsyms
                        .get(first + chain)
                        .ok_or("hash symbol is absent")?;
                    let name = loader_meta_string(strings, symbol.st_name as u64)?;
                    let name_hash = loader_meta_gnu_hash(name);
                    require(
                        (value | 1) == (name_hash | 1) && name_hash as usize % buckets == bucket,
                        "GNU hash chain/bucket disagrees with symbol name",
                    )?;
                    let word =
                        loader_meta_u64(hash, 16 + ((name_hash as usize / 64) & (bloom - 1)) * 8)?;
                    let bits = (1_u64 << (name_hash % 64)) | (1_u64 << ((name_hash >> shift) % 64));
                    require(word & bits == bits, "GNU hash bloom omits indexed symbol")?;
                    if value & 1 != 0 {
                        break;
                    }
                    chain += 1;
                }
            }
            require(
                seen.iter().all(|&value| value),
                "GNU hash has unaccounted chain records",
            )?;
            for symbol in context.elf.dynsyms.iter().take(first) {
                require(
                    symbol.st_shndx == goblin::elf::section_header::SHN_UNDEF as usize
                        || symbol.st_info >> 4 == goblin::elf::sym::STB_LOCAL,
                    "defined nonlocal symbol is absent from GNU hash index",
                )?;
            }
        }
    }
    Ok(())
}

// Finite complete layouts, not an arbitrary linked-record graph fallback.
// VERNEED supports interleaved header/aux groups and the retained LLD form
// with a complete header prefix followed by contiguous per-header aux groups.
// VERDEF retains only its existing interleaved contract.
fn loader_meta_version_rows(
    table: &[u8],
    count: usize,
    is_need: bool,
) -> Result<Vec<(usize, usize, usize)>> {
    let header: usize = if is_need { 16 } else { 20 };
    let aux_width: usize = if is_need { 16 } else { 8 };
    let header_prefix_size = count
        .checked_mul(header)
        .ok_or("version header count overflows")?;
    require(
        count != 0 && header_prefix_size <= table.len(),
        "version headers exceed whole table",
    )?;
    let header_prefix = is_need && loader_meta_u32(table, 8)? as usize == header_prefix_size;
    let mut cursor = 0usize;
    let mut aux_cursor = if header_prefix { header_prefix_size } else { 0 };
    let mut rows = Vec::new();
    for row in 0..count {
        loader_meta_slice(table, cursor, header)?;
        require(
            loader_meta_u16(table, cursor)? == 1,
            "unsupported version record format",
        )?;
        let aux_count = loader_meta_u16(table, cursor + if is_need { 2 } else { 6 })? as usize;
        require(aux_count != 0, "version record has no auxiliaries")?;
        let aux_size = aux_count
            .checked_mul(aux_width)
            .ok_or("version auxiliary size overflows")?;
        let aux_start = if header_prefix {
            aux_cursor
        } else {
            cursor
                .checked_add(header)
                .ok_or("version auxiliary offset overflows")?
        };
        let expected_aux = aux_start
            .checked_sub(cursor)
            .ok_or("version auxiliary aliases header")?;
        require(
            loader_meta_u32(table, cursor + if is_need { 8 } else { 12 })? as usize == expected_aux,
            "version auxiliary offset leaves the selected complete layout",
        )?;
        loader_meta_slice(table, aux_start, aux_size)?;
        let aux_end = aux_start
            .checked_add(aux_size)
            .ok_or("version auxiliary end overflows")?;
        for aux in 0..aux_count {
            let at = aux_start + aux * aux_width;
            require(
                loader_meta_u32(table, at + if is_need { 12 } else { 4 })? as usize
                    == if aux + 1 == aux_count { 0 } else { aux_width },
                "version auxiliary count/termination disagrees",
            )?;
        }
        let step = if header_prefix {
            header
        } else {
            header
                .checked_add(aux_size)
                .ok_or("version record width overflows")?
        };
        require(
            loader_meta_u32(table, cursor + if is_need { 12 } else { 16 })? as usize
                == if row + 1 == count { 0 } else { step },
            "version record count/termination disagrees",
        )?;
        rows.push((cursor, aux_start, aux_count));
        cursor = cursor
            .checked_add(step)
            .ok_or("version header walk overflows")?;
        aux_cursor = aux_end;
    }
    // Fixed offsets partition the entire physical table. Prefix headers cannot
    // overlap their aux tail; interleaved groups have no holes or shared bytes.
    require(
        (if header_prefix { aux_cursor } else { cursor }) == table.len(),
        "version table has trailing/unaccounted records",
    )?;
    Ok(rows)
}

fn loader_meta_verneed_provider(strings: &[u8], file: u64, needed: &[u64]) -> Result<()> {
    let provider = loader_meta_string(strings, file)?;
    require(!provider.is_empty(), "VERNEED provider string is empty")?;
    let mut matches = false;
    for &offset in needed {
        let dependency = loader_meta_string(strings, offset)?;
        require(!dependency.is_empty(), "DT_NEEDED provider string is empty")?;
        matches |= dependency == provider;
    }
    require(
        matches,
        "VERNEED provider is absent from authenticated DT_NEEDED strings",
    )
}

// Restrict linked GNU version records to two complete finite VERNEED layouts
// and the existing interleaved VERDEF layout; no arbitrary graph admission.
// Goblin parses these by section type/sh_info, not the dynamic addresses.
fn loader_meta_versions(
    context: &mut CanonicalLoaderMetadata<'_, '_, '_, '_>,
    tags: &BTreeMap<u64, u64>,
    strings: &[u8],
    symbol_count: usize,
    dynsym_index: usize,
    dynstr_index: usize,
    needed: &[u64],
) -> Result<()> {
    use goblin::elf::dynamic as d;
    use goblin::elf::section_header as sh;
    let mut declared = BTreeMap::new();
    for (tag, count_tag, kind, is_need) in [
        (d::DT_VERNEED, d::DT_VERNEEDNUM, sh::SHT_GNU_VERNEED, true),
        (d::DT_VERDEF, d::DT_VERDEFNUM, sh::SHT_GNU_VERDEF, false),
    ] {
        let present = tags.contains_key(&tag) || tags.contains_key(&count_tag);
        if !present {
            require(
                !context
                    .elf
                    .section_headers
                    .iter()
                    .any(|s| s.sh_type == kind)
                    && if is_need {
                        context.elf.verneed.is_none()
                    } else {
                        context.elf.verdef.is_none()
                    },
                "version section/decoded view has no complete dynamic tags",
            )?;
            continue;
        }
        let address = loader_meta_required(tags, tag)?;
        let count = loader_meta_usize(loader_meta_required(tags, count_tag)?)?;
        let index = context.only_section(kind)?;
        let length = context.elf.section_headers[index].sh_size;
        let (_, info_count) = context.section(kind, address, length, None, Some(dynstr_index))?;
        require(
            count != 0 && count as u64 == info_count,
            "version count disagrees with section view",
        )?;
        let (offset, table) = context.extent(address, length)?;
        let dynamic = context
            .elf
            .dynamic
            .as_ref()
            .ok_or("dynamic view disappeared")?;
        require(
            offset as u64
                == if is_need {
                    dynamic.info.verneed
                } else {
                    dynamic.info.verdef
                },
            "version mapped offset differs from Goblin dynamic view",
        )?;
        // Do not use DynamicInfo.verdefnum: Goblin 0.10.7 VM-translates that
        // integer as though it were an address. The raw count and sh_info above
        // are joined to a complete bounded record walk instead.
        let decoded_count = if is_need {
            context
                .elf
                .verneed
                .as_ref()
                .ok_or("missing decoded VERNEED")?
                .iter()
                .count()
        } else {
            context
                .elf
                .verdef
                .as_ref()
                .ok_or("missing decoded VERDEF")?
                .iter()
                .count()
        };
        require(
            decoded_count == count,
            "decoded version walk terminates early",
        )?;
        let rows = loader_meta_version_rows(table, count, is_need)?;
        for (cursor, aux_start, aux_count) in rows {
            require(
                loader_meta_u16(table, cursor)? == 1,
                "unsupported version record format",
            )?;
            if !is_need {
                let index = loader_meta_u16(table, cursor + 4)?;
                require(
                    index != 0 && index & 0x8000 == 0 && declared.insert(index, false).is_none(),
                    "VERDEF index is absent/ambiguous/unsupported",
                )?;
            }
            if is_need {
                loader_meta_verneed_provider(
                    strings,
                    loader_meta_u32(table, cursor + 4)? as u64,
                    needed,
                )?;
            }
            let aux_width = if is_need { 16 } else { 8 };
            for aux in 0..aux_count {
                let at = aux_start + aux * aux_width;
                let name_at = at + if is_need { 8 } else { 0 };
                let name = loader_meta_string(strings, loader_meta_u32(table, name_at)? as u64)?;
                if is_need {
                    let index = loader_meta_u16(table, at + 6)? & 0x7fff;
                    require(
                        index > 1 && declared.insert(index, true).is_none(),
                        "VERNEED index is absent/ambiguous",
                    )?;
                    require(
                        loader_meta_u32(table, at)? == loader_meta_elf_hash(name),
                        "VERNEED name/hash disagree",
                    )?;
                } else if aux == 0 {
                    require(
                        loader_meta_u32(table, cursor + 8)? == loader_meta_elf_hash(name),
                        "VERDEF name/hash disagree",
                    )?;
                }
                let next_at = at + if is_need { 12 } else { 4 };
                require(
                    loader_meta_u32(table, next_at)? as usize
                        == if aux + 1 == aux_count { 0 } else { aux_width },
                    "version auxiliary count/termination disagrees",
                )?;
            }
        }
    }
    if let Some(&address) = tags.get(&d::DT_VERSYM) {
        let length = (symbol_count as u64)
            .checked_mul(2)
            .ok_or("VERSYM length overflows")?;
        context.only_section(sh::SHT_GNU_VERSYM)?;
        context.section(
            sh::SHT_GNU_VERSYM,
            address,
            length,
            Some(2),
            Some(dynsym_index),
        )?;
        let (offset, table) = context.extent(address, length)?;
        let dynamic = context
            .elf
            .dynamic
            .as_ref()
            .ok_or("dynamic view disappeared")?;
        let parsed = context
            .elf
            .versym
            .as_ref()
            .ok_or("missing decoded VERSYM")?;
        require(
            offset as u64 == dynamic.info.versym && parsed.len() == symbol_count,
            "VERSYM dynamic/decoded extent differs",
        )?;
        for index in 0..symbol_count {
            let raw = loader_meta_u16(table, index * 2)?;
            require(
                parsed
                    .get_at(index)
                    .ok_or("decoded VERSYM is truncated")?
                    .vs_val
                    == raw,
                "raw/decoded VERSYM disagree",
            )?;
            require(
                raw & 0x7fff <= 1 || declared.contains_key(&(raw & 0x7fff)),
                "VERSYM index has no complete declared version",
            )?;
        }
    } else {
        require(
            context.elf.versym.is_none()
                && !context
                    .elf
                    .section_headers
                    .iter()
                    .any(|s| s.sh_type == sh::SHT_GNU_VERSYM)
                && !tags.contains_key(&d::DT_VERDEF)
                && !tags.contains_key(&d::DT_VERNEED),
            "versioned symbols lack canonical VERSYM",
        )?;
    }
    Ok(())
}

fn canonical_loader_metadata(elf: &Elf<'_>, bytes: &[u8], writers: &[LoaderWriter]) -> Result<()> {
    use goblin::elf::dynamic as d;
    use goblin::elf::header;
    use goblin::elf::section_header as sh;
    require(
        usize::BITS == 64
            && elf.is_64
            && elf.little_endian
            && elf.header.e_machine == header::EM_X86_64
            && elf.header.e_type == header::ET_DYN,
        "canonical loader metadata requires ELF64 LE x86-64 ET_DYN",
    )?;
    // All lengths below are bounded by physical slices before indexing or walks.
    require(
        elf.header.e_ehsize == 64
            && elf.header.e_phentsize == 56
            && elf.header.e_phoff == 64
            && elf.header.e_phnum as usize == elf.program_headers.len(),
        "canonical loaded ELF/program-header shape is unsupported",
    )?;
    let ph_bytes = (elf.header.e_phnum as u64)
        .checked_mul(56)
        .ok_or("canonical program-header size overflows")?;
    let header_end = 64_u64
        .checked_add(ph_bytes)
        .ok_or("canonical header extent overflows")?;
    let (_, header_offset) = unique_file_mapping(elf, bytes, 0, loader_meta_usize(header_end)?)?;
    require(
        header_offset == 0,
        "canonical header file/load origin differs",
    )?;
    readonly_loaded_bytes(elf, bytes, 0, loader_meta_usize(header_end)?)?;
    let phdrs: Vec<_> = elf
        .program_headers
        .iter()
        .filter(|p| p.p_type == program_header::PT_PHDR)
        .collect();
    require(
        phdrs.len() == 1
            && phdrs[0].p_offset == 64
            && phdrs[0].p_vaddr == 64
            && phdrs[0].p_filesz == ph_bytes
            && phdrs[0].p_memsz == ph_bytes,
        "canonical PT_PHDR and loaded program-header table differ",
    )?;
    require(
        writers
            .iter()
            .all(|writer| writer.relocation.r_offset >= header_end),
        "runtime writer intersects loaded ELF/program-header metadata",
    )?;
    require(
        !elf.dynrelas
            .iter()
            .chain(elf.dynrels.iter())
            .chain(elf.pltrelocs.iter())
            .any(|r| matches!(r.r_type, reloc::R_X86_64_IRELATIVE | reloc::R_X86_64_COPY)),
        "canonical loader contract refuses resolver callbacks and COPY relocations",
    )?;
    require(
        !elf.dynsyms.iter().any(|s| {
            s.st_type() == goblin::elf::sym::STT_GNU_IFUNC && s.st_shndx != sh::SHN_UNDEF as usize
        }),
        "canonical loader contract refuses local IFUNC resolvers",
    )?;
    let mut context = CanonicalLoaderMetadata {
        elf,
        bytes,
        writers,
        extents: vec![(0, header_end)],
    };
    let dynamic_headers: Vec<_> = elf
        .program_headers
        .iter()
        .filter(|p| p.p_type == program_header::PT_DYNAMIC)
        .collect();
    require(
        dynamic_headers.len() == 1,
        "canonical PT_DYNAMIC is absent/ambiguous",
    )?;
    let ph = dynamic_headers[0];
    require(
        ph.p_filesz != 0
            && ph.p_filesz % 16 == 0
            && ph.p_memsz == ph.p_filesz
            && ph.p_vaddr % 8 == 0
            && ph.p_offset % 8 == 0,
        "canonical PT_DYNAMIC is empty/partial/not wholly file backed",
    )?;
    let (offset, table) = context.extent(ph.p_vaddr, ph.p_filesz)?;
    require(
        offset as u64 == ph.p_offset,
        "PT_DYNAMIC file offset disagrees with loaded address",
    )?;
    context.only_section(sh::SHT_DYNAMIC)?;
    let dynamic = elf.dynamic.as_ref().ok_or("missing Goblin dynamic view")?;
    let mut tags = BTreeMap::new();
    let mut needed = Vec::new();
    let mut terminated = false;
    let mut decoded_count = 0;
    for record in table.as_chunks::<16>().0 {
        let tag = loader_meta_u64(record, 0)?;
        let value = loader_meta_u64(record, 8)?;
        if terminated {
            require(
                tag == d::DT_NULL && value == 0,
                "nonzero PT_DYNAMIC tail after terminator",
            )?;
            continue;
        }
        let decoded = dynamic
            .dyns
            .get(decoded_count)
            .ok_or("Goblin dynamic view is truncated")?;
        require(
            decoded.d_tag == tag && decoded.d_val == value,
            "raw/decoded dynamic entries disagree",
        )?;
        decoded_count += 1;
        if tag == d::DT_NULL {
            require(value == 0, "nonzero DT_NULL payload is refused")?;
            terminated = true;
            continue;
        }
        // Unknown loader extensions (including RELR/Android packed tables,
        // audit/filter/syminfo/conflict tables and DT_DEBUG loader mutation)
        // are a named refusal, never ignored as harmless extra input.
        require(
            matches!(tag, 1..=20 | 22..=30 | 0x6ffffef5 | 0x6ffffff0
            | 0x6ffffff9 | 0x6ffffffa | 0x6ffffffb | 0x6ffffffc
            | 0x6ffffffd | 0x6ffffffe | 0x6fffffff),
            "unsupported canonical dynamic tag/layout",
        )?;
        if tag == d::DT_NEEDED {
            needed.push(value);
        } else {
            require(
                tags.insert(tag, value).is_none(),
                "duplicate canonical dynamic tag",
            )?;
        }
    }
    require(
        terminated && decoded_count == dynamic.dyns.len(),
        "PT_DYNAMIC is unterminated/inconsistent",
    )?;
    // Lazy PLT setup has reserved-slot writes beyond the encoded relocation
    // records. This finite contract only admits declared eager binding.
    let flags = tags.get(&d::DT_FLAGS).copied().unwrap_or(0);
    let flags1 = tags.get(&d::DT_FLAGS_1).copied().unwrap_or(0);
    require(
        flags & !8 == 0
            && flags1 & !1 == 0
            && (tags.contains_key(&d::DT_BIND_NOW) || flags == 8 || flags1 == 1),
        "canonical loader contract requires eager binding with supported flags",
    )?;
    let strings_address = loader_meta_required(&tags, d::DT_STRTAB)?;
    let strings_length = loader_meta_required(&tags, d::DT_STRSZ)?;
    let (dynstr_index, _) =
        context.section(sh::SHT_STRTAB, strings_address, strings_length, None, None)?;
    context.section(
        sh::SHT_DYNAMIC,
        ph.p_vaddr,
        ph.p_filesz,
        Some(16),
        Some(dynstr_index),
    )?;
    let (strings_offset, strings) = context.extent(strings_address, strings_length)?;
    require(
        strings_offset == dynamic.info.strtab
            && strings.len() == dynamic.info.strsz
            && strings.first() == Some(&0)
            && strings.last() == Some(&0),
        "dynamic string extent/termination disagrees",
    )?;
    for offset in needed.iter().copied().chain(
        [d::DT_SONAME, d::DT_RPATH, d::DT_RUNPATH]
            .into_iter()
            .filter_map(|tag| tags.get(&tag).copied()),
    ) {
        let raw = loader_meta_string(strings, offset)?;
        require(
            !raw.is_empty()
                && elf
                    .dynstrtab
                    .get_at(loader_meta_usize(offset)?)
                    .is_some_and(|decoded| decoded.as_bytes() == raw),
            "loader provider/path string raw/decoded view disagrees",
        )?;
    }
    let sym_address = loader_meta_required(&tags, d::DT_SYMTAB)?;
    require(
        loader_meta_required(&tags, d::DT_SYMENT)? == 24,
        "noncanonical dynamic symbol width",
    )?;
    let dynsym_index = context.only_section(sh::SHT_DYNSYM)?;
    let symbol_length = elf.section_headers[dynsym_index].sh_size;
    context.section(
        sh::SHT_DYNSYM,
        sym_address,
        symbol_length,
        Some(24),
        Some(dynstr_index),
    )?;
    require(
        symbol_length.is_multiple_of(24),
        "partial dynamic symbol table",
    )?;
    let (symbol_offset, symbols) = context.extent(sym_address, symbol_length)?;
    let symbol_count = symbols.len() / 24;
    require(
        symbol_count != 0 && symbols[..24].iter().all(|&byte| byte == 0),
        "dynamic symbol zero is not the canonical null record",
    )?;
    require(
        symbol_offset == dynamic.info.symtab
            && dynamic.info.syment == 24
            && elf.dynsyms.offset() == symbol_offset
            && elf.dynsyms.len() == symbol_count,
        "dynamic symbol mapped/decoded extent disagrees",
    )?;
    for (index, symbol) in elf.dynsyms.iter().enumerate() {
        let record = &symbols[index * 24..(index + 1) * 24];
        require(
            symbol.st_name as u64 == loader_meta_u32(record, 0)? as u64
                && symbol.st_info == record[4]
                && symbol.st_other == record[5]
                && symbol.st_shndx as u64 == loader_meta_u16(record, 6)? as u64
                && symbol.st_value == loader_meta_u64(record, 8)?
                && symbol.st_size == loader_meta_u64(record, 16)?,
            "dynamic symbol raw/decoded view disagrees",
        )?;
        let raw = loader_meta_string(strings, symbol.st_name as u64)?;
        require(
            elf.dynstrtab
                .get_at(symbol.st_name)
                .is_some_and(|decoded| decoded.as_bytes() == raw),
            "dynamic symbol name raw/decoded view disagrees",
        )?;
    }
    loader_meta_hashes(&mut context, &tags, symbol_count, dynsym_index, strings)?;
    loader_meta_versions(
        &mut context,
        &tags,
        strings,
        symbol_count,
        dynsym_index,
        dynstr_index,
        &needed,
    )?;
    loader_meta_relocations(
        &mut context,
        &tags,
        LoaderRelocationSpec {
            addr_tag: d::DT_RELA,
            size_tag: d::DT_RELASZ,
            entry_tag: Some(d::DT_RELAENT),
            fast_tag: Some(d::DT_RELACOUNT),
            is_rela: true,
        },
        &elf.dynrelas,
        dynamic.info.rela,
        dynamic.info.relasz,
        dynsym_index,
    )?;
    loader_meta_relocations(
        &mut context,
        &tags,
        LoaderRelocationSpec {
            addr_tag: d::DT_REL,
            size_tag: d::DT_RELSZ,
            entry_tag: Some(d::DT_RELENT),
            fast_tag: Some(d::DT_RELCOUNT),
            is_rela: false,
        },
        &elf.dynrels,
        dynamic.info.rel,
        dynamic.info.relsz,
        dynsym_index,
    )?;
    let plt_present = tags.contains_key(&d::DT_JMPREL)
        || tags.contains_key(&d::DT_PLTRELSZ)
        || tags.contains_key(&d::DT_PLTREL);
    if plt_present {
        let kind = loader_meta_required(&tags, d::DT_PLTREL)?;
        require(
            kind == d::DT_RELA || kind == d::DT_REL,
            "unsupported PLT relocation encoding",
        )?;
        loader_meta_relocations(
            &mut context,
            &tags,
            LoaderRelocationSpec {
                addr_tag: d::DT_JMPREL,
                size_tag: d::DT_PLTRELSZ,
                entry_tag: None,
                fast_tag: None,
                is_rela: kind == d::DT_RELA,
            },
            &elf.pltrelocs,
            dynamic.info.jmprel,
            dynamic.info.pltrelsz,
            dynsym_index,
        )?;
    } else {
        require(
            elf.pltrelocs.is_empty() && dynamic.info.jmprel == 0 && dynamic.info.pltrelsz == 0,
            "decoded PLT relocations have no complete dynamic tags",
        )?;
    }
    Ok(())
}

// The named refusal boundary for every public actual-image admission. The
// caller must supply the same bytes used to construct this fresh Elf view.
// Low-level operand helpers cannot independently establish loader metadata;
// their callers use this whole-image gate before earning qualification.
fn authenticate_loader_metadata(elf: &Elf<'_>, bytes: &[u8]) -> Result<()> {
    fixed_require_sane_loads(elf, bytes)?;
    canonical_loader_metadata(elf, bytes, &loader_writers(elf)?)
}

fn extent_writers(elf: &Elf<'_>, address: u64, length: usize) -> Result<Vec<reloc::Reloc>> {
    let end = address
        .checked_add(length as u64)
        .ok_or("selected writer extent overflows")?;
    require(length != 0, "empty selected writer extent")?;
    Ok(loader_writers(elf)?
        .into_iter()
        .filter(|writer| writer.relocation.r_offset < end && writer.end > address)
        .map(|writer| writer.relocation)
        .collect())
}

// Count actual rounded PT_LOAD mappings, not deduplicated file offsets. A
// second partial-page mapping can replace the page containing the selected
// bytes even when it does not contain their nominal virtual address range.
fn unique_file_mapping<'a>(
    elf: &'a Elf<'_>,
    bytes: &[u8],
    address: u64,
    length: usize,
) -> Result<(&'a program_header::ProgramHeader, usize)> {
    fixed_require_sane_loads(elf, bytes)?;
    require(length != 0, "empty selected loaded extent")?;
    let end = address
        .checked_add(length as u64)
        .ok_or("selected loaded extent overflows")?;
    let page_start = address & !4095;
    let page_end = end
        .checked_add(4095)
        .ok_or("selected loaded pages overflow")?
        & !4095;
    let mappings: Vec<_> = elf
        .program_headers
        .iter()
        .filter(|p| p.p_type == program_header::PT_LOAD)
        .filter(|p| {
            (p.p_vaddr & !4095) < page_end && ((p.p_vaddr + p.p_memsz + 4095) & !4095) > page_start
        })
        .collect();
    require(
        mappings.len() == 1,
        "selected bytes lack a unique actual page mapping",
    )?;
    let mapping = mappings[0];
    require(
        address >= mapping.p_vaddr && end <= mapping.p_vaddr + mapping.p_filesz,
        "selected bytes are not wholly file backed in the actual mapping",
    )?;
    let offset = mapping
        .p_offset
        .checked_add(address - mapping.p_vaddr)
        .and_then(|offset| usize::try_from(offset).ok())
        .ok_or("selected loaded file offset overflows")?;
    require(
        offset
            .checked_add(length)
            .is_some_and(|end| end <= bytes.len()),
        "selected loaded bytes exceed the actual file",
    )?;
    Ok((mapping, offset))
}

fn readonly_loaded_bytes<'a>(
    elf: &Elf<'_>,
    bytes: &'a [u8],
    address: u64,
    length: usize,
) -> Result<&'a [u8]> {
    let (mapping, offset) = unique_file_mapping(elf, bytes, address, length)?;
    require(
        mapping.p_flags & program_header::PF_R != 0,
        "selected readonly bytes have wrong actual mapping flags",
    )?;
    if mapping.p_flags & program_header::PF_W != 0 {
        let relros: Vec<_> = elf
            .program_headers
            .iter()
            .filter(|p| p.p_type == program_header::PT_GNU_RELRO)
            .collect();
        require(
            relros.len() == 1,
            "selected readonly bytes need unique GNU_RELRO",
        )?;
        let relro = relros[0];
        let relro_end = relro
            .p_vaddr
            .checked_add(relro.p_memsz)
            .ok_or("selected GNU_RELRO extent overflows")?;
        require(
            relro.p_memsz != 0
                && relro.p_vaddr >= mapping.p_vaddr
                && relro_end <= mapping.p_vaddr + mapping.p_memsz
                && address >= relro.p_vaddr
                && address + length as u64 <= (relro_end & !4095),
            "selected bytes are outside complete protected GNU_RELRO pages",
        )?;
    }
    Ok(&bytes[offset..offset + length])
}

fn init_array_bytes<'a>(
    elf: &Elf<'_>,
    bytes: &'a [u8],
    section: &section_header::SectionHeader,
) -> Result<&'a [u8]> {
    let length = usize::try_from(section.sh_size).map_err(|_| "init_array size overflows")?;
    let (_, offset) = unique_file_mapping(elf, bytes, section.sh_addr, length)?;
    require(
        offset as u64 == section.sh_offset,
        "init_array section/load physical join differs",
    )?;
    readonly_loaded_bytes(elf, bytes, section.sh_addr, length)
}

fn immutable_allocator_object(
    elf: &Elf<'_>,
    bytes: &[u8],
    object_name: &str,
    size: u64,
) -> Result<ImmutableAllocatorObject> {
    require(
        elf.header.e_machine == header::EM_X86_64
            && elf.header.e_type == header::ET_DYN
            && elf.header.e_ident[header::EI_CLASS] == header::ELFCLASS64
            && elf.header.e_ident[header::EI_DATA] == header::ELFDATA2LSB,
        "allocator descriptor requires actual little-endian x86-64 shared ELF",
    )?;
    let symbols: Vec<_> = elf
        .syms
        .iter()
        .filter(|symbol| elf.strtab.get_at(symbol.st_name) == Some(object_name))
        .collect();
    require(
        symbols.len() == 1,
        "required unique allocator descriptor is absent/ambiguous",
    )?;
    let symbol = symbols[0];
    require(
        symbol.st_type() == sym::STT_OBJECT
            && symbol.st_size == size
            && symbol.st_value % 8 == 0
            && symbol.st_shndx != section_header::SHN_UNDEF as usize
            && descriptor_binding(symbol.st_bind(), symbol.st_visibility()),
        "allocator descriptor is not an aligned strong hidden/local defined sixteen-byte object",
    )?;
    let end = symbol
        .st_value
        .checked_add(size)
        .ok_or("allocator descriptor range overflows")?;
    let section = elf
        .section_headers
        .get(symbol.st_shndx)
        .ok_or("allocator descriptor section is absent")?;
    require(
        section.sh_type == section_header::SHT_PROGBITS
            && section.sh_flags & u64::from(section_header::SHF_ALLOC) != 0
            && section.sh_flags
                & u64::from(section_header::SHF_WRITE | section_header::SHF_EXECINSTR)
                == 0
            && symbol.st_value >= section.sh_addr
            && section
                .sh_addr
                .checked_add(section.sh_size)
                .is_some_and(|high| end <= high),
        "allocator descriptor section is not allocated immutable file-backed data",
    )?;
    let mut overlapping = Vec::new();
    for (index, segment) in elf
        .program_headers
        .iter()
        .enumerate()
        .filter(|(_, segment)| segment.p_type == program_header::PT_LOAD)
    {
        let memory_end = segment
            .p_vaddr
            .checked_add(segment.p_memsz)
            .ok_or("allocator descriptor loader mapping range overflows")?;
        let high = memory_end
            .checked_add(0xfff)
            .ok_or("allocator descriptor loader page range overflows")?
            & !0xfff;
        let low = segment.p_vaddr & !0xfff;
        // Linux maps load segments at page granularity. A later writable
        // segment sharing this page invalidates physical immutability even
        // when its unrounded byte interval begins after the descriptor.
        if low < end && symbol.st_value < high {
            overlapping.push((index, segment));
        }
    }
    require(
        overlapping.len() == 1,
        "allocator descriptor has overlapping/absent loader mappings",
    )?;
    let (load_segment_index, segment) = overlapping[0];
    require(
        segment.p_flags & program_header::PF_R != 0
            && segment.p_flags & (program_header::PF_W | program_header::PF_X) == 0
            && segment.p_vaddr % 0x1000 == segment.p_offset % 0x1000
            && symbol.st_value >= segment.p_vaddr
            && segment
                .p_vaddr
                .checked_add(segment.p_filesz)
                .is_some_and(|high| end <= high),
        "allocator descriptor lacks a readable nonwritable nonexecuting physical PT_LOAD",
    )?;
    let file_offset = segment
        .p_offset
        .checked_add(symbol.st_value - segment.p_vaddr)
        .ok_or("allocator descriptor physical offset overflows")?;
    require(
        section
            .sh_offset
            .checked_add(symbol.st_value - section.sh_addr)
            == Some(file_offset),
        "allocator descriptor section/loader physical offsets disagree",
    )?;
    for dynamic in elf.dynsyms.iter() {
        let name = elf.dynstrtab.get_at(dynamic.st_name);
        if name == Some(object_name) {
            require(
                symbol.st_bind() == sym::STB_GLOBAL
                    && dynamic.st_bind() == sym::STB_GLOBAL
                    && dynamic.st_visibility() == sym::STV_HIDDEN
                    && dynamic.st_type() == sym::STT_OBJECT
                    && dynamic.st_shndx != section_header::SHN_UNDEF as usize
                    && dynamic.st_value == symbol.st_value
                    && dynamic.st_size == size,
                "allocator descriptor has a dynamic undefined/preemptible/conflicting identity",
            )?;
        } else if dynamic.st_shndx != section_header::SHN_UNDEF as usize {
            let aliases = dynamic.st_value >= symbol.st_value && dynamic.st_value < end
                || dynamic
                    .st_value
                    .checked_add(dynamic.st_size)
                    .is_some_and(|high| dynamic.st_value < end && symbol.st_value < high);
            require(
                !aliases,
                "allocator descriptor has an unbound dynamic alias",
            )?;
        }
    }
    require(
        elf.dynamic
            .as_ref()
            .is_none_or(|dynamic| dynamic.dyns.iter().all(|entry| entry.d_tag != 36)),
        "packed DT_RELR relocation writes are not decoded for descriptor immutability",
    )?;
    for relocation in elf
        .dynrelas
        .iter()
        .chain(elf.dynrels.iter())
        .chain(elf.pltrelocs.iter())
    {
        let width = descriptor_relocation_width(elf, &relocation)?;
        let high = relocation
            .r_offset
            .checked_add(width)
            .ok_or("allocator descriptor relocation range overflows")?;
        require(
            width == 0 || relocation.r_offset >= end || high <= symbol.st_value,
            "runtime relocation writes immutable allocator descriptor payload",
        )?;
        // References from other storage/text to this object remain legitimate;
        // immutability concerns the relocation destination, not its addend/name.
    }
    let payload = loaded_bytes(
        elf,
        bytes,
        symbol.st_value,
        usize::try_from(size).map_err(|e| e.to_string())?,
    )?;
    Ok(ImmutableAllocatorObject {
        symbol: symbol_evidence(object_name, &symbol),
        payload_sha256: sha256(payload),
        file_offset,
        section_index: symbol.st_shndx,
        load_segment_index,
    })
}

fn allocator_descriptor(elf: &Elf<'_>, bytes: &[u8]) -> Result<AllocatorDescriptorEvidence> {
    let object = immutable_allocator_object(elf, bytes, ALLOCATOR_BACKING_SYMBOL, 16)?;
    let payload = loaded_bytes(elf, bytes, object.symbol.address, 16)?;
    let (version, mode) = descriptor_mode(payload)?;
    Ok(AllocatorDescriptorEvidence {
        symbol: object.symbol,
        version,
        mode,
        payload_sha256: object.payload_sha256,
        file_offset: object.file_offset,
        section_index: object.section_index,
        load_segment_index: object.load_segment_index,
    })
}

const FIXED_TOOL_BOTTOM: u64 = 0x6000_1000_0000;
const FIXED_PATCH_BOTTOM: u64 = 0x6000_1400_0000;
const FIXED_ARENA_BYTES: u64 = 0x0200_0000;
const FIXED_METADATA: u64 = 0x6000_0002_3000;
const FIXED_BACKING_RECORD_ROLE: &str =
    "_RNvNtNtNtCs_15reverie_inguest5guest11tool_region5arena13FIXED_BACKING";
const FIXED_TLS_CELL_ROLE: &str = "_RNvNCNKNvNtCs_16reverie_liteinst11patch_alloc18INSTALLATION_DEPTH0s_023___RUST_STD_INTERNAL_VAL";

fn fixed_backing_record(elf: &Elf<'_>, bytes: &[u8]) -> Result<ImmutableAllocatorObject> {
    let candidates: Vec<_> = elf
        .syms
        .iter()
        .filter(|symbol| {
            elf.strtab
                .get_at(symbol.st_name)
                .and_then(canonical_rust_symbol)
                .is_some_and(|name| name == FIXED_BACKING_RECORD_ROLE)
        })
        .collect();
    require(
        candidates.len() == 1,
        "actual immutable Fixed backing record absent/ambiguous",
    )?;
    let symbol = candidates[0];
    let name = elf
        .strtab
        .get_at(symbol.st_name)
        .ok_or("Fixed backing record name absent")?;
    let object = immutable_allocator_object(elf, bytes, name, 40)?;
    let payload = loaded_bytes(elf, bytes, object.symbol.address, 40)?;
    let expected = [
        FIXED_TOOL_BOTTOM,
        FIXED_TOOL_BOTTOM + FIXED_ARENA_BYTES,
        FIXED_PATCH_BOTTOM,
        FIXED_PATCH_BOTTOM + FIXED_ARENA_BYTES,
        FIXED_METADATA + 24,
    ];
    require(
        payload
            .as_chunks::<8>()
            .0
            .iter()
            .map(|word| u64::from_le_bytes(*word))
            .eq(expected),
        "immutable Fixed record has wrong exact selected spans/cursor",
    )?;
    Ok(object)
}

// Insert into scripts/m1_artifact.rs alongside its Result/require and
// ConstructorTransfer definitions. No runtime/ELF IO, hashing or admission here.
// Whole bytes must already be joined to the exact complete executable symbol.
// `got` MUST come from local_got_targets: unique R_X86_64_RELATIVE, STB_LOCAL
// executable target, complete eight-byte slot in mapped GNU RELRO. `trusted_gate`
// MUST be the independently qualified same-owner hidden trusted-gate symbol.
// A plain BTreeMap cannot itself establish these ELF/visibility premises.
// SysV x86-64 integer-register entry, valid owned scratch/destination/source,
// complete caller-proven bounds/nonoverlap, and the frozen clear-DF premise apply.

const FIXED_SCALAR_ZERO_DEV: &[u8] = &[
    0x48, 0x89, 0xf1, 0x48, 0x89, 0x7c, 0x24, 0xf0, 0x48, 0x89, 0x4c, 0x24, 0xf8, 0x31, 0xc0, 0xf3,
    0xaa, 0xc3,
];
const FIXED_SCALAR_ZERO_RELEASE: &[u8] = &[0x48, 0x89, 0xf1, 0x31, 0xc0, 0xf3, 0xaa, 0xc3];
const FIXED_SCALAR_COPY_DEV: &[u8] = &[
    0x48, 0x89, 0xd1, 0x48, 0x89, 0x74, 0x24, 0xe0, 0x48, 0x89, 0xfe, 0x48, 0x8b, 0x7c, 0x24, 0xe0,
    0x48, 0x89, 0x74, 0x24, 0xe8, 0x48, 0x89, 0x7c, 0x24, 0xf0, 0x48, 0x89, 0x4c, 0x24, 0xf8, 0xf3,
    0xa4, 0xc3,
];
const FIXED_SCALAR_COPY_RELEASE: &[u8] = &[
    0x48, 0x89, 0xd1, 0x48, 0x89, 0xf8, 0x48, 0x89, 0xf7, 0x48, 0x89, 0xc6, 0xf3, 0xa4, 0xc3,
];
const FIXED_SCALAR_SYSCALL_DEV_PREFIX: &[u8] = &[
    0x48, 0x83, 0xec, 0x28, 0x48, 0x89, 0x7c, 0x24, 0x08, 0x48, 0x89, 0x74, 0x24, 0x10, 0x48, 0x89,
    0x54, 0x24, 0x18, 0x48, 0x89, 0x4c, 0x24, 0x20, 0x31, 0xc0, 0x41, 0x89, 0xc1, 0x4d, 0x89, 0xc8,
    0x48, 0xc7, 0x04, 0x24, 0x00, 0x00, 0x00, 0x00, 0xff, 0x15,
];
const FIXED_SCALAR_SYSCALL_DEV_SUFFIX: &[u8] = &[0x48, 0x83, 0xc4, 0x28, 0xc3];
const FIXED_SCALAR_SYSCALL_RELEASE_PREFIX: &[u8] = &[
    0x50, 0x48, 0xc7, 0x04, 0x24, 0x00, 0x00, 0x00, 0x00, 0x45, 0x31, 0xc0, 0x45, 0x31, 0xc9, 0xff,
    0x15,
];
const FIXED_SCALAR_SYSCALL_RELEASE_SUFFIX: &[u8] = &[0x59, 0xc3];

fn fixed_scalar_helper_recipe(
    role: &str,
    address: u64,
    bytes: &[u8],
    got: &BTreeMap<u64, u64>,
    trusted_gate: u64,
) -> Result<Vec<ConstructorTransfer>> {
    require(
        address.checked_add(bytes.len() as u64).is_some(),
        "fixed scalar helper function range overflow",
    )?;
    match role {
        "fixed_zero_bytes" => {
            require(
                bytes == FIXED_SCALAR_ZERO_DEV || bytes == FIXED_SCALAR_ZERO_RELEASE,
                "unrecognized whole fixed zero-byte ABI recipe",
            )?;
            // Both complete variants move length RSI->RCX, preserve incoming
            // destination RDI, XOR EAX (therefore AL=0), then sole REP STOSB, RET.
            // Dev writes only observed ABI red-zone spill cells -16 and -8.
            // No call, callee-saved register, additional payload access or DF edit.
            Ok(Vec::new())
        }
        "fixed_copy_bytes" => {
            require(
                bytes == FIXED_SCALAR_COPY_DEV || bytes == FIXED_SCALAR_COPY_RELEASE,
                "unrecognized whole fixed copy-byte ABI recipe",
            )?;
            // Both move length RDX->RCX, source incoming RDI->RSI and destination
            // incoming RSI->RDI, then sole REP MOVSB, RET. The release variant
            // uses RAX as a caller-saved source temporary. Dev writes only exact
            // red-zone spill cells -32,-24,-16,-8; no callee-saved register change.
            Ok(Vec::new())
        }
        "fixed_scalar_syscall" => {
            let call_offset = if bytes.len() == 51
                && bytes.starts_with(FIXED_SCALAR_SYSCALL_DEV_PREFIX)
                && bytes[46..] == *FIXED_SCALAR_SYSCALL_DEV_SUFFIX
            {
                40_usize
            } else if bytes.len() == 23
                && bytes.starts_with(FIXED_SCALAR_SYSCALL_RELEASE_PREFIX)
                && bytes[21..] == *FIXED_SCALAR_SYSCALL_RELEASE_SUFFIX
            {
                15_usize
            } else {
                return Err("unrecognized whole fixed scalar-syscall ABI recipe".into());
            };
            // All non-displacement bytes match the immutable full recipe.
            // Preserve incoming number RDI, arg0 RSI, arg1 RDX, arg2 RCX;
            // set arg3 R8=0/arg4 R9=0 and [RSP] arg5=0 before the sole FF15 CALL.
            // That cell is gate-entry [RSP+8]. Dev SUB40/ADD40; release PUSH RAX/
            // POP RCX. Both align the SysV call stack and restore old RSP exactly,
            // preserving gate result RAX and every callee-saved register.
            require(trusted_gate != 0, "missing exact trusted syscall gate")?;
            let displacement = i32::from_le_bytes(
                bytes[call_offset + 2..call_offset + 6]
                    .try_into()
                    .map_err(|_| "truncated fixed scalar syscall displacement")?,
            );
            let instruction = address
                .checked_add(call_offset as u64)
                .ok_or("fixed scalar syscall instruction address overflow")?;
            let next = instruction
                .checked_add(6)
                .ok_or("fixed scalar syscall next RIP overflow")?;
            let slot = next
                .checked_add_signed(i64::from(displacement))
                .ok_or("fixed scalar syscall GOT displacement overflow")?;
            require(
                got.get(&slot) == Some(&trusted_gate),
                "fixed scalar syscall requires exact local RELATIVE RELRO trusted gate",
            )?;
            Ok(vec![ConstructorTransfer {
                instruction,
                target: trusted_gate,
                local_got_slot: Some(slot),
            }])
        }
        _ => Err("unknown fixed scalar helper role".into()),
    }
}

fn fixed_hex(hex: &str) -> Vec<u8> {
    assert_eq!(hex.len() % 2, 0);
    hex.as_bytes()
        .as_chunks::<2>()
        .0
        .iter()
        .map(|pair| u8::from_str_radix(std::str::from_utf8(pair).unwrap(), 16).unwrap())
        .collect()
}

fn fixed_rip_target(address: u64, bytes: &[u8], displacement: usize, next: usize) -> Result<u64> {
    let offset = i32::from_le_bytes(
        bytes
            .get(displacement..displacement + 4)
            .ok_or("truncated Fixed operand")?
            .try_into()
            .unwrap(),
    );
    address
        .checked_add(next as u64)
        .and_then(|end| end.checked_add_signed(i64::from(offset)))
        .ok_or("Fixed operand address overflows".to_owned())
}

/// Full constant recipes with only independently bound address operands removed.
/// Register choices, field offsets, branches, lengths and all other bytes remain
/// exact. The caller classifies every removed operand; this is no wildcard mask.
fn fixed_whole_recipe(
    address: u64,
    bytes: &[u8],
    hex: &str,
    operands: &[(usize, usize, u64)],
) -> Result<()> {
    require(
        !bytes.is_empty() && address.checked_add(bytes.len() as u64).is_some(),
        "Fixed whole function address extent overflows or is empty",
    )?;
    let mut actual = bytes.to_vec();
    let mut expected = fixed_hex(hex);
    require(
        actual.len() == expected.len(),
        "unrecognized whole Fixed function extent",
    )?;
    let mut claimed = BTreeSet::new();
    for &(displacement, next, target) in operands {
        require(
            (displacement..displacement + 4).all(|offset| claimed.insert(offset)),
            "overlapping Fixed recipe operands",
        )?;
        require(
            fixed_rip_target(address, bytes, displacement, next)? == target,
            "Fixed recipe operand has the wrong actual target",
        )?;
        actual
            .get_mut(displacement..displacement + 4)
            .ok_or("Fixed recipe operand outside function")?
            .fill(0);
        expected
            .get_mut(displacement..displacement + 4)
            .ok_or("Fixed recipe constant operand outside function")?
            .fill(0);
    }
    require(
        actual == expected,
        "unrecognized whole Fixed operand/register/CFG recipe",
    )
}

/// Caller independently binds these operands to the actual same-ELF symbols
/// and readonly payload. The zero-size compiler global is an address marker,
/// not a claim that a zero-size object provides addressable storage. Its type
/// identity is established by all four shims reaching the exact Fixed methods.
#[derive(Clone, Copy)]
struct FixedCompilerShimOperands {
    layout_constructor: Option<u64>,
    allocator_zst: u64,
    layout_location: Option<u64>,
}

const FIXED_SHIM_ALLOC_DEV: &str = "4883ec1848897c24084889742410488d1583a31f00e8e6f6ffff4889c6488d3dd2b8efffff150e0623004883c418c3";
const FIXED_SHIM_DEALLOC_DEV: &str = "4883ec38488914244889f0488b342448894424084889f8488b7c24084889442410488944242048897c24284889742430488d1531a31f00e894f6ffff488b74241048894424184889d1488b542418488d3d71b8efffff15b50523004883c438c3";
const FIXED_SHIM_REALLOC_DEV: &str = "4883ec48488914244889f0488b342448894424084889f8488b7c2408488944241048894c2418488944242848897c2430488974243848894c2440488d15c7a21f00e82af6ffff488b7424104c8b44241848894424204889d1488b542420488d3d02b8efffff154e0523004883c448c3";
const FIXED_SHIM_ALLOC_RELEASE: &str = "4889fa488d3ddc1ffbffff25709e0b00";
const FIXED_SHIM_DEALLOC_RELEASE: &str = "4889f14889fe488d3dc91ffbffff25659e0b00";
const FIXED_SHIM_REALLOC_RELEASE: &str = "4989c84889f14889fe488d3da61ffbffff254a9e0b00";

/// Whole emitted Rust compiler-global shims, never a shortest-path test.
/// `got` must already bind unique local RELATIVE relocations in mapped RELRO.
/// The caller pairs the named shim with its exact corresponding typed Fixed
/// implementation; alloc/alloc_zeroed have identical ABI bytes and are not
/// distinguished by a made-up difference in their instruction shapes.
///
/// Debug shims call the exact Layout constructor, then the implementation.
/// The constructor must separately be proven to return (align in RAX, size in
/// RDX) for valid GlobalAlloc Layout arguments; merely naming it is inadequate.
/// Release shims forward those fields directly and have one tail transfer.
fn fixed_compiler_shim_recipe(
    shim: &str,
    address: u64,
    bytes: &[u8],
    implementation: u64,
    got: &BTreeMap<u64, u64>,
    operands: FixedCompilerShimOperands,
) -> Result<Vec<ConstructorTransfer>> {
    require(
        address.checked_add(bytes.len() as u64).is_some()
            && implementation != 0
            && operands.allocator_zst != 0,
        "Fixed compiler shim has absent/overflowing identity",
    )?;
    let dev = operands.layout_constructor.is_some();
    require(
        dev == operands.layout_location.is_some(),
        "Fixed compiler shim Layout/location mode mismatch",
    )?;
    let (template, marker, method, layout) = match (shim, dev) {
        ("__rust_alloc" | "__rust_alloc_zeroed", true) => {
            (FIXED_SHIM_ALLOC_DEV, 32, 38, Some((17, 22)))
        }
        ("__rust_dealloc", true) => (FIXED_SHIM_DEALLOC_DEV, 81, 87, Some((51, 56))),
        ("__rust_realloc", true) => (FIXED_SHIM_REALLOC_DEV, 96, 102, Some((61, 66))),
        ("__rust_alloc" | "__rust_alloc_zeroed", false) => (FIXED_SHIM_ALLOC_RELEASE, 6, 12, None),
        ("__rust_dealloc", false) => (FIXED_SHIM_DEALLOC_RELEASE, 9, 15, None),
        ("__rust_realloc", false) => (FIXED_SHIM_REALLOC_RELEASE, 12, 18, None),
        _ => return Err("unknown Fixed compiler shim role".into()),
    };
    let method_slot = fixed_rip_target(address, bytes, method, method + 4)?;
    require(
        got.get(&method_slot) == Some(&implementation),
        "Fixed compiler shim requires its exact local RELATIVE/RELRO operation",
    )?;
    let mut fields = vec![
        (marker, marker + 4, operands.allocator_zst),
        (method, method + 4, method_slot),
    ];
    let mut transfers = Vec::new();
    if let Some((location, call)) = layout {
        let target = operands
            .layout_constructor
            .ok_or("Fixed shim Layout missing")?;
        let payload = operands
            .layout_location
            .ok_or("Fixed shim caller location missing")?;
        require(
            target != 0 && payload != 0,
            "Fixed shim Layout/location is null",
        )?;
        fields.extend([(location, location + 4, payload), (call, call + 4, target)]);
        transfers.push(ConstructorTransfer {
            instruction: address
                .checked_add((call - 1) as u64)
                .ok_or("Fixed shim Layout call address overflow")?,
            target,
            local_got_slot: None,
        });
    }
    fixed_whole_recipe(address, bytes, template, &fields)?;
    transfers.push(ConstructorTransfer {
        instruction: address
            .checked_add((method - 2) as u64)
            .ok_or("Fixed shim method transfer address overflow")?,
        target: implementation,
        local_got_slot: Some(method_slot),
    });
    // All stack adjustments/spills and register moves are exact. Debug restores
    // RSP after its call; release neither changes the stack nor returns locally.
    // alloc: (size,align) -> self,align,size. dealloc: (ptr,size,align) ->
    // self,ptr,align,size. realloc additionally forwards new_size in R8.
    // No other call, conditional edge, return, payload access or fallback exists.
    Ok(transfers)
}

// Pure source snippet. Integration supplies BTreeMap, Result<T>, require, ConstructorTransfer.
// Whole-function physical ELF and canonical-role/object/GOT authentication are caller prerequisites.
// No input-derived golden hash, wildcard instruction, optional transfer or unknown layout is accepted.
#[derive(Clone, Copy)]
enum FixedArenaOperandKind {
    Object,
    DirectCall,
    GotCall,
}
#[derive(Clone, Copy)]
struct FixedArenaOperand {
    instruction: usize,
    displacement: usize,
    next: usize,
    key: &'static str,
    addend: u64,
    kind: FixedArenaOperandKind,
}
struct FixedArenaTemplate {
    role: &'static str,
    bytes: &'static [u8],
    operands: &'static [FixedArenaOperand],
}

// Retained dev / fixed_arena_setup; all constant operands and internal branches are literal.
