fn dev_fixed_heap_recipe(
    role: &str,
    address: u64,
    bytes: &[u8],
    targets: &BTreeMap<String, u64>,
    got: &BTreeMap<u64, u64>,
    readonly: &BTreeMap<u64, Vec<u8>>,
) -> Result<Vec<ConstructorTransfer>> {
    require(
        address != 0 && address.checked_add(bytes.len() as u64).is_some(),
        "invalid dev heap function extent",
    )?;
    let template = DEV_FIXED_HEAP_TEMPLATES
        .iter()
        .find(|t| t.role == role)
        .ok_or("unknown dev heap function role")?;
    let mut fields = Vec::new();
    let mut transfers = Vec::new();
    for op in template.operands {
        let expected = dev_fixed_heap_target(targets, op.key)?;
        let expected = expected
            .checked_add(op.addend)
            .ok_or("dev heap object addend overflow")?;
        let resolved = fixed_rip_target(address, bytes, op.displacement, op.next)?;
        match op.kind {
            0 => {
                dev_fixed_heap_readonly(
                    op.key,
                    dev_fixed_heap_target(targets, op.key)?,
                    targets,
                    readonly,
                )?;
                fields.push((op.displacement, op.next, expected));
            }
            1 => {
                fields.push((op.displacement, op.next, expected));
                transfers.push(ConstructorTransfer {
                    instruction: address
                        .checked_add(op.instruction as u64)
                        .ok_or("dev heap call PC overflow")?,
                    target: expected,
                    local_got_slot: None,
                });
            }
            2 => {
                require(
                    got.get(&resolved) == Some(&expected),
                    "dev heap call lacks exact executable local RELATIVE/RELRO target",
                )?;
                fields.push((op.displacement, op.next, resolved));
                transfers.push(ConstructorTransfer {
                    // For CALL RAX this is its real instruction, not the earlier GOT load.
                    instruction: address
                        .checked_add(op.instruction as u64)
                        .ok_or("dev heap register-call PC overflow")?,
                    target: expected,
                    local_got_slot: Some(resolved),
                });
            }
            _ => return Err("invalid constant dev heap operand kind".into()),
        }
    }
    // All branches/register assignments/constants, including each load-to-CALL RAX chain, are fixed.
    fixed_whole_recipe(address, bytes, template.hex, &fields)?;
    // Tables are tied to this exact function's authenticated entry, not a second arbitrary owner.
    if role == "fixed_heap_atomic_store_u8" || role == "fixed_heap_atomic_compare_u8" {
        require(
            dev_fixed_heap_target(targets, role)? == address,
            "dev heap switch owner identity mismatch",
        )?;
    }
    transfers.sort_by_key(|t| t.instruction);
    Ok(transfers)
}

#[derive(Clone, Debug, PartialEq, Eq, Serialize, Deserialize)]
#[serde(deny_unknown_fields)]
pub struct FixedReadonlyEvidence {
    pub address: u64,
    pub size: usize,
    pub sha256: String,
    pub file_address: Option<u64>,
    pub file_sha256: Option<String>,
    pub relative_pointer_slot: Option<u64>,
}
struct FixedReadonlySpec {
    key: &'static str,
    kind: &'static str,
    hex: &'static str,
    file_hex: &'static str,
    owner: &'static str,
    switch: &'static [usize],
}
struct FixedWrapperOperand {
    displacement: usize,
    next: usize,
    target: &'static str,
    got: bool,
    target_offset: u64,
}
struct FixedWrapperRecipe {
    role: &'static str,
    hex: &'static str,
    operands: &'static [FixedWrapperOperand],
    transfers: &'static [(usize, usize, &'static str, bool)],
}

// Authentication of data addresses is independent of instruction-template matching.
// Writable Location records must be wholly in RELRO. Their sole runtime write is
// the exact local RELATIVE filename pointer; it never enters executable GOT policy.
fn fixed_require_sane_loads(elf: &Elf<'_>, bytes: &[u8]) -> Result<()> {
    let mut pages = Vec::new();
    for p in elf
        .program_headers
        .iter()
        .filter(|p| p.p_type == program_header::PT_LOAD)
    {
        require(
            p.p_memsz != 0
                && p.p_filesz <= p.p_memsz
                && p.p_offset
                    .checked_add(p.p_filesz)
                    .is_some_and(|end| end <= bytes.len() as u64)
                && p.p_vaddr.checked_add(p.p_filesz).is_some()
                && p.p_vaddr
                    .checked_add(p.p_memsz)
                    .and_then(|end| end.checked_add(4095))
                    .is_some()
                && p.p_offset % 4096 == p.p_vaddr % 4096,
            "canonical loader contract refuses empty or malformed PT_LOAD bounds or page congruence",
        )?;
        pages.push((p.p_vaddr & !4095, (p.p_vaddr + p.p_memsz + 4095) & !4095));
    }
    pages.sort_unstable();
    require(
        !pages.is_empty() && pages.windows(2).all(|pair| pair[0].1 <= pair[1].0),
        "canonical loader contract refuses overlapping rounded PT_LOAD pages",
    )?;
    Ok(())
}
fn fixed_readonly_range<'a>(
    elf: &Elf<'_>,
    bytes: &'a [u8],
    address: u64,
    length: usize,
) -> Result<&'a [u8]> {
    let end = address
        .checked_add(length as u64)
        .ok_or("Fixed readonly extent overflow")?;
    require(length != 0, "empty Fixed readonly payload")?;
    fixed_require_sane_loads(elf, bytes)?;
    let page_start = address & !4095;
    let page_end = end
        .checked_add(4095)
        .ok_or("Fixed data page extent overflow")?
        & !4095;
    let segments: Vec<_> = elf
        .program_headers
        .iter()
        .filter(|p| p.p_type == program_header::PT_LOAD)
        .filter(|p| {
            let start = p.p_vaddr & !4095;
            p.p_vaddr
                .checked_add(p.p_memsz)
                .and_then(|e| e.checked_add(4095))
                .is_some_and(|e| start < page_end && (e & !4095) > page_start)
        })
        .collect();
    require(
        segments.len() == 1,
        "Fixed data has overlapping or absent actual page mappings",
    )?;
    let segment = segments[0];
    require(
        segment.p_flags & program_header::PF_R != 0
            && segment.p_flags & program_header::PF_X == 0
            && segment.p_offset % 4096 == segment.p_vaddr % 4096
            && address >= segment.p_vaddr
            && segment
                .p_vaddr
                .checked_add(segment.p_filesz)
                .is_some_and(|e| end <= e),
        "Fixed data mapping flags/file extent/page congruence differ",
    )?;
    if segment.p_flags & program_header::PF_W != 0 {
        let relros: Vec<_> = elf
            .program_headers
            .iter()
            .filter(|p| p.p_type == program_header::PT_GNU_RELRO)
            .collect();
        require(
            relros.len() == 1,
            "Fixed writable readonly data needs unique actual GNU_RELRO",
        )?;
        let relro = relros[0];
        let relro_end = relro
            .p_vaddr
            .checked_add(relro.p_memsz)
            .ok_or("Fixed GNU_RELRO extent overflow")?;
        require(
            relro.p_memsz != 0
                && relro.p_vaddr >= segment.p_vaddr
                && relro_end <= segment.p_vaddr + segment.p_memsz
                && address >= relro.p_vaddr
                && end <= (relro_end & !4095),
            "Fixed data is not wholly in the actual protected GNU_RELRO pages",
        )?;
    }
    let sections: Vec<_> = elf
        .section_headers
        .iter()
        .filter(|s| {
            s.sh_type == section_header::SHT_PROGBITS
                && s.sh_flags & u64::from(section_header::SHF_ALLOC) != 0
                && s.sh_flags & u64::from(section_header::SHF_EXECINSTR | section_header::SHF_TLS)
                    == 0
                && address >= s.sh_addr
                && s.sh_addr.checked_add(s.sh_size).is_some_and(|e| end <= e)
        })
        .collect();
    require(
        sections.len() == 1
            && segment.p_offset.checked_add(address - segment.p_vaddr)
                == sections[0]
                    .sh_offset
                    .checked_add(address - sections[0].sh_addr),
        "Fixed data section/load physical join differs",
    )?;
    loaded_bytes(elf, bytes, address, length)
}
fn fixed_no_data_relocation(
    elf: &Elf<'_>,
    address: u64,
    length: usize,
    permitted: Option<u64>,
) -> Result<()> {
    let end = address
        .checked_add(length as u64)
        .ok_or("Fixed data relocation extent overflow")?;
    for r in extent_writers(elf, address, length)? {
        let width = descriptor_relocation_width(elf, &r)?;
        let relocation_end = r
            .r_offset
            .checked_add(width)
            .ok_or("Fixed data relocation overflow")?;
        if width != 0 && r.r_offset < end && relocation_end > address {
            require(
                permitted == Some(r.r_offset)
                    && r.r_offset == address
                    && width == 8
                    && r.r_type == reloc::R_X86_64_RELATIVE
                    && r.r_sym == 0,
                "Fixed readonly payload has an unauthorized relocation writer",
            )?;
        }
    }
    Ok(())
}
#[cfg(test)]
fn fixed_bind_readonly(
    elf: &Elf<'_>,
    bytes: &[u8],
    spec: &FixedReadonlySpec,
    address: u64,
    targets: &mut BTreeMap<String, u64>,
    readonly: &mut BTreeMap<u64, Vec<u8>>,
    evidence: &mut BTreeMap<String, FixedReadonlyEvidence>,
) -> Result<()> {
    fixed_bind_readonly_in_source_context(
        (elf, bytes),
        spec,
        address,
        targets,
        readonly,
        evidence,
        None,
    )
}
fn fixed_bind_readonly_in_source_context(
    (elf, bytes): (&Elf<'_>, &[u8]),
    spec: &FixedReadonlySpec,
    address: u64,
    targets: &mut BTreeMap<String, u64>,
    readonly: &mut BTreeMap<u64, Vec<u8>>,
    evidence: &mut BTreeMap<String, FixedReadonlyEvidence>,
    sources: Option<&VerifiedCompiledSources>,
) -> Result<()> {
    if let Some(prior) = targets.get(spec.key) {
        require(
            *prior == address,
            "Fixed readonly key is used for conflicting actual operands",
        )?;
    }
    let mut expected = fixed_hex(spec.hex);
    let mut filename = fixed_hex(spec.file_hex);
    if spec.kind == "location" {
        require(expected.len() == 24, "Fixed Location is not 24 bytes")?;
        if let Some(sources) = sources {
            filename = sources.filename(&filename)?;
            expected[8..16].copy_from_slice(&(filename.len() as u64).to_le_bytes());
        }
    }
    let actual = fixed_readonly_range(elf, bytes, address, expected.len())?;
    let mut file_address = None;
    let mut file_sha256 = None;
    match spec.kind {
        "location" => {
            require(
                expected.len() == 24 && actual == expected && expected[..8] == [0; 8],
                "wrong complete Fixed source Location",
            )?;
            fixed_no_data_relocation(elf, address, 24, Some(address))?;
            let relocations: Vec<_> = elf
                .dynrelas
                .iter()
                .chain(elf.dynrels.iter())
                .chain(elf.pltrelocs.iter())
                .filter(|r| r.r_offset == address)
                .collect();
            require(
                relocations.len() == 1
                    && relocations[0].r_type == reloc::R_X86_64_RELATIVE
                    && relocations[0].r_sym == 0,
                "Fixed Location needs its unique local RELATIVE filename",
            )?;
            let addend = relocations[0]
                .r_addend
                .ok_or("Fixed Location relocation lacks explicit addend")?;
            let file = u64::try_from(addend).map_err(|e| e.to_string())?;
            require(
                u64::from_le_bytes(expected[8..16].try_into().unwrap()) == filename.len() as u64,
                "Fixed Location filename length differs",
            )?;
            let actual_file = fixed_readonly_range(elf, bytes, file, filename.len())?;
            require(
                actual_file == filename,
                "Fixed Location filename differs from exact source role",
            )?;
            fixed_no_data_relocation(elf, file, filename.len(), None)?;
            targets.insert(format!("{}_file", spec.key), file);
            fixed_insert_readonly(readonly, file, &filename)?;
            file_address = Some(file);
            file_sha256 = Some(sha256(&filename));
        }
        "switch" => {
            require(
                actual.len() == 20 && spec.switch.len() == 5,
                "Fixed switch must retain all five ordering entries",
            )?;
            let owner = *targets
                .get(spec.owner)
                .ok_or("Fixed switch lacks its typed owning function")?;
            for (word, &offset) in actual.as_chunks::<4>().0.iter().zip(spec.switch) {
                require(
                    address.checked_add_signed(i64::from(i32::from_le_bytes(*word)))
                        == owner.checked_add(offset as u64),
                    "Fixed switch redirects an internal ordering branch",
                )?;
            }
            fixed_no_data_relocation(elf, address, actual.len(), None)?;
        }
        "bytes" => {
            require(actual == expected, "wrong complete Fixed readonly constant")?;
            fixed_no_data_relocation(elf, address, actual.len(), None)?;
        }
        _ => return Err("unknown Fixed readonly data kind".into()),
    }
    fixed_insert_readonly(readonly, address, actual)?;
    targets.insert(spec.key.to_owned(), address);
    let record = FixedReadonlyEvidence {
        address,
        size: actual.len(),
        sha256: sha256(actual),
        file_address,
        file_sha256,
        relative_pointer_slot: (spec.kind == "location").then_some(address),
    };
    if let Some(prior) = evidence.insert(spec.key.to_owned(), record.clone()) {
        require(prior == record, "conflicting Fixed readonly evidence")?;
    }
    Ok(())
}
fn fixed_insert_readonly(
    readonly: &mut BTreeMap<u64, Vec<u8>>,
    address: u64,
    payload: &[u8],
) -> Result<()> {
    if let Some(prior) = readonly.get(&address) {
        let width = prior.len().min(payload.len());
        require(
            prior[..width] == payload[..width],
            "overlapping readonly operands disagree",
        )?;
        if prior.len() >= payload.len() {
            return Ok(());
        }
    }
    readonly.insert(address, payload.to_vec());
    Ok(())
}
fn fixed_template_shape(
    bytes: &[u8],
    template: &[u8],
    fields: impl Iterator<Item = usize>,
) -> bool {
    if bytes.len() != template.len() {
        return false;
    }
    let mut actual = bytes.to_vec();
    let mut expected = template.to_vec();
    let mut claimed = BTreeSet::new();
    for offset in fields {
        let Some(end) = offset.checked_add(4) else {
            return false;
        };
        if end > bytes.len() || !(offset..end).all(|i| claimed.insert(i)) {
            return false;
        }
        actual[offset..end].fill(0);
        expected[offset..end].fill(0);
    }
    actual == expected
}
#[cfg(test)]
fn fixed_bind_operand_data(
    elf: &Elf<'_>,
    bytes: &[u8],
    key: &str,
    address: u64,
    targets: &mut BTreeMap<String, u64>,
    readonly: &mut BTreeMap<u64, Vec<u8>>,
    evidence: &mut BTreeMap<String, FixedReadonlyEvidence>,
) -> Result<()> {
    fixed_bind_operand_data_in_source_context(
        (elf, bytes),
        key,
        address,
        targets,
        readonly,
        evidence,
        None,
    )
}
fn fixed_bind_operand_data_in_source_context(
    (elf, bytes): (&Elf<'_>, &[u8]),
    key: &str,
    address: u64,
    targets: &mut BTreeMap<String, u64>,
    readonly: &mut BTreeMap<u64, Vec<u8>>,
    evidence: &mut BTreeMap<String, FixedReadonlyEvidence>,
    sources: Option<&VerifiedCompiledSources>,
) -> Result<()> {
    let spec = FIXED_READONLY_SPECS
        .iter()
        .find(|spec| spec.key == key)
        .ok_or_else(|| format!("no finite Fixed readonly identity for {key}"))?;
    fixed_bind_readonly_in_source_context(
        (elf, bytes),
        spec,
        address,
        targets,
        readonly,
        evidence,
        sources,
    )
}
// A typed recipe may read an interior field of one complete readonly object.
// Recover its base before authenticating that object's unique physical identity.
fn fixed_readonly_operand_base(resolved: u64, addend: u64) -> Result<u64> {
    resolved
        .checked_sub(addend)
        .ok_or_else(|| "Fixed readonly operand precedes its typed object addend".into())
}
fn fixed_wrapper_recipe(
    role: &str,
    address: u64,
    bytes: &[u8],
    targets: &BTreeMap<String, u64>,
    got: &BTreeMap<u64, u64>,
    readonly: &BTreeMap<u64, Vec<u8>>,
) -> Result<Vec<ConstructorTransfer>> {
    let mut errors = Vec::new();
    for recipe in FIXED_WRAPPER_RECIPES
        .iter()
        .chain(PUBLICATION_WRAPPER_RECIPES)
        .filter(|r| {
            r.role == role
                && fixed_template_shape(
                    bytes,
                    &fixed_hex(r.hex),
                    r.operands.iter().map(|op| op.displacement),
                )
        })
    {
        let attempt = (|| -> Result<Vec<ConstructorTransfer>> {
            let mut fields = Vec::new();
            for op in recipe.operands {
                let expected = targets
                    .get(op.target)
                    .copied()
                    .ok_or_else(|| format!("unbound Fixed wrapper operand {}", op.target))?
                    .checked_add(op.target_offset)
                    .ok_or("Fixed wrapper object offset overflow")?;
                let resolved = fixed_rip_target(address, bytes, op.displacement, op.next)?;
                if op.got {
                    require(
                        got.get(&resolved) == Some(&expected),
                        "Fixed wrapper transfer lacks exact local RELATIVE/RELRO target",
                    )?;
                    fields.push((op.displacement, op.next, resolved));
                } else {
                    fields.push((op.displacement, op.next, expected));
                }
                if let Some(spec) = FIXED_READONLY_SPECS.iter().find(|s| s.key == op.target) {
                    require(
                        readonly
                            .get(&expected)
                            .is_some_and(|data| data.len() >= fixed_hex(spec.hex).len()),
                        "Fixed wrapper has no whole physical readonly payload",
                    )?;
                }
            }
            fixed_whole_recipe(address, bytes, recipe.hex, &fields)?;
            let mut transfers = Vec::new();
            for &(instruction, displacement, key, is_got) in recipe.transfers {
                let expected = *targets
                    .get(key)
                    .ok_or("Fixed wrapper callee identity missing")?;
                let op = recipe
                    .operands
                    .iter()
                    .find(|op| op.displacement == displacement)
                    .ok_or("Fixed wrapper transfer lacks its exact retained operand")?;
                let slot = is_got
                    .then(|| fixed_rip_target(address, bytes, displacement, op.next))
                    .transpose()?;
                transfers.push(ConstructorTransfer {
                    instruction: address
                        .checked_add(instruction as u64)
                        .ok_or("Fixed wrapper call PC overflow")?,
                    target: expected,
                    local_got_slot: slot,
                });
            }
            transfers.sort_by_key(|edge| edge.instruction);
            Ok(transfers)
        })();
        match attempt {
            Ok(v) => return Ok(v),
            Err(e) => errors.push(e),
        }
    }
    Err(format!(
        "unrecognized whole Fixed wrapper {role}: {}",
        errors.join("; ")
    ))
}

