fn fixed_private_role_code<'a>(
    role: &str,
    roles: &BTreeMap<String, sym::Sym>,
    code: &'a BTreeMap<u64, Vec<u8>>,
) -> Result<(u64, &'a [u8])> {
    let symbol = roles
        .get(role)
        .ok_or_else(|| format!("actual Fixed role {role} absent"))?;
    let bytes = code
        .get(&symbol.st_value)
        .ok_or_else(|| format!("whole actual Fixed role {role} bytes absent"))?;
    require(
        bytes.len() as u64 == symbol.st_size,
        "Fixed role interval/bytes differ",
    )?;
    Ok((symbol.st_value, bytes))
}

fn fixed_local_call_operand(
    address: u64,
    code: &[u8],
    displacement: usize,
    next: usize,
    target: u64,
    got: &BTreeMap<u64, u64>,
) -> Result<u64> {
    let slot = fixed_rip_target(address, code, displacement, next)?;
    require(
        got.get(&slot) == Some(&target),
        "Fixed helper lacks exact local RELATIVE/RELRO target",
    )?;
    Ok(slot)
}

fn fixed_tls_import(elf: &Elf<'_>, bytes: &[u8], plt: u64) -> Result<(usize, u64, String)> {
    let candidates: Vec<_> = elf
        .dynsyms
        .iter()
        .enumerate()
        .filter(|(_, symbol)| elf.dynstrtab.get_at(symbol.st_name) == Some("__tls_get_addr"))
        .collect();
    require(
        candidates.len() == 1,
        "actual unique TLS provider import absent/ambiguous",
    )?;
    let (index, symbol) = candidates[0];
    require(
        symbol.st_type() == sym::STT_FUNC
            && symbol.st_bind() == sym::STB_GLOBAL
            && symbol.st_visibility() == sym::STV_DEFAULT
            && symbol.st_shndx == section_header::SHN_UNDEF as usize,
        "TLS dependency is not the exact unresolved function import",
    )?;
    // Bind the version of this symbol, rather than any unrelated GLIBC need.
    let tables: Vec<_> = elf
        .section_headers
        .iter()
        .filter(|section| section.sh_type == 0x6fff_ffff)
        .collect();
    require(
        tables.len() == 1,
        "actual unique dynamic symbol-version table absent",
    )?;
    let table = loaded_bytes(
        elf,
        bytes,
        tables[0].sh_addr,
        usize::try_from(tables[0].sh_size).map_err(|e| e.to_string())?,
    )?;
    let version = u16::from_le_bytes(
        table
            .get(index * 2..index * 2 + 2)
            .ok_or("TLS import symbol version absent")?
            .try_into()
            .unwrap(),
    ) & 0x7fff;
    let mut providers = Vec::new();
    if let Some(needs) = &elf.verneed {
        for need in needs.iter() {
            for auxiliary in need.iter() {
                if auxiliary.vna_other & 0x7fff == version {
                    require(
                        elf.dynstrtab.get_at(auxiliary.vna_name) == Some("GLIBC_2.3"),
                        "TLS provider has an unrecognized symbol version",
                    )?;
                    providers.push(
                        elf.dynstrtab
                            .get_at(need.vn_file)
                            .ok_or("TLS provider library identity absent")?
                            .to_owned(),
                    );
                }
            }
        }
    }
    require(
        providers == ["ld-linux-x86-64.so.2"],
        "TLS provider version/library binding differs",
    )?;
    let stub = loaded_bytes(elf, bytes, plt, 16)?;
    require(
        stub[..2] == [0xff, 0x25] && stub[6] == 0x68 && stub[11] == 0xe9,
        "TLS transfer lacks the actual complete classic PLT entry",
    )?;
    require(
        elf.program_headers.iter().any(|segment| {
            segment.p_type == program_header::PT_LOAD
                && segment.p_flags & (program_header::PF_R | program_header::PF_X)
                    == program_header::PF_R | program_header::PF_X
                && segment.p_flags & program_header::PF_W == 0
                && plt >= segment.p_vaddr
                && plt
                    .checked_add(16)
                    .is_some_and(|end| end <= segment.p_vaddr.saturating_add(segment.p_filesz))
        }),
        "TLS PLT is not physical nonwritable executable code",
    )?;
    let slot = fixed_rip_target(plt, stub, 2, 6)?;
    let relocations: Vec<_> = elf
        .pltrelocs
        .iter()
        .enumerate()
        .filter(|(_, relocation)| relocation.r_offset == slot)
        .collect();
    require(
        relocations.len() == 1,
        "TLS PLT/GOT relocation absent/ambiguous",
    )?;
    let (ordinal, relocation) = relocations[0];
    require(
        relocation.r_type == reloc::R_X86_64_JUMP_SLOT
            && relocation.r_sym == index
            && relocation.r_addend == Some(0)
            && u32::from_le_bytes(stub[7..11].try_into().unwrap()) as usize == ordinal,
        "TLS PLT does not bind its exact dynamic import/ordinal",
    )?;
    require(
        elf.dynamic.as_ref().is_some_and(|dynamic| {
            dynamic.dyns.iter().any(|entry| {
                entry.d_tag == 24
                    || entry.d_tag == 30 && entry.d_val & 8 != 0
                    || entry.d_tag == 0x6fff_fffb && entry.d_val & 1 != 0
            })
        }),
        "TLS provider relocation is not eagerly bound",
    )?;
    // Reuse the same all-load/unique protected-page join as other immutable data.
    fixed_readonly_range(elf, bytes, slot, 8)?;
    let slot_end = slot
        .checked_add(8)
        .ok_or("TLS import slot extent overflow")?;
    let mut writers = Vec::new();
    for writer in elf
        .dynrelas
        .iter()
        .chain(elf.dynrels.iter())
        .chain(elf.pltrelocs.iter())
    {
        let width = descriptor_relocation_width(elf, &writer)?;
        let end = writer
            .r_offset
            .checked_add(width)
            .ok_or("TLS import writer overflow")?;
        if width != 0 && writer.r_offset < slot_end && slot < end {
            writers.push(writer);
        }
    }
    require(
        writers.len() == 1
            && writers[0].r_offset == slot
            && writers[0].r_type == reloc::R_X86_64_JUMP_SLOT
            && writers[0].r_sym == index
            && writers[0].r_addend == Some(0),
        "TLS import slot has an additional or conflicting relocation writer",
    )?;
    let plt_sections: Vec<_> = elf
        .section_headers
        .iter()
        .filter(|section| elf.shdr_strtab.get_at(section.sh_name) == Some(".plt"))
        .collect();
    require(
        plt_sections.len() == 1
            && plt_sections[0].sh_type == section_header::SHT_PROGBITS
            && plt_sections[0].sh_flags
                & u64::from(section_header::SHF_ALLOC | section_header::SHF_EXECINSTR)
                == u64::from(section_header::SHF_ALLOC | section_header::SHF_EXECINSTR)
            && plt_sections[0].sh_flags & u64::from(section_header::SHF_WRITE) == 0
            && plt_sections[0]
                .sh_addr
                .checked_add((ordinal as u64 + 1) * 16)
                == Some(plt)
            && fixed_rip_target(plt, stub, 12, 16)? == plt_sections[0].sh_addr,
        "TLS PLT fallback/entry position is not the exact image's PLT0",
    )?;
    // Eager binding makes the resolver push/JMP tail unreachable during a call;
    // retain and bind its whole bytes without treating PLT0 as a private role.
    Ok((index, slot, sha256(stub)))
}

fn fixed_tls_cell(elf: &Elf<'_>) -> Result<SymbolEvidence> {
    let candidates: Vec<_> = elf
        .syms
        .iter()
        .filter(|symbol| {
            elf.strtab
                .get_at(symbol.st_name)
                .and_then(canonical_rust_symbol)
                .is_some_and(|name| name == FIXED_TLS_CELL_ROLE)
        })
        .collect();
    require(
        candidates.len() == 1,
        "actual exact INSTALLATION_DEPTH TLS cell absent/ambiguous",
    )?;
    let symbol = candidates[0];
    let name = elf
        .strtab
        .get_at(symbol.st_name)
        .ok_or("TLS cell name absent")?;
    require(
        symbol.st_type() == sym::STT_TLS
            && symbol.st_bind() == sym::STB_LOCAL
            && symbol.st_size == 8
            && symbol.st_value % 8 == 0
            && !elf
                .dynsyms
                .iter()
                .any(|dynamic| elf.dynstrtab.get_at(dynamic.st_name) == Some(name)),
        "INSTALLATION_DEPTH is not an exact nonpreemptible scalar TLS cell",
    )?;
    let section = elf
        .section_headers
        .get(symbol.st_shndx)
        .ok_or("TLS cell section absent")?;
    require(
        section.sh_type == section_header::SHT_NOBITS
            && section.sh_flags
                & u64::from(
                    section_header::SHF_ALLOC | section_header::SHF_WRITE | section_header::SHF_TLS,
                )
                == u64::from(
                    section_header::SHF_ALLOC | section_header::SHF_WRITE | section_header::SHF_TLS,
                )
            && section.sh_flags & u64::from(section_header::SHF_EXECINSTR) == 0,
        "INSTALLATION_DEPTH is not the actual zero-initialized TLS cell",
    )?;
    let segments: Vec<_> = elf
        .program_headers
        .iter()
        .filter(|segment| segment.p_type == program_header::PT_TLS)
        .collect();
    require(
        segments.len() == 1
            && symbol.st_value >= segments[0].p_filesz
            && symbol
                .st_value
                .checked_add(8)
                .is_some_and(|end| end <= segments[0].p_memsz)
            && segments[0].p_align >= 8,
        "INSTALLATION_DEPTH does not join the exact image's TLS zero-fill span",
    )?;
    require(
        elf.syms.iter().all(|other| {
            other.st_type() != sym::STT_TLS
                || other.st_value == symbol.st_value && other.st_name == symbol.st_name
                || other.st_size == 0
                || other.st_value >= symbol.st_value + 8
                || other
                    .st_value
                    .checked_add(other.st_size)
                    .is_some_and(|end| end <= symbol.st_value)
        }),
        "INSTALLATION_DEPTH has an unbound overlapping TLS identity",
    )?;
    require(
        elf.dynsyms.iter().all(|other| {
            other.st_type() != sym::STT_TLS
                || other.st_shndx == section_header::SHN_UNDEF as usize
                || other.st_size == 0
                || other.st_value >= symbol.st_value + 8
                || other
                    .st_value
                    .checked_add(other.st_size)
                    .is_some_and(|end| end <= symbol.st_value)
        }),
        "INSTALLATION_DEPTH has a dynamic overlapping TLS identity",
    )?;
    Ok(symbol_evidence(name, &symbol))
}

fn fixed_tls_descriptor(elf: &Elf<'_>, bytes: &[u8], address: u64) -> Result<()> {
    let descriptor_end = address
        .checked_add(16)
        .ok_or("TLS descriptor range overflows")?;
    require(
        address.is_multiple_of(8) && fixed_readonly_range(elf, bytes, address, 16)? == [0; 16],
        "TLS module/offset descriptor has unexpected raw payload or protected mapping",
    )?;
    let mut records = Vec::new();
    for relocation in elf
        .dynrelas
        .iter()
        .chain(elf.dynrels.iter())
        .chain(elf.pltrelocs.iter())
    {
        let width = descriptor_relocation_width(elf, &relocation)?;
        let end = relocation
            .r_offset
            .checked_add(width)
            .ok_or("TLS relocation write overflows")?;
        if width != 0 && relocation.r_offset < descriptor_end && address < end {
            records.push(relocation);
        }
    }
    require(
        records.len() == 1
            && records[0].r_offset == address
            && records[0].r_type == reloc::R_X86_64_DTPMOD64
            && records[0].r_sym == 0
            && records[0].r_addend == Some(0),
        "TLS descriptor is not the exact current-image module and zero offset",
    )?;
    Ok(())
}

const FIXED_OPTIMIZED_PATCH_ALLOC_DIAGNOSTIC_HEX: &str = "";
const FIXED_OPTIMIZED_TLS_THUNK_HEX: &str = "50488d3de86c0a00e8e3050a00488d804800000059c3";
const FIXED_OPTIMIZED_TLS_THUNK_DIAGNOSTIC_HEX: &str =
    "50488d3da0960a00e8832f0a00488d808800000059c3";
const FIXED_DEV_TLS_CELL_GETTER_HEX: &str =
    "4883ec1848897c24084889742410488d3daba42100e8b6321e00488d80480000004883c418c3";
const FIXED_DEV_TLS_CELL_GETTER_EVENT_ARGUMENT_HEX: &str =
    "4883ec1848897c24084889742410488d3ddb4a2200e8a6d11e00488d80400000004883c418c3";
const FIXED_DEV_TLS_CELL_GETTER_DIAGNOSTIC_EVENT_ARGUMENT_HEX: &str =
    "4883ec1848897c24084889742410488d3d7bfc2200e8967f1f00488d80800000004883c418c3";
const FIXED_OPTIMIZED_PATCH_ALLOC_EVENT_ARGUMENT_HEX: &str = "";
const FIXED_OPTIMIZED_TLS_THUNK_EVENT_ARGUMENT_HEX: &str =
    "50488d3d907d0a00e8b3160a00488d804000000059c3";
const FIXED_OPTIMIZED_PATCH_ALLOC_DIAGNOSTIC_EVENT_ARGUMENT_HEX: &str = "";
const FIXED_OPTIMIZED_TLS_THUNK_DIAGNOSTIC_EVENT_ARGUMENT_HEX: &str =
    "50488d3da0980a00e893310a00488d808000000059c3";
// Only eleven whole observed cell-access recipes are accepted. The caller must
// authenticate STT_TLS/zero-fill/module identity with fixed_tls_cell and the
// descriptor/provider joins; a synthetic SymbolEvidence is not ELF admission.
fn fixed_tls_cell_access_recipe(
    role: &str,
    address: u64,
    bytes: &[u8],
    cell: &SymbolEvidence,
    operands: &[(usize, usize, u64)],
) -> Result<()> {
    require(
        cell.binding == sym::STB_LOCAL
            && cell.size == 8
            && canonical_rust_symbol(&cell.name).as_deref() == Some(FIXED_TLS_CELL_ROLE),
        "TLS read lacks its exact authenticated INSTALLATION_DEPTH source identity",
    )?;
    let (hex, displacement, fields): (&str, usize, &[(usize, usize)]) = match (role, cell.address) {
        ("fixed_patch_alloc", 0x48) => (
            FIXED_OPTIMIZED_PATCH_ALLOC_HEX,
            0x34,
            &[(0x10, 0x14), (0x28, 0x2c), (0x2d, 0x31), (0xb6, 0xba)],
        ),
        ("fixed_patch_alloc", 0x88) => (
            FIXED_OPTIMIZED_PATCH_ALLOC_DIAGNOSTIC_HEX,
            0x34,
            &[(0x10, 0x14), (0x28, 0x2c), (0x2d, 0x31), (0xb6, 0xba)],
        ),
        ("fixed_tls_fn_once", 0x48) => (FIXED_OPTIMIZED_TLS_THUNK_HEX, 16, &[(4, 8), (9, 13)]),
        ("fixed_tls_fn_once", 0x88) => (
            FIXED_OPTIMIZED_TLS_THUNK_DIAGNOSTIC_HEX,
            16,
            &[(4, 8), (9, 13)],
        ),
        ("fixed_tls_cell_getter", 0x48) => {
            (FIXED_DEV_TLS_CELL_GETTER_HEX, 29, &[(17, 21), (22, 26)])
        }
        ("fixed_tls_cell_getter", 0x40) => (
            FIXED_DEV_TLS_CELL_GETTER_EVENT_ARGUMENT_HEX,
            29,
            &[(17, 21), (22, 26)],
        ),
        ("fixed_tls_cell_getter", 0x80) => (
            FIXED_DEV_TLS_CELL_GETTER_DIAGNOSTIC_EVENT_ARGUMENT_HEX,
            29,
            &[(17, 21), (22, 26)],
        ),
        ("fixed_patch_alloc", 64) => (
            FIXED_OPTIMIZED_PATCH_ALLOC_EVENT_ARGUMENT_HEX,
            52,
            &[(16, 20), (40, 44), (45, 49), (182, 186)],
        ),
        ("fixed_tls_fn_once", 64) => (
            FIXED_OPTIMIZED_TLS_THUNK_EVENT_ARGUMENT_HEX,
            16,
            &[(4, 8), (9, 13)],
        ),
        ("fixed_patch_alloc", 128) => (
            FIXED_OPTIMIZED_PATCH_ALLOC_DIAGNOSTIC_EVENT_ARGUMENT_HEX,
            52,
            &[(16, 20), (40, 44), (45, 49), (182, 186)],
        ),
        ("fixed_tls_fn_once", 128) => (
            FIXED_OPTIMIZED_TLS_THUNK_DIAGNOSTIC_EVENT_ARGUMENT_HEX,
            16,
            &[(4, 8), (9, 13)],
        ),
        _ => return Err("unsupported whole TLS read role/cell-offset pair".into()),
    };
    require(
        operands
            .iter()
            .map(|&(offset, next, _)| (offset, next))
            .eq(fields.iter().copied()),
        "TLS recipe adds/omits an address field or masks the cell offset",
    )?;
    let encoded = u32::from_le_bytes(
        bytes
            .get(displacement..displacement + 4)
            .ok_or("complete TLS cell access is truncated")?
            .try_into()
            .unwrap(),
    );
    require(
        u64::from(encoded) == cell.address,
        "actual TLS read displacement differs from its authenticated cell",
    )?;
    fixed_whole_recipe(address, bytes, hex, operands)
}

struct DirectTlsGetterCensus {
    mappings: Vec<TlsExecutableMapping>,
    raw_names_sha256: String,
    loader_writer_count: usize,
    loader_writers_sha256: String,
    named_getters: Vec<u64>,
    recipe_getters: Vec<u64>,
    getter_pointer_slots: Vec<u64>,
}

// This low-level census grants no admission. Its production caller first
// authenticates loader metadata and actual VerifiedCompiledSources. Tests can
// exercise physical bytes/names independently without fabricating that type.
fn direct_tls_getter_census(
    elf: &Elf<'_>,
    bytes: &[u8],
    cell: &SymbolEvidence,
    module: u64,
    plt: u64,
) -> Result<DirectTlsGetterCensus> {
    let mut raw_names = Vec::new();
    let mut named_getters = BTreeSet::new();
    for (dynamic, symbols, strings) in [
        (false, &elf.syms, &elf.strtab),
        (true, &elf.dynsyms, &elf.dynstrtab),
    ] {
        for symbol in symbols.iter() {
            let name = strings
                .get_at(symbol.st_name)
                .ok_or("raw TLS census symbol name is malformed")?;
            raw_names.push((
                dynamic,
                name,
                symbol.st_info,
                symbol.st_other,
                symbol.st_shndx,
                symbol.st_value,
                symbol.st_size,
            ));
            if !name.contains("INSTALLATION_DEPTH") {
                continue;
            }
            // Inspect the raw name BEFORE callable type/size/mapping filters.
            // An actual scalar TLS cell is not a callable identity.
            if canonical_rust_symbol(name).as_deref() == Some(FIXED_TLS_CELL_ROLE) {
                require(
                    !dynamic
                        && symbol.st_type() == sym::STT_TLS
                        && symbol.st_bind() == sym::STB_LOCAL
                        && symbol.st_value == cell.address
                        && symbol.st_size == cell.size,
                    "raw INSTALLATION_DEPTH cell identity differs",
                )?;
                continue;
            }
            require(
                !dynamic
                    && fixed_emitted_role(name) == Some("fixed_tls_fn_once")
                    && symbol.st_type() == sym::STT_FUNC
                    && symbol.st_bind() == sym::STB_LOCAL
                    && symbol.st_size == 22
                    && symbol.st_value != 0,
                "raw INSTALLATION_DEPTH getter is unknown, dynamic or malformed",
            )?;
            let (mapping, offset) = unique_file_mapping(elf, bytes, symbol.st_value, 22)?;
            require(
                mapping.p_flags == program_header::PF_R | program_header::PF_X,
                "raw INSTALLATION_DEPTH getter is not file-backed RX",
            )?;
            fixed_tls_cell_access_recipe(
                "fixed_tls_fn_once",
                symbol.st_value,
                &bytes[offset..offset + 22],
                cell,
                &[(4, 8, module), (9, 13, plt)],
            )?;
            require(
                named_getters.insert(symbol.st_value),
                "duplicate raw INSTALLATION_DEPTH getter",
            )?;
        }
    }
    let writers = loader_writers(elf)?;
    let mut mappings = Vec::new();
    let mut recipe_getters = BTreeSet::new();
    for (index, segment) in elf.program_headers.iter().enumerate() {
        if segment.p_type != program_header::PT_LOAD || segment.p_flags & program_header::PF_X == 0
        {
            continue;
        }
        let offset = loader_meta_usize(segment.p_offset)?;
        let length = loader_meta_usize(segment.p_filesz)?;
        let code = loader_meta_slice(bytes, offset, length)?;
        let end = segment
            .p_vaddr
            .checked_add(segment.p_filesz)
            .ok_or("TLS census executable mapping overflows")?;
        require(
            segment.p_flags == program_header::PF_R | program_header::PF_X
                && segment.p_filesz != 0
                && segment.p_memsz >= segment.p_filesz
                && writers
                    .iter()
                    .all(|w| w.relocation.r_offset >= end || w.end <= segment.p_vaddr),
            "TLS census mapping is malformed, writable or loader-modified",
        )?;
        mappings.push(TlsExecutableMapping {
            program_header_index: index,
            file_offset: segment.p_offset,
            virtual_address: segment.p_vaddr,
            file_size: segment.p_filesz,
            memory_size: segment.p_memsz,
            flags: segment.p_flags,
            sha256: sha256(code),
        });
        // Every byte start of each physical file-backed executable PT_LOAD,
        // including unnamed code and bytes absent from executable sections.
        for (start, candidate) in code.windows(22).enumerate() {
            if candidate[..4] != [0x50, 0x48, 0x8d, 0x3d]
                || candidate[8] != 0xe8
                || candidate[13..16] != [0x48, 0x8d, 0x80]
                || candidate[20..] != [0x59, 0xc3]
                || u64::from(u32::from_le_bytes(candidate[16..20].try_into().unwrap()))
                    != cell.address
            {
                continue;
            }
            let address = segment
                .p_vaddr
                .checked_add(start as u64)
                .ok_or("TLS census recipe address overflows")?;
            fixed_tls_cell_access_recipe(
                "fixed_tls_fn_once",
                address,
                candidate,
                cell,
                &[(4, 8, module), (9, 13, plt)],
            )?;
            recipe_getters.insert(address);
        }
    }
    require(
        !mappings.is_empty(),
        "TLS census has no executable PT_LOAD mapping",
    )?;
    let getters: BTreeSet<_> = named_getters.union(&recipe_getters).copied().collect();
    let mut getter_pointer_slots = BTreeSet::new();
    let mut raw_writers = Vec::new();
    for writer in &writers {
        let r = &writer.relocation;
        let width = loader_meta_usize(writer.end - r.r_offset)?;
        let (_, offset) = unique_file_mapping(elf, bytes, r.r_offset, width)?;
        let raw = loader_meta_slice(bytes, offset, width)?;
        let mut targets = Vec::new();
        for word in raw.as_chunks::<8>().0 {
            targets.push(u64::from_le_bytes(*word));
        }
        if let Some(target) = r.r_addend.and_then(|addend| u64::try_from(addend).ok()) {
            targets.push(target);
        }
        if r.r_sym != 0 {
            let symbol = elf
                .dynsyms
                .get(r.r_sym)
                .ok_or("TLS census relocation symbol absent")?;
            if symbol.st_shndx != section_header::SHN_UNDEF as usize {
                let addend = r
                    .r_addend
                    .unwrap_or_else(|| targets.first().copied().unwrap_or(0) as i64);
                targets.push(
                    symbol
                        .st_value
                        .checked_add_signed(addend)
                        .ok_or("TLS census symbol pointer overflows")?,
                );
            }
        }
        for target in &targets {
            if getters
                .iter()
                .any(|&getter| getter <= *target && *target < getter.saturating_add(22))
            {
                getter_pointer_slots.insert(r.r_offset);
            }
        }
        raw_writers.push((
            r.r_offset,
            writer.end,
            r.r_type,
            r.r_sym,
            r.r_addend,
            sha256(raw),
            targets,
        ));
    }
    Ok(DirectTlsGetterCensus {
        mappings,
        raw_names_sha256: sha256(&serde_json::to_vec(&raw_names).map_err(|e| e.to_string())?),
        loader_writer_count: writers.len(),
        loader_writers_sha256: sha256(
            &serde_json::to_vec(&raw_writers).map_err(|e| e.to_string())?,
        ),
        named_getters: named_getters.into_iter().collect(),
        recipe_getters: recipe_getters.into_iter().collect(),
        getter_pointer_slots: getter_pointer_slots.into_iter().collect(),
    })
}

fn direct_tls_source_context(
    sources: Option<&VerifiedCompiledSources>,
) -> Result<&VerifiedCompiledSources> {
    let sources = sources
        .ok_or("direct allocation TLS proof requires independently verified compiled sources")?;
    sources.require_image(STANDALONE_ROOT)?;
    Ok(sources)
}

fn derive_direct_allocation_tls_evidence(
    elf: &Elf<'_>,
    bytes: &[u8],
    cell: &SymbolEvidence,
    module: u64,
    plt: u64,
    allocation_bytes: &[u8],
    sources: Option<&VerifiedCompiledSources>,
) -> Result<DirectAllocationTlsEvidence> {
    let sources = direct_tls_source_context(sources)?;
    authenticate_loader_metadata(elf, bytes)?;
    let census = direct_tls_getter_census(elf, bytes, cell, module, plt)?;
    require(
        census.named_getters.is_empty()
            && census.recipe_getters.is_empty()
            && census.getter_pointer_slots.is_empty(),
        "direct allocation TLS proof found a getter or raw loader pointer edge",
    )?;
    Ok(DirectAllocationTlsEvidence {
        version: 1,
        policy: DIRECT_TLS_CENSUS_POLICY.into(),
        elf_sha256: sha256(bytes),
        compiled_sources_sha256: sha256(
            &serde_json::to_vec(sources.record()).map_err(|e| e.to_string())?,
        ),
        reverie_pin: sources.record().reverie_pin.clone(),
        allocation_sha256: sha256(allocation_bytes),
        mappings: census.mappings,
        static_symbol_count: elf.syms.len(),
        dynamic_symbol_count: elf.dynsyms.len(),
        raw_names_sha256: census.raw_names_sha256,
        loader_writer_count: census.loader_writer_count,
        loader_writers_sha256: census.loader_writers_sha256,
        named_getters: census.named_getters,
        recipe_getters: census.recipe_getters,
        getter_pointer_slots: census.getter_pointer_slots,
    })
}

fn validate_direct_allocation_tls_evidence(
    tls: &AllocatorTlsBoundary,
    proof: &DirectAllocationTlsEvidence,
) -> Result<()> {
    let hash =
        |s: &str, length: usize| s.len() == length && s.bytes().all(|b| b.is_ascii_hexdigit());
    let allocation = tls
        .local_chain
        .get("fixed_patch_alloc")
        .ok_or("direct TLS allocation role absent")?;
    require(
        proof.version == 1
            && proof.policy == DIRECT_TLS_CENSUS_POLICY
            && [
                proof.elf_sha256.as_str(),
                proof.compiled_sources_sha256.as_str(),
                proof.raw_names_sha256.as_str(),
                proof.loader_writers_sha256.as_str(),
                proof.allocation_sha256.as_str(),
            ]
            .iter()
            .all(|h| hash(h, 64))
            && hash(&proof.reverie_pin, 40)
            && proof.static_symbol_count != 0
            && !proof.mappings.is_empty()
            && proof.mappings.iter().all(|m| {
                m.flags == program_header::PF_R | program_header::PF_X
                    && m.file_size != 0
                    && m.memory_size >= m.file_size
                    && m.file_offset.checked_add(m.file_size).is_some()
                    && m.virtual_address.checked_add(m.memory_size).is_some()
                    && hash(&m.sha256, 64)
            })
            && proof
                .mappings
                .windows(2)
                .all(|w| w[0].program_header_index < w[1].program_header_index)
            && proof.named_getters.is_empty()
            && proof.recipe_getters.is_empty()
            && proof.getter_pointer_slots.is_empty()
            && matches!(tls.tls_cell.address, 0x40 | 0x80)
            && allocation.size == 186
            && fixed_emitted_role(&allocation.name) == Some("fixed_patch_alloc")
            && tls
                .local_chain
                .keys()
                .map(String::as_str)
                .collect::<BTreeSet<_>>()
                == BTreeSet::from(["fixed_patch_alloc"])
            && tls.function_sha256.get("fixed_patch_alloc") == Some(&proof.allocation_sha256)
            && tls.callsites
                == [ConstructorTransfer {
                    instruction: allocation
                        .address
                        .checked_add(0x2c)
                        .ok_or("direct TLS callsite overflows")?,
                    target: tls.plt_address,
                    local_got_slot: None,
                }]
            && tls.local_key_object.is_none()
            && tls.local_key_transfer.is_none()
            && tls.local_key_resolution.is_none(),
        "direct allocation TLS provenance/recipe/census is incomplete or inconsistent",
    )
}

fn qualify_allocator_tls_boundary_in_source_context(
    elf: &Elf<'_>,
    bytes: &[u8],
    code: &BTreeMap<u64, Vec<u8>>,
    _disassembly: &str,
    got: &BTreeMap<u64, u64>,
    image_kind: FixedImageKind,
    sources: Option<&VerifiedCompiledSources>,
) -> Result<AllocatorTlsBoundary> {
    let roles = fixed_role_symbols(elf)?;
    let cell = fixed_tls_cell(elf)?;
    let mut chain = BTreeMap::new();
    let mut hashes = BTreeMap::new();
    let mut bind = |role: &str| -> Result<(u64, &[u8])> {
        let (address, instructions) = fixed_private_role_code(role, &roles, code)?;
        let symbol = &roles[role];
        chain.insert(
            role.to_owned(),
            symbol_evidence(elf.strtab.get_at(symbol.st_name).unwrap(), symbol),
        );
        hashes.insert(role.to_owned(), sha256(instructions));
        Ok((address, instructions))
    };
    let (allocation, allocation_bytes) = bind("fixed_patch_alloc")?;
    let mut callsites = Vec::new();
    let (plt, module, local_key_object, local_key_transfer) = if image_kind
        == FixedImageKind::Detcore
    {
        require(
            allocation_bytes.len() == 241
                && matches!(cell.address, 0x98 | 0xa0 | 0xd8 | 0xe0 | 0x128),
            format!(
                "Detcore validate allocation/TLS shape differs: allocation length {}, cell offset {:#x}",
                allocation_bytes.len(),
                cell.address
            ),
        )?;
        let module = fixed_rip_target(allocation, allocation_bytes, 54, 58)?;
        let plt = fixed_rip_target(allocation, allocation_bytes, 59, 63)?;
        let encoded = u32::from_le_bytes(allocation_bytes[66..70].try_into().unwrap());
        require(
            u64::from(encoded) == cell.address,
            "Detcore allocation reads another TLS cell",
        )?;
        callsites.push(ConstructorTransfer {
            instruction: allocation + 58,
            target: plt,
            local_got_slot: None,
        });
        let (function, function_bytes) = bind("fixed_tls_fn_once")?;
        require(
            function_bytes.len() == 22,
            "Detcore FnOnce whole extent differs",
        )?;
        let encoded = u32::from_le_bytes(function_bytes[16..20].try_into().unwrap());
        require(
            u64::from(encoded) == cell.address,
            "Detcore FnOnce reads another TLS cell",
        )?;
        let template = DETCORE_VALIDATE_TEMPLATES
            .iter()
            .filter(|t| {
                t.role == "fixed_tls_fn_once"
                    && fixed_template_shape(
                        function_bytes,
                        &fixed_hex(t.hex),
                        t.operands.iter().map(|op| op.displacement),
                    )
            })
            .collect::<Vec<_>>();
        require(
            template.len() == 1,
            "Detcore FnOnce unrecognized full template",
        )?;
        fixed_whole_recipe(
            function,
            function_bytes,
            template[0].hex,
            &[(4, 8, module), (9, 13, plt)],
        )?;
        callsites.push(ConstructorTransfer {
            instruction: function + 8,
            target: plt,
            local_got_slot: None,
        });
        (plt, module, None, None)
    } else if allocation_bytes.len() == 186 {
        // The real optimized alloc preserves ready backing in R12 and its
        // cursor in R15 before the actual TLS query. RAX from the query is the
        // module base; its finite exact displacement must equal the authenticated
        // actual TLS cell (retained0x48/0x88 or observed0x40/0x80). No imported allocator/copy.
        let module = fixed_rip_target(allocation, allocation_bytes, 0x28, 0x2c)?;
        let plt = fixed_rip_target(allocation, allocation_bytes, 0x2d, 0x31)?;
        let backing = fixed_local_call_operand(
            allocation,
            allocation_bytes,
            0x10,
            0x14,
            roles["fixed_arena_backing"].st_value,
            got,
        )?;
        let reusable = fixed_local_call_operand(
            allocation,
            allocation_bytes,
            0xb6,
            0xba,
            roles["fixed_tool_alloc"].st_value,
            got,
        )?;
        fixed_tls_cell_access_recipe(
            "fixed_patch_alloc",
            allocation,
            allocation_bytes,
            &cell,
            &[
                (0x10, 0x14, backing),
                (0x28, 0x2c, module),
                (0x2d, 0x31, plt),
                (0xb6, 0xba, reusable),
            ],
        )?;
        callsites.push(ConstructorTransfer {
            instruction: allocation + 0x2c,
            target: plt,
            local_got_slot: None,
        });
        // The retained typed LocalKey thunk is also selected when present;
        // its complete function observes the same module and actual offset.
        if roles.contains_key("fixed_tls_fn_once") {
            let (address, instructions) = bind("fixed_tls_fn_once")?;
            fixed_tls_cell_access_recipe(
                "fixed_tls_fn_once",
                address,
                instructions,
                &cell,
                &[(4, 8, module), (9, 13, plt)],
            )?;
            callsites.push(ConstructorTransfer {
                instruction: address + 8,
                target: plt,
                local_got_slot: None,
            });
        }
        (plt, module, None, None)
    } else {
        require(
            allocation_bytes.len() == 177,
            "Fixed allocation has no recognized dev/optimized TLS recipe",
        )?;
        let (active, active_bytes) = bind("fixed_installation_active")?;
        let key = fixed_rip_target(active, active_bytes, 4, 8)?;
        let get_slot = fixed_local_call_operand(
            active,
            active_bytes,
            10,
            14,
            roles["fixed_tls_get"].st_value,
            got,
        )?;
        fixed_whole_recipe(
            active,
            active_bytes,
            "50488d3d18b71d00ff150a1c21004883f8000f95c0240159c3",
            &[(4, 8, key), (10, 14, get_slot)],
        )?;
        let fn_once = roles
            .get("fixed_tls_fn_once")
            .ok_or("actual dev TLS FnOnce role absent")?
            .st_value;
        require(
            got.get(&key) == Some(&fn_once),
            "dev LocalKey object is not an immutable RELATIVE pointer to its exact typed getter",
        )?;
        let (getter, getter_bytes) = bind("fixed_tls_cell_getter")?;
        let module = fixed_rip_target(getter, getter_bytes, 17, 21)?;
        let plt = fixed_rip_target(getter, getter_bytes, 22, 26)?;
        fixed_tls_cell_access_recipe(
            "fixed_tls_cell_getter",
            getter,
            getter_bytes,
            &cell,
            &[(17, 21, module), (22, 26, plt)],
        )?;
        callsites.push(ConstructorTransfer {
            instruction: getter + 21,
            target: plt,
            local_got_slot: None,
        });
        let (function, function_bytes) = bind("fixed_tls_fn_once")?;
        fixed_whole_recipe(
            function,
            function_bytes,
            "4883ec1848897c2410488b742410488d7c240fe8a802000048890424488b04244883c418c3",
            &[(20, 24, getter)],
        )?;
        let (get, get_bytes) = bind("fixed_tls_get")?;
        let get_to_with =
            fixed_local_call_operand(get, get_bytes, 7, 11, roles["fixed_tls_with"].st_value, got)?;
        fixed_whole_recipe(
            get,
            get_bytes,
            "5048893c24ff15cd631a0059c3",
            &[(7, 11, get_to_with)],
        )?;
        let (with, with_bytes) = bind("fixed_tls_with")?;
        let with_to_try = fixed_local_call_operand(
            with,
            with_bytes,
            11,
            15,
            roles["fixed_tls_try_with"].st_value,
            got,
        )?;
        let refusal = fixed_local_call_operand(
            with,
            with_bytes,
            43,
            47,
            roles["fixed_tls_access_refusal"].st_value,
            got,
        )?;
        let refusal_data = fixed_rip_target(with, with_bytes, 37, 41)?;
        // The branch is retained literally. The supplied getter's return is
        // exactly TLS module base + this existing cell offset; only a provider
        // satisfying the named TLS ABI premise makes the successful path live.
        fixed_whole_recipe(
            with,
            with_bytes,
            "4883ec2848897c2410ff15d16d1a0048890424488954240848f7042401000000740d488d3db7231700ff1501371a00488b44240848894424204883c428c3",
            &[
                (11, 15, with_to_try),
                (37, 41, refusal_data),
                (43, 47, refusal),
            ],
        )?;
        // This is source-location data for a retained unreachable refusal,
        // not an expected backing or an admitted external provider.
        loaded_bytes(elf, bytes, refusal_data, 24)?;
        let (try_with, try_bytes) = bind("fixed_tls_try_with")?;
        let callback = fixed_local_call_operand(
            try_with,
            try_bytes,
            0x65,
            0x69,
            roles["fixed_tls_cell_callback"].st_value,
            got,
        )?;
        fixed_whole_recipe(
            try_with,
            try_bytes,
            FIXED_DEV_TLS_TRY_WITH_HEX,
            &[(0x65, 0x69, callback)],
        )?;
        // Entire exact prefix retains the incoming immutable LocalKey in RAX,
        // supplies the None argument, and calls precisely *(RAX). This edge is
        // qualified by the bound readonly LocalKey object, not a register-call
        // allowlist. No body/function pointer from the guest earns this role.
        let transfer = ConstructorTransfer {
            instruction: try_with + 0x15,
            target: fn_once,
            local_got_slot: None,
        };
        let (callback_address, callback_bytes) = bind("fixed_tls_cell_callback")?;
        // Missing or unrecognized emission must refuse, not panic on indexing.
        let (read, read_bytes) = bind("fixed_tls_cell_read")?;
        let read_slot =
            fixed_local_call_operand(callback_address, callback_bytes, 16, 20, read, got)?;
        fixed_whole_recipe(
            callback_address,
            callback_bytes,
            "4883ec1848897c2408488b7c2408ff15c48219004883c418c3",
            &[(16, 20, read_slot)],
        )?;
        fixed_whole_recipe(read, read_bytes, "48897c24f8488b07c3", &[])?;
        (plt, module, Some(key), Some(transfer))
    };
    fixed_tls_descriptor(elf, bytes, module)?;
    let (dynamic_symbol_index, got_slot, plt_sha256) = fixed_tls_import(elf, bytes, plt)?;
    let direct_allocation = if image_kind == FixedImageKind::Standalone
        && matches!(cell.address, 0x40 | 0x80)
        && allocation_bytes.len() == 186
        && !roles.contains_key("fixed_tls_fn_once")
    {
        Some(derive_direct_allocation_tls_evidence(
            elf,
            bytes,
            &cell,
            module,
            plt,
            allocation_bytes,
            sources,
        )?)
    } else {
        None
    };
    Ok(AllocatorTlsBoundary {
        dependency: "existing_installation_depth_tls".to_owned(),
        provider_symbol: "__tls_get_addr".to_owned(),
        provider_version: "GLIBC_2.3".to_owned(),
        provider_library: "ld-linux-x86-64.so.2".to_owned(),
        plt_address: plt,
        got_slot,
        dynamic_symbol_index,
        tls_cell: cell,
        tls_module_slot: module,
        tls_offset_slot: module.checked_add(8).ok_or("TLS offset slot overflows")?,
        callsites,
        local_key_object,
        local_key_resolution: local_key_object
            .map(|_| "local_relative_readonly_function_pointer".to_owned()),
        local_key_transfer,
        unisolated: true,
        plt_sha256,
        function_sha256: hashes,
        local_chain: chain,
        direct_allocation,
    })
}

const FIXED_DEV_TLS_TRY_WITH_HEX: &str = "";

const FIXED_OPTIMIZED_PATCH_ALLOC_HEX: &str = "";

fn fixed_emitted_role(name: &str) -> Option<&'static str> {
    let canonical = canonical_rust_symbol(name)?;
    FIXED_EMITTED_ROLE_SYMBOLS
        .iter()
        .chain(FIXED_OPERATION_ROLE_SYMBOLS)
        .chain(FIXED_SUPPORT_ROLE_SYMBOLS)
        .chain(PUBLICATION_ROLE_SYMBOLS)
        .chain(DETCORE_VALIDATE_ROLE_SYMBOLS)
        .find_map(|&(role, observed)| (canonical == observed).then_some(role))
}

fn fixed_role_symbols(elf: &Elf<'_>) -> Result<BTreeMap<String, sym::Sym>> {
    require(
        !FIXED_EMITTED_ROLE_SYMBOLS.is_empty(),
        "fixed allocator/setup emitted-role census is pending actual release/dev ELF evidence",
    )?;
    let mut result = BTreeMap::new();
    for symbol in elf
        .syms
        .iter()
        .filter(|symbol| executable_symbol(elf, symbol))
    {
        let Some(name) = elf.strtab.get_at(symbol.st_name) else {
            continue;
        };
        let Some(canonical) = canonical_rust_symbol(name) else {
            continue;
        };
        let aliases: BTreeSet<_> = FIXED_EMITTED_ROLE_SYMBOLS
            .iter()
            .chain(FIXED_OPERATION_ROLE_SYMBOLS)
            .chain(FIXED_SUPPORT_ROLE_SYMBOLS)
            .chain(PUBLICATION_ROLE_SYMBOLS)
            .chain(DETCORE_VALIDATE_ROLE_SYMBOLS)
            .filter_map(|&(role, observed)| (canonical == observed).then_some(role))
            .collect();
        if aliases.is_empty() {
            continue;
        }
        require(
            symbol.st_bind() == sym::STB_LOCAL
                && !elf
                    .dynsyms
                    .iter()
                    .any(|dynamic| elf.dynstrtab.get_at(dynamic.st_name) == Some(name)),
            format!("Fixed emitted function {name} is dynamically visible/preemptible"),
        )?;
        for role in aliases {
            require(
                result.insert(role.to_owned(), symbol).is_none(),
                format!("ambiguous Fixed emitted role {role}"),
            )?;
        }
    }
    for role in FIXED_REQUIRED_ROLES {
        require(
            result.contains_key(role),
            format!("required actual Fixed emitted role {role} absent"),
        )?;
    }
    Ok(result)
}

// Both observed equality cohorts can coexist in one DSO. This finite census
// grants byte coverage only; admission chooses one pair from complete callers.
const FIXED_HEAP_EQUAL_COHORTS: [(&str, &str); 2] = [
    (
        "_RNvXsf_NtCs_4core6optionINtB5_6OptionjENtNtB7_3cmp9PartialEq2eqCs_12regex_syntax",
        "_RNvXsj_NtNtCs_4core3cmp5implsjNtB7_9PartialEq2eqCs_12regex_syntax",
    ),
    (
        "_RNvXsf_NtCs_4core6optionINtB5_6OptionjENtNtB7_3cmp9PartialEq2eqCs_10safeptrace",
        "_RNvXsj_NtNtCs_4core3cmp5implsjNtB7_9PartialEq2eqCs_10safeptrace",
    ),
];

fn fixed_heap_equal_candidates(elf: &Elf<'_>) -> Result<BTreeMap<&'static str, sym::Sym>> {
    let mut result = BTreeMap::new();
    for (option, scalar) in FIXED_HEAP_EQUAL_COHORTS {
        for spelling in [option, scalar] {
            let candidates: Vec<_> = elf
                .syms
                .iter()
                .filter(|symbol| {
                    elf.strtab
                        .get_at(symbol.st_name)
                        .and_then(canonical_rust_symbol)
                        .as_deref()
                        == Some(spelling)
                })
                .collect();
            if candidates.is_empty() {
                continue;
            }
            require(
                candidates.len() == 1,
                "ambiguous exact heap equality provider",
            )?;
            let symbol = candidates[0];
            let name = elf.strtab.get_at(symbol.st_name).unwrap();
            require(
                executable_symbol(elf, &symbol)
                    && symbol.st_bind() == sym::STB_LOCAL
                    && !elf
                        .dynsyms
                        .iter()
                        .any(|dynamic| elf.dynstrtab.get_at(dynamic.st_name) == Some(name)),
                "heap equality provider is not executable LOCAL/non-dynamic",
            )?;
            result.insert(spelling, symbol);
        }
    }
    Ok(result)
}

// Rebind only this two-role cohort, after the unchanged whole2690B caller
// shape, both actual GOT operands and the complete124B/22B providers prove it.
// This does not change the ordinary emitted-role duplicate/alias rules.
fn fixed_select_heap_equal_cohort(
    elf: &Elf<'_>,
    bytes: &[u8],
    code: &BTreeMap<u64, Vec<u8>>,
    got: &BTreeMap<u64, u64>,
    roles: &mut BTreeMap<String, sym::Sym>,
) -> Result<()> {
    let Some(caller) = roles.get("fixed_heap_deallocate") else {
        return Ok(());
    };
    let (_, caller_code) = fixed_private_role_code("fixed_heap_deallocate", roles, code)?;
    if !fixed_template_shape(
        caller_code,
        &fixed_hex(DEV_FIXED_HEAP_HEX_1),
        DEV_FIXED_HEAP_OPERANDS_1.iter().map(|op| op.displacement),
    ) {
        // Other bodies still require their original complete production proof.
        return Ok(());
    }
    require(
        loaded_bytes(elf, bytes, caller.st_value, caller_code.len())? == caller_code,
        "heap equality caller loses its physical complete bytes",
    )?;
    let candidates = fixed_heap_equal_candidates(elf)?;
    let mut selected = None;
    for (displacement, next) in [(1143, 1147), (1923, 1927)] {
        let slot = fixed_rip_target(caller.st_value, caller_code, displacement, next)?;
        require(
            fixed_readonly_range(elf, bytes, slot, 8)? == [0; 8],
            "heap equality GOT lacks its exact file-zero word",
        )?;
        let relros: Vec<_> = elf
            .program_headers
            .iter()
            .filter(|header| header.p_type == program_header::PT_GNU_RELRO)
            .collect();
        require(
            relros.len() == 1
                && slot >= relros[0].p_vaddr
                && slot.checked_add(8).is_some_and(|end| {
                    relros[0]
                        .p_vaddr
                        .checked_add(relros[0].p_memsz)
                        .is_some_and(|limit| end <= (limit & !4095))
                }),
            "heap equality GOT is not wholly in unique protected RELRO",
        )?;
        let writers = extent_writers(elf, slot, 8)?;
        let target = *got
            .get(&slot)
            .ok_or("heap equality GOT is unauthenticated")?;
        require(
            writers.len() == 1
                && writers[0].r_offset == slot
                && writers[0].r_type == reloc::R_X86_64_RELATIVE
                && writers[0].r_sym == 0
                && writers[0].r_addend == Some(i64::try_from(target).map_err(|e| e.to_string())?),
            "heap equality GOT lacks its sole exact local RELATIVE writer",
        )?;
        require(
            selected.is_none_or(|prior| prior == target),
            "deallocate equality operands select different providers",
        )?;
        selected = Some(target);
    }
    let selected = selected.unwrap();
    let cohorts: Vec<_> = FIXED_HEAP_EQUAL_COHORTS
        .iter()
        .filter(|(option, _)| {
            candidates
                .get(option)
                .is_some_and(|s| s.st_value == selected)
        })
        .collect();
    require(
        cohorts.len() == 1,
        "deallocate lacks one exact typed equality cohort",
    )?;
    let (option_name, scalar_name) = *cohorts[0];
    let option = candidates[option_name];
    let scalar = *candidates
        .get(scalar_name)
        .ok_or("heap equality scalar provider absent")?;
    let mut bodies = Vec::new();
    for symbol in [option, scalar] {
        let body = code
            .get(&symbol.st_value)
            .ok_or("heap equality provider lacks whole bytes")?;
        require(
            body.len() as u64 == symbol.st_size
                && loaded_bytes(elf, bytes, symbol.st_value, body.len())? == body,
            "heap equality provider loses its physical complete bytes",
        )?;
        let (mapping, _) = unique_file_mapping(elf, bytes, symbol.st_value, body.len())?;
        require(
            mapping.p_flags & (program_header::PF_R | program_header::PF_W | program_header::PF_X)
                == program_header::PF_R | program_header::PF_X,
            "heap equality provider is not uniquely mapped RX",
        )?;
        bodies.push(body);
    }
    fixed_whole_recipe(
        option.st_value,
        bodies[0],
        DEV_FIXED_HEAP_HEX_23,
        &[(105, 109, scalar.st_value)],
    )?;
    fixed_whole_recipe(scalar.st_value, bodies[1], DEV_FIXED_HEAP_HEX_22, &[])?;
    roles.insert("fixed_heap_option_usize_equal".into(), option);
    roles.insert("fixed_heap_usize_equal".into(), scalar);
    Ok(())
}

fn compiler_shim_symbols(elf: &Elf<'_>) -> Result<BTreeMap<String, sym::Sym>> {
    let mut result = BTreeMap::new();
    for shim in SHIMS {
        let candidates: Vec<_> = elf
            .syms
            .iter()
            .filter(|s| executable_symbol(elf, s))
            .filter(|s| {
                elf.strtab
                    .get_at(s.st_name)
                    .is_some_and(|name| name == shim || name.ends_with(shim))
            })
            .collect();
        require(
            candidates.len() == 1,
            format!("required unique compiler-selected shim {shim} absent/ambiguous"),
        )?;
        let symbol = candidates[0];
        let name = elf
            .strtab
            .get_at(symbol.st_name)
            .ok_or("allocation shim name absent")?;
        require(
            symbol.st_bind() == sym::STB_LOCAL
                && !elf
                    .dynsyms
                    .iter()
                    .any(|s| elf.dynstrtab.get_at(s.st_name) == Some(name))
                && !elf
                    .dynrelas
                    .iter()
                    .chain(elf.dynrels.iter())
                    .chain(elf.pltrelocs.iter())
                    .any(|r| {
                        elf.dynsyms
                            .get(r.r_sym)
                            .is_some_and(|s| elf.dynstrtab.get_at(s.st_name) == Some(name))
                    }),
            format!("compiler allocation shim {shim} is dynamically visible/preemptible"),
        )?;
        result.insert(shim.to_owned(), symbol);
    }
    Ok(result)
}

fn fixed_compiler_path(
    graph: &CallGraph,
    shim: u64,
    implementation: u64,
    fixed_nodes: &BTreeSet<u64>,
) -> Result<Vec<u64>> {
    let nodes: BTreeSet<_> = fixed_nodes.iter().copied().chain([shim]).collect();
    let restricted: CallGraph = graph
        .iter()
        .filter(|(source, _)| nodes.contains(source))
        .map(|(source, targets)| {
            (
                *source,
                targets
                    .iter()
                    .filter(|target| nodes.contains(target))
                    .copied()
                    .collect(),
            )
        })
        .collect();
    let path = shortest_path(&restricted, shim, implementation)?;
    require(
        path.len() >= 2,
        "compiler shim and Fixed implementation may not be the same invented endpoint",
    )?;
    Ok(path)
}

fn owned_fixed_setup_role(role: &str) -> bool {
    matches!(
        role,
        "fixed_arena_setup"
            | "fixed_heap_metadata_initialize"
            | "fixed_setup_bitmap_range"
            | "fixed_setup_shift_guard"
            | "fixed_metadata_atomic_new_bool"
            | "fixed_metadata_atomic_new_usize"
            | "fixed_scalar_syscall"
            | "fixed_region_publication_get"
            | "fixed_region_publication_set"
            | "fixed_native_bitmap_range"
    )
}

