    preparation_role(name).or_else(|| {
        fixed_emitted_role(name).filter(|role| {
            owned_fixed_setup_role(role)
                || *role == "fixed_panic_nounwind_fmt"
                || PUBLICATION_PREPARATION_ROLES.contains(role)
        })
    })
