#[cfg(test)]
fn validate_fixed_backing_evidence(backing: &AllocatorBackingEvidence) -> Result<()> {
    validate_fixed_backing_evidence_in_source_context(backing, FixedImageKind::Standalone)
}
fn validate_fixed_backing_evidence_in_source_context(
    backing: &AllocatorBackingEvidence,
    image_kind: FixedImageKind,
) -> Result<()> {
    validate_fixed_native_syscall_evidence(backing, image_kind)?;
    require(
        backing.fixed_arena_version == FIXED_ARENA_VERSION
            && backing.descriptor.version == 1
            && backing.descriptor.mode == AllocatorBackingMode::Fixed
            && backing.descriptor.symbol.name == ALLOCATOR_BACKING_SYMBOL
            && backing.descriptor.symbol.size == 16
            && descriptor_binding(
                backing.descriptor.symbol.binding,
                backing.descriptor.symbol.visibility,
            )
            && backing.compiler_global_type
                == "reverie_liteinst::patch_alloc::FixedPrivatePatchAllocator",
        "unsupported/unqualified Fixed allocator backing identity",
    )?;
    require(
        backing.guard_contract == FIXED_GUARD_CONTRACT
            && backing
                .selection_objects
                .keys()
                .map(String::as_str)
                .collect::<BTreeSet<_>>()
                == BTreeSet::from([
                    "fixed_initializing",
                    "fixed_region",
                    "fixed_compiler_global_marker",
                ]),
        "Fixed backing lacks exact selection/valid-input contract",
    )?;
    for (key, size, canonical) in [
        (
            "fixed_initializing",
            1,
            "_RNvNtNtCs_15reverie_inguest5guest11tool_region12INITIALIZING",
        ),
        (
            "fixed_region",
            32,
            "_RNvNtNtCs_15reverie_inguest5guest11tool_region6REGION",
        ),
    ] {
        let object = &backing.selection_objects[key];
        require(
            object.binding == sym::STB_LOCAL
                && object.size == size
                && canonical_rust_symbol(&object.name).as_deref() == Some(canonical),
            "Fixed selection state has wrong actual source identity",
        )?;
    }
    let marker = &backing.selection_objects["fixed_compiler_global_marker"];
    require(
        marker.binding == sym::STB_LOCAL
            && marker.size == 0
            && canonical_rust_symbol(&marker.name).as_deref()
                == Some(match image_kind {
                    FixedImageKind::Standalone => {
                        "_RNvCs_24reverie_liteinst_preload26REVERIE_LITEINST_ALLOCATOR"
                    }
                    FixedImageKind::Detcore => {
                        "_RNvCs_16detcore_liteinst26REVERIE_LITEINST_ALLOCATOR"
                    }
                }),
        "Fixed compiler global marker differs",
    )?;
    for object in backing.readonly_objects.values() {
        require(
            object.address != 0
                && object.size != 0
                && object.sha256.len() == 64
                && object.sha256.bytes().all(|b| b.is_ascii_hexdigit())
                && object.file_address.is_some() == object.file_sha256.is_some()
                && object.file_address.is_some() == object.relative_pointer_slot.is_some()
                && object.file_sha256.as_ref().is_none_or(|hash| {
                    hash.len() == 64 && hash.bytes().all(|b| b.is_ascii_hexdigit())
                }),
            "Fixed readonly object proof is incomplete",
        )?;
    }
    for terminal in backing.guarded_terminal_edges.values() {
        require(
            fixed_guarded_terminal_pairs(image_kind).contains(&(
                terminal.caller_role.as_str(),
                terminal.terminal_role.as_str(),
                terminal.premise.as_str(),
            )) && backing
                .allocator_transfers
                .get(&terminal.caller_role)
                .is_some_and(|edges| edges.contains(&terminal.transfer))
                && backing
                    .functions
                    .get(&terminal.terminal_role)
                    .is_some_and(|symbol| symbol.address == terminal.transfer.target),
            "Fixed guarded terminal loses its exact caller/premise/actual edge",
        )?;
    }
    let record = &backing.fixed_backing_record;
    let expected: Vec<u8> = [
        FIXED_TOOL_BOTTOM,
        FIXED_TOOL_BOTTOM + FIXED_ARENA_BYTES,
        FIXED_PATCH_BOTTOM,
        FIXED_PATCH_BOTTOM + FIXED_ARENA_BYTES,
        FIXED_METADATA + 24,
    ]
    .into_iter()
    .flat_map(u64::to_le_bytes)
    .collect();
    require(
        canonical_rust_symbol(&record.symbol.name).as_deref() == Some(FIXED_BACKING_RECORD_ROLE)
            && record.symbol.size == 40
            && descriptor_binding(record.symbol.binding, record.symbol.visibility)
            && record.payload_sha256 == sha256(&expected),
        "Fixed backing lacks its immutable exact span/cursor record",
    )?;
    let tls = &backing.tls_boundary;
    require(
        tls.dependency == "existing_installation_depth_tls"
            && tls.provider_symbol == "__tls_get_addr"
            && tls.provider_version == "GLIBC_2.3"
            && tls.provider_library == "ld-linux-x86-64.so.2"
            && tls.unisolated
            && tls.tls_cell.binding == sym::STB_LOCAL
            && canonical_rust_symbol(&tls.tls_cell.name).as_deref() == Some(FIXED_TLS_CELL_ROLE)
            && match image_kind {
                FixedImageKind::Standalone => {
                    matches!(tls.tls_cell.address, 0x40 | 0x48 | 0x80 | 0x88)
                }
                FixedImageKind::Detcore => {
                    matches!(tls.tls_cell.address, 0x98 | 0xa0 | 0xd8 | 0xe0 | 0x128)
                }
            }
            && tls.tls_cell.size == 8
            && tls.tls_offset_slot
                == tls
                    .tls_module_slot
                    .checked_add(8)
                    .ok_or("TLS offset overflows")?
            && !tls.callsites.is_empty()
            && tls
                .callsites
                .iter()
                .all(|edge| edge.target == tls.plt_address && edge.local_got_slot.is_none())
            && tls.local_chain.keys().eq(tls.function_sha256.keys())
            && tls.local_chain.contains_key("fixed_patch_alloc")
            && tls
                .local_chain
                .values()
                .all(|symbol| symbol.binding == sym::STB_LOCAL && symbol.size != 0)
            && tls
                .function_sha256
                .values()
                .chain([&tls.plt_sha256])
                .all(|hash| hash.len() == 64 && hash.bytes().all(|byte| byte.is_ascii_hexdigit())),
        "Fixed backing lacks the exact named unisolated TLS boundary",
    )?;
    require(
        tls.direct_allocation.is_none()
            || (tls.local_key_object.is_none()
                && tls.local_key_transfer.is_none()
                && tls.local_key_resolution.is_none()),
        "direct TLS provenance cannot relabel a LocalKey chain",
    )?;
    match (
        &tls.local_key_object,
        &tls.local_key_transfer,
        &tls.local_key_resolution,
    ) {
        (Some(_), Some(edge), Some(resolution)) => require(
            resolution == "local_relative_readonly_function_pointer"
                && (tls.tls_cell.address == 0x48
                    || (image_kind == FixedImageKind::Standalone
                        && matches!(tls.tls_cell.address, 0x40 | 0x80)))
                && edge.local_got_slot.is_none()
                && tls
                    .local_chain
                    .get("fixed_tls_fn_once")
                    .is_some_and(|symbol| symbol.address == edge.target)
                && [
                    "fixed_tls_get",
                    "fixed_tls_with",
                    "fixed_tls_try_with",
                    "fixed_tls_cell_getter",
                    "fixed_tls_cell_callback",
                    "fixed_tls_cell_read",
                ]
                .iter()
                .all(|role| tls.local_chain.contains_key(*role)),
            "Fixed TLS local function-pointer chain is incomplete or mislabeled as GOT",
        )?,
        (None, None, None) if tls.direct_allocation.is_some() => {
            require(
                image_kind == FixedImageKind::Standalone,
                "direct allocation TLS proof belongs only to standalone images",
            )?;
            validate_direct_allocation_tls_evidence(tls, tls.direct_allocation.as_ref().unwrap())?;
        }
        (None, None, None) => {
            let extent = match (image_kind, tls.tls_cell.address) {
                (FixedImageKind::Standalone, 0x40 | 0x80) => Some(186),
                (FixedImageKind::Detcore, 0x98 | 0xd8 | 0x128) => Some(241),
                _ => None,
            };
            if let Some(extent) = extent {
                require(
                    tls.local_chain
                        .get("fixed_patch_alloc")
                        .is_some_and(|s| s.size == extent)
                        && tls
                            .local_chain
                            .get("fixed_tls_fn_once")
                            .is_some_and(|s| s.size == 22)
                        && tls
                            .local_chain
                            .keys()
                            .map(String::as_str)
                            .collect::<BTreeSet<_>>()
                            == BTreeSet::from(["fixed_patch_alloc", "fixed_tls_fn_once"]),
                    "new optimized TLS offset lacks its exact None-LocalKey whole chain",
                )?;
            }
        }
        _ => return Err("Fixed TLS local function-pointer evidence is inconsistent".into()),
    }
    if image_kind == FixedImageKind::Standalone
        && matches!(tls.tls_cell.address, 0x40 | 0x80)
        && tls.local_key_object.is_some()
    {
        let try_with = tls.local_chain.get("fixed_tls_try_with");
        require(
            tls.local_chain
                .get("fixed_patch_alloc")
                .is_some_and(|s| s.size == 177)
                && tls
                    .local_key_object
                    .is_some_and(|key| key != 0 && key.is_multiple_of(8))
                && tls.local_key_transfer.as_ref().is_some_and(|edge| {
                    try_with.is_some_and(|caller| {
                        caller.address.checked_add(0x15) == Some(edge.instruction)
                    })
                })
                && tls
                    .local_chain
                    .keys()
                    .map(String::as_str)
                    .collect::<BTreeSet<_>>()
                    == BTreeSet::from([
                        "fixed_patch_alloc",
                        "fixed_installation_active",
                        "fixed_tls_fn_once",
                        "fixed_tls_get",
                        "fixed_tls_with",
                        "fixed_tls_try_with",
                        "fixed_tls_cell_getter",
                        "fixed_tls_cell_callback",
                        "fixed_tls_cell_read",
                    ]),
            "new DEV TLS offset lacks its complete Some-LocalKey whole chain",
        )?;
    }
    require(
        backing
            .compiler_routes
            .keys()
            .map(String::as_str)
            .collect::<BTreeSet<_>>()
            == BTreeSet::from(SHIMS),
        "Fixed backing lacks four compiler-selected typed routes",
    )?;
    for (shim, role) in [
        ("__rust_alloc", "fixed_patch_alloc"),
        ("__rust_alloc_zeroed", "fixed_patch_alloc_zeroed"),
        ("__rust_realloc", "fixed_patch_realloc"),
        ("__rust_dealloc", "fixed_patch_dealloc"),
    ] {
        let route = &backing.compiler_routes[shim];
        require(
            backing.functions.get(role) == Some(&route.implementation)
                && backing.functions.get(shim) == Some(&route.shim)
                && route.shim.binding == sym::STB_LOCAL
                && route.implementation.binding == sym::STB_LOCAL
                && route.call_path.len() >= 2
                && route.call_path.first() == Some(&route.shim.address)
                && route.call_path.last() == Some(&route.implementation.address),
            format!("Fixed {shim} route does not bind its actual distinct typed operation"),
        )?;
    }
    require(
        FIXED_REQUIRED_ROLES
            .iter()
            .all(|role| backing.functions.contains_key(*role))
            && FIXED_PUBLICATION_REQUIRED_ROLES.iter().all(|role| {
                backing.functions.contains_key(*role)
                    && backing.allocator_transfers.contains_key(*role)
            })
            && backing.functions.keys().eq(backing.function_sha256.keys())
            && backing
                .function_sha256
                .values()
                .all(|hash| hash.len() == 64 && hash.bytes().all(|byte| byte.is_ascii_hexdigit()))
            && backing
                .owned_setup_transfers
                .contains_key("fixed_arena_setup")
            && FIXED_REQUIRED_ROLES[..4]
                .iter()
                .all(|role| backing.allocator_transfers.contains_key(*role))
            && backing
                .allocator_transfers
                .keys()
                .all(|role| backing.functions.contains_key(role)),
        "Fixed backing lacks whole required function/setup evidence",
    )
}

#[cfg(test)]
fn qualify_fixed_allocator(
    elf: &Elf<'_>,
    bytes: &[u8],
    code: &BTreeMap<u64, Vec<u8>>,
    disassembly: &str,
    got: &BTreeMap<u64, u64>,
) -> Result<AllocatorBackingEvidence> {
    qualify_fixed_allocator_in_source_context(
        elf,
        bytes,
        code,
        disassembly,
        got,
        FixedImageKind::Standalone,
        None,
    )
}
fn qualify_fixed_allocator_in_source_context(
    elf: &Elf<'_>,
    bytes: &[u8],
    code: &BTreeMap<u64, Vec<u8>>,
    disassembly: &str,
    got: &BTreeMap<u64, u64>,
    image_kind: FixedImageKind,
    sources: Option<&VerifiedCompiledSources>,
) -> Result<AllocatorBackingEvidence> {
    if let Some(sources) = sources {
        sources.require_image(image_kind.initializer())?;
    }
    if image_kind == FixedImageKind::Detcore {
        require(
            sources.is_some(),
            "Detcore validate needs independently verified compiled sources",
        )?;
    }
    if image_kind == FixedImageKind::Standalone {
        require_legacy_standalone_gate(elf)?;
    }
    let descriptor = allocator_descriptor(elf, bytes)?;
    require(
        descriptor.mode == AllocatorBackingMode::Fixed,
        "Legacy descriptor cannot satisfy Fixed production admission",
    )?;
    let fixed_backing_record = fixed_backing_record(elf, bytes)?;
    let gate_owner = private_function(elf, CONSTRUCTOR_GATE_OWNER)?;
    let gate_ip = constructor_interior_label(elf, CONSTRUCTOR_GATE, &gate_owner)?;
    let gate_return = constructor_interior_label(elf, CONSTRUCTOR_GATE_RETURN, &gate_owner)?;
    let gate_view = constructor_gate_disassembly_view(
        disassembly,
        &gate_owner,
        &BTreeMap::from([
            (gate_ip.st_value, CONSTRUCTOR_GATE),
            (gate_return.st_value, CONSTRUCTOR_GATE_RETURN),
        ]),
    )?;
    let disassembly = gate_view.as_str();
    let mut roles = fixed_role_symbols(elf)?;
    if image_kind == FixedImageKind::Detcore {
        add_fixed_native_owner(elf, &mut roles)?;
    }
    if image_kind == FixedImageKind::Standalone {
        fixed_select_heap_equal_cohort(elf, bytes, code, got, &mut roles)?;
    }
    let shims = compiler_shim_symbols(elf)?;
    if image_kind == FixedImageKind::Detcore {
        for (name, symbol) in &shims {
            require(
                roles.insert(name.clone(), *symbol).is_none(),
                "Detcore shim conflicts with typed role",
            )?;
        }
    }
    let tls = qualify_allocator_tls_boundary_in_source_context(
        elf,
        bytes,
        code,
        disassembly,
        got,
        image_kind,
        sources,
    )?;
    let context = fixed_machine_context(
        (elf, bytes),
        code,
        got,
        &shims,
        &fixed_backing_record,
        &tls,
        (image_kind, sources, &roles),
    )?;
    let closure = qualify_fixed_operation_closure(
        elf,
        (code, disassembly),
        got,
        &roles,
        &context,
        &tls,
        (image_kind, sources),
    )?;
    let functions: BTreeMap<_, _> = code
        .iter()
        .map(|(&address, bytes)| (address, bytes.len() as u64))
        .collect();
    let (graph, got_edges) = disassembly_edges(disassembly, &functions, got)?;
    let nodes = roles
        .iter()
        .filter(|(role, _)| !owned_fixed_setup_role(role))
        .map(|(_, symbol)| symbol.st_value)
        .collect();
    let mut compiler_routes = BTreeMap::new();
    for (shim, role) in [
        ("__rust_alloc", "fixed_patch_alloc"),
        ("__rust_alloc_zeroed", "fixed_patch_alloc_zeroed"),
        ("__rust_realloc", "fixed_patch_realloc"),
        ("__rust_dealloc", "fixed_patch_dealloc"),
    ] {
        let implementation = &roles[role];
        let shim_symbol = &shims[shim];
        let shim_code = code
            .get(&shim_symbol.st_value)
            .ok_or("Fixed compiler shim lacks full bytes")?;
        let dev = shim_code.len() > 22;
        let edges = if image_kind == FixedImageKind::Detcore {
            fixed_detcore_compiler_shim_recipe(
                DETCORE_ROOT,
                shim,
                shim_symbol.st_value,
                shim_code,
                implementation.st_value,
                DetcoreRecipeBindings {
                    targets: &context.targets,
                    got,
                    readonly: &context.readonly,
                    context: &context.compiled_filenames,
                },
                tls.tls_cell.address,
            )?
        } else {
            fixed_compiler_shim_recipe(
                shim,
                shim_symbol.st_value,
                shim_code,
                implementation.st_value,
                got,
                FixedCompilerShimOperands {
                    layout_constructor: dev
                        .then(|| context.targets.get("fixed_compiler_layout").copied())
                        .flatten(),
                    allocator_zst: context.targets["fixed_compiler_global_marker"],
                    layout_location: dev
                        .then(|| {
                            context
                                .targets
                                .get("fixed_compiler_layout_location")
                                .copied()
                        })
                        .flatten(),
                },
            )?
        };
        fixed_census_transfers(
            &constructor_instructions(disassembly, shim_symbol.st_value)?,
            shim_symbol.st_value,
            shim_code,
            &edges,
            got,
            false,
        )?;
        let path = fixed_compiler_path(
            &graph,
            shims[shim].st_value,
            implementation.st_value,
            &nodes,
        )?;
        compiler_routes.insert(
            shim.to_owned(),
            FixedAllocatorRoute {
                shim: symbol_evidence(
                    elf.strtab.get_at(shims[shim].st_name).unwrap(),
                    &shims[shim],
                ),
                implementation: symbol_evidence(
                    elf.strtab.get_at(implementation.st_name).unwrap(),
                    implementation,
                ),
                local_got_edges: got_edges
                    .iter()
                    .filter(|edge| {
                        path.windows(2).any(|pair| {
                            edge.source_function == pair[0] && edge.target_function == pair[1]
                        })
                    })
                    .cloned()
                    .collect(),
                call_path: path,
            },
        );
    }
    let preparation = preparation_symbols(elf)?;
    let allowed = preparation.values().map(|symbol| symbol.st_value).collect();
    let mut owned_setup_transfers = BTreeMap::new();
    let mut owned_setup_got_edges = Vec::new();
    for (name, symbol) in &preparation {
        let role = resolved_preparation_role(name).unwrap();
        if matches!(role, "from_native" | "publish") || owned_fixed_setup_role(role) {
            let instructions = constructor_instructions(disassembly, symbol.st_value)?;
            let function = symbol_evidence(name, symbol);
            let (transfers, edges) = fixed_setup_preparation_transfers(
                role,
                &function,
                &instructions,
                got,
                &allowed,
                context.native_syscalls.as_ref(),
            )?;
            owned_setup_transfers.insert(role.to_owned(), transfers);
            owned_setup_got_edges.extend(edges);
        }
    }
    // The always-outlined setup role must be in the owned transfer census.
    require(
        owned_setup_transfers.contains_key("fixed_arena_setup"),
        "actual fresh-owner setup has no whole transfer census",
    )?;
    let mut evidence_functions = BTreeMap::new();
    for (role, symbol) in roles {
        evidence_functions.insert(
            role,
            symbol_evidence(elf.strtab.get_at(symbol.st_name).unwrap(), &symbol),
        );
    }
    for (shim, symbol) in shims {
        evidence_functions.insert(
            shim,
            symbol_evidence(elf.strtab.get_at(symbol.st_name).unwrap(), &symbol),
        );
    }
    for (name, symbol) in preparation {
        let role = resolved_preparation_role(&name).unwrap();
        evidence_functions
            .entry(role.to_owned())
            .or_insert_with(|| symbol_evidence(&name, &symbol));
    }
    let function_sha256 = evidence_functions
        .iter()
        .map(|(role, symbol)| {
            let bytes = code
                .get(&symbol.address)
                .ok_or_else(|| format!("Fixed role {role} lacks complete actual function bytes"))?;
            Ok((role.clone(), sha256(bytes)))
        })
        .collect::<Result<_>>()?;
    let evidence = AllocatorBackingEvidence {
        fixed_native_syscalls: context.native_syscalls.map(|native| native.evidence),
        fixed_arena_version: FIXED_ARENA_VERSION,
        descriptor,
        compiler_global_type: "reverie_liteinst::patch_alloc::FixedPrivatePatchAllocator"
            .to_owned(),
        compiler_routes,
        fixed_backing_record,
        tls_boundary: tls,
        allocator_transfers: closure.transfers,
        readonly_objects: context.readonly_evidence,
        selection_objects: context.selection_objects,
        guard_contract: FIXED_GUARD_CONTRACT.into(),
        guarded_terminal_edges: closure.guarded,
        functions: evidence_functions,
        function_sha256,
        owned_setup_transfers,
        owned_setup_got_edges,
    };
    validate_fixed_backing_evidence_in_source_context(&evidence, image_kind)?;
    Ok(evidence)
}

