fn detcore_validate_expected_data(
    spec: &DetcoreValidateDataSpec,
    context: &BTreeMap<String, Vec<u8>>,
) -> Result<(Vec<u8>, Option<Vec<u8>>)> {
    if !spec.location {
        return Ok((fixed_hex(spec.hex), None));
    }
    let filename = match spec.source_context_key {
        Some(key) => context
            .get(key)
            .ok_or_else(|| format!("missing authenticated compiled-source filename {key}"))?
            .clone(),
        None => fixed_hex(spec.file_hex),
    };
    require(
        !filename.is_empty() && !filename.contains(&0),
        "empty/NUL compiled-source filename",
    )?;
    let mut expected = vec![0u8; 24];
    expected[8..16].copy_from_slice(&(filename.len() as u64).to_le_bytes());
    expected[16..20].copy_from_slice(&spec.line.to_le_bytes());
    expected[20..24].copy_from_slice(&spec.column.to_le_bytes());
    Ok((expected, Some(filename)))
}
fn detcore_validate_readonly_recipe(
    spec: &DetcoreValidateDataSpec,
    address: u64,
    targets: &BTreeMap<String, u64>,
    readonly: &BTreeMap<u64, Vec<u8>>,
    context: &BTreeMap<String, Vec<u8>>,
) -> Result<()> {
    let (expected, filename) = detcore_validate_expected_data(spec, context)?;
    let actual = readonly
        .get(&address)
        .ok_or("complete Detcore readonly object absent")?;
    require(
        actual.get(..expected.len()) == Some(expected.as_slice()),
        "complete Detcore readonly object differs",
    )?;
    if let Some(filename) = filename {
        let key = format!("{}_file", spec.key);
        let file = *targets
            .get(&key)
            .ok_or("separately authenticated Location filename pointer absent")?;
        require(file != 0, "Location filename pointer is null")?;
        let actual_file = readonly
            .get(&file)
            .ok_or("complete Location filename bytes absent")?;
        require(
            actual_file.get(..filename.len()) == Some(filename.as_slice()),
            "complete Location filename differs",
        )?;
    }
    Ok(())
}

// Caller enters this binder only after canonical loader authentication and
// derives `address` from the matching whole-code operand. Do not replace it
// with merely inserting the recipe's expected bytes into readonly.
fn detcore_validate_bind_readonly(
    (elf, bytes): (&Elf<'_>, &[u8]),
    spec: &DetcoreValidateDataSpec,
    address: u64,
    context: &BTreeMap<String, Vec<u8>>,
    targets: &mut BTreeMap<String, u64>,
    readonly: &mut BTreeMap<u64, Vec<u8>>,
    evidence: &mut BTreeMap<String, FixedReadonlyEvidence>,
) -> Result<()> {
    if let Some(prior) = targets.get(spec.key) {
        require(
            *prior == address,
            "Detcore data key has conflicting actual operands",
        )?;
    }
    let (expected, filename) = detcore_validate_expected_data(spec, context)?;
    let actual = fixed_readonly_range(elf, bytes, address, expected.len())?;
    require(
        actual == expected,
        "whole physical Detcore readonly data differs",
    )?;
    let mut file_address = None;
    let mut file_hash = None;
    if let Some(filename) = filename {
        fixed_no_data_relocation(elf, address, 24, Some(address))?;
        let writers = extent_writers(elf, address, 24)?;
        require(
            writers.len() == 1
                && writers[0].r_offset == address
                && writers[0].r_type == reloc::R_X86_64_RELATIVE
                && writers[0].r_sym == 0,
            "Location lacks sole exact RELATIVE writer",
        )?;
        let file = u64::try_from(
            writers[0]
                .r_addend
                .ok_or("Location needs explicit addend")?,
        )
        .map_err(|e| e.to_string())?;
        let actual_file = fixed_readonly_range(elf, bytes, file, filename.len())?;
        require(
            actual_file == filename,
            "whole physical source filename differs",
        )?;
        fixed_no_data_relocation(elf, file, filename.len(), None)?;
        targets.insert(format!("{}_file", spec.key), file);
        fixed_insert_readonly(readonly, file, actual_file)?;
        file_address = Some(file);
        file_hash = Some(sha256(actual_file));
    } else {
        fixed_no_data_relocation(elf, address, actual.len(), None)?;
    }
    fixed_insert_readonly(readonly, address, actual)?;
    targets.insert(spec.key.into(), address);
    let item = FixedReadonlyEvidence {
        address,
        size: actual.len(),
        sha256: sha256(actual),
        file_address,
        file_sha256: file_hash,
        relative_pointer_slot: spec.location.then_some(address),
    };
    if let Some(prior) = evidence.insert(spec.key.into(), item.clone()) {
        require(prior == item, "conflicting physical Detcore data evidence")?;
    }
    detcore_validate_readonly_recipe(spec, address, targets, readonly, context)
}

