struct DetcoreRecipeBindings<'a> {
    targets: &'a BTreeMap<String, u64>,
    got: &'a BTreeMap<u64, u64>,
    readonly: &'a BTreeMap<u64, Vec<u8>>,
    context: &'a BTreeMap<String, Vec<u8>>,
}

struct DetcoreRecipeIdentity {
    template_index: usize,
    edges: Vec<ConstructorTransfer>,
}

fn fixed_detcore_validate_recipe(
    role: &str,
    address: u64,
    bytes: &[u8],
    bindings: DetcoreRecipeBindings<'_>,
    tls_cell_offset: u64,
) -> Result<Vec<ConstructorTransfer>> {
    Ok(
        fixed_detcore_validate_recipe_identity(role, address, bytes, bindings, tls_cell_offset)?
            .edges,
    )
}

fn fixed_detcore_validate_recipe_identity(
    role: &str,
    address: u64,
    bytes: &[u8],
    DetcoreRecipeBindings {
        targets,
        got,
        readonly,
        context,
    }: DetcoreRecipeBindings<'_>,
    tls_cell_offset: u64,
) -> Result<DetcoreRecipeIdentity> {
    let candidates: Vec<_> = DETCORE_VALIDATE_TEMPLATES
        .iter()
        .enumerate()
        .filter(|(_, t)| {
            t.role == role
                && fixed_template_shape(
                    bytes,
                    &fixed_hex(t.hex),
                    t.operands.iter().map(|o| o.displacement),
                )
        })
        .collect();
    require(
        candidates.len() == 1,
        "unknown or ambiguous whole Detcore validate recipe",
    )?;
    let (template_index, t) = candidates[0];
    let mut fields = Vec::new();
    let mut resolved = Vec::new();
    if role == "fixed_patch_alloc" || role == "fixed_tls_fn_once" {
        let at = if role == "fixed_patch_alloc" { 66 } else { 16 };
        let encoded = u32::from_le_bytes(
            bytes
                .get(at..at + 4)
                .ok_or("truncated exact TLS cell operand")?
                .try_into()
                .unwrap(),
        );
        require(
            u64::from(encoded) == tls_cell_offset,
            "validate TLS read differs from authenticated exact LOCAL8 cell",
        )?;
    }
    for op in t.operands {
        let expected = *targets
            .get(op.key)
            .ok_or_else(|| format!("unbound exact Detcore operand {}", op.key))?;
        require(expected != 0, "null Detcore typed operand")?;
        if op.key == "fixed_region_ready" || op.key == "fixed_region_value16" {
            let base = *targets
                .get("fixed_region")
                .ok_or("publication field has no authenticated REGION base")?;
            let offset = if op.key == "fixed_region_ready" {
                24
            } else {
                16
            };
            require(
                base.checked_add(offset) == Some(expected),
                "publication operand differs from exact REGION field",
            )?;
        }
        let operand = fixed_rip_target(address, bytes, op.displacement, op.next)?;
        if op.got {
            require(
                got.get(&operand) == Some(&expected),
                "Detcore operand lacks exact local RELATIVE/RELRO callee",
            )?;
            fields.push((op.displacement, op.next, operand));
        } else {
            fields.push((op.displacement, op.next, expected));
        }
        if DETCORE_VALIDATE_DATA.iter().any(|s| s.key == op.key) {
            let spec = DETCORE_VALIDATE_DATA
                .iter()
                .find(|s| s.key == op.key)
                .ok_or("missing Detcore data specification")?;
            detcore_validate_readonly_recipe(spec, expected, targets, readonly, context)?;
        }
        resolved.push((expected, op.got.then_some(operand)));
    }
    fixed_whole_recipe(address, bytes, t.hex, &fields)?;
    let edges = t
        .transfers
        .iter()
        .map(|&(pc, i)| {
            let (target, slot) = *resolved.get(i).ok_or("Detcore transfer has no operand")?;
            Ok(ConstructorTransfer {
                instruction: address
                    .checked_add(pc as u64)
                    .ok_or("Detcore transfer overflow")?,
                target,
                local_got_slot: slot,
            })
        })
        .collect::<Result<Vec<_>>>()?;
    Ok(DetcoreRecipeIdentity {
        template_index,
        edges,
    })
}

// Source-only route adapter. `expected_root` is supplied by the caller-owned
// constructor contract; the complete root/init-array proof must also succeed.
// It is never inferred from an arbitrary marker in the ELF. Parent may replace
// this string adapter with its closed FixedImageKind without changing predicates.
fn fixed_detcore_compiler_shim_recipe(
    expected_root: &str,
    shim: &str,
    address: u64,
    bytes: &[u8],
    implementation: u64,
    DetcoreRecipeBindings {
        targets,
        got,
        readonly,
        context,
    }: DetcoreRecipeBindings<'_>,
    tls_cell_offset: u64,
) -> Result<Vec<ConstructorTransfer>> {
    require(
        expected_root == DETCORE_ROOT,
        "Detcore shim recipe requested by wrong constructor contract",
    )?;
    let method = match shim {
        "__rust_alloc" => "fixed_patch_alloc",
        "__rust_alloc_zeroed" => "fixed_patch_alloc_zeroed",
        "__rust_dealloc" => "fixed_patch_dealloc",
        "__rust_realloc" => "fixed_patch_realloc",
        _ => return Err("unknown exact Detcore compiler shim".into()),
    };
    require(
        implementation != 0 && targets.get(method) == Some(&implementation),
        "Detcore shim lacks the selected exact typed implementation",
    )?;
    let edges = fixed_detcore_validate_recipe(
        shim,
        address,
        bytes,
        DetcoreRecipeBindings {
            targets,
            got,
            readonly,
            context,
        },
        tls_cell_offset,
    )?;
    require(
        edges.len() == 2
            && edges[0].target == implementation
            && edges[0].local_got_slot.is_some()
            && edges[1].target
                == *targets
                    .get("fixed_panic_nounwind_fmt")
                    .ok_or("Detcore shim retained Layout panic absent")?
            && edges[1].local_got_slot.is_some(),
        "Detcore shim lost method tail or retained Layout guard",
    )?;
    Ok(edges)
}

fn fixed_detcore_marker(elf: &Elf<'_>, bytes: &[u8], expected_root: &str) -> Result<sym::Sym> {
    require(
        expected_root == DETCORE_ROOT,
        "Detcore marker requested by wrong constructor contract",
    )?;
    fixed_named_selection_object(
        elf,
        bytes,
        "_RNvCs_16detcore_liteinst26REVERIE_LITEINST_ALLOCATOR",
        0,
        false,
    )
}

