fn fixed_guarded_terminal_pairs(
    kind: FixedImageKind,
) -> &'static [(&'static str, &'static str, &'static str)] {
    match kind {
        FixedImageKind::Standalone => FIXED_GUARDED_TERMINAL_PAIRS,
        FixedImageKind::Detcore => DETCORE_VALIDATE_GUARDED_TERMINAL_PAIRS,
    }
}
fn fixed_detcore_compiled_filenames(
    kind: FixedImageKind,
    sources: Option<&VerifiedCompiledSources>,
) -> Result<BTreeMap<String, Vec<u8>>> {
    let mut context = BTreeMap::new();
    if kind == FixedImageKind::Detcore {
        let sources = sources.ok_or("Detcore requires verified compiled filenames")?;
        sources.require_image(DETCORE_ROOT)?;
        for relative in [
            "reverie-liteinst/src/patch_alloc.rs",
            "reverie-inguest/src/guest/alloc.rs",
            "reverie-inguest/src/guest/tool_region_constructor.rs",
            "reverie-inguest/src/guest/tool_region_arena.rs",
        ] {
            context.insert(
                format!("rv:{relative}"),
                sources.filename(relative.as_bytes())?,
            );
        }
    }
    Ok(context)
}
const FIXED_GUARD_CONTRACT: &str =
    "valid_globalalloc_layout_live_same_owner_pointer_intact_locked_metadata_no_foreign_unwind";
struct FixedMachineContext {
    // Only the actual ELF factory constructs this private witness.
    native_syscalls: Option<FixedNativeSyscallContext>,
    compiled_filenames: BTreeMap<String, Vec<u8>>,
    targets: BTreeMap<String, u64>,
    readonly: BTreeMap<u64, Vec<u8>>,
    readonly_evidence: BTreeMap<String, FixedReadonlyEvidence>,
    selection_objects: BTreeMap<String, SymbolEvidence>,
}
fn fixed_named_selection_object(
    elf: &Elf<'_>,
    bytes: &[u8],
    canonical: &str,
    size: u64,
    writable: bool,
) -> Result<sym::Sym> {
    let candidates: Vec<_> = elf
        .syms
        .iter()
        .filter(|s| {
            elf.strtab
                .get_at(s.st_name)
                .and_then(canonical_rust_symbol)
                .as_deref()
                == Some(canonical)
        })
        .collect();
    require(
        candidates.len() == 1,
        "Fixed source selection object absent/ambiguous",
    )?;
    let symbol = candidates[0];
    let name = elf
        .strtab
        .get_at(symbol.st_name)
        .ok_or("Fixed selection object name absent")?;
    require(
        symbol.st_type() == sym::STT_OBJECT
            && symbol.st_bind() == sym::STB_LOCAL
            && symbol.st_size == size
            && symbol.st_shndx != section_header::SHN_UNDEF as usize
            && !elf
                .dynsyms
                .iter()
                .any(|s| elf.dynstrtab.get_at(s.st_name) == Some(name)),
        "Fixed selection object type/size/private identity differs",
    )?;
    let section = elf
        .section_headers
        .get(symbol.st_shndx)
        .ok_or("Fixed selection object section absent")?;
    let end = symbol
        .st_value
        .checked_add(size.max(1))
        .ok_or("Fixed selection object overflow")?;
    require(
        section.sh_flags & u64::from(section_header::SHF_ALLOC) != 0
            && section.sh_flags
                & u64::from(section_header::SHF_EXECINSTR | section_header::SHF_TLS)
                == 0
            && symbol.st_value >= section.sh_addr
            && section
                .sh_addr
                .checked_add(section.sh_size)
                .is_some_and(|e| end <= e),
        "Fixed selection object section join differs",
    )?;
    if writable {
        fixed_require_sane_loads(elf, bytes)?;
        require(
            section.sh_flags & u64::from(section_header::SHF_WRITE) != 0
                && matches!(
                    section.sh_type,
                    section_header::SHT_PROGBITS | section_header::SHT_NOBITS
                ),
            "Fixed selection state lacks actual writable storage",
        )?;
        let start = symbol.st_value & !4095;
        let page_end = end
            .checked_add(4095)
            .ok_or("Fixed selection object page overflow")?
            & !4095;
        let loads: Vec<_> = elf
            .program_headers
            .iter()
            .filter(|p| {
                p.p_type == program_header::PT_LOAD
                    && p.p_vaddr & !4095 < page_end
                    && p.p_vaddr
                        .checked_add(p.p_memsz)
                        .and_then(|e| e.checked_add(4095))
                        .is_some_and(|e| e & !4095 > start)
            })
            .collect();
        require(
            loads.len() == 1
                && loads[0].p_flags
                    & (program_header::PF_R | program_header::PF_W | program_header::PF_X)
                    == program_header::PF_R | program_header::PF_W
                && loads[0].p_offset % 4096 == loads[0].p_vaddr % 4096
                && symbol.st_value >= loads[0].p_vaddr
                && loads[0]
                    .p_vaddr
                    .checked_add(loads[0].p_memsz)
                    .is_some_and(|e| end <= e),
            "Fixed selection object has conflicting/nonwritable mappings",
        )?;
        fixed_no_data_relocation(elf, symbol.st_value, size as usize, None)?;
        if canonical.ends_with("12INITIALIZING") {
            require(
                size == 1
                    && (section.sh_type == section_header::SHT_NOBITS
                        || loaded_bytes(elf, bytes, symbol.st_value, 1)? == [0]),
                "Fixed INITIALIZING does not start clear",
            )?;
        } else {
            require(
                symbol.st_value % 8 == 0
                    && size == 32
                    && (section.sh_type == section_header::SHT_NOBITS
                        || loaded_bytes(elf, bytes, symbol.st_value, 32)? == [0; 32]),
                "Fixed REGION publication does not start unpublished with zero storage",
            )?;
        }
    } else {
        require(
            size == 0 && section.sh_flags & u64::from(section_header::SHF_WRITE) == 0,
            "compiler ZST marker has unexpected storage",
        )?;
        // It is an address marker; the four exact shims establish the allocator type.
        fixed_readonly_range(elf, bytes, symbol.st_value, 1)?;
    }
    Ok(symbol)
}
fn fixed_machine_context(
    (elf, bytes): (&Elf<'_>, &[u8]),
    code: &BTreeMap<u64, Vec<u8>>,
    got: &BTreeMap<u64, u64>,
    shims: &BTreeMap<String, sym::Sym>,
    record: &ImmutableAllocatorObject,
    tls: &AllocatorTlsBoundary,
    (image_kind, sources, roles): (
        FixedImageKind,
        Option<&VerifiedCompiledSources>,
        &BTreeMap<String, sym::Sym>,
    ),
) -> Result<FixedMachineContext> {
    let native_syscalls = if image_kind == FixedImageKind::Detcore {
        qualify_fixed_native_syscalls(elf, bytes, code, got, roles)?
    } else {
        None
    };
    let compiled_filenames = fixed_detcore_compiled_filenames(image_kind, sources)?;
    let mut targets: BTreeMap<_, _> = roles
        .iter()
        .map(|(role, s)| (role.clone(), s.st_value))
        .collect();
    targets.insert("fixed_tls_get_addr_plt".into(), tls.plt_address);
    targets.insert(
        "fixed_publication_tls_descriptor".into(),
        tls.tls_module_slot,
    );
    let mut readonly = BTreeMap::new();
    let mut readonly_evidence = BTreeMap::new();
    let mut selection_objects = BTreeMap::new();
    for (key, canonical, size) in [
        (
            "fixed_initializing",
            "_RNvNtNtCs_15reverie_inguest5guest11tool_region12INITIALIZING",
            1,
        ),
        (
            "fixed_region",
            "_RNvNtNtCs_15reverie_inguest5guest11tool_region6REGION",
            32,
        ),
    ] {
        let object = fixed_named_selection_object(elf, bytes, canonical, size, true)?;
        targets.insert(key.to_owned(), object.st_value);
        selection_objects.insert(
            key.to_owned(),
            symbol_evidence(elf.strtab.get_at(object.st_name).unwrap(), &object),
        );
    }
    targets.insert(
        "fixed_region_ready".into(),
        targets["fixed_region"]
            .checked_add(24)
            .ok_or("REGION ready overflow")?,
    );
    targets.insert(
        "fixed_region_value16".into(),
        targets["fixed_region"]
            .checked_add(16)
            .ok_or("REGION value overflow")?,
    );
    targets.insert("fixed_backing_object".into(), record.symbol.address);
    let marker = match image_kind {
        FixedImageKind::Detcore => fixed_detcore_marker(elf, bytes, DETCORE_ROOT)?,
        FixedImageKind::Standalone => fixed_named_selection_object(
            elf,
            bytes,
            "_RNvCs_24reverie_liteinst_preload26REVERIE_LITEINST_ALLOCATOR",
            0,
            false,
        )?,
    };
    targets.insert("fixed_compiler_global_marker".into(), marker.st_value);
    selection_objects.insert(
        "fixed_compiler_global_marker".into(),
        symbol_evidence(elf.strtab.get_at(marker.st_name).unwrap(), &marker),
    );
    if image_kind == FixedImageKind::Detcore {
        for (role, symbol) in roles {
            let actual = code
                .get(&symbol.st_value)
                .ok_or("Detcore role lacks whole code")?;
            if native_syscalls
                .as_ref()
                .is_some_and(|native| native.evidence.wrappers.contains_key(role))
            {
                // The factory checked this complete native body and both
                // operands. It cannot masquerade as an old template index.
                continue;
            }
            if !DETCORE_VALIDATE_TEMPLATES.iter().any(|t| t.role == role) {
                continue;
            }
            let templates: Vec<_> = DETCORE_VALIDATE_TEMPLATES
                .iter()
                .filter(|t| {
                    t.role == role
                        && fixed_template_shape(
                            actual,
                            &fixed_hex(t.hex),
                            t.operands.iter().map(|op| op.displacement),
                        )
                })
                .collect();
            require(
                templates.len() == 1,
                format!("Detcore {role} has no unique complete validate template"),
            )?;
            for op in templates[0].operands {
                if let Some(spec) = DETCORE_VALIDATE_DATA.iter().find(|spec| spec.key == op.key) {
                    require(
                        !op.got,
                        "Detcore readonly data incorrectly classified as executable GOT",
                    )?;
                    let address =
                        fixed_rip_target(symbol.st_value, actual, op.displacement, op.next)?;
                    detcore_validate_bind_readonly(
                        (elf, bytes),
                        spec,
                        address,
                        &compiled_filenames,
                        &mut targets,
                        &mut readonly,
                        &mut readonly_evidence,
                    )?;
                }
            }
        }
    } else {
        for (role, symbol) in roles {
            let actual = code
                .get(&symbol.st_value)
                .ok_or("Fixed role has no whole emitted code")?;
            for template in FIXED_WRAPPER_RECIPES
                .iter()
                .chain(PUBLICATION_WRAPPER_RECIPES)
                .filter(|r| {
                    r.role == role
                        && fixed_template_shape(
                            actual,
                            &fixed_hex(r.hex),
                            r.operands.iter().map(|op| op.displacement),
                        )
                })
            {
                for op in template.operands.iter().filter(|op| {
                    FIXED_READONLY_SPECS
                        .iter()
                        .any(|spec| spec.key == op.target)
                }) {
                    let address = fixed_readonly_operand_base(
                        fixed_rip_target(symbol.st_value, actual, op.displacement, op.next)?,
                        op.target_offset,
                    )?;
                    fixed_bind_operand_data_in_source_context(
                        (elf, bytes),
                        op.target,
                        address,
                        &mut targets,
                        &mut readonly,
                        &mut readonly_evidence,
                        sources,
                    )?;
                }
            }
            for template in FIXED_ARENA_TEMPLATES.iter().filter(|r| {
                r.role == role
                    && fixed_template_shape(
                        actual,
                        r.bytes,
                        r.operands.iter().map(|op| op.displacement),
                    )
            }) {
                for op in template.operands.iter().filter(|op| {
                    matches!(op.kind, FixedArenaOperandKind::Object)
                        && FIXED_READONLY_SPECS.iter().any(|spec| spec.key == op.key)
                }) {
                    let address = fixed_readonly_operand_base(
                        fixed_rip_target(symbol.st_value, actual, op.displacement, op.next)?,
                        op.addend,
                    )?;
                    fixed_bind_operand_data_in_source_context(
                        (elf, bytes),
                        op.key,
                        address,
                        &mut targets,
                        &mut readonly,
                        &mut readonly_evidence,
                        sources,
                    )?;
                }
            }
            for template in DEV_FIXED_HEAP_TEMPLATES.iter().filter(|r| {
                r.role == role
                    && fixed_template_shape(
                        actual,
                        &fixed_hex(r.hex),
                        r.operands.iter().map(|op| op.displacement),
                    )
            }) {
                for op in template.operands.iter().filter(|op| op.kind == 0) {
                    let address = fixed_readonly_operand_base(
                        fixed_rip_target(symbol.st_value, actual, op.displacement, op.next)?,
                        op.addend,
                    )?;
                    fixed_bind_operand_data_in_source_context(
                        (elf, bytes),
                        op.key,
                        address,
                        &mut targets,
                        &mut readonly,
                        &mut readonly_evidence,
                        sources,
                    )?;
                }
            }
        }
        let shim = &shims["__rust_alloc"];
        let actual = &code[&shim.st_value];
        if actual.len() == 47 {
            let address = fixed_rip_target(shim.st_value, actual, 17, 21)?;
            fixed_bind_operand_data_in_source_context(
                (elf, bytes),
                "fixed_compiler_layout_location",
                address,
                &mut targets,
                &mut readonly,
                &mut readonly_evidence,
                sources,
            )?;
        }
    }
    Ok(FixedMachineContext {
        native_syscalls,
        compiled_filenames,
        targets,
        readonly,
        readonly_evidence,
        selection_objects,
    })
}
fn fixed_census_transfers(
    instructions: &[EncodedConstructorInstruction],
    address: u64,
    actual: &[u8],
    expected: &[ConstructorTransfer],
    got: &BTreeMap<u64, u64>,
    internal_switch: bool,
) -> Result<()> {
    let end = address
        .checked_add(actual.len() as u64)
        .ok_or("Fixed function census extent overflow")?;
    let mut cursor = address;
    let mut joined = Vec::new();
    for instruction in instructions {
        require(
            instruction.address == cursor,
            "Fixed whole census has an instruction gap/alias",
        )?;
        cursor = cursor
            .checked_add(instruction.bytes.len() as u64)
            .ok_or("Fixed census cursor overflow")?;
        joined.extend_from_slice(&instruction.bytes);
    }
    require(
        cursor == end && joined == actual,
        "Fixed whole instruction census omits or changes actual bytes",
    )?;
    let mut covered = BTreeSet::new();
    for instruction in instructions {
        require(
            instruction.address >= address
                && instruction
                    .address
                    .checked_add(instruction.bytes.len() as u64)
                    .is_some_and(|e| e <= end),
            "Fixed census escapes whole typed function",
        )?;
        let b = &instruction.bytes;
        let edge = expected
            .iter()
            .find(|e| e.instruction == instruction.address);
        let call = b.first() == Some(&0xe8)
            || b.first() == Some(&0xff) && b.get(1).is_some_and(|m| m & 0x38 == 0x10);
        let tail = b.first() == Some(&0xe9)
            || b.first() == Some(&0xff) && b.get(1).is_some_and(|m| m & 0x38 == 0x20);
        if call || tail {
            let resolved = if b.first().is_some_and(|v| matches!(v, 0xe8 | 0xe9)) {
                Some(fixed_rip_target(instruction.address, b, 1, 5)?)
            } else if b.starts_with(&[0xff, 0x15]) || b.starts_with(&[0xff, 0x25]) {
                let slot = fixed_rip_target(instruction.address, b, 2, 6)?;
                Some(
                    *got.get(&slot)
                        .ok_or("Fixed census unchecked indirect slot")?,
                )
            } else {
                None
            };
            if let Some(edge) = edge {
                require(
                    resolved.is_none_or(|target| target == edge.target)
                        && covered.insert(edge.instruction),
                    "Fixed transfer census differs from whole recipe",
                )?;
                if b == &[0xff, 0xd0] {
                    require(
                        edge.local_got_slot.is_some() || edge.target != 0,
                        "Fixed register call lacks typed whole-recipe origin",
                    )?;
                }
            } else if tail
                && (resolved.is_some_and(|target| target >= address && target < end)
                    || (b == &[0xff, 0xe0] && internal_switch))
            {
            } else {
                return Err(format!(
                    "Fixed whole recipe omits an actual transfer: function {address:#x}, instruction {:#x}, bytes {}",
                    instruction.address,
                    b.iter()
                        .map(|byte| format!("{byte:02x}"))
                        .collect::<String>()
                ));
            }
        } else {
            require(
                edge.is_none(),
                "Fixed recipe names a nontransfer instruction",
            )?;
        }
    }
    require(
        covered.len() == expected.len(),
        "Fixed transfer proof names missing/duplicate actual instructions",
    )
}
fn fixed_tls_transfers(
    role: &str,
    symbol: &sym::Sym,
    instructions: &[EncodedConstructorInstruction],
    tls: &AllocatorTlsBoundary,
    got: &BTreeMap<u64, u64>,
) -> Result<Vec<ConstructorTransfer>> {
    require(
        tls.local_chain
            .get(role)
            .is_some_and(|s| s.address == symbol.st_value && s.size == symbol.st_size),
        "TLS operation role is outside the complete qualified local chain",
    )?;
    let mut edges = Vec::new();
    for instruction in instructions {
        let b = &instruction.bytes;
        if b.first().is_some_and(|v| matches!(v, 0xe8 | 0xe9)) {
            let target = fixed_rip_target(instruction.address, b, 1, 5)?;
            if target >= symbol.st_value && target < symbol.st_value + symbol.st_size {
                continue;
            }
            if target == tls.plt_address {
                require(
                    tls.callsites
                        .iter()
                        .any(|e| e.instruction == instruction.address && e.target == target),
                    "TLS boundary callsite differs",
                )?;
            }
            edges.push(ConstructorTransfer {
                instruction: instruction.address,
                target,
                local_got_slot: None,
            });
        } else if b.starts_with(&[0xff, 0x15]) || b.starts_with(&[0xff, 0x25]) {
            let slot = fixed_rip_target(instruction.address, b, 2, 6)?;
            edges.push(ConstructorTransfer {
                instruction: instruction.address,
                target: *got
                    .get(&slot)
                    .ok_or("TLS local closure has unchecked GOT target")?,
                local_got_slot: Some(slot),
            });
        } else if b == &[0xff, 0x10] {
            // Actual dev try_with calls the function pointer stored in the
            // incoming immutable LocalKey: CALL [RAX], not CALL RAX. Its full
            // prefix/whole function and LocalKey RELATIVE target were already
            // authenticated by qualify_allocator_tls_boundary. This form is
            // not permission for another memory/register-indirect call.
            let key = tls
                .local_key_object
                .ok_or("TLS memory call lacks its readonly LocalKey object")?;
            let getter = tls
                .local_chain
                .get("fixed_tls_fn_once")
                .ok_or("TLS LocalKey lacks its exact typed FnOnce target")?;
            let edge = tls
                .local_key_transfer
                .as_ref()
                .filter(|e| e.instruction == instruction.address)
                .ok_or("TLS memory call lacks exact readonly local key proof")?;
            require(
                role == "fixed_tls_try_with"
                    && symbol.st_value.checked_add(0x15) == Some(instruction.address)
                    && tls.local_key_resolution.as_deref()
                        == Some("local_relative_readonly_function_pointer")
                    && getter.address != 0
                    && edge.target == getter.address
                    && edge.local_got_slot.is_none()
                    && got.get(&key) == Some(&getter.address),
                "TLS memory call differs from its exact LocalKey/typed getter proof",
            )?;
            edges.push(edge.clone());
        }
    }
    Ok(edges)
}
#[derive(Clone, Debug, PartialEq, Eq, Serialize, Deserialize)]
#[serde(deny_unknown_fields)]
pub struct FixedGuardedTerminal {
    pub caller_role: String,
    pub terminal_role: String,
    pub premise: String,
    pub transfer: ConstructorTransfer,
}
// A witness exists only after a complete typed recipe and actual transfer census.
// It is private and derived again during physical ELF requalification.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
enum AuthenticatedDetcoreOperationKind {
    ValidateTemplate(usize),
    NativeFixedSyscall3,
    NativeFixedSyscall6,
}
struct AuthenticatedDetcoreOperation {
    role: String,
    address: u64,
    kind: AuthenticatedDetcoreOperationKind,
    edges: Vec<ConstructorTransfer>,
}

fn fixed_detcore_qualified_operation(
    role: &str,
    address: u64,
    (bytes, instructions): (&[u8], &[EncodedConstructorInstruction]),
    bindings: DetcoreRecipeBindings<'_>,
    tls_cell_offset: u64,
    internal_switch: bool,
) -> Result<AuthenticatedDetcoreOperation> {
    let got = bindings.got;
    let recipe =
        fixed_detcore_validate_recipe_identity(role, address, bytes, bindings, tls_cell_offset)?;
    fixed_census_transfers(
        instructions,
        address,
        bytes,
        &recipe.edges,
        got,
        internal_switch,
    )?;
    Ok(AuthenticatedDetcoreOperation {
        role: role.into(),
        address,
        kind: AuthenticatedDetcoreOperationKind::ValidateTemplate(recipe.template_index),
        edges: recipe.edges,
    })
}

// Template identities refer to the retained original0..30 and the five exact
// mapping diagnostic additions. Extents and receipt labels are never evidence.
const DETCORE_PUBLICATION_COHORT: [(&str, usize, usize); 5] = [
    ("fixed_constructor_prepare", 28, 31),
    ("fixed_generic_prepare", 22, 32),
    ("fixed_region_publication_set", 21, 33),
    ("fixed_tool_dealloc", 18, 34),
    ("fixed_tool_realloc", 11, 35),
];

fn fixed_detcore_publication_cohort(
    witnesses: &BTreeMap<String, AuthenticatedDetcoreOperation>,
    transfers: &BTreeMap<String, Vec<ConstructorTransfer>>,
    selected: &BTreeMap<String, u64>,
    targets: &BTreeMap<String, u64>,
) -> Result<()> {
    let mut addresses = BTreeSet::new();
    for &(role, old, new) in &DETCORE_PUBLICATION_COHORT {
        let witness = witnesses
            .get(role)
            .ok_or("missing authenticated Detcore publication role")?;
        require(
            witness.role == role
                && selected.get(role) == Some(&witness.address)
                && targets.get(role) == Some(&witness.address)
                && transfers.get(role) == Some(&witness.edges),
            "Detcore publication witness loses its actual role/address/transfers",
        )?;
        require(
            witness.address != 0 && addresses.insert(witness.address),
            "aliased Detcore publication roles",
        )?;
        require(
            matches!(witness.kind, AuthenticatedDetcoreOperationKind::ValidateTemplate(index)
                if (index == old || index == new) && DETCORE_VALIDATE_TEMPLATES[index].role == role),
            "unknown authenticated Detcore publication variant",
        )?;
    }
    let old = DETCORE_PUBLICATION_COHORT.iter().all(|(role, index, _)| {
        witnesses[*role].kind == AuthenticatedDetcoreOperationKind::ValidateTemplate(*index)
    });
    let new = DETCORE_PUBLICATION_COHORT.iter().all(|(role, _, index)| {
        witnesses[*role].kind == AuthenticatedDetcoreOperationKind::ValidateTemplate(*index)
    });
    let keyed_normal = DETCORE_PUBLICATION_COHORT
        .iter()
        .zip([31, 32, 33, 18, 11])
        .all(|((role, _, _), index)| {
            witnesses[*role].kind == AuthenticatedDetcoreOperationKind::ValidateTemplate(index)
        });
    require(
        old || new || keyed_normal,
        "mixed authenticated Detcore publication family",
    )?;
    let region = *targets
        .get("fixed_region")
        .ok_or("Detcore publication REGION absent")?;
    require(
        region != 0
            && targets.get("fixed_region_ready").copied() == region.checked_add(24)
            && targets.get("fixed_region_value16").copied() == region.checked_add(16),
        "Detcore publication loses its exact REGION fields",
    )?;
    let setter = witnesses["fixed_region_publication_set"].address;
    let pc = if old { 114 } else { 125 };
    let mut incoming = BTreeSet::new();
    for (role, edges) in transfers {
        for edge in edges.iter().filter(|edge| edge.target == setter) {
            require(
                role == "fixed_constructor_prepare" || role == "fixed_generic_prepare",
                "unexpected qualified Detcore setter caller",
            )?;
            let caller = &witnesses[role];
            require(
                edge.instruction
                    == caller
                        .address
                        .checked_add(pc)
                        .ok_or("Detcore setter edge overflow")?
                    && edge.local_got_slot.is_none()
                    && incoming.insert(role.as_str()),
                "duplicate or shifted Detcore setter edge",
            )?;
        }
    }
    require(
        incoming == BTreeSet::from(["fixed_constructor_prepare", "fixed_generic_prepare"]),
        "missing qualified Detcore setter edge",
    )?;
    // Full caller/setter templates prove RSI=payload plus global REGION (old),
    // or RSI=the typed REGION and RDX=payload (new), at these actual callsites.
    Ok(())
}

// Private whole-body/census witnesses; never serialized or caller-authored.
#[derive(Clone, Copy, PartialEq, Eq)]
enum FixedNormalReturnIdentity {
    Caller291,
    Setup247,
    OtherSetup,
}
struct AuthenticatedFixedNormalReturn {
    role: String,
    address: u64,
    identity: FixedNormalReturnIdentity,
    edges: Vec<ConstructorTransfer>,
}

fn fixed_normal_return_qualified_operation(
    role: &str,
    address: u64,
    (bytes, instructions): (&[u8], &[EncodedConstructorInstruction]),
    targets: &BTreeMap<String, u64>,
    got: &BTreeMap<u64, u64>,
    readonly: &BTreeMap<u64, Vec<u8>>,
) -> Result<Option<AuthenticatedFixedNormalReturn>> {
    let (identity, edges) = if role == "fixed_native_from_native" {
        let matching: Vec<_> = FIXED_WRAPPER_RECIPES
            .iter()
            .chain(PUBLICATION_WRAPPER_RECIPES)
            .filter(|recipe| {
                recipe.role == role
                    && fixed_template_shape(
                        bytes,
                        &fixed_hex(recipe.hex),
                        recipe.operands.iter().map(|op| op.displacement),
                    )
            })
            .collect();
        if !matching
            .iter()
            .any(|recipe| recipe.hex == FIXED_NORMAL_FROM_NATIVE_291)
        {
            return Ok(None); // Pre-existing caller contracts acquire no new restriction.
        }
        require(matching.len() == 1, "ambiguous new normal caller identity")?;
        (
            FixedNormalReturnIdentity::Caller291,
            fixed_wrapper_recipe(role, address, bytes, targets, got, readonly)?,
        )
    } else if role == "fixed_arena_setup" {
        let edges = fixed_arena_recipe(role, address, bytes, targets, got)?;
        let matching: Vec<_> = FIXED_ARENA_TEMPLATES
            .iter()
            .filter(|template| {
                template.role == role
                    && fixed_template_shape(
                        bytes,
                        template.bytes,
                        template.operands.iter().map(|op| op.displacement),
                    )
            })
            .collect();
        require(
            matching.len() == 1,
            "ambiguous qualified normal setup identity",
        )?;
        let identity = if matching[0].bytes == FIXED_ARENA_BYTES_10 {
            FixedNormalReturnIdentity::Setup247
        } else {
            FixedNormalReturnIdentity::OtherSetup
        };
        (identity, edges)
    } else {
        return Ok(None);
    };
    fixed_census_transfers(instructions, address, bytes, &edges, got, false)?;
    Ok(Some(AuthenticatedFixedNormalReturn {
        role: role.into(),
        address,
        identity,
        edges,
    }))
}

fn fixed_normal_return_contract(
    witnesses: &BTreeMap<String, AuthenticatedFixedNormalReturn>,
    transfers: &BTreeMap<String, Vec<ConstructorTransfer>>,
    selected: &BTreeMap<String, u64>,
    targets: &BTreeMap<String, u64>,
) -> Result<()> {
    let Some(caller) = witnesses.get("fixed_native_from_native") else {
        return Ok(()); // Conditional only on the additional authenticated291 body.
    };
    require(
        caller.identity == FixedNormalReturnIdentity::Caller291,
        "unknown authenticated new normal caller",
    )?;
    let setup = witnesses
        .get("fixed_arena_setup")
        .filter(|setup| setup.identity == FixedNormalReturnIdentity::Setup247)
        .ok_or("new normal caller lacks authenticated canonical normal247 setup")?;
    for (role, witness) in [
        ("fixed_native_from_native", caller),
        ("fixed_arena_setup", setup),
    ] {
        require(
            witness.role == role
                && witness.address != 0
                && selected.get(role) == Some(&witness.address)
                && targets.get(role) == Some(&witness.address)
                && transfers.get(role) == Some(&witness.edges),
            "normal return witness loses its actual role/address/transfers",
        )?;
    }
    let region = *targets
        .get("fixed_region")
        .ok_or("normal return REGION absent")?;
    let initializing = *targets
        .get("fixed_initializing")
        .ok_or("normal return INITIALIZING absent")?;
    require(
        region != 0
            && initializing != 0
            && BTreeSet::from([caller.address, setup.address, region, initializing]).len() == 4,
        "normal return receiver/function identities alias",
    )?;
    let setup_pc = caller
        .address
        .checked_add(269)
        .ok_or("normal setup call PC overflow")?;
    let incoming: Vec<_> = caller
        .edges
        .iter()
        .filter(|edge| edge.target == setup.address)
        .collect();
    require(
        incoming.len() == 1
            && incoming[0].instruction == setup_pc
            && incoming[0].local_got_slot.is_none(),
        "new normal caller lacks unique exact direct setup edge",
    )?;
    // Full291 bytes prove the fixed control receiver, payload and EDX error store.
    // Full247 bytes prove EBX literal1, success XOR EBX,EBX and the sole full
    // EAX/EDX epilogue. Its six actual bitmap/syscall edges remain recursively
    // qualified by the production closure; no enum, extent or source type is ABI proof.
    Ok(())
}

struct FixedOperationClosure {
    transfers: BTreeMap<String, Vec<ConstructorTransfer>>,
    guarded: BTreeMap<String, FixedGuardedTerminal>,
}
// The finite pair table describes exact unreachable arms of these complete
// recipes. It grants no permission to execute panic/libunwind/foreign callees.
// Caller validity is the existing GlobalAlloc contract, not hostile-memory
// isolation. The actual instruction/data predicates remain immutable above.
fn qualify_fixed_operation_closure(
    elf: &Elf<'_>,
    (code, disassembly): (&BTreeMap<u64, Vec<u8>>, &str),
    got: &BTreeMap<u64, u64>,
    roles: &BTreeMap<String, sym::Sym>,
    context: &FixedMachineContext,
    tls: &AllocatorTlsBoundary,
    (image_kind, _sources): (FixedImageKind, Option<&VerifiedCompiledSources>),
) -> Result<FixedOperationClosure> {
    let mut pending = FIXED_REQUIRED_ROLES
        .iter()
        .map(|role| roles[*role].st_value)
        .collect::<Vec<_>>();
    if let Some(layout) = roles.get("fixed_compiler_layout") {
        pending.push(layout.st_value);
    }
    for &required in FIXED_PUBLICATION_REQUIRED_ROLES {
        pending.push(
            roles
                .get(required)
                .ok_or_else(|| format!("mandatory publication whole role {required} absent"))?
                .st_value,
        );
    }
    if image_kind == FixedImageKind::Detcore {
        for shim in SHIMS {
            pending.push(
                roles
                    .get(shim)
                    .ok_or("Detcore mandatory compiler shim role absent")?
                    .st_value,
            );
        }
    }
    if let Some(native) = &context.native_syscalls {
        // Both finite branches need their own actual instruction census even
        // when one wrapper is not on the compiler operation's shortest path.
        pending.extend(
            native
                .evidence
                .wrappers
                .values()
                .map(|w| w.function.address),
        );
    }
    let mut done = BTreeSet::new();
    let mut transfers = BTreeMap::new();
    let mut guarded = BTreeMap::new();
    let mut detcore_witnesses = BTreeMap::new();
    let mut normal_return_witnesses = BTreeMap::new();
    let trusted = private_function(elf, CONSTRUCTOR_GATE_OWNER)?;
    constructor_gate_operands(
        code.get(&trusted.st_value)
            .ok_or("Fixed trusted gate lacks full actual bytes")?,
        0x20,
        0x22,
    )?;
    while let Some(address) = pending.pop() {
        if !done.insert(address) {
            continue;
        }
        let aliases: Vec<_> = roles
            .iter()
            .filter(|(_, s)| s.st_value == address)
            .collect();
        require(
            !aliases.is_empty(),
            "Fixed closure reaches an unselected typed function",
        )?;
        let actual = code
            .get(&address)
            .ok_or("Fixed closure lacks complete emitted function")?;
        let instructions = constructor_instructions(disassembly, address)?;
        let internal_switch = FIXED_READONLY_SPECS.iter().any(|spec| {
            spec.kind == "switch"
                && context.targets.get(spec.owner) == Some(&address)
                && context.readonly_evidence.contains_key(spec.key)
        });
        let mut chosen = None;
        let mut errors = Vec::new();
        for (role, symbol) in aliases {
            if let Some(native) = &context.native_syscalls {
                if role == FIXED_NATIVE_OWNER {
                    require(
                        symbol.st_value == native.evidence.owner.address
                            && symbol.st_size == native.evidence.owner.size,
                        "native fixed owner loses its selected complete identity",
                    )?;
                    fixed_native_owner_census(actual, &instructions, &native.evidence)?;
                    chosen = Some((role.clone(), vec![native.evidence.page_transfer.clone()]));
                    break;
                }
                if let Some(wrapper) = native.evidence.wrappers.get(role) {
                    let edges = vec![
                        wrapper.fixed_transfer.clone(),
                        wrapper.legacy_transfer.clone(),
                    ];
                    fixed_census_transfers(&instructions, address, actual, &edges, got, false)?;
                    let kind = if role == FIXED_NATIVE_RAW6 {
                        AuthenticatedDetcoreOperationKind::NativeFixedSyscall6
                    } else {
                        AuthenticatedDetcoreOperationKind::NativeFixedSyscall3
                    };
                    require(
                        detcore_witnesses
                            .insert(
                                role.clone(),
                                AuthenticatedDetcoreOperation {
                                    role: role.clone(),
                                    address,
                                    kind,
                                    edges: edges.clone(),
                                },
                            )
                            .is_none(),
                        "duplicate native syscall witness",
                    )?;
                    chosen = Some((role.clone(), edges));
                    break;
                }
            }
            if image_kind == FixedImageKind::Detcore && address != trusted.st_value {
                match fixed_detcore_qualified_operation(
                    role,
                    address,
                    (actual, &instructions),
                    DetcoreRecipeBindings {
                        targets: &context.targets,
                        got,
                        readonly: &context.readonly,
                        context: &context.compiled_filenames,
                    },
                    tls.tls_cell.address,
                    internal_switch,
                ) {
                    Ok(witness) => {
                        chosen = Some((role.clone(), witness.edges.clone()));
                        require(
                            detcore_witnesses.insert(role.clone(), witness).is_none(),
                            "duplicate authenticated Detcore operation role",
                        )?;
                        break;
                    }
                    Err(error) => errors.push(format!("{role}: {error}")),
                }
                continue;
            }
            let attempts = if image_kind == FixedImageKind::Detcore {
                vec![fixed_detcore_validate_recipe(
                    role,
                    address,
                    actual,
                    DetcoreRecipeBindings {
                        targets: &context.targets,
                        got,
                        readonly: &context.readonly,
                        context: &context.compiled_filenames,
                    },
                    tls.tls_cell.address,
                )]
            } else {
                vec![
                    fixed_wrapper_recipe(
                        role,
                        address,
                        actual,
                        &context.targets,
                        got,
                        &context.readonly,
                    ),
                    fixed_arena_recipe(role, address, actual, &context.targets, got),
                    dev_fixed_heap_recipe(
                        role,
                        address,
                        actual,
                        &context.targets,
                        got,
                        &context.readonly,
                    ),
                    fixed_release_heap_recipe(
                        role,
                        address,
                        actual,
                        &context.targets,
                        got,
                        &context.readonly,
                    ),
                    fixed_scalar_helper_recipe(role, address, actual, got, trusted.st_value),
                ]
            };
            let mut valid = None;
            for attempt in attempts {
                match attempt {
                    Ok(edges) => {
                        valid = Some(edges);
                        break;
                    }
                    Err(error) => errors.push(format!("{role}: {error}")),
                }
            }
            if let Some(edges) = valid {
                chosen = Some((role.clone(), edges));
                break;
            }
            if image_kind == FixedImageKind::Standalone
                && tls
                    .local_chain
                    .get(role)
                    .is_some_and(|s| s.address == address && s.size == symbol.st_size)
            {
                match fixed_tls_transfers(role, symbol, &instructions, tls, got) {
                    Ok(edges) => {
                        chosen = Some((role.clone(), edges));
                        break;
                    }
                    Err(error) => errors.push(error),
                }
            }
            if address == trusted.st_value {
                constructor_gate_operands(actual, 0x20, 0x22)?;
                chosen = Some((role.clone(), Vec::new()));
                break;
            }
        }
        let (role, edges) = chosen.ok_or_else(|| {
            format!(
                "unsupported whole Fixed operation/helper at {address:#x}: {}",
                errors.join("; ")
            )
        })?;
        let native_leaf = context.native_syscalls.as_ref().filter(|native| {
            role == FIXED_NATIVE_OWNER && address == native.evidence.owner.address
        });
        if let Some(native) = native_leaf {
            fixed_native_owner_census(actual, &instructions, &native.evidence)?;
        } else {
            fixed_census_transfers(&instructions, address, actual, &edges, got, internal_switch)
                .map_err(|error| format!("Fixed role {role} at {address:#x}: {error}"))?;
        }
        let normal_return_witness = if image_kind == FixedImageKind::Standalone {
            fixed_normal_return_qualified_operation(
                &role,
                address,
                (actual, &instructions),
                &context.targets,
                got,
                &context.readonly,
            )?
        } else {
            None
        };
        if let Some(witness) = normal_return_witness {
            require(
                normal_return_witnesses
                    .insert(role.clone(), witness)
                    .is_none(),
                "duplicate authenticated normal return role",
            )?;
        }
        for edge in &edges {
            if let Some(native) = native_leaf {
                require(
                    edge == &native.evidence.page_transfer && edges.len() == 1,
                    "native fixed owner has an unqualified leaf transfer",
                )?;
                continue;
            }
            if edge.target == tls.plt_address {
                require(
                    tls.callsites.iter().any(|actual| actual == edge),
                    "Fixed allocator adds an unproved external TLS call",
                )?;
                continue;
            }
            let target_aliases: Vec<_> = roles
                .iter()
                .filter(|(_, s)| s.st_value == edge.target)
                .map(|(role, _)| role.as_str())
                .collect();
            require(
                !target_aliases.is_empty(),
                format!("Fixed {role} calls unselected target {:#x}", edge.target),
            )?;
            if let Some(&(caller, terminal, premise)) = fixed_guarded_terminal_pairs(image_kind)
                .iter()
                .find(|&&(caller, terminal, _)| {
                    caller == role && target_aliases.contains(&terminal)
                })
            {
                let key = format!(
                    "{role}+{:#x}",
                    edge.instruction
                        .checked_sub(address)
                        .ok_or("Fixed guard call precedes function")?
                );
                require(
                    guarded
                        .insert(
                            key,
                            FixedGuardedTerminal {
                                caller_role: caller.into(),
                                terminal_role: terminal.into(),
                                premise: premise.into(),
                                transfer: edge.clone(),
                            },
                        )
                        .is_none(),
                    "duplicate Fixed guarded terminal edge",
                )?;
            } else {
                pending.push(edge.target);
            }
        }
        require(
            transfers.insert(role, edges).is_none(),
            "Fixed closure role aliases conflicting functions",
        )?;
    }
    require(
        FIXED_REQUIRED_ROLES
            .iter()
            .all(|role| transfers.contains_key(*role)),
        "Fixed closure omits a compiler operation or fresh setup",
    )?;
    if image_kind == FixedImageKind::Detcore {
        let selected = roles
            .iter()
            .map(|(role, symbol)| (role.clone(), symbol.st_value))
            .collect();
        fixed_detcore_publication_cohort(
            &detcore_witnesses,
            &transfers,
            &selected,
            &context.targets,
        )?;
    }
    if image_kind == FixedImageKind::Standalone {
        let selected = roles
            .iter()
            .map(|(role, symbol)| (role.clone(), symbol.st_value))
            .collect();
        fixed_normal_return_contract(
            &normal_return_witnesses,
            &transfers,
            &selected,
            &context.targets,
        )?;
    }
    Ok(FixedOperationClosure { transfers, guarded })
}

// Retained Legacy discovery/parser predicate only. Candidate admission and
// inline routes require exact typed Fixed roles, never this shared endpoint.
fn qualifies_owned_endpoint(name: &str) -> bool {
    let name = name.split(".llvm.").next().unwrap_or(name);
    ((name.contains("PrivatePatchAllocator") || name.contains("PrivateToolAllocator"))
        && name.contains("GlobalAlloc")
        && (name.ends_with("5alloc") || name.ends_with("12alloc_zeroed")))
        || (name.contains("ToolHeap") && name.ends_with("8allocate"))
}

fn allocation_wrapper(name: &str) -> bool {
    name.contains("allocator_fixture") && name.contains("m1_")
        || [
            "5alloc5alloc5alloc",
            "5alloc5alloc12alloc_zeroed",
            "5alloc5alloc7realloc",
            "5alloc5alloc7dealloc",
        ]
        .iter()
        .any(|pattern| name.contains(pattern))
}

fn called_shim_path(
    elf: &Elf<'_>,
    graph: &BTreeMap<u64, BTreeSet<u64>>,
    entry: u64,
    shim: u64,
) -> Result<Vec<u64>> {
    let wrappers: BTreeSet<_> = elf
        .syms
        .iter()
        .filter_map(|s| {
            elf.strtab
                .get_at(s.st_name)
                .filter(|name| allocation_wrapper(name))
                .map(|_| s.st_value)
        })
        .chain([entry, shim])
        .collect();
    // Panic/cleanup/container allocation is not evidence that the exported
    // operation's std::alloc call executes its compiler-selected shim.
    let restricted = graph
        .iter()
        .filter(|(source, _)| wrappers.contains(source))
        .map(|(source, targets)| {
            (
                *source,
                targets
                    .iter()
                    .filter(|target| wrappers.contains(target))
                    .copied()
                    .collect(),
            )
        })
        .collect();
    shortest_path(&restricted, entry, shim)
}

fn qualify_inline_route(
    key: &str,
    elf: &Elf<'_>,
    entry: &SymbolEvidence,
    shim: &SymbolEvidence,
    graph: &CallGraph,
    got_edges: &[GotEdge],
) -> Result<InlineAllocationRoute> {
    let endpoint_role = match key {
        "m1_alloc->__rust_alloc" => "fixed_patch_alloc",
        "m1_alloc->__rust_alloc_zeroed" => "fixed_patch_alloc_zeroed",
        _ => return Err("unsupported optimized allocation route".to_owned()),
    };
    let roles = fixed_role_symbols(elf)?;
    let endpoint = &roles[endpoint_role];
    let wrappers = elf
        .syms
        .iter()
        .filter(|symbol| executable_symbol(elf, symbol))
        .filter(|symbol| {
            elf.strtab
                .get_at(symbol.st_name)
                .is_some_and(allocation_wrapper)
        })
        .map(|symbol| symbol.st_value);
    let route_nodes: BTreeSet<_> = roles
        .iter()
        .filter(|(role, _)| !owned_fixed_setup_role(role))
        .map(|(_, symbol)| symbol.st_value)
        .chain(wrappers)
        .chain([entry.address, shim.address])
        .collect();
    let restricted: CallGraph = graph
        .iter()
        .filter(|(source, _)| route_nodes.contains(source))
        .map(|(source, targets)| {
            (
                *source,
                targets
                    .iter()
                    .filter(|target| route_nodes.contains(target))
                    .copied()
                    .collect(),
            )
        })
        .collect();
    let entry_to_endpoint = shortest_path(&restricted, entry.address, endpoint.st_value)?;
    let shim_to_endpoint = shortest_path(&restricted, shim.address, endpoint.st_value)?;
    require(
        entry_to_endpoint.len() >= 2 && shim_to_endpoint.len() >= 2,
        "actual export and compiler shim require distinct calls to the typed Fixed operation",
    )?;
    let path_edges = |path: &[u64]| {
        got_edges
            .iter()
            .filter(|edge| {
                path.windows(2)
                    .any(|pair| edge.source_function == pair[0] && edge.target_function == pair[1])
            })
            .cloned()
            .collect()
    };
    Ok(InlineAllocationRoute {
        entry: entry.clone(), shim: shim.clone(),
        target: symbol_evidence(elf.strtab.get_at(endpoint.st_name).unwrap(), endpoint),
        entry_got_edges: path_edges(&entry_to_endpoint),
        shim_got_edges: path_edges(&shim_to_endpoint),
        entry_to_endpoint, shim_to_endpoint,
        observation: "Actual export and its separately emitted LOCAL compiler shim reach the same exact typed Fixed operation. A shared heap algorithm or Legacy/System endpoint cannot satisfy this route; selected spans and runtime ownership still require their independent checks.".to_owned(),
    })
}

fn executable_symbol(elf: &Elf<'_>, s: &sym::Sym) -> bool {
    s.st_type() == sym::STT_FUNC
        && s.st_shndx != section_header::SHN_UNDEF as usize
        && s.st_value != 0
        && s.st_size > 0
        && elf.program_headers.iter().any(|p| {
            p.p_type == program_header::PT_LOAD
                && p.p_flags & program_header::PF_X != 0
                && s.st_value >= p.p_vaddr
                && s.st_value
                    .checked_add(s.st_size)
                    .is_some_and(|end| end <= p.p_vaddr.saturating_add(p.p_memsz))
        })
}

fn symbol_evidence(name: &str, s: &sym::Sym) -> SymbolEvidence {
    SymbolEvidence {
        name: name.to_owned(),
        address: s.st_value,
        size: s.st_size,
        binding: s.st_bind(),
        visibility: s.st_visibility(),
    }
}

fn export(elf: &Elf<'_>, name: &str) -> Result<(usize, sym::Sym)> {
    let candidates: Vec<_> = elf
        .dynsyms
        .iter()
        .enumerate()
        .filter(|(_, s)| elf.dynstrtab.get_at(s.st_name) == Some(name) && executable_symbol(elf, s))
        .collect();
    require(
        candidates.len() == 1,
        format!("required unique defined dynamic function {name} is absent/ambiguous"),
    )?;
    let (index, s) = candidates[0];
    require(
        s.st_bind() == sym::STB_GLOBAL
            && matches!(s.st_visibility(), sym::STV_DEFAULT | sym::STV_PROTECTED),
        format!("required function {name} is not externally exported"),
    )?;
    Ok((index, s))
}

fn private_function(elf: &Elf<'_>, name: &str) -> Result<sym::Sym> {
    let candidates: Vec<_> =
        elf.syms
            .iter()
            .filter(|s| elf.strtab.get_at(s.st_name) == Some(name) && executable_symbol(elf, s))
            .chain(elf.dynsyms.iter().filter(|s| {
                elf.dynstrtab.get_at(s.st_name) == Some(name) && executable_symbol(elf, s)
            }))
            .collect();
    require(
        !candidates.is_empty(),
        format!("missing private constructor function {name}"),
    )?;
    let first = candidates[0];
    require(
        candidates.iter().all(|s| {
            s.st_value == first.st_value
                && s.st_size == first.st_size
                && private_constructor_binding(s.st_bind(), s.st_visibility())
        }),
        format!("constructor function {name} is ambiguous/preemptible"),
    )?;
    Ok(first)
}

const FIXED_NATIVE_SELECTOR: &str =
    "_RNvNtNtNtCs_15reverie_inguest5guest11tool_region11constructor11native_gate";
const FIXED_NATIVE_PUBLICATION: &str = "reverie_inguest_fixed_gates_published";
const FIXED_NATIVE_TEMPLATE: &str = "reverie_inguest_fixed_gate_template";
const FIXED_NATIVE_TEMPLATE_END: &str = "reverie_inguest_fixed_gate_template_end";
const FIXED_NATIVE_ENTRY: u64 = 0x5000_0000_007c;
const FIXED_NATIVE_SELECTOR_HEX: &str =
    "f30f1efa488b0d00000000e30d49bb7c0000000050000041ffe3e900000000";

/// Complete actual selector/data evidence, not publication or page installation.
#[derive(Clone, Debug, PartialEq, Eq, Serialize, Deserialize)]
#[serde(deny_unknown_fields)]
pub struct FixedNativeGateEvidence {
    pub version: u32,
    pub selector: SymbolEvidence,
    pub selector_sha256: String,
    pub publication: SymbolEvidence,
    pub publication_storage: String,
    pub publication_read_instruction: u64,
    pub unpublished_transfer: ConstructorTransfer,
    pub published_transfer_instruction: u64,
    pub fixed_entry: u64,
    pub template_symbol: SymbolEvidence,
    pub template_bytes: FixedReadonlyEvidence,
}
impl FixedNativeGateEvidence {
    /// Compare the actual qualifier's page record to a successfully compiled
    /// bootstrap page. This shape/equality check grants no ELF/runtime authority.
    pub fn verify_bootstrap_page_digest(&self, actual_gate_digest: &[u8; 32]) -> Result<()> {
        require(
            self.version == 1
                && self.fixed_entry == FIXED_NATIVE_ENTRY
                && self.template_symbol.size == 4096
                && self.template_bytes.size == 4096
                && self.template_symbol.address == self.template_bytes.address
                && self.template_bytes.file_address.is_none()
                && self.template_bytes.file_sha256.is_none()
                && self.template_bytes.relative_pointer_slot.is_none(),
            "fixed native page record version/address/shape differs",
        )?;
        require(
            fixed_native_digest(&self.template_bytes.sha256)? == *actual_gate_digest,
            "fixed native DSO and compiled bootstrap page digests differ",
        )
    }
}
fn fixed_native_digest(hex: &str) -> Result<[u8; 32]> {
    require(
        hex.len() == 64 && hex.bytes().all(|b| b.is_ascii_hexdigit()),
        "fixed native digest is not a complete SHA256",
    )?;
    let mut result = [0_u8; 32];
    for (index, word) in hex.as_bytes().as_chunks::<2>().0.iter().enumerate() {
        result[index] =
            u8::from_str_radix(std::str::from_utf8(word).map_err(|e| e.to_string())?, 16)
                .map_err(|e| e.to_string())?;
    }
    Ok(result)
}
fn fixed_native_selector_name(name: &str) -> bool {
    // Count malformed LLVM-suffixed definitions too, before checking their
    // shape. A third/zero-sized/dynamic candidate cannot vanish in a filter.
    canonical_rust_symbol(name.split(".llvm.").next().unwrap())
        .is_some_and(|name| name == FIXED_NATIVE_SELECTOR)
}
// Native roles additionally bind their symbol's declared file-backed code
// section to the whole actual RX load span. Loader bytes alone cannot make an
// unrelated/non-file section index authentic source-role metadata.
fn fixed_native_function_section(elf: &Elf<'_>, symbol: &sym::Sym) -> Result<()> {
    require(
        symbol.st_shndx > section_header::SHN_UNDEF as usize
            && symbol.st_shndx < section_header::SHN_LORESERVE as usize,
        "native function has an undefined/reserved section index",
    )?;
    let section = elf
        .section_headers
        .get(symbol.st_shndx)
        .ok_or("native function section index is absent/reserved")?;
    let end = symbol
        .st_value
        .checked_add(symbol.st_size)
        .ok_or("native function extent overflow")?;
    let section_end = section
        .sh_addr
        .checked_add(section.sh_size)
        .ok_or("native function section address extent overflow")?;
    let section_file_end = section
        .sh_offset
        .checked_add(section.sh_size)
        .ok_or("native function section file extent overflow")?;
    require(
        symbol.st_size != 0
            && section.sh_type == section_header::SHT_PROGBITS
            && section.sh_flags
                & u64::from(
                    section_header::SHF_ALLOC
                        | section_header::SHF_EXECINSTR
                        | section_header::SHF_WRITE
                        | section_header::SHF_TLS,
                )
                == u64::from(section_header::SHF_ALLOC | section_header::SHF_EXECINSTR)
            && symbol.st_value >= section.sh_addr
            && end <= section_end,
        "native function is not wholly in its declared file-backed executable section",
    )?;
    let section_offset = section
        .sh_offset
        .checked_add(symbol.st_value - section.sh_addr)
        .ok_or("native function section file offset overflow")?;
    let section_symbol_end = section_offset
        .checked_add(symbol.st_size)
        .ok_or("native function section file range overflow")?;
    require(
        section_symbol_end <= section_file_end,
        "native function escapes its complete section file span",
    )?;
    let page_start = symbol.st_value & !4095;
    let page_end = end
        .checked_add(4095)
        .ok_or("native function pages overflow")?
        & !4095;
    let mut mappings = Vec::new();
    for mapping in elf
        .program_headers
        .iter()
        .filter(|p| p.p_type == program_header::PT_LOAD)
    {
        let memory_end = mapping
            .p_vaddr
            .checked_add(mapping.p_memsz)
            .ok_or("native function load memory range overflow")?;
        let mapped_page_end = memory_end
            .checked_add(4095)
            .ok_or("native function load pages overflow")?
            & !4095;
        if (mapping.p_vaddr & !4095) < page_end && mapped_page_end > page_start {
            mappings.push(mapping);
        }
    }
    require(
        mappings.len() == 1,
        "native function section lacks its unique actual page mapping",
    )?;
    let mapping = mappings[0];
    let file_virtual_end = mapping
        .p_vaddr
        .checked_add(mapping.p_filesz)
        .ok_or("native function load file address range overflow")?;
    let file_end = mapping
        .p_offset
        .checked_add(mapping.p_filesz)
        .ok_or("native function load file offset range overflow")?;
    require(
        mapping.p_flags == program_header::PF_R | program_header::PF_X
            && mapping.p_filesz <= mapping.p_memsz
            && mapping.p_offset % 4096 == mapping.p_vaddr % 4096
            && symbol.st_value >= mapping.p_vaddr
            && end <= file_virtual_end,
        "native function section does not match its whole file-backed RX load",
    )?;
    let load_offset = mapping
        .p_offset
        .checked_add(symbol.st_value - mapping.p_vaddr)
        .ok_or("native function load file offset overflow")?;
    let load_symbol_end = load_offset
        .checked_add(symbol.st_size)
        .ok_or("native function load file span overflow")?;
    require(
        section_offset == load_offset
            && section_symbol_end == load_symbol_end
            && load_symbol_end <= file_end,
        "native function section and actual RX file offsets differ",
    )
}
fn fixed_native_selector_symbol(elf: &Elf<'_>) -> Result<Option<sym::Sym>> {
    let raw: Vec<_> = elf
        .syms
        .iter()
        .filter(|s| {
            elf.strtab
                .get_at(s.st_name)
                .is_some_and(fixed_native_selector_name)
        })
        .collect();
    let dynamic = elf.dynsyms.iter().any(|s| {
        elf.dynstrtab
            .get_at(s.st_name)
            .is_some_and(fixed_native_selector_name)
    });
    if raw.is_empty() && !dynamic {
        return Ok(None);
    }
    require(
        raw.len() == 1 && !dynamic,
        "fixed native selector raw census is ambiguous/dynamic",
    )?;
    let selected = raw[0];
    require(
        elf.strtab
            .get_at(selected.st_name)
            .and_then(canonical_rust_symbol)
            .as_deref()
            == Some(FIXED_NATIVE_SELECTOR)
            && selected.st_bind() == sym::STB_LOCAL
            && selected.st_visibility() == sym::STV_HIDDEN
            && selected.st_size == 31
            && executable_symbol(elf, &selected),
        "fixed native selector is not its unique complete local hidden function",
    )?;
    fixed_native_function_section(elf, &selected)?;
    fixed_native_no_alias(elf, &selected, None)?;
    Ok(Some(selected))
}
fn fixed_native_named_symbol(elf: &Elf<'_>, name: &str) -> Result<sym::Sym> {
    let raw: Vec<_> = elf
        .syms
        .iter()
        .filter(|s| elf.strtab.get_at(s.st_name) == Some(name))
        .collect();
    require(
        raw.len() == 1
            && !elf
                .dynsyms
                .iter()
                .any(|s| elf.dynstrtab.get_at(s.st_name) == Some(name)),
        format!("fixed native object/label {name} has ambiguous/dynamic raw identity"),
    )?;
    let selected = raw[0];
    require(
        selected.st_shndx != section_header::SHN_UNDEF as usize
            && selected.st_bind() == sym::STB_LOCAL
            && selected.st_visibility() == sym::STV_HIDDEN,
        format!("fixed native object/label {name} is not local hidden defined storage"),
    )?;
    Ok(selected)
}
fn fixed_native_no_alias(
    elf: &Elf<'_>,
    selected: &sym::Sym,
    allowed_end: Option<&str>,
) -> Result<()> {
    let end = selected
        .st_value
        .checked_add(selected.st_size)
        .ok_or("fixed native extent overflow")?;
    let selected_name = elf
        .strtab
        .get_at(selected.st_name)
        .ok_or("fixed native symbol lacks name")?;
    for (name, other) in elf
        .syms
        .iter()
        .map(|s| (elf.strtab.get_at(s.st_name), s))
        .chain(
            elf.dynsyms
                .iter()
                .map(|s| (elf.dynstrtab.get_at(s.st_name), s)),
        )
    {
        if other.st_shndx == section_header::SHN_UNDEF as usize
            || !matches!(
                other.st_type(),
                sym::STT_FUNC
                    | sym::STT_OBJECT
                    | sym::STT_TLS
                    | sym::STT_NOTYPE
                    | sym::STT_GNU_IFUNC
            )
            || name == Some(selected_name)
            || (allowed_end.is_some()
                && name == allowed_end
                && other.st_value == end
                && other.st_size == 0)
        {
            continue;
        }
        let other_end = other
            .st_value
            .checked_add(other.st_size)
            .ok_or("fixed native alias overflow")?;
        require(
            if other.st_size == 0 {
                other.st_value < selected.st_value || other.st_value >= end
            } else {
                other_end <= selected.st_value || other.st_value >= end
            },
            "fixed native role has a conflicting entry/storage alias",
        )?;
    }
    Ok(())
}
fn add_fixed_native_selector(
    elf: &Elf<'_>,
    symbols: &mut BTreeMap<String, sym::Sym>,
) -> Result<()> {
    if let Some(selector) = fixed_native_selector_symbol(elf)? {
        require(
            symbols
                .insert(FIXED_NATIVE_SELECTOR.into(), selector)
                .is_none(),
            "duplicate fixed native role",
        )?;
    }
    Ok(())
}
fn fixed_native_publication(elf: &Elf<'_>) -> Result<sym::Sym> {
    let object = fixed_native_named_symbol(elf, FIXED_NATIVE_PUBLICATION)?;
    require(
        object.st_type() == sym::STT_OBJECT && object.st_size == 8 && object.st_value % 8 == 0,
        "fixed native publication type/size/alignment differs",
    )?;
    fixed_native_no_alias(elf, &object, None)?;
    let end = object
        .st_value
        .checked_add(8)
        .ok_or("fixed publication extent overflow")?;
    let section = elf
        .section_headers
        .get(object.st_shndx)
        .ok_or("fixed publication section absent")?;
    require(
        section.sh_type == section_header::SHT_NOBITS
            && section.sh_flags == (section_header::SHF_ALLOC | section_header::SHF_WRITE) as u64
            && elf.shdr_strtab.get_at(section.sh_name) == Some(".bss")
            && object.st_value >= section.sh_addr
            && section
                .sh_addr
                .checked_add(section.sh_size)
                .is_some_and(|hi| end <= hi),
        "fixed publication is not complete non-TLS BSS storage",
    )?;
    let loads: Vec<_> = elf
        .program_headers
        .iter()
        .filter(|p| {
            p.p_type == program_header::PT_LOAD
                && object.st_value >= p.p_vaddr
                && p.p_vaddr.checked_add(p.p_memsz).is_some_and(|hi| end <= hi)
        })
        .collect();
    require(
        loads.len() == 1
            && loads[0].p_flags == program_header::PF_R | program_header::PF_W
            && loads[0]
                .p_vaddr
                .checked_add(loads[0].p_filesz)
                .is_some_and(|lo| object.st_value >= lo),
        "fixed publication is not loader-zero-initialized RW/non-X memory",
    )?;
    require(
        elf.program_headers
            .iter()
            .filter(|p| p.p_type == program_header::PT_GNU_RELRO)
            .all(|p| {
                p.p_vaddr
                    .checked_add(p.p_memsz)
                    .is_some_and(|hi| (p.p_vaddr & !4095) >= end || (hi & !4095) <= object.st_value)
            }),
        "fixed publication becomes readonly after relocation",
    )?;
    require(
        extent_writers(elf, object.st_value, 8)?.is_empty(),
        "loader writes fixed publication storage",
    )?;
    Ok(object)
}
fn qualify_fixed_native_gate(
    elf: &Elf<'_>,
    bytes: &[u8],
    code: &BTreeMap<u64, Vec<u8>>,
    legacy_gate: u64,
) -> Result<Option<FixedNativeGateEvidence>> {
    let Some(selector) = fixed_native_selector_symbol(elf)? else {
        return Ok(None);
    };
    authenticate_loader_metadata(elf, bytes)?;
    let actual = proof_function_bytes(
        elf,
        bytes,
        &BTreeMap::from([(selector.st_value, selector.st_size)]),
    )?;
    let selector_bytes = actual
        .get(&selector.st_value)
        .ok_or("fixed selector bytes absent")?;
    require(
        code.get(&selector.st_value) == Some(selector_bytes),
        "fixed selector is absent/changed in complete proof scope",
    )?;
    let owner = private_function(elf, CONSTRUCTOR_GATE_OWNER)?;
    let gate = constructor_interior_label(elf, CONSTRUCTOR_GATE, &owner)?;
    let ret = constructor_interior_label(elf, CONSTRUCTOR_GATE_RETURN, &owner)?;
    constructor_gate_operands(
        code.get(&owner.st_value)
            .ok_or("legacy gate owner scope absent")?,
        gate.st_value - owner.st_value,
        ret.st_value - owner.st_value,
    )?;
    require(
        gate.st_value == legacy_gate,
        "fixed route lost the independently qualified legacy gate",
    )?;
    let publication = fixed_native_publication(elf)?;
    fixed_whole_recipe(
        selector.st_value,
        selector_bytes,
        FIXED_NATIVE_SELECTOR_HEX,
        &[(7, 11, publication.st_value), (27, 31, legacy_gate)],
    )?;
    let template = fixed_native_named_symbol(elf, FIXED_NATIVE_TEMPLATE)?;
    require(
        template.st_type() == sym::STT_OBJECT
            && template.st_size == 4096
            && template.st_value % 4096 == 0,
        "fixed native template type/extent/alignment differs",
    )?;
    fixed_native_no_alias(elf, &template, Some(FIXED_NATIVE_TEMPLATE_END))?;
    let template_end = fixed_native_named_symbol(elf, FIXED_NATIVE_TEMPLATE_END)?;
    require(
        template_end.st_type() == sym::STT_NOTYPE
            && template_end.st_size == 0
            && template_end.st_value
                == template
                    .st_value
                    .checked_add(4096)
                    .ok_or("fixed page end overflow")?
            && template_end.st_shndx == template.st_shndx,
        "fixed native template end label differs",
    )?;
    let (mapping, offset) = unique_file_mapping(elf, bytes, template.st_value, 4096)?;
    let section = elf
        .section_headers
        .get(template.st_shndx)
        .ok_or("fixed native template section absent")?;
    require(
        mapping.p_flags == program_header::PF_R
            && section.sh_type == section_header::SHT_PROGBITS
            && section.sh_flags == section_header::SHF_ALLOC as u64
            && template.st_value >= section.sh_addr
            && section
                .sh_addr
                .checked_add(section.sh_size)
                .is_some_and(|hi| template_end.st_value <= hi)
            && section
                .sh_offset
                .checked_add(template.st_value - section.sh_addr)
                == Some(offset as u64),
        "fixed native template section/file/readonly mapping join differs",
    )?;
    require(
        extent_writers(elf, template.st_value, 4096)?.is_empty(),
        "loader writes fixed native template",
    )?;
    let page = &bytes[offset..offset + 4096];
    require(
        page.get(0x7c..0x85) == Some(&[0xf3, 0x0f, 0x1e, 0xfa, 0x0f, 0x05, 0x41, 0xff, 0xe4]),
        "fixed native page ABI interval differs",
    )?;
    let selector_name = elf
        .strtab
        .get_at(selector.st_name)
        .ok_or("fixed selector name absent")?;
    Ok(Some(FixedNativeGateEvidence {
        version: 1,
        selector: symbol_evidence(selector_name, &selector),
        selector_sha256: sha256(selector_bytes),
        publication: symbol_evidence(FIXED_NATIVE_PUBLICATION, &publication),
        publication_storage: "zero_initialized_nobits".into(),
        publication_read_instruction: selector
            .st_value
            .checked_add(4)
            .ok_or("fixed publication read overflow")?,
        unpublished_transfer: ConstructorTransfer {
            instruction: selector
                .st_value
                .checked_add(26)
                .ok_or("fixed transfer overflow")?,
            target: legacy_gate,
            local_got_slot: None,
        },
        published_transfer_instruction: selector
            .st_value
            .checked_add(23)
            .ok_or("fixed transfer overflow")?,
        fixed_entry: FIXED_NATIVE_ENTRY,
        template_symbol: symbol_evidence(FIXED_NATIVE_TEMPLATE, &template),
        template_bytes: FixedReadonlyEvidence {
            address: template.st_value,
            size: 4096,
            sha256: sha256(page),
            file_address: None,
            file_sha256: None,
            relative_pointer_slot: None,
        },
    }))
}
const FIXED_NATIVE_OWNER: &str = "reverie_inguest_fixed_trusted_syscall";
const FIXED_NATIVE_RAW6: &str = "_RNvNtCs_15reverie_inguest4trap12raw_syscall6";
const FIXED_NATIVE_RAW3: &str = "_RNvNtCs_15reverie_inguest4trap12raw_syscall3";
const FIXED_NATIVE_RAW6_HEX: &str = "50488b05e0fd2300488b004885c07426488b06488b5608488b4e104c8b46184c8b4e20488b7628488934244889c6ff152440240059c3488b06488b5608488b4e104c8b46184c8b4e20488b7628488934244889c6ff150640240059c3";
const FIXED_NATIVE_RAW3_HEX: &str = "50488b0520fe2300488b004885c0741648c70424000000004531c04531c9ff157440240059c348c70424000000004531c04531c9ff156640240059c3";
const FIXED_NATIVE_OWNER_HEX: &str = "f30f1efa41544c8d25240000004889f84889f74889d64889ca4d89c24d89c84c8b4c241049bb7c0000000050000041ffe3f30f1efa415cc3";

/// One whole native syscall wrapper, including both publication branches.
#[derive(Clone, Debug, PartialEq, Eq, Serialize, Deserialize)]
#[serde(deny_unknown_fields)]
pub struct FixedNativeSyscallEvidence {
    pub function: SymbolEvidence,
    pub function_sha256: String,
    pub publication_instruction: u64,
    pub publication_slot: u64,
    pub zero_branch_instruction: u64,
    pub zero_branch_target: u64,
    pub fixed_transfer: ConstructorTransfer,
    pub legacy_transfer: ConstructorTransfer,
}
/// Actual finite native wrapper cohort, joined to the single selector/page record.
#[derive(Clone, Debug, PartialEq, Eq, Serialize, Deserialize)]
#[serde(deny_unknown_fields)]
pub struct FixedNativeSyscallsEvidence {
    pub version: u32,
    pub publication_address: u64,
    pub template_sha256: String,
    pub wrappers: BTreeMap<String, FixedNativeSyscallEvidence>,
    pub owner: SymbolEvidence,
    pub owner_sha256: String,
    pub continuation: u64,
    pub page_transfer: ConstructorTransfer,
}
// No public evidence record or caller-provided role map can construct this
// witness: the actual ELF factory below reopens all code/data/loader bytes.
struct FixedNativeSyscallContext {
    evidence: FixedNativeSyscallsEvidence,
}
fn fixed_native_function_symbol(elf: &Elf<'_>, canonical: &str, size: u64) -> Result<sym::Sym> {
    let matches = |name: &str| {
        let base = name.split(".llvm.").next().unwrap();
        base == canonical || canonical_rust_symbol(base).as_deref() == Some(canonical)
    };
    let raw: Vec<_> = elf
        .syms
        .iter()
        .filter(|s| elf.strtab.get_at(s.st_name).is_some_and(matches))
        .collect();
    require(
        raw.len() == 1
            && !elf
                .dynsyms
                .iter()
                .any(|s| elf.dynstrtab.get_at(s.st_name).is_some_and(matches)),
        "native fixed function raw census is ambiguous/dynamic",
    )?;
    let symbol = raw[0];
    let name = elf
        .strtab
        .get_at(symbol.st_name)
        .ok_or("native fixed function name absent")?;
    require(
        (name == canonical || canonical_rust_symbol(name).as_deref() == Some(canonical))
            && symbol.st_bind() == sym::STB_LOCAL
            && symbol.st_visibility() == sym::STV_HIDDEN
            && symbol.st_size == size
            && executable_symbol(elf, &symbol),
        "native fixed function lacks its exact local hidden whole extent",
    )?;
    fixed_native_function_section(elf, &symbol)?;
    fixed_native_no_alias(elf, &symbol, None)?;
    Ok(symbol)
}
fn require_legacy_standalone_gate(elf: &Elf<'_>) -> Result<()> {
    require(
        fixed_native_selector_symbol(elf)?.is_none(),
        "Standalone fixed selector lacks the declared Detcore publication source profile",
    )
}
fn add_fixed_native_owner(elf: &Elf<'_>, symbols: &mut BTreeMap<String, sym::Sym>) -> Result<()> {
    if fixed_native_selector_symbol(elf)?.is_some() {
        let owner = fixed_native_function_symbol(elf, FIXED_NATIVE_OWNER, 56)?;
        require(
            symbols.insert(FIXED_NATIVE_OWNER.into(), owner).is_none(),
            "duplicate native fixed owner role",
        )?;
    }
    Ok(())
}
fn fixed_native_publication_slot(
    elf: &Elf<'_>,
    bytes: &[u8],
    slot: u64,
    publication: u64,
) -> Result<()> {
    require(
        slot.is_multiple_of(8)
            && elf.program_headers.iter().any(|p| {
                p.p_type == program_header::PT_GNU_RELRO
                    && slot >= p.p_vaddr
                    && p.p_vaddr.checked_add(p.p_memsz).is_some_and(|end| {
                        slot.checked_add(8).is_some_and(|hi| hi <= (end & !4095))
                    })
            }),
        "native publication pointer is not complete aligned RELRO storage",
    )?;
    let (mapping, _) = unique_file_mapping(elf, bytes, slot, 8)?;
    require(
        mapping.p_flags & (program_header::PF_R | program_header::PF_X) == program_header::PF_R,
        "native pointer slot has executable/nonreadable storage",
    )?;
    readonly_loaded_bytes(elf, bytes, slot, 8)?;
    let writers = extent_writers(elf, slot, 8)?;
    require(
        writers.len() == 1
            && writers[0].r_offset == slot
            && writers[0].r_type == reloc::R_X86_64_RELATIVE
            && writers[0].r_sym == 0
            && writers[0]
                .r_addend
                .is_some_and(|addend| addend >= 0 && addend as u64 == publication),
        "native publication pointer lacks its sole exact object RELATIVE writer",
    )
}
struct FixedNativePublicationRead {
    instruction: u64,
    slot: u64,
    object: u64,
}
fn fixed_native_publication_read(
    elf: &Elf<'_>,
    bytes: &[u8],
    address: u64,
    actual: &[u8],
    gate: &FixedNativeGateEvidence,
) -> Result<FixedNativePublicationRead> {
    let slot = fixed_rip_target(address, actual, 4, 8)?;
    fixed_native_publication_slot(elf, bytes, slot, gate.publication.address)?;
    Ok(FixedNativePublicationRead {
        instruction: address.checked_add(1).ok_or("native data read overflow")?,
        slot,
        object: gate.publication.address,
    })
}
fn fixed_native_wrapper(
    (elf, bytes): (&Elf<'_>, &[u8]),
    (actual, symbol): (&[u8], &sym::Sym),
    gate: &FixedNativeGateEvidence,
    (owner, legacy): (&sym::Sym, &sym::Sym),
    got: &BTreeMap<u64, u64>,
    role: &str,
) -> Result<FixedNativeSyscallEvidence> {
    let (hex, fixed_displacement, fixed_next, legacy_displacement, legacy_next, zero_target) =
        match role {
            FIXED_NATIVE_RAW6 => (FIXED_NATIVE_RAW6_HEX, 0x30, 0x34, 0x56, 0x5a, 0x36),
            "fixed_scalar_syscall" => (FIXED_NATIVE_RAW3_HEX, 0x20, 0x24, 0x36, 0x3a, 0x26),
            _ => return Err("unknown native fixed syscall role".into()),
        };
    require(
        fixed_template_shape(
            actual,
            &fixed_hex(hex),
            [4, fixed_displacement, legacy_displacement].into_iter(),
        ),
        "native fixed syscall whole marshal/branch/return recipe differs",
    )?;
    let data_read = fixed_native_publication_read(elf, bytes, symbol.st_value, actual, gate)?;
    require(
        data_read.object == gate.publication.address,
        "native data read loses its actual publication object",
    )?;
    let fixed_slot = fixed_rip_target(symbol.st_value, actual, fixed_displacement, fixed_next)?;
    let legacy_slot = fixed_rip_target(symbol.st_value, actual, legacy_displacement, legacy_next)?;
    // The publication pointer never enters the function-only GOT map.
    for (slot, target) in [(fixed_slot, owner.st_value), (legacy_slot, legacy.st_value)] {
        // Same existing local-function RELATIVE route, with the complete writer
        // census retained rather than relying on a map's last insertion.
        fixed_native_publication_slot(elf, bytes, slot, target)?;
    }
    require(
        got.get(&fixed_slot) == Some(&owner.st_value)
            && got.get(&legacy_slot) == Some(&legacy.st_value),
        "native syscall CALL slots do not reach exact fixed/legacy owner starts",
    )?;
    let address = symbol.st_value;
    Ok(FixedNativeSyscallEvidence {
        function: symbol_evidence(elf.strtab.get_at(symbol.st_name).unwrap(), symbol),
        function_sha256: sha256(actual),
        publication_instruction: data_read.instruction,
        publication_slot: data_read.slot,
        zero_branch_instruction: address.checked_add(14).ok_or("native branch overflow")?,
        zero_branch_target: address
            .checked_add(zero_target)
            .ok_or("native zero target overflow")?,
        fixed_transfer: ConstructorTransfer {
            instruction: address
                .checked_add(fixed_displacement as u64 - 2)
                .ok_or("native CALL overflow")?,
            target: owner.st_value,
            local_got_slot: Some(fixed_slot),
        },
        legacy_transfer: ConstructorTransfer {
            instruction: address
                .checked_add(legacy_displacement as u64 - 2)
                .ok_or("native CALL overflow")?,
            target: legacy.st_value,
            local_got_slot: Some(legacy_slot),
        },
    })
}
fn qualify_fixed_native_syscalls(
    elf: &Elf<'_>,
    bytes: &[u8],
    code: &BTreeMap<u64, Vec<u8>>,
    got: &BTreeMap<u64, u64>,
    roles: &BTreeMap<String, sym::Sym>,
) -> Result<Option<FixedNativeSyscallContext>> {
    let legacy = private_function(elf, CONSTRUCTOR_GATE_OWNER)?;
    let gate_ip = constructor_interior_label(elf, CONSTRUCTOR_GATE, &legacy)?;
    let Some(gate) = qualify_fixed_native_gate(elf, bytes, code, gate_ip.st_value)? else {
        // The old templates will still reject an unsupported native-sized body.
        return Ok(None);
    };
    let owner = fixed_native_function_symbol(elf, FIXED_NATIVE_OWNER, 56)?;
    let raw6 = fixed_native_function_symbol(elf, FIXED_NATIVE_RAW6, 92)?;
    let raw3 = fixed_native_function_symbol(elf, FIXED_NATIVE_RAW3, 60)?;
    for (role, selected) in [
        (FIXED_NATIVE_OWNER, owner),
        (FIXED_NATIVE_RAW6, raw6),
        ("fixed_scalar_syscall", raw3),
    ] {
        require(
            roles.get(role) == Some(&selected),
            "native syscall cohort loses its actual selected role",
        )?;
    }
    let actual = proof_function_bytes(
        elf,
        bytes,
        &BTreeMap::from([
            (owner.st_value, 56),
            (raw6.st_value, 92),
            (raw3.st_value, 60),
        ]),
    )?;
    for (address, body) in &actual {
        require(
            code.get(address) == Some(body),
            "native syscall lacks complete unchanged proof bytes",
        )?;
    }
    let owner_bytes = &actual[&owner.st_value];
    let continuation = owner
        .st_value
        .checked_add(0x31)
        .ok_or("native continuation overflow")?;
    fixed_whole_recipe(
        owner.st_value,
        owner_bytes,
        FIXED_NATIVE_OWNER_HEX,
        &[(9, 13, continuation)],
    )?;
    let authenticated_got = local_got_targets(elf, bytes)?;
    let mut wrappers = BTreeMap::new();
    for (role, symbol) in [(FIXED_NATIVE_RAW6, raw6), ("fixed_scalar_syscall", raw3)] {
        let record = fixed_native_wrapper(
            (elf, bytes),
            (&actual[&symbol.st_value], &symbol),
            &gate,
            (&owner, &legacy),
            &authenticated_got,
            role,
        )?;
        for edge in [&record.fixed_transfer, &record.legacy_transfer] {
            require(
                edge.local_got_slot
                    .is_some_and(|slot| got.get(&slot) == Some(&edge.target)),
                "retained function GOT evidence differs from actual native slots",
            )?;
        }
        wrappers.insert(role.into(), record);
    }
    Ok(Some(FixedNativeSyscallContext {
        evidence: FixedNativeSyscallsEvidence {
            version: 1,
            publication_address: gate.publication.address,
            template_sha256: gate.template_bytes.sha256,
            wrappers,
            owner: symbol_evidence(FIXED_NATIVE_OWNER, &owner),
            owner_sha256: sha256(owner_bytes),
            continuation,
            page_transfer: ConstructorTransfer {
                instruction: owner
                    .st_value
                    .checked_add(0x2e)
                    .ok_or("native page transfer overflow")?,
                target: gate.fixed_entry,
                local_got_slot: None,
            },
        },
    }))
}
fn fixed_native_owner_census(
    actual: &[u8],
    instructions: &[EncodedConstructorInstruction],
    record: &FixedNativeSyscallsEvidence,
) -> Result<()> {
    let offsets = [0, 4, 6, 13, 16, 19, 22, 25, 28, 31, 36, 46, 49, 53, 55, 56];
    require(
        actual.len() == 56
            && sha256(actual) == record.owner_sha256
            && instructions.len() == offsets.len() - 1,
        "native fixed owner census extent/hash/instruction count differs",
    )?;
    for (instruction, pair) in instructions.iter().zip(offsets.windows(2)) {
        require(
            record.owner.address.checked_add(pair[0] as u64) == Some(instruction.address)
                && instruction.bytes == actual[pair[0]..pair[1]],
            "native fixed owner whole instruction cursor/bytes differ",
        )?;
    }
    require(
        instructions[11].bytes == [0x41, 0xff, 0xe3]
            && record.page_transfer.instruction == instructions[11].address
            && record.page_transfer.target == FIXED_NATIVE_ENTRY
            && record.page_transfer.local_got_slot.is_none()
            && record.owner.address.checked_add(49) == Some(record.continuation),
        "native fixed owner loses its unique authenticated page leaf/continuation",
    )
}
/// Only a fully qualified native scalar wrapper can extend its own setup
/// census with the independently proved fixed owner. Other preparation roles
/// retain the original helper set and complete instruction scanner.
fn fixed_setup_preparation_transfers(
    role: &str,
    function: &SymbolEvidence,
    instructions: &[EncodedConstructorInstruction],
    got: &BTreeMap<u64, u64>,
    helpers: &BTreeSet<u64>,
    native: Option<&FixedNativeSyscallContext>,
) -> Result<(Vec<ConstructorTransfer>, Vec<GotEdge>)> {
    let Some(native) = native.filter(|_| role == "fixed_scalar_syscall") else {
        return preparation_transfers(instructions, got, helpers);
    };
    let wrapper = native
        .evidence
        .wrappers
        .get(role)
        .ok_or("native scalar setup lacks independently qualified wrapper")?;
    let actual: Vec<u8> = instructions
        .iter()
        .flat_map(|i| i.bytes.iter().copied())
        .collect();
    require(
        function == &wrapper.function
            && instructions.first().map(|i| i.address) == Some(function.address)
            && actual.len() as u64 == function.size
            && sha256(&actual) == wrapper.function_sha256,
        "native scalar setup loses its independently qualified whole function",
    )?;
    let mut allowed = helpers.clone();
    allowed.insert(native.evidence.owner.address);
    let (transfers, edges) = preparation_transfers(instructions, got, &allowed)?;
    require(
        transfers
            == [
                wrapper.fixed_transfer.clone(),
                wrapper.legacy_transfer.clone(),
            ]
            && edges == fixed_native_wrapper_got_edges(wrapper)?,
        "native scalar setup census differs from its qualified fixed/legacy transfers",
    )?;
    Ok((transfers, edges))
}

fn fixed_native_wrapper_got_edges(wrapper: &FixedNativeSyscallEvidence) -> Result<Vec<GotEdge>> {
    [&wrapper.fixed_transfer, &wrapper.legacy_transfer]
        .into_iter()
        .map(|transfer| {
            Ok(GotEdge {
                source_function: wrapper.function.address,
                instruction: transfer.instruction,
                slot: transfer
                    .local_got_slot
                    .ok_or("native wrapper transfer lost its GOT slot")?,
                target_function: transfer.target,
            })
        })
        .collect()
}

fn validate_fixed_native_syscall_evidence(
    backing: &AllocatorBackingEvidence,
    image: FixedImageKind,
) -> Result<()> {
    let Some(record) = &backing.fixed_native_syscalls else {
        return require(
            !backing.functions.contains_key(FIXED_NATIVE_OWNER),
            "native fixed function evidence was stripped",
        );
    };
    require(
        image == FixedImageKind::Detcore
            && record.version == 1
            && record
                .wrappers
                .keys()
                .map(String::as_str)
                .collect::<BTreeSet<_>>()
                == BTreeSet::from([FIXED_NATIVE_RAW6, "fixed_scalar_syscall"])
            && backing.functions.get(FIXED_NATIVE_OWNER) == Some(&record.owner)
            && backing.function_sha256.get(FIXED_NATIVE_OWNER) == Some(&record.owner_sha256)
            && record.owner.name == FIXED_NATIVE_OWNER
            && record.owner.size == 56
            && record.owner.binding == sym::STB_LOCAL
            && record.owner.visibility == sym::STV_HIDDEN
            && record.owner.address.checked_add(49) == Some(record.continuation)
            && record.owner.address.checked_add(46) == Some(record.page_transfer.instruction)
            && record.page_transfer.target == FIXED_NATIVE_ENTRY
            && record.page_transfer.local_got_slot.is_none()
            && backing.allocator_transfers.get(FIXED_NATIVE_OWNER)
                == Some(&vec![record.page_transfer.clone()]),
        "native fixed syscall evidence version/owner/leaf identity differs",
    )?;
    fixed_native_digest(&record.owner_sha256)?;
    fixed_native_digest(&record.template_sha256)?;
    for (role, canonical, size, fixed_pc, legacy_pc, zero_target) in [
        (FIXED_NATIVE_RAW6, FIXED_NATIVE_RAW6, 92, 46, 84, 54),
        ("fixed_scalar_syscall", FIXED_NATIVE_RAW3, 60, 30, 52, 38),
    ] {
        let wrapper = &record.wrappers[role];
        let function = &wrapper.function;
        fixed_native_digest(&wrapper.function_sha256)?;
        require(
            backing.functions.get(role) == Some(function)
                && backing.function_sha256.get(role) == Some(&wrapper.function_sha256)
                && canonical_rust_symbol(&function.name).as_deref() == Some(canonical)
                && function.size == size
                && function.binding == sym::STB_LOCAL
                && function.visibility == sym::STV_HIDDEN
                && function.address.checked_add(1) == Some(wrapper.publication_instruction)
                && wrapper.publication_slot != 0
                && wrapper.publication_slot % 8 == 0
                && function.address.checked_add(14) == Some(wrapper.zero_branch_instruction)
                && function.address.checked_add(zero_target) == Some(wrapper.zero_branch_target)
                && function.address.checked_add(fixed_pc)
                    == Some(wrapper.fixed_transfer.instruction)
                && function.address.checked_add(legacy_pc)
                    == Some(wrapper.legacy_transfer.instruction)
                && wrapper.fixed_transfer.target == record.owner.address
                && wrapper.fixed_transfer.local_got_slot.is_some()
                && wrapper.legacy_transfer.local_got_slot.is_some()
                && wrapper.legacy_transfer.target != record.owner.address
                && backing.allocator_transfers.get(role)
                    == Some(&vec![
                        wrapper.fixed_transfer.clone(),
                        wrapper.legacy_transfer.clone(),
                    ]),
            "native fixed wrapper loses exact role/hash/branch/data/transfer joins",
        )?;
        let legacy = backing
            .functions
            .values()
            .find(|function| function.name == CONSTRUCTOR_GATE_OWNER)
            .ok_or("native wrapper legacy owner evidence absent")?;
        require(
            wrapper.legacy_transfer.target == legacy.address,
            "native wrapper legacy transfer loses complete owner start",
        )?;
        if role == "fixed_scalar_syscall" {
            let end = function
                .address
                .checked_add(function.size)
                .ok_or("native scalar setup extent overflows")?;
            // Join both source attribution and instruction ownership. A forged
            // source must not hide an extra record at an actual scalar CALL.
            let owned_edges: Vec<_> = backing
                .owned_setup_got_edges
                .iter()
                .filter(|edge| {
                    edge.source_function == function.address
                        || (function.address..end).contains(&edge.instruction)
                })
                .cloned()
                .collect();
            require(
                backing.owned_setup_transfers.get(role)
                    == Some(&vec![
                        wrapper.fixed_transfer.clone(),
                        wrapper.legacy_transfer.clone(),
                    ])
                    && owned_edges == fixed_native_wrapper_got_edges(wrapper)?,
                "native scalar owned setup loses its exact transfer/GOT census",
            )?;
        }
    }
    Ok(())
}
fn join_fixed_native_syscalls(
    backing: &AllocatorBackingEvidence,
    gate: Option<&FixedNativeGateEvidence>,
) -> Result<()> {
    match (&backing.fixed_native_syscalls, gate) {
        (None, None) => Ok(()),
        (Some(record), Some(gate)) => require(
            record.publication_address == gate.publication.address
                && record.template_sha256 == gate.template_bytes.sha256
                && record.page_transfer.target == gate.fixed_entry,
            "native wrappers and selector do not share one publication/page context",
        ),
        _ => Err("native wrapper/selector feature cohort is incomplete".into()),
    }
}

fn native_bridge_gate_address(
    fixed: Option<&FixedNativeGateEvidence>,
    legacy: &SymbolEvidence,
) -> Result<u64> {
    let Some(fixed) = fixed else {
        return Ok(legacy.address);
    };
    fixed.verify_bootstrap_page_digest(&fixed_native_digest(&fixed.template_bytes.sha256)?)?;
    fixed_native_digest(&fixed.selector_sha256)?;
    require(
        fixed.selector.size == 31
            && fixed.selector.binding == sym::STB_LOCAL
            && fixed.selector.visibility == sym::STV_HIDDEN
            && canonical_rust_symbol(&fixed.selector.name).as_deref()
                == Some(FIXED_NATIVE_SELECTOR)
            && fixed.publication_storage == "zero_initialized_nobits"
            && fixed.publication.name == FIXED_NATIVE_PUBLICATION
            && fixed.publication.size == 8
            && fixed.publication.binding == sym::STB_LOCAL
            && fixed.publication.visibility == sym::STV_HIDDEN
            && fixed.publication_read_instruction
                == fixed
                    .selector
                    .address
                    .checked_add(4)
                    .ok_or("fixed read overflow")?
            && fixed.published_transfer_instruction
                == fixed
                    .selector
                    .address
                    .checked_add(23)
                    .ok_or("fixed transfer overflow")?
            && fixed.unpublished_transfer.instruction
                == fixed
                    .selector
                    .address
                    .checked_add(26)
                    .ok_or("fixed transfer overflow")?
            && fixed.unpublished_transfer.target == legacy.address
            && fixed.unpublished_transfer.local_got_slot.is_none(),
        "fixed native serialized route identity differs",
    )?;
    Ok(fixed.selector.address)
}

fn private_constructor_binding(binding: u8, visibility: u8) -> bool {
    binding == sym::STB_LOCAL || matches!(visibility, sym::STV_HIDDEN | sym::STV_INTERNAL)
}

fn unique_standalone_slot(root_slots: &[u64], generic_slots: &[u64]) -> Result<u64> {
    require(
        generic_slots.is_empty(),
        "generic initializer is a second leaf init_array root",
    )?;
    require(
        root_slots.len() == 1,
        "standalone native root must have exactly one relocated init_array slot",
    )?;
    Ok(root_slots[0])
}

fn standalone_symbols(elf: &Elf<'_>) -> Result<BTreeMap<String, sym::Sym>> {
    require_legacy_standalone_gate(elf)?;
    let mut symbols = BTreeMap::new();
    for name in [
        STANDALONE_ROOT,
        STANDALONE_BODY,
        STANDALONE_INITIALIZER,
        STANDALONE_RESOLVER,
        CONSTRUCTOR_BRIDGE,
        CONSTRUCTOR_ADOPTION,
        CONSTRUCTOR_GATE_OWNER,
    ] {
        symbols.insert(name.to_owned(), private_function(elf, name)?);
    }
    // Whole private typed owner helpers remain source-bound preparation roles.
    // They confer no supplied-body target or compiler-frame dispatch proof.
    symbols.extend(preparation_symbols(elf)?);
    add_fixed_native_selector(elf, &mut symbols)?;
    add_fixed_native_owner(elf, &mut symbols)?;
    // This cannot be inferred from an rlib/no_mangle declaration. Require the
    // actual public dynamic export even when the real leaf no longer calls it.
    symbols.insert(
        GENERIC_INITIALIZER.to_owned(),
        export(elf, GENERIC_INITIALIZER)?.1,
    );
    require(
        symbols
            .values()
            .map(|s| s.st_value)
            .collect::<BTreeSet<_>>()
            .len()
            == symbols.len(),
        "standalone constructor roles alias one another",
    )?;
    Ok(symbols)
}

fn detcore_public_initializer(elf: &Elf<'_>) -> Result<sym::Sym> {
    let (_, root) = export(elf, DETCORE_ROOT)?;
    require(
        root.st_bind() == sym::STB_GLOBAL
            && root.st_visibility() == sym::STV_PROTECTED
            && root.st_size == 16,
        "Detcore root must be a strong protected 16-byte function",
    )?;
    let statics: Vec<_> = elf
        .syms
        .iter()
        .filter(|s| elf.strtab.get_at(s.st_name) == Some(DETCORE_ROOT))
        .collect();
    require(
        statics.len() == 1
            && statics[0].st_value == root.st_value
            && statics[0].st_size == root.st_size
            && statics[0].st_bind() == root.st_bind()
            && statics[0].st_visibility() == root.st_visibility()
            && executable_symbol(elf, &statics[0]),
        "Detcore root static/dynamic identities disagree",
    )?;
    let end = root
        .st_value
        .checked_add(root.st_size)
        .ok_or("Detcore root extent overflow")?;
    for (name, symbol) in elf
        .syms
        .iter()
        .map(|s| (elf.strtab.get_at(s.st_name), s))
        .chain(
            elf.dynsyms
                .iter()
                .map(|s| (elf.dynstrtab.get_at(s.st_name), s)),
        )
    {
        if symbol.st_type() == sym::STT_FUNC
            && symbol.st_shndx != section_header::SHN_UNDEF as usize
        {
            let other_end = symbol
                .st_value
                .checked_add(symbol.st_size)
                .ok_or("function alias extent overflow")?;
            if symbol.st_value < end && root.st_value < other_end {
                require(
                    name == Some(DETCORE_ROOT)
                        && symbol.st_value == root.st_value
                        && symbol.st_size == 16
                        && symbol.st_bind() == sym::STB_GLOBAL
                        && symbol.st_visibility() == sym::STV_PROTECTED,
                    "Detcore root has a conflicting function alias",
                )?;
            }
        }
    }
    Ok(root)
}

fn detcore_symbols(elf: &Elf<'_>) -> Result<BTreeMap<String, sym::Sym>> {
    let mut symbols = BTreeMap::from([(DETCORE_ROOT.to_owned(), detcore_public_initializer(elf)?)]);
    for name in [
        DETCORE_BODY,
        CONSTRUCTOR_BRIDGE,
        CONSTRUCTOR_ADOPTION,
        CONSTRUCTOR_GATE_OWNER,
    ] {
        let function = private_function(elf, name)?;
        require(
            function.st_visibility() == sym::STV_HIDDEN,
            format!("Detcore native role {name} is not hidden"),
        )?;
        symbols.insert(name.to_owned(), function);
    }
    symbols.extend(preparation_symbols(elf)?);
    add_fixed_native_selector(elf, &mut symbols)?;
    add_fixed_native_owner(elf, &mut symbols)?;
    require_disjoint_bootstrap_roles(&symbols)?;
    Ok(symbols)
}

fn detcore_init_slot(
    elf: &Elf<'_>,
    bytes: &[u8],
    symbols: &BTreeMap<String, sym::Sym>,
) -> Result<(u64, String)> {
    let root = &symbols[DETCORE_ROOT];
    let mut ranges = Vec::new();
    for name in [
        DETCORE_ROOT,
        DETCORE_BODY,
        CONSTRUCTOR_BRIDGE,
        CONSTRUCTOR_ADOPTION,
    ] {
        let function = &symbols[name];
        ranges.push((
            function.st_value,
            function
                .st_value
                .checked_add(function.st_size)
                .ok_or("Detcore native role extent overflow")?,
        ));
    }
    let generic = generic_symbols(elf)?;
    for name in [
        GENERIC_INITIALIZER,
        GENERIC_BODY,
        GENERIC_BRIDGE,
        GENERIC_ADOPTION,
    ] {
        let function = &generic[name];
        ranges.push((
            function.st_value,
            function
                .st_value
                .checked_add(function.st_size)
                .ok_or("generic native role extent overflow")?,
        ));
    }
    if let Some(selector) = fixed_native_selector_symbol(elf)? {
        ranges.push((
            selector.st_value,
            selector
                .st_value
                .checked_add(selector.st_size)
                .ok_or("fixed selector range overflow")?,
        ));
        for (canonical, size) in [
            (FIXED_NATIVE_OWNER, 56),
            (FIXED_NATIVE_RAW6, 92),
            (FIXED_NATIVE_RAW3, 60),
        ] {
            let function = fixed_native_function_symbol(elf, canonical, size)?;
            ranges.push((
                function.st_value,
                function
                    .st_value
                    .checked_add(size)
                    .ok_or("fixed native registration range overflow")?,
            ));
        }
    }
    detcore_loader_registration(elf, bytes, root, &ranges)
}

fn detcore_loader_registration(
    elf: &Elf<'_>,
    bytes: &[u8],
    root: &sym::Sym,
    ranges: &[(u64, u64)],
) -> Result<(u64, String)> {
    require(
        ranges.iter().all(|&(lo, hi)| lo < hi)
            && ranges.contains(&(
                root.st_value,
                root.st_value
                    .checked_add(root.st_size)
                    .ok_or("root extent overflow")?,
            )),
        "Detcore registration lacks complete native role extents",
    )?;
    let overlaps_native = |target: u64| ranges.iter().any(|&(lo, hi)| lo <= target && target < hi);
    let sections: Vec<_> = elf
        .section_headers
        .iter()
        .filter(|s| s.sh_type == section_header::SHT_INIT_ARRAY)
        .collect();
    require(
        sections.len() == 1 && elf.shdr_strtab.get_at(sections[0].sh_name) == Some(".init_array"),
        "Detcore registration requires one actual init_array section",
    )?;
    let section = sections[0];
    require(
        section.sh_addr % 8 == 0 && section.sh_size != 0 && section.sh_size % 8 == 0,
        "Detcore registration has invalid init_array extent/alignment",
    )?;
    let dynamic = elf
        .dynamic
        .as_ref()
        .ok_or("Detcore registration lacks dynamic data")?;
    for tag in [
        goblin::elf::dynamic::DT_INIT,
        goblin::elf::dynamic::DT_INIT_ARRAY,
        goblin::elf::dynamic::DT_INIT_ARRAYSZ,
        goblin::elf::dynamic::DT_PREINIT_ARRAY,
        goblin::elf::dynamic::DT_PREINIT_ARRAYSZ,
    ] {
        let values: Vec<_> = dynamic
            .dyns
            .iter()
            .filter(|d| d.d_tag == tag)
            .map(|d| d.d_val)
            .collect();
        require(
            values.len() <= 1,
            "Detcore registration has duplicate dynamic init tags",
        )?;
        if tag == goblin::elf::dynamic::DT_INIT_ARRAY {
            require(
                values == [section.sh_addr],
                "Detcore dynamic init_array address differs",
            )?;
        } else if tag == goblin::elf::dynamic::DT_INIT_ARRAYSZ {
            require(
                values == [section.sh_size],
                "Detcore dynamic init_array size differs",
            )?;
        } else if tag == goblin::elf::dynamic::DT_INIT {
            require(
                values.iter().all(|&v| !overlaps_native(v)),
                "Detcore native route also registered in DT_INIT",
            )?;
        } else {
            require(
                values.iter().all(|&v| v == 0),
                "Detcore native proof refuses nonzero preinit registration",
            )?;
        }
    }
    let entries = init_array_bytes(elf, bytes, section)?;
    readonly_loaded_bytes(elf, bytes, section.sh_addr, entries.len())?;
    let mut selected = Vec::new();
    for (index, entry) in entries.as_chunks::<8>().0.iter().enumerate() {
        let slot = section
            .sh_addr
            .checked_add((index as u64).checked_mul(8).ok_or("init index overflow")?)
            .ok_or("init slot overflow")?;
        let writers = extent_writers(elf, slot, 8)?;
        require(
            writers.len() <= 1
                && writers.iter().all(|r| {
                    r.r_offset == slot && descriptor_relocation_width(elf, r).is_ok_and(|n| n == 8)
                }),
            "Detcore init slot has partial/overlapping writers",
        )?;
        let raw = u64::from_le_bytes(*entry);
        let (target, is_relative) = if let Some(writer) = writers.first() {
            let addend = writer
                .r_addend
                .ok_or("Detcore init relocation lacks explicit addend")?;
            if writer.r_type == reloc::R_X86_64_RELATIVE && writer.r_sym == 0 {
                (
                    u64::try_from(addend).map_err(|_| "negative init relative target")?,
                    true,
                )
            } else if writer.r_type == reloc::R_X86_64_64 {
                let function = elf
                    .dynsyms
                    .get(writer.r_sym)
                    .filter(|s| s.st_shndx != section_header::SHN_UNDEF as usize)
                    .ok_or("unresolved Detcore neighboring initializer")?;
                (
                    function
                        .st_value
                        .checked_add_signed(addend)
                        .ok_or("init symbol target overflow")?,
                    false,
                )
            } else {
                return Err("unsupported Detcore init relocation".into());
            }
        } else {
            (raw, false)
        };
        if target == root.st_value {
            require(
                is_relative,
                "Detcore root registration must be sole symbol-zero RELATIVE",
            )?;
            selected.push(slot);
        } else {
            require(
                !overlaps_native(target),
                "init_array bypasses a proved Detcore or generic native entry",
            )?;
        }
    }
    require(
        selected.len() == 1,
        "Detcore root must have exactly one RELATIVE init_array slot",
    )?;
    Ok((selected[0], "Unique protected Detcore root through sole local RELATIVE; no competing native-role registration".to_owned()))
}

fn generic_public_initializer(elf: &Elf<'_>) -> Result<sym::Sym> {
    let (_, initializer) = export(elf, GENERIC_INITIALIZER)?;
    require(
        initializer.st_visibility() == sym::STV_DEFAULT && initializer.st_size == 16,
        "public generic initializer must retain its strong DEFAULT-visible 16-byte ABI entry",
    )?;
    require(
        elf.syms
            .iter()
            .filter(|s| {
                elf.strtab.get_at(s.st_name) == Some(GENERIC_INITIALIZER)
                    && executable_symbol(elf, s)
            })
            .all(|s| {
                s.st_value == initializer.st_value
                    && s.st_size == initializer.st_size
                    && s.st_bind() == sym::STB_GLOBAL
                    && s.st_visibility() == sym::STV_DEFAULT
            }),
        "public generic initializer has conflicting static/dynamic ABI identities",
    )?;
    Ok(initializer)
}

fn generic_symbols(elf: &Elf<'_>) -> Result<BTreeMap<String, sym::Sym>> {
    let mut symbols = BTreeMap::from([(
        GENERIC_INITIALIZER.to_owned(),
        generic_public_initializer(elf)?,
    )]);
    for name in [GENERIC_BODY, GENERIC_BRIDGE, GENERIC_ADOPTION] {
        let function = private_function(elf, name)?;
        require(
            elf.syms
                .iter()
                .filter(|s| elf.strtab.get_at(s.st_name) == Some(name) && executable_symbol(elf, s))
                .chain(elf.dynsyms.iter().filter(|s| {
                    elf.dynstrtab.get_at(s.st_name) == Some(name) && executable_symbol(elf, s)
                }))
                .all(|s| {
                    s.st_visibility() == sym::STV_HIDDEN
                        && matches!(s.st_bind(), sym::STB_LOCAL | sym::STB_GLOBAL)
                }),
            format!("generic bootstrap role {name} must be a defined hidden function"),
        )?;
        symbols.insert(name.to_owned(), function);
    }
    symbols.insert(
        CONSTRUCTOR_GATE_OWNER.to_owned(),
        private_function(elf, CONSTRUCTOR_GATE_OWNER)?,
    );
    symbols.extend(preparation_symbols(elf)?);
    add_fixed_native_selector(elf, &mut symbols)?;
    add_fixed_native_owner(elf, &mut symbols)?;
    // Roles must own distinct complete functions. Alias names or overlapping
    // ranges cannot manufacture a bridge, body or adoption operand route.
    require_disjoint_bootstrap_roles(&symbols)?;
    Ok(symbols)
}

fn require_disjoint_bootstrap_roles(symbols: &BTreeMap<String, sym::Sym>) -> Result<()> {
    let roles: Vec<_> = symbols.iter().collect();
    for (index, (name, function)) in roles.iter().enumerate() {
        let end = function
            .st_value
            .checked_add(function.st_size)
            .ok_or("bootstrap function range overflows")?;
        require(
            function.st_size != 0,
            "bootstrap role has no complete function extent",
        )?;
        for (other_name, other) in &roles[index + 1..] {
            let other_end = other
                .st_value
                .checked_add(other.st_size)
                .ok_or("bootstrap function range overflows")?;
            require(
                end <= other.st_value || other_end <= function.st_value,
                format!("bootstrap roles {name} and {other_name} alias/overlap"),
            )?;
        }
    }
    Ok(())
}

fn combined_bootstrap_symbols(elf: &Elf<'_>) -> Result<BTreeMap<String, sym::Sym>> {
    let mut symbols = standalone_symbols(elf)?;
    for (name, function) in generic_symbols(elf)? {
        if let Some(shared) = symbols.get(&name) {
            require(
                shared.st_value == function.st_value
                    && shared.st_size == function.st_size
                    && shared.st_bind() == function.st_bind()
                    && shared.st_visibility() == function.st_visibility(),
                "constructor and generic proofs disagree about a shared role",
            )?;
        } else {
            symbols.insert(name, function);
        }
    }
    require_disjoint_bootstrap_roles(&symbols)?;
    Ok(symbols)
}

/// Check the actual loader registration independently of the public prefix.
/// Standalone's exact private root checks remain separate and unchanged.
fn generic_no_init_registration(
    elf: &Elf<'_>,
    bytes: &[u8],
    generic_roles: &BTreeSet<u64>,
) -> Result<()> {
    let sections: Vec<_> = elf
        .section_headers
        .iter()
        .filter(|s| s.sh_type == section_header::SHT_INIT_ARRAY)
        .collect();
    require(
        sections.len() == 1 && elf.shdr_strtab.get_at(sections[0].sh_name) == Some(".init_array"),
        "generic registration proof requires the unique actual .init_array section",
    )?;
    let section = sections[0];
    require(
        section.sh_size > 0 && section.sh_size % 8 == 0 && section.sh_addr % 8 == 0,
        "generic registration proof has invalid init_array layout",
    )?;
    let dynamic = elf
        .dynamic
        .as_ref()
        .ok_or("generic registration proof lacks dynamic data")?;
    let array_tags: Vec<_> = dynamic
        .dyns
        .iter()
        .filter(|d| d.d_tag == goblin::elf::dynamic::DT_INIT_ARRAY)
        .collect();
    let size_tags: Vec<_> = dynamic
        .dyns
        .iter()
        .filter(|d| d.d_tag == goblin::elf::dynamic::DT_INIT_ARRAYSZ)
        .collect();
    require(
        array_tags.len() == 1
            && size_tags.len() == 1
            && array_tags[0].d_val == section.sh_addr
            && size_tags[0].d_val == section.sh_size,
        "loader init_array tags differ from the inspected actual section",
    )?;
    require(
        !dynamic.dyns.iter().any(|d| {
            (d.d_tag == goblin::elf::dynamic::DT_INIT && generic_roles.contains(&d.d_val))
                || (matches!(
                    d.d_tag,
                    goblin::elf::dynamic::DT_PREINIT_ARRAY
                        | goblin::elf::dynamic::DT_PREINIT_ARRAYSZ
                ) && d.d_val != 0)
        }),
        "generic initializer has a loader init/preinit registration",
    )?;
    let entries = init_array_bytes(elf, bytes, section)?;
    loader_writers(elf)?;
    for (index, entry) in entries.as_chunks::<8>().0.iter().enumerate() {
        let slot = section.sh_addr + index as u64 * 8;
        let raw = u64::from_le_bytes(*entry);
        let records = extent_writers(elf, slot, 8)?;
        require(
            records.len() <= 1
                && records.iter().all(|r| {
                    r.r_offset == slot
                        && descriptor_relocation_width(elf, r).is_ok_and(|width| width == 8)
                }),
            "partial or overlapping generic init_array relocation writers",
        )?;
        let target = if let Some(r) = records.first() {
            let addend = r.r_addend.unwrap_or(raw as i64);
            if r.r_type == reloc::R_X86_64_RELATIVE && r.r_sym == 0 && addend >= 0 {
                addend as u64
            } else if r.r_type == reloc::R_X86_64_64 {
                let symbol = elf
                    .dynsyms
                    .get(r.r_sym)
                    .filter(|s| s.st_shndx != section_header::SHN_UNDEF as usize)
                    .ok_or("unresolved generic registration proof init_array target")?;
                symbol
                    .st_value
                    .checked_add_signed(addend)
                    .ok_or("generic init_array relocation target overflows")?
            } else {
                return Err("unsupported init_array relocation cannot prove absence of generic registration".to_owned());
            }
        } else {
            raw
        };
        require(
            !generic_roles.contains(&target),
            "generic bootstrap role is registered in init_array",
        )?;
    }
    Ok(())
}

/// Normalize Rust-v0 crate disambiguators only; all remaining path/type/
/// method/backreference spelling must match one actually emitted typed role.
/// This is deliberately not a general demangler or substring allowlist.
fn canonical_rust_symbol(name: &str) -> Option<String> {
    let plain = if let Some((plain, suffix)) = name.split_once(".llvm.") {
        if suffix.is_empty() || !suffix.bytes().all(|b| b.is_ascii_digit()) {
            return None;
        }
        plain
    } else {
        name
    };
    let mut canonical = String::new();
    let mut remaining = plain;
    while let Some(offset) = remaining.find("Cs") {
        canonical.push_str(&remaining[..offset]);
        remaining = &remaining[offset + 2..];
        let end = remaining
            .bytes()
            .take_while(|b| b.is_ascii_alphanumeric())
            .count();
        if end == 0 || remaining.as_bytes().get(end) != Some(&b'_') {
            return None;
        }
        canonical.push_str("Cs_");
        remaining = &remaining[end + 1..];
    }
    canonical.push_str(remaining);
    Some(canonical)
}

fn preparation_role(name: &str) -> Option<&'static str> {
    let canonical = canonical_rust_symbol(name)?;
    match canonical.as_str() {
        "_RINvMNtNtCs_3std4sync9once_lockINtB3_8OnceLockINtNtCs_4core6result6ResultNtNtNtCs_15reverie_inguest5guest11tool_region10ToolRegionlEE10initializeNCINvB2_11get_or_initNCNvB2_10try_insert0E0zEB1B_" => {
            Some("tool_region_once_initialize")
        }
        "_RINvYINtNtNtCs_4core3ops5range5RangejENtNtNtNtBa_4iter6traits8iterator8Iterator8try_folduNCINvNvBL_3all5checkjNCNvMs_NtNtNtCs_15reverie_inguest5guest11tool_region11constructorNtB22_16NativeFreshOwner11from_natives_0E0INtNtB8_12control_flow11ControlFlowuEEB28_" => {
            Some("from_native_bitmap_range")
        }
        "_RNvMs16_NtNtCs_4core4sync6atomicINtB6_6AtomicjE5storeCs_15reverie_inguest" => {
            Some("atomic_usize_store")
        }
        "_RNvMs_NtNtNtCs_15reverie_inguest5guest11tool_region11constructorNtB4_16NativeFreshOwner11from_native" => {
            Some("from_native")
        }
        "_RNvMs_NtNtNtCs_15reverie_inguest5guest11tool_region11constructorNtB4_16NativeFreshOwner7publish" => {
            Some("publish")
        }
        "_RNvNtCs_4core9panicking19panic_cannot_unwind" => Some("panic_cannot_unwind"),
        "_RNvNtCs_4core9panicking32panic_null_reference_constructed" => {
            Some("panic_null_reference_constructed")
        }
        "_RNvNtCs_4core9panicking36panic_misaligned_pointer_dereference" => {
            Some("panic_misaligned_pointer_dereference")
        }
        "reverie_inguest_trusted_syscall" => Some("trusted_syscall"),
        _ => None,
    }
}

fn preparation_symbols(elf: &Elf<'_>) -> Result<BTreeMap<String, sym::Sym>> {
    let mut result = BTreeMap::new();
    let mut roles = BTreeSet::new();
    for symbol in elf.syms.iter().filter(|s| executable_symbol(elf, s)) {
        let Some(name) = elf.strtab.get_at(symbol.st_name) else {
            continue;
        };
        let Some(role) = preparation_role(name) else {
            continue;
        };
        require(
            symbol.st_bind() == sym::STB_LOCAL,
            format!("preparation helper {role} is preemptible"),
        )?;
        require(
            !elf.dynsyms
                .iter()
                .any(|s| elf.dynstrtab.get_at(s.st_name) == Some(name)),
            "private preparation helper has a dynamic identity",
        )?;
        if let Some(prior) = result.get(name) {
            let prior: &sym::Sym = prior;
            require(
                prior.st_value == symbol.st_value
                    && prior.st_size == symbol.st_size
                    && prior.st_bind() == symbol.st_bind()
                    && prior.st_visibility() == symbol.st_visibility(),
                "conflicting preparation helper identity",
            )?;
        } else {
            require(
                roles.insert(role.to_owned()),
                format!("ambiguous preparation helper {role}"),
            )?;
            result.insert(name.to_owned(), symbol);
        }
    }
    for (role, symbol) in fixed_role_symbols(elf)? {
        if owned_fixed_setup_role(&role)
            || role == "fixed_panic_nounwind_fmt"
            || PUBLICATION_PREPARATION_ROLES.contains(&role.as_str())
        {
            let name = elf
                .strtab
                .get_at(symbol.st_name)
                .ok_or("Fixed setup role name absent")?;
            if result.contains_key(name) {
                continue;
            }
            require(
                roles.insert(role),
                "Fixed/legacy preparation role collision",
            )?;
            require(
                result.insert(name.to_owned(), symbol).is_none(),
                "Fixed preparation function alias",
            )?;
        }
    }
    Ok(result)
}

fn constructor_interior_label(elf: &Elf<'_>, name: &str, owner: &sym::Sym) -> Result<sym::Sym> {
    let labels: Vec<_> = elf
        .syms
        .iter()
        .filter(|s| elf.strtab.get_at(s.st_name) == Some(name))
        .chain(
            elf.dynsyms
                .iter()
                .filter(|s| elf.dynstrtab.get_at(s.st_name) == Some(name)),
        )
        .collect();
    require(
        labels.len() == 1,
        format!("constructor interior label {name} is absent/ambiguous"),
    )?;
    let label = labels[0];
    require(
        owner.st_bind() == sym::STB_LOCAL
            && owner.st_visibility() == sym::STV_HIDDEN
            && label.st_type() == sym::STT_NOTYPE
            && label.st_size == 0
            && label.st_bind() == sym::STB_LOCAL
            && label.st_visibility() == sym::STV_HIDDEN
            && label.st_shndx == owner.st_shndx
            && label.st_value >= owner.st_value
            && owner
                .st_value
                .checked_add(owner.st_size)
                .is_some_and(|end| label.st_value < end),
        format!(
            "constructor label {name} is not a unique hidden interior label of its actual function"
        ),
    )?;
    Ok(label)
}

const CONSTRUCTOR_GATE_OWNER_BYTES: &[u8] = &[
    0x41, 0x54, 0x4c, 0x8d, 0x25, 0x1c, 0, 0, 0, 0x48, 0x89, 0xf8, 0x48, 0x89, 0xf7, 0x48, 0x89,
    0xd6, 0x48, 0x89, 0xca, 0x4d, 0x89, 0xc2, 0x4d, 0x89, 0xc8, 0x4c, 0x8b, 0x4c, 0x24, 0x10, 0x0f,
    0x05, 0x41, 0xff, 0xe4, 0xf3, 0x0f, 0x1e, 0xfa, 0x41, 0x5c, 0xc3,
];
fn constructor_gate_operands(code: &[u8], ip_offset: u64, return_offset: u64) -> Result<()> {
    require(
        code == CONSTRUCTOR_GATE_OWNER_BYTES
            && ip_offset == 0x20
            && return_offset == 0x22
            && code.get(0x20..0x25) == Some(&[0x0f, 0x05, 0x41, 0xff, 0xe4]),
        "constructor gate owner/label offset is not the complete existing syscall/JMP R12 gate",
    )
}

// Objdump annotates NOTYPE interior labels with additional headers. Authenticate
// exactly these two annotations and their instruction cursor; retain the raw
// evidence verbatim and feed all instruction bytes to the unchanged strict
// verifier. This is not acceptance of arbitrary nested headers/functions.
fn constructor_gate_disassembly_view(
    text: &str,
    owner: &sym::Sym,
    labels: &BTreeMap<u64, &str>,
) -> Result<String> {
    let end = owner
        .st_value
        .checked_add(owner.st_size)
        .ok_or("gate owner range overflows")?;
    let mut within = false;
    let mut cursor = owner.st_value;
    let mut seen = BTreeSet::new();
    let mut output = String::new();
    for line in text.lines() {
        let trimmed = line.trim();
        if let Some((address, suffix)) = trimmed.split_once(" <").filter(|(_, s)| s.ends_with(">:"))
        {
            let address = u64::from_str_radix(address, 16)
                .map_err(|_| "invalid constructor disassembly header")?;
            if let Some(name) = labels.get(&address) {
                require(
                    within
                        && cursor == address
                        && suffix == format!("{name}>:")
                        && seen.insert(address),
                    "gate interior header is duplicate/misplaced or names the wrong actual label",
                )?;
                continue;
            }
            if within {
                require(cursor == end, "gate owner raw disassembly is truncated")?;
            }
            within = address == owner.st_value;
            if within {
                cursor = address;
            }
        } else if let Some((address, raw)) = trimmed
            .split_once(':')
            .and_then(|(address, raw)| {
                u64::from_str_radix(address.trim(), 16)
                    .ok()
                    .map(|address| (address, raw))
            })
            .filter(|_| within)
        {
            let bytes = raw
                .split_whitespace()
                .map_while(raw_byte)
                .collect::<Vec<_>>();
            require(
                address == cursor && !bytes.is_empty(),
                "gate annotation cursor has a gap or missing bytes",
            )?;
            cursor = cursor
                .checked_add(bytes.len() as u64)
                .ok_or("gate instruction cursor overflow")?;
            require(
                cursor <= end,
                "gate disassembly overruns its complete function",
            )?;
        }
        output.push_str(line);
        output.push('\n');
    }
    if within {
        require(cursor == end, "gate owner raw disassembly is incomplete")?;
    }
    require(
        seen.len() == labels.len(),
        "actual gate interior label header is missing",
    )?;
    Ok(output)
}

// Every qualification now includes the common trusted gate's whole function.
// Producer and independent consumer use only its two exact interior headers;
// arbitrary nested headers, byte coverage and graph rules remain unchanged.
fn verify_constructor_complete_bytes(
    elf: &Elf<'_>,
    _initializer: &str,
    text: &str,
    expected: &BTreeMap<u64, Vec<u8>>,
) -> Result<()> {
    let owner = private_function(elf, CONSTRUCTOR_GATE_OWNER)?;
    let ip = constructor_interior_label(elf, CONSTRUCTOR_GATE, &owner)?;
    let return_ip = constructor_interior_label(elf, CONSTRUCTOR_GATE_RETURN, &owner)?;
    let view = constructor_gate_disassembly_view(
        text,
        &owner,
        &BTreeMap::from([
            (ip.st_value, CONSTRUCTOR_GATE),
            (return_ip.st_value, CONSTRUCTOR_GATE_RETURN),
        ]),
    )?;
    verify_disassembly_bytes(&view, expected)
}

fn standalone_init_slot(elf: &Elf<'_>, bytes: &[u8], root: &sym::Sym) -> Result<(u64, String)> {
    let (generic_index, generic) = export(elf, GENERIC_INITIALIZER)?;
    let sections: Vec<_> = elf
        .section_headers
        .iter()
        .filter(|s| {
            s.sh_type == section_header::SHT_INIT_ARRAY
                && elf.shdr_strtab.get_at(s.sh_name) == Some(".init_array")
        })
        .collect();
    require(
        sections.len() == 1,
        "standalone requires one .init_array section",
    )?;
    let s = sections[0];
    require(
        s.sh_size > 0 && s.sh_size % 8 == 0 && s.sh_addr % 8 == 0,
        "standalone has invalid .init_array layout",
    )?;
    let entries = init_array_bytes(elf, bytes, s)?;
    loader_writers(elf)?;
    let mut root_slots = Vec::new();
    let mut generic_slots = Vec::new();
    for (i, entry) in entries.as_chunks::<8>().0.iter().enumerate() {
        let slot = s.sh_addr + i as u64 * 8;
        let raw = u64::from_le_bytes(*entry);
        let records = extent_writers(elf, slot, 8)?;
        require(
            records.len() <= 1
                && records.iter().all(|r| {
                    r.r_offset == slot
                        && descriptor_relocation_width(elf, r).is_ok_and(|width| width == 8)
                }),
            "partial or overlapping standalone init_array relocation writers",
        )?;
        let mut resolved = None;
        if let Some(r) = records.first() {
            let addend = r.r_addend.unwrap_or(raw as i64);
            if r.r_type == reloc::R_X86_64_RELATIVE && r.r_sym == 0 && addend >= 0 {
                resolved = Some(addend as u64);
            } else if r.r_type == reloc::R_X86_64_64 && addend == 0 {
                if r.r_sym == generic_index {
                    resolved = Some(generic.st_value);
                } else if let Some(symbol) = elf
                    .dynsyms
                    .get(r.r_sym)
                    .filter(|symbol| symbol.st_shndx != section_header::SHN_UNDEF as usize)
                {
                    resolved = Some(symbol.st_value);
                }
            }
        } else {
            require(
                raw != root.st_value && raw != generic.st_value,
                "standalone/generic initializer pointer lacks loader relocation",
            )?;
        }
        if resolved == Some(generic.st_value) {
            generic_slots.push(slot);
        }
        if resolved == Some(root.st_value) {
            let record = records
                .first()
                .ok_or("standalone root lacks loader relocation")?;
            let addend = record.r_addend.unwrap_or(raw as i64);
            require(
                record.r_type == reloc::R_X86_64_RELATIVE
                    && record.r_sym == 0
                    && addend >= 0
                    && addend as u64 == root.st_value,
                "standalone root requires an exact RELATIVE/symbol-zero relocation; a dynamic alias is not its loader identity",
            )?;
            root_slots.push(slot);
        }
    }
    Ok((unique_standalone_slot(&root_slots, &generic_slots)?,
        "Unique loader relocation to exact hidden standalone root; no generic initializer registration".to_owned()))
}

fn init_array_slot(
    elf: &Elf<'_>,
    bytes: &[u8],
    initializer_index: usize,
    initializer: &sym::Sym,
) -> Result<(u64, String)> {
    let sections: Vec<_> = elf
        .section_headers
        .iter()
        .filter(|s| {
            s.sh_type == section_header::SHT_INIT_ARRAY
                && elf.shdr_strtab.get_at(s.sh_name) == Some(".init_array")
        })
        .collect();
    require(
        sections.len() == 1,
        "required unique .init_array section absent",
    )?;
    let section = sections[0];
    require(
        section.sh_size > 0 && section.sh_size % 8 == 0 && section.sh_addr % 8 == 0,
        "invalid x86_64 init_array layout",
    )?;
    let entries = init_array_bytes(elf, bytes, section)?;
    loader_writers(elf)?;
    for (i, entry) in entries.as_chunks::<8>().0.iter().enumerate() {
        let slot = section.sh_addr + (i as u64) * 8;
        let raw = u64::from_le_bytes(*entry);
        let at_slot = extent_writers(elf, slot, 8)?;
        require(
            at_slot.len() <= 1
                && at_slot.iter().all(|r| {
                    r.r_offset == slot
                        && descriptor_relocation_width(elf, r).is_ok_and(|width| width == 8)
                }),
            "partial or overlapping init_array relocation writers",
        )?;
        if let Some(r) = at_slot.first() {
            let addend = r.r_addend.unwrap_or(raw as i64);
            if r.r_type == reloc::R_X86_64_RELATIVE
                && r.r_sym == 0
                && addend >= 0
                && addend as u64 == initializer.st_value
            {
                return Ok((
                    slot,
                    "R_X86_64_RELATIVE to exact initializer address".to_owned(),
                ));
            }
            if r.r_type == reloc::R_X86_64_64 && r.r_sym == initializer_index && addend == 0 {
                return Ok((
                    slot,
                    "R_X86_64_64 exact initializer symbol plus zero".to_owned(),
                ));
            }
        } else if raw == initializer.st_value {
            // A nonrelocated relative virtual address in ET_DYN is not a
            // callable pointer after ASLR. It cannot prove a real constructor.
            return Err("initializer address in init_array has no loader relocation".to_owned());
        }
    }
    Err(".init_array does not resolve an aligned slot to the required initializer".to_owned())
}

fn required_versions(text: &str) -> Result<Vec<String>> {
    let mut versions = BTreeSet::new();
    for line in text.lines() {
        let Some((_, rest)) = line.split_once("Name:") else {
            continue;
        };
        require(rest.contains("Flags:"), "malformed readelf version record")?;
        let name = rest
            .split_whitespace()
            .next()
            .ok_or("missing symbol version name")?;
        let components: Vec<_> = name
            .strip_prefix("GLIBC_2.")
            .ok_or_else(|| format!("guest preload requires unsupported version {name}"))?
            .split('.')
            .collect();
        require(
            (1..=2).contains(&components.len())
                && components
                    .iter()
                    .all(|c| !c.is_empty() && c.bytes().all(|b| b.is_ascii_digit())),
            format!("unsupported guest symbol version {name}"),
        )?;
        let minor: u32 = components[0]
            .parse()
            .map_err(|e| format!("glibc version: {e}"))?;
        require(
            minor <= 34,
            format!("guest preload requires {name}, above GLIBC_2.34 floor"),
        )?;
        versions.insert(name.to_owned());
    }
    Ok(versions.into_iter().collect())
}

fn elf_required_versions(elf: &Elf<'_>) -> Result<Vec<String>> {
    let mut names = BTreeSet::new();
    if let Some(verneed) = &elf.verneed {
        for need in verneed.iter() {
            let mut observed = 0usize;
            for auxiliary in need.iter() {
                let name = elf
                    .dynstrtab
                    .get_at(auxiliary.vna_name)
                    .ok_or("ELF version need has invalid string offset")?;
                // Use exactly the same version parser as retained readelf.
                names.extend(required_versions(&format!("Name: {name} Flags: none"))?);
                observed += 1;
            }
            require(
                observed == usize::from(need.vn_cnt),
                "truncated ELF symbol-version requirements",
            )?;
        }
    }
    Ok(names.into_iter().collect())
}

/// Resolve a GOT slot only when the loader's unique relocation computes an
/// exact locally bound function address without lookup in another DSO.
fn local_got_targets(elf: &Elf<'_>, bytes: &[u8]) -> Result<BTreeMap<u64, u64>> {
    authenticate_loader_metadata(elf, bytes)?;
    let local_functions: BTreeSet<_> = elf
        .syms
        .iter()
        .filter(|s| executable_symbol(elf, s) && s.st_bind() == sym::STB_LOCAL)
        .map(|s| s.st_value)
        .collect();
    let mut qualified = BTreeMap::new();
    for writer in loader_writers(elf)? {
        let r = &writer.relocation;
        let slot = r.r_offset;
        if r.r_type != reloc::R_X86_64_RELATIVE || r.r_sym != 0 {
            continue;
        }
        let Some(addend) = r.r_addend else {
            continue;
        };
        if addend < 0 || !local_functions.contains(&(addend as u64)) {
            continue;
        }
        // Slot must be loader-mapped and made read-only after relocations;
        // otherwise runtime writes could change the observed pointer route.
        let in_relro = elf.program_headers.iter().any(|p| {
            p.p_type == program_header::PT_GNU_RELRO
                && slot >= p.p_vaddr
                && slot
                    .checked_add(8)
                    .is_some_and(|end| end <= p.p_vaddr.saturating_add(p.p_memsz))
        });
        if in_relro && readonly_loaded_bytes(elf, bytes, slot, 8).is_ok() {
            qualified.insert(slot, addend as u64);
        }
    }
    Ok(qualified)
}

/// Direct calls/tail calls and RIP-relative indirect calls with independently
/// qualified local RELATIVE GOT slots are admissible. Register-indirect calls
/// and other unsupported paths earn no edge, so required unresolved paths fail.
type CallGraph = BTreeMap<u64, BTreeSet<u64>>;

const MAX_OBJDUMP_BYTES: usize = 64 * 1024 * 1024;

/// The complete node union admitted by the existing required-route and named
/// allocator graphs. Scope is derived from the ELF, not a receipt or a successful
/// path: unchosen alternatives remain part of the required byte evidence.
fn proof_functions(elf: &Elf<'_>, initializer_name: &str) -> Result<BTreeMap<u64, u64>> {
    if initializer_name == STANDALONE_ROOT {
        require_legacy_standalone_gate(elf)?;
    }
    let mut addresses: BTreeSet<_> = elf
        .syms
        .iter()
        .filter(|s| executable_symbol(elf, s))
        .filter_map(|s| {
            elf.strtab
                .get_at(s.st_name)
                .filter(|name| {
                    allocation_wrapper(name)
                        || qualifies_owned_endpoint(name)
                        || (s.st_bind() == sym::STB_LOCAL
                            && (name.contains("PrivatePatchAllocator")
                                || name.contains("PrivateToolAllocator")))
                })
                .map(|_| s.st_value)
        })
        .collect();
    addresses.extend(
        fixed_role_symbols(elf)?
            .values()
            .map(|symbol| symbol.st_value),
    );
    // Do not let a naming predicate prune a mandatory entry or compiler shim.
    for name in EXPORTS {
        addresses.insert(export(elf, name)?.1.st_value);
    }
    if initializer_name == STANDALONE_ROOT {
        addresses.extend(constructor_proof_functions(elf)?.keys().copied());
    } else if initializer_name == DETCORE_ROOT {
        addresses.extend(detcore_proof_functions(elf)?.keys().copied());
    } else {
        addresses.insert(export(elf, initializer_name)?.1.st_value);
    }
    addresses.extend(generic_symbols(elf)?.values().map(|s| s.st_value));
    for shim in SHIMS {
        let candidates: Vec<_> = elf
            .syms
            .iter()
            .filter(|s| executable_symbol(elf, s))
            .filter(|s| {
                elf.strtab
                    .get_at(s.st_name)
                    .is_some_and(|name| name == shim || name.ends_with(shim))
            })
            .collect();
        require(
            candidates.len() == 1,
            format!("required unique compiler-selected shim {shim} absent/ambiguous"),
        )?;
        addresses.insert(candidates[0].st_value);
    }
    selected_function_ranges(elf, addresses)
}

/// The standalone constructor scope is independent of diagnostic M1 exports,
/// but retains every private constructor and generic bootstrap role.
fn constructor_proof_functions(elf: &Elf<'_>) -> Result<BTreeMap<u64, u64>> {
    require_legacy_standalone_gate(elf)?;
    let addresses = combined_bootstrap_symbols(elf)?
        .values()
        .map(|s| s.st_value)
        .chain(fixed_role_symbols(elf)?.values().map(|s| s.st_value))
        .chain(
            fixed_heap_equal_candidates(elf)?
                .values()
                .map(|s| s.st_value),
        )
        .chain(compiler_shim_symbols(elf)?.values().map(|s| s.st_value))
        .collect();
    selected_function_ranges(elf, addresses)
}

fn detcore_proof_functions(elf: &Elf<'_>) -> Result<BTreeMap<u64, u64>> {
    let mut symbols = detcore_symbols(elf)?;
    for (name, function) in generic_symbols(elf)? {
        if let Some(shared) = symbols.get(&name) {
            require(
                *shared == function,
                "Detcore and generic proofs disagree about a shared role",
            )?;
        } else {
            symbols.insert(name, function);
        }
    }
    require_disjoint_bootstrap_roles(&symbols)?;
    let addresses = symbols
        .values()
        .map(|s| s.st_value)
        .chain(fixed_role_symbols(elf)?.values().map(|s| s.st_value))
        .chain(compiler_shim_symbols(elf)?.values().map(|s| s.st_value))
        .collect();
    selected_function_ranges(elf, addresses)
}

fn selected_function_ranges(elf: &Elf<'_>, addresses: BTreeSet<u64>) -> Result<BTreeMap<u64, u64>> {
    let mut functions = BTreeMap::new();
    for address in addresses {
        let sizes: BTreeSet<_> = elf
            .syms
            .iter()
            .chain(elf.dynsyms.iter())
            .filter(|s| {
                s.st_type() == sym::STT_FUNC
                    && s.st_shndx != section_header::SHN_UNDEF as usize
                    && s.st_value == address
            })
            .map(|s| s.st_size)
            .collect();
        require(
            sizes.len() == 1 && !sizes.contains(&0),
            format!("selected function {address:#x} has absent/conflicting alias sizes"),
        )?;
        let size = *sizes.iter().next().unwrap();
        require(
            address.checked_add(size).is_some(),
            format!("selected function {address:#x} overflows its address range"),
        )?;
        functions.insert(address, size);
    }
    Ok(functions)
}

/// Independently read every selected function's complete bytes from its
/// file-backed executable PT_LOAD range. Memory-only tails are not evidence.
fn proof_function_bytes(
    elf: &Elf<'_>,
    bytes: &[u8],
    functions: &BTreeMap<u64, u64>,
) -> Result<BTreeMap<u64, Vec<u8>>> {
    authenticate_loader_metadata(elf, bytes)?;
    let mut expected = BTreeMap::new();
    let mut total = 0usize;
    let writers = loader_writers(elf)?;
    for (&address, &size) in functions {
        let end = address.checked_add(size).ok_or("function range overflow")?;
        let size = usize::try_from(size).map_err(|_| "function size exceeds usize")?;
        let (mapping, offset) = unique_file_mapping(elf, bytes, address, size)?;
        require(
            mapping.p_flags == program_header::PF_R | program_header::PF_X,
            "selected complete function is not in an actual RX mapping",
        )?;
        require(
            writers
                .iter()
                .all(|writer| writer.relocation.r_offset >= end || writer.end <= address),
            "runtime relocation writes into a selected complete function",
        )?;
        for relro in elf
            .program_headers
            .iter()
            .filter(|p| p.p_type == program_header::PT_GNU_RELRO)
        {
            let relro_end = relro
                .p_vaddr
                .checked_add(relro.p_memsz)
                .ok_or("GNU_RELRO extent overflows")?
                & !4095;
            require(
                (relro.p_vaddr & !4095) >= end || relro_end <= address,
                "GNU_RELRO replaces selected executable page permissions",
            )?;
        }
        let code = &bytes[offset..offset + size];
        total = total
            .checked_add(size)
            .ok_or("selected function byte total overflow")?;
        require(
            total <= MAX_OBJDUMP_BYTES,
            "selected function bytes exceed disassembly output cap",
        )?;
        expected.insert(address, code.to_vec());
    }
    Ok(expected)
}

fn raw_byte(word: &str) -> Option<u8> {
    (word.len() == 2 && word.bytes().all(|b| b.is_ascii_hexdigit()))
        .then(|| u8::from_str_radix(word, 16).unwrap())
}

/// A header is not completeness evidence. Require each selected interval once,
/// contiguous instruction addresses, and an exact match for every ELF byte.
fn verify_disassembly_bytes(text: &str, expected: &BTreeMap<u64, Vec<u8>>) -> Result<()> {
    require(!expected.is_empty(), "no selected disassembly functions")?;
    let mut consumed = BTreeMap::<u64, usize>::new();
    let mut current = None;
    for line in text.lines() {
        let trimmed = line.trim();
        let header = trimmed
            .split_once(" <")
            .filter(|(_, suffix)| suffix.ends_with(">:"))
            .and_then(|(addr, _)| u64::from_str_radix(addr, 16).ok());
        if let Some(address) = header {
            if let Some(source) = current {
                require(
                    consumed[&source] == expected[&source].len(),
                    format!("selected function {source:#x} disassembly is truncated"),
                )?;
            }
            require(
                expected.contains_key(&address),
                format!("unselected disassembly function {address:#x}"),
            )?;
            require(
                !consumed.contains_key(&address),
                format!("duplicate disassembly function {address:#x}"),
            )?;
            consumed.insert(address, 0);
            current = Some(address);
            continue;
        }
        let Some((address, instruction)) = trimmed.split_once(':') else {
            continue;
        };
        let Ok(address) = u64::from_str_radix(address.trim(), 16) else {
            continue;
        };
        let source = current.ok_or("instruction outside selected function header")?;
        let mut words = instruction.split_whitespace().peekable();
        let mut raw = Vec::new();
        while let Some(byte) = words.peek().and_then(|word| raw_byte(word)) {
            raw.push(byte);
            words.next();
        }
        require(
            !raw.is_empty() && raw.len() <= 15 && words.next().is_some(),
            format!("instruction {address:#x} lacks complete raw x86 bytes/mnemonic"),
        )?;
        let offset = consumed[&source];
        let next = source
            .checked_add(offset as u64)
            .ok_or("instruction address overflow")?;
        require(
            address == next,
            format!("function {source:#x} has a gap/duplicate at {address:#x}, expected {next:#x}"),
        )?;
        let end = offset
            .checked_add(raw.len())
            .ok_or("instruction byte range overflow")?;
        let code = expected[&source]
            .get(offset..end)
            .ok_or_else(|| format!("function {source:#x} disassembly overruns its ELF interval"))?;
        require(
            raw == code,
            format!("instruction {address:#x} raw bytes differ from actual ELF"),
        )?;
        consumed.insert(source, end);
    }
    require(
        consumed.len() == expected.len(),
        "selected function disassembly is missing a range",
    )?;
    for (address, bytes) in expected {
        require(
            consumed.get(address) == Some(&bytes.len()),
            format!("selected function {address:#x} disassembly is incomplete"),
        )?;
    }
    Ok(())
}

// These are finite checks for the reviewed constructor, not another call-graph
// rule. In particular no register-indirect edge is added to disassembly_edges.
struct ConstructorCode<'a> {
    address: u64,
    bytes: &'a [u8],
    offset: usize,
}

impl<'a> ConstructorCode<'a> {
    fn ip(&self) -> u64 {
        self.address + self.offset as u64
    }
    fn exact(&mut self, expected: &[u8]) -> Result<u64> {
        let ip = self.ip();
        let end = self
            .offset
            .checked_add(expected.len())
            .ok_or("constructor byte overflow")?;
        require(
            self.bytes.get(self.offset..end) == Some(expected),
            format!("unsupported constructor instruction/operand at {ip:#x}"),
        )?;
        self.offset = end;
        Ok(ip)
    }
    fn relative(&mut self, opcode: &[u8]) -> Result<(u64, u64)> {
        let ip = self.exact(opcode)?;
        let end = self
            .offset
            .checked_add(4)
            .ok_or("constructor displacement overflow")?;
        let raw = self
            .bytes
            .get(self.offset..end)
            .ok_or("truncated constructor displacement")?;
        let displacement = i32::from_le_bytes(raw.try_into().unwrap());
        self.offset = end;
        let target = self
            .ip()
            .checked_add_signed(i64::from(displacement))
            .ok_or("constructor relative address overflow")?;
        Ok((ip, target))
    }
    fn conditional(&mut self, condition: u8) -> Result<u64> {
        if self.bytes.get(self.offset) == Some(&(0x70 | condition)) {
            self.exact(&[0x70 | condition])?;
            let byte = *self
                .bytes
                .get(self.offset)
                .ok_or("truncated constructor branch")?;
            self.offset += 1;
            self.ip()
                .checked_add_signed(i64::from(byte as i8))
                .ok_or_else(|| "constructor branch overflow".to_owned())
        } else {
            self.relative(&[0x0f, 0x80 | condition])
                .map(|(_, target)| target)
        }
    }
    fn jump(&mut self) -> Result<ConstructorTransfer> {
        let ip = self.ip();
        let target = if self.bytes.get(self.offset) == Some(&0xeb) {
            self.exact(&[0xeb])?;
            let byte = *self
                .bytes
                .get(self.offset)
                .ok_or("truncated constructor jump")?;
            self.offset += 1;
            self.ip()
                .checked_add_signed(i64::from(byte as i8))
                .ok_or("constructor jump overflow")?
        } else {
            self.relative(&[0xe9])?.1
        };
        Ok(ConstructorTransfer {
            instruction: ip,
            target,
            local_got_slot: None,
        })
    }
    fn transfer(&mut self, call: bool, got: &BTreeMap<u64, u64>) -> Result<ConstructorTransfer> {
        if self.bytes.get(self.offset) == Some(&(if call { 0xe8 } else { 0xe9 })) {
            let (instruction, target) = self.relative(&[if call { 0xe8 } else { 0xe9 }])?;
            Ok(ConstructorTransfer {
                instruction,
                target,
                local_got_slot: None,
            })
        } else {
            let (instruction, slot) = self.relative(&[0xff, if call { 0x15 } else { 0x25 }])?;
            let target = *got
                .get(&slot)
                .ok_or("constructor transfer is not an exact LOCAL RELATIVE GOT route")?;
            Ok(ConstructorTransfer {
                instruction,
                target,
                local_got_slot: Some(slot),
            })
        }
    }
    fn done(&self) -> Result<()> {
        require(
            self.offset == self.bytes.len(),
            "constructor has unchecked trailing instructions",
        )
    }
}

fn loaded_bytes<'a>(
    elf: &Elf<'_>,
    bytes: &'a [u8],
    address: u64,
    length: usize,
) -> Result<&'a [u8]> {
    let (mapping, offset) = unique_file_mapping(elf, bytes, address, length)?;
    require(
        mapping.p_flags & program_header::PF_R != 0,
        "constructor data lacks an actual readable mapping",
    )?;
    Ok(&bytes[offset..offset + length])
}

struct PrefixRoute {
    environ: u64,
    selector: u64,
    materialization: u64,
    active: ConstructorTransfer,
    inert: ConstructorTransfer,
}

fn standalone_prefix(
    code: &[u8],
    address: u64,
    body: u64,
    bridge: u64,
    resolver: u64,
) -> Result<PrefixRoute> {
    let mut c = ConstructorCode {
        address,
        bytes: code,
        offset: 0,
    };
    c.exact(&[0xf3, 0x0f, 0x1e, 0xfa])?;
    let (_, environ) = c.relative(&[0x48, 0x8b, 0x05])?;
    c.exact(&[0x48, 0x8b, 0x10, 0x48, 0x85, 0xd2])?;
    let no_vector = c.conditional(4)?;
    let (_, selector) = c.relative(&[0x4c, 0x8d, 0x05])?;
    let vector_loop = c.ip();
    c.exact(&[0x4c, 0x8b, 0x12, 0x4d, 0x85, 0xd2])?;
    let vector_end = c.conditional(4)?;
    c.exact(&[0x45, 0x31, 0xc9])?;
    let byte_loop = c.ip();
    c.exact(&[0x43, 0x8a, 0x04, 0x0a, 0x84, 0xc0])?;
    let short_entry = c.conditional(4)?;
    c.exact(&[0x43, 0x3a, 0x04, 0x08])?;
    let mismatch = c.conditional(5)?;
    c.exact(&[0x41, 0xff, 0xc1, 0x41, 0x83, 0xf9, 22])?;
    require(
        c.conditional(5)? == byte_loop,
        "selector byte loop has wrong destination",
    )?;
    let (materialization, supplied_body) = c.relative(&[0x48, 0x8d, 0x3d])?;
    let active = c.jump()?;
    let next_entry = c.ip();
    c.exact(&[0x48, 0x83, 0xc2, 8])?;
    require(
        c.jump()?.target == vector_loop,
        "selector vector loop has wrong destination",
    )?;
    let inert_entry = c.ip();
    let inert = c.jump()?;
    c.done()?;
    require(
        supplied_body == body && active.target == bridge && inert.target == resolver,
        "standalone prefix does not materialize/transfer to its actual owned body/bridge/resolver",
    )?;
    require(
        no_vector == inert_entry
            && vector_end == inert_entry
            && short_entry == next_entry
            && mismatch == next_entry,
        "standalone missing/short/mismatched selector branch is wrong",
    )?;
    Ok(PrefixRoute {
        environ,
        selector,
        materialization,
        active,
        inert,
    })
}

fn standalone_body_order(
    code: &[u8],
    address: u64,
    helper: u64,
    resolver: u64,
    got: &BTreeMap<u64, u64>,
) -> Result<(ConstructorTransfer, ConstructorTransfer)> {
    let mut c = ConstructorCode {
        address,
        bytes: code,
        offset: 0,
    };
    if c.bytes.starts_with(&[0xf3, 0x0f, 0x1e, 0xfa]) {
        c.exact(&[0xf3, 0x0f, 0x1e, 0xfa])?;
    }
    let push = c.bytes.get(c.offset) == Some(&0x50);
    c.exact(if push {
        &[0x50]
    } else {
        &[0x48, 0x83, 0xec, 8]
    })?;
    let initialization = c.transfer(true, got)?;
    let resolution = if c.bytes.get(c.offset) == Some(&0x58)
        || c.bytes.get(c.offset..c.offset + 4) == Some(&[0x48, 0x83, 0xc4, 8])
    {
        c.exact(if push {
            &[0x58]
        } else {
            &[0x48, 0x83, 0xc4, 8]
        })?;
        c.transfer(false, got)?
    } else {
        let resolution = c.transfer(true, got)?;
        c.exact(if push {
            &[0x58]
        } else {
            &[0x48, 0x83, 0xc4, 8]
        })?;
        c.exact(&[0xc3])?;
        resolution
    };
    c.done()?;
    require(
        initialization.target == helper && resolution.target == resolver,
        "active standalone body does not finish its exact initializer before explicit resolution",
    )?;
    Ok((initialization, resolution))
}

const NATIVE_DISPATCH_VERSION: u32 = 1;
const CONSTRUCTOR_RECORD: u64 = 0x6000_0002_1030;
const GENERIC_RECORD: u64 = 0x6000_0002_10a0;
const CONSTRUCTOR_BOTTOM: u64 = 0x6000_0010_1000;
const CONSTRUCTOR_TOP: u64 = 0x6000_0090_1000;

/// PCs are populated only by the complete actual emitted native recipe.
/// The supplied-body CALL is not represented as a direct graph edge.
struct NativeDispatchRoute {
    prepare: ConstructorTransfer,
    prepare_return: u64,
    body_retain: u64,
    ready_gate: u64,
    body_identity_check: u64,
    body_sample_store: u64,
    body_call: u64,
    body_return: u64,
    returned_store: u64,
    body_save: u64,
    stack_switch: u64,
    restore: u64,
    native_return: u64,
    terminal_exit: ConstructorTransfer,
    terminal_ud2: u64,
}

// Actual root build-only emission01: complete744B Constructor and669B
// ExplicitGeneric native functions. Normal-release and diagnostic-dev match
// byte-for-byte after only the independently checked displacement fields.
const CONSTRUCTOR_NATIVE_HEX: &str = concat!(
    "f30f1efa66480f6ec466480f6ecb66480f6ed566490f6edc66490f6ee566490f6eee66490f6ef766480f6eff31c0b201f00fb015448d09040f8543020000b80900000048bf000000000060000048be000000000100000031d241",
    "ba2200100049c7c0ffffffff4531c94c8d2505000000e95f3c0000f30f1efa4885c00f88ff01000049bd00000000006000004c39e874274889c748be0000000001000000b80b0000004c8d2505000000e9253c0000f30f1efae9",
    "c901000048bf0010000000600000be00f00f00ba03000000b80a0000004c8d2505000000e9f73b0000f30f1efa4885c00f859701000049bd001000000060000041c6450000498d7d28b92000000048c707ffffffff4883c708ff",
    "c975f148c7070300000049be301002000060000066480f7ec049890666480f7ec84989460866480f7ed04989461066480f7ed84989461866480f7ee04989462066480f7ee84989462866480f7ef04989463066480f7ef8498946",
    "3849c746500100000049c7464801000000b8ba0000004c8d2505000000e94a3b0000f30f1efa4885c00f8eea0000004989464048bf0010100000600000be00008000ba03000000b80a0000004c8d2505000000e9143b0000f30f",
    "1efa4885c00f85b400000066490f7eff48bc00109000006000004c89f7e8900f000085c00f859500000048b800109000006000004839c40f858200000049be301002000060000049837e5001757149837e4803756a803d5e8b09",
    "040075614d85ff745c4d397e3875564883ec104989666041ffd748b8f00f9000006000004839c4753c4883c41049be301002000060000049c746480400000048b83010020000600000488b5808488b68104c8b60184c8b68204c",
    "8b70284c8b7830488b20c3b801000000bf02000000488d3531000000ba250000004c8d2505000000e9313a0000f30f1efab8e7000000bf7f0000004c8d2505000000e9173a0000f30f1efa0f0b7265766572696520636f6e7374",
    "727563746f7220626f6f747374726170206661696c65640a",
);

#[derive(Clone, Copy)]
enum NativeDispatchOrigin {
    Constructor,
    ExplicitGeneric,
}

fn native_template(origin: NativeDispatchOrigin) -> Vec<u8> {
    let mut code = CONSTRUCTOR_NATIVE_HEX
        .as_bytes()
        .as_chunks::<2>()
        .0
        .iter()
        .map(|pair| u8::from_str_radix(std::str::from_utf8(pair).unwrap(), 16).unwrap())
        .collect::<Vec<_>>();
    if matches!(origin, NativeDispatchOrigin::ExplicitGeneric) {
        code.truncate(0x281);
        for offset in [0x11a, 0x201, 0x24b, 0x25d] {
            code[offset..offset + 8].copy_from_slice(&GENERIC_RECORD.to_le_bytes());
        }
        code.extend_from_slice(&[
            0xb8, 0xe7, 0x00, 0x00, 0x00, 0xbf, 0x7f, 0x00, 0x00, 0x00, 0x4c, 0x8d, 0x25, 0x05,
            0x00, 0x00, 0x00, 0xe9, 0x55, 0x37, 0x00, 0x00, 0xf3, 0x0f, 0x1e, 0xfa, 0x0f, 0x0b,
        ]);
    }
    code
}

fn native_dispatch_bridge(
    code: &[u8],
    address: u64,
    initializing: u64,
    gate: u64,
    prepare: u64,
    origin: NativeDispatchOrigin,
) -> Result<NativeDispatchRoute> {
    let template = native_template(origin);
    require(
        code.len() == template.len(),
        "native dispatch has unsupported complete extent",
    )?;
    require(
        address.checked_add(code.len() as u64).is_some(),
        "native dispatch address range overflows",
    )?;
    let mut fields = vec![
        (0x34, initializing, 0x38),
        (0x71, gate, 0x75),
        (0xab, gate, 0xaf),
        (0xd9, gate, 0xdd),
        (0x186, gate, 0x18a),
        (0x1bc, gate, 0x1c0),
        (0x1e0, prepare, 0x1e4),
        // CMP [RIP+disp32],0: RIP base includes the final immediate byte.
        (0x219, initializing, 0x21e),
    ];
    let (terminal_exit, terminal_ud2) = match origin {
        NativeDispatchOrigin::Constructor => {
            fields.extend([(0x29f, gate, 0x2a3), (0x2b9, gate, 0x2bd)]);
            (0x2b8, 0x2c1)
        }
        NativeDispatchOrigin::ExplicitGeneric => {
            fields.push((0x293, gate, 0x297));
            (0x292, 0x29b)
        }
    };
    for &(offset, target, end) in &fields {
        let displacement = i32::from_le_bytes(code[offset..offset + 4].try_into().unwrap());
        require(
            address
                .checked_add(end)
                .and_then(|end| end.checked_add_signed(i64::from(displacement)))
                == Some(target),
            format!(
                "native dispatch displacement at {:#x} is not its exact local target",
                address + offset as u64
            ),
        )?;
    }
    for (offset, (&actual, &expected)) in code.iter().zip(&template).enumerate() {
        if !fields
            .iter()
            .any(|(start, _, _)| (*start..*start + 4).contains(&offset))
        {
            require(
                actual == expected,
                format!(
                    "native dispatch opcode/operand differs at {:#x}",
                    address + offset as u64
                ),
            )?;
        }
    }
    // The entire byte sequence proves original RDI→XMM7/bodyfield→R15,
    // exact fresh origin/RDI, scalar prepare, status/TOP/version/READY/guard/
    // identity gates, frame16/interior sample and sole41FFD7 CALL. Returned
    // RSP is compared (never reseeded); ADD16 and RETURNED precede the full
    // literal-record scalar restore and RET. Every fatal branch/terminal byte
    // is checked, including Constructor's fixed diagnostic string.
    Ok(NativeDispatchRoute {
        prepare: ConstructorTransfer {
            instruction: address + 0x1df,
            target: prepare,
            local_got_slot: None,
        },
        prepare_return: address + 0x1e4,
        body_retain: address + 0x1cd,
        ready_gate: address + 0x210,
        body_identity_check: address + 0x225,
        body_sample_store: address + 0x22f,
        body_call: address + 0x233,
        body_return: address + 0x236,
        returned_store: address + 0x253,
        body_save: address + 0x165,
        stack_switch: address + 0x1d2,
        restore: address + 0x25b,
        native_return: address + 0x280,
        terminal_exit: ConstructorTransfer {
            instruction: address + terminal_exit,
            target: gate,
            local_got_slot: None,
        },
        terminal_ud2: address + terminal_ud2,
    })
}

fn constructor_native_bridge(
    code: &[u8],
    address: u64,
    initializing: u64,
    gate: u64,
    prepare: u64,
) -> Result<NativeDispatchRoute> {
    native_dispatch_bridge(
        code,
        address,
        initializing,
        gate,
        prepare,
        NativeDispatchOrigin::Constructor,
    )
}

fn generic_entry_prefix(
    code: &[u8],
    address: u64,
    body: u64,
    bridge: u64,
) -> Result<(u64, ConstructorTransfer)> {
    require(
        code.len() == 16,
        "public generic initializer has unsupported complete extent",
    )?;
    let mut entry = ConstructorCode {
        address,
        bytes: code,
        offset: 0,
    };
    entry.exact(&[0xf3, 0x0f, 0x1e, 0xfa])?;
    let (body_materialization, actual_body) = entry.relative(&[0x48, 0x8d, 0x3d])?;
    require(
        actual_body == body,
        "public generic initializer does not materialize its exact hidden body in RDI",
    )?;
    // Require the native direct E9, not an arbitrary graph/GOT/register route.
    let (instruction, target) = entry.relative(&[0xe9])?;
    require(
        target == bridge,
        "public generic initializer does not tail-jump to its exact hidden native bridge",
    )?;
    entry.done()?;
    Ok((
        body_materialization,
        ConstructorTransfer {
            instruction,
            target,
            local_got_slot: None,
        },
    ))
}

fn generic_native_bridge(
    code: &[u8],
    address: u64,
    initializing: u64,
    gate: u64,
    prepare: u64,
) -> Result<NativeDispatchRoute> {
    native_dispatch_bridge(
        code,
        address,
        initializing,
        gate,
        prepare,
        NativeDispatchOrigin::ExplicitGeneric,
    )
}

#[derive(Clone)]
struct EncodedConstructorInstruction {
    address: u64,
    bytes: Vec<u8>,
}

fn constructor_instructions(
    text: &str,
    function: u64,
) -> Result<Vec<EncodedConstructorInstruction>> {
    let mut selected = false;
    let mut instructions = Vec::new();
    for line in text.lines() {
        let line = line.trim();
        if let Some((address, suffix)) = line
            .split_once(" <")
            .filter(|(_, suffix)| suffix.ends_with(">:"))
        {
            let _ = suffix;
            selected = u64::from_str_radix(address, 16).ok() == Some(function);
            continue;
        }
        if !selected {
            continue;
        }
        let Some((address, rest)) = line.split_once(':') else {
            continue;
        };
        let Ok(address) = u64::from_str_radix(address.trim(), 16) else {
            continue;
        };
        let bytes = rest
            .split_whitespace()
            .map_while(raw_byte)
            .collect::<Vec<_>>();
        require(
            !bytes.is_empty(),
            "constructor instruction lacks checked raw bytes",
        )?;
        instructions.push(EncodedConstructorInstruction { address, bytes });
    }
    require(
        !instructions.is_empty(),
        "constructor instruction range missing",
    )?;
    Ok(instructions)
}

/// Census every actual instruction in the complete prepare function. Only
/// direct private helper transfers and independently resolved local RELATIVE
/// GOT transfers to those same exact roles are admitted. A register-indirect
/// supplied-body transfer is never a preparation helper, at any position.
fn preparation_transfers(
    instructions: &[EncodedConstructorInstruction],
    got: &BTreeMap<u64, u64>,
    helpers: &BTreeSet<u64>,
) -> Result<(Vec<ConstructorTransfer>, Vec<GotEdge>)> {
    let first = instructions
        .first()
        .ok_or("empty complete prepare function")?
        .address;
    let mut expected = first;
    let mut boundaries = BTreeSet::new();
    for instruction in instructions {
        require(
            instruction.address == expected && !instruction.bytes.is_empty(),
            "prepare instruction sequence is discontinuous/empty",
        )?;
        boundaries.insert(instruction.address);
        expected = expected
            .checked_add(instruction.bytes.len() as u64)
            .ok_or("prepare instruction range overflows")?;
    }
    let mut transfers = Vec::new();
    let mut edges = Vec::new();
    for instruction in instructions {
        let bytes = &instruction.bytes;
        let prefix = bytes
            .iter()
            .take_while(|byte| {
                matches!(
                    **byte,
                    0xf0 | 0xf2
                        | 0xf3
                        | 0x26
                        | 0x2e
                        | 0x36
                        | 0x3e
                        | 0x64
                        | 0x65
                        | 0x66
                        | 0x67
                        | 0x40..=0x4f
                )
            })
            .count();
        let opcode = *bytes.get(prefix).ok_or("prefix-only prepare instruction")?;
        let second = if opcode == 0x0f {
            Some(
                *bytes
                    .get(prefix + 1)
                    .ok_or("truncated prepare two-byte opcode")?,
            )
        } else {
            None
        };
        let system_group = if second == Some(0x01) {
            Some(
                *bytes
                    .get(prefix + 2)
                    .ok_or("truncated prepare system-group opcode")?,
            )
        } else {
            None
        };
        // Intentional kernel/system/interrupt transfers have no independently
        // qualified helper target. Raw SYSCALL belongs only to the separately
        // byte-qualified trusted gate, never to ordinary Rust preparation.
        require(
            !matches!(opcode, 0xcc | 0xcd | 0xce | 0xcf | 0xf1 | 0xf4)
                && !matches!(second, Some(0x05 | 0x07 | 0x0b | 0x34 | 0x35 | 0x37 | 0xaa))
                && !matches!(system_group, Some(0xc1..=0xc3 | 0xd9)),
            "unqualified prepare kernel/system/interrupt transfer",
        )?;
        let relative = |offset: usize, width: usize| -> Result<u64> {
            let displacement = match width {
                1 => i64::from(*bytes.get(offset).ok_or("truncated prepare branch")? as i8),
                4 => i64::from(i32::from_le_bytes(
                    bytes
                        .get(offset..offset + 4)
                        .ok_or("truncated prepare transfer")?
                        .try_into()
                        .unwrap(),
                )),
                _ => return Err("unsupported prepare displacement width".to_owned()),
            };
            instruction
                .address
                .checked_add(bytes.len() as u64)
                .and_then(|end| end.checked_add_signed(displacement))
                .ok_or("prepare transfer target overflows".to_owned())
        };
        if matches!(opcode, 0xe8 | 0xe9 | 0xeb | 0x70..=0x7f | 0xe0..=0xe3)
            || (opcode == 0x0f
                && bytes
                    .get(prefix + 1)
                    .is_some_and(|b| (0x80..=0x8f).contains(b)))
        {
            require(
                prefix == 0,
                "prefixed prepare direct transfer is unsupported",
            )?;
            let (offset, width, external) = match opcode {
                0xe8 | 0xe9 => (1, 4, true),
                0xeb => (1, 1, true),
                0x0f => (2, 4, false),
                _ => (1, 1, false),
            };
            require(
                bytes.len() == offset + width,
                "extra/truncated prepare direct transfer",
            )?;
            let target = relative(offset, width)?;
            if boundaries.contains(&target) && opcode != 0xe8 {
                continue;
            }
            require(
                external && helpers.contains(&target),
                format!(
                    "prepare direct transfer is not an exact private preparation role/in-function branch: function {first:#x}, instruction {:#x}, target {target:#x}",
                    instruction.address,
                ),
            )?;
            transfers.push(ConstructorTransfer {
                instruction: instruction.address,
                target,
                local_got_slot: None,
            });
        } else if opcode == 0xff {
            let modrm = *bytes
                .get(prefix + 1)
                .ok_or("truncated prepare FF instruction")?;
            if !matches!((modrm >> 3) & 7, 2..=5) {
                continue;
            }
            require(
                prefix == 0 && bytes.len() == 6 && bytes.starts_with(&[0xff, 0x15]),
                "unsupported prepare register/memory/prefixed indirect call/jump",
            )?;
            let slot = relative(2, 4)?;
            let target = *got
                .get(&slot)
                .ok_or("prepare call GOT is unresolved/preemptible")?;
            require(
                helpers.contains(&target),
                format!(
                    "prepare GOT target lacks exact private helper role: function {first:#x}, instruction {:#x}, slot {slot:#x}, target {target:#x}",
                    instruction.address,
                ),
            )?;
            transfers.push(ConstructorTransfer {
                instruction: instruction.address,
                target,
                local_got_slot: Some(slot),
            });
            edges.push(GotEdge {
                source_function: first,
                instruction: instruction.address,
                slot,
                target_function: target,
            });
        } else {
            require(
                !matches!(opcode, 0x9a | 0xea | 0xca | 0xcb | 0xcf),
                "unsupported prepare far transfer/return",
            )?;
            if opcode == 0xc3 {
                require(
                    prefix == 0 && bytes.len() == 1,
                    "prefixed/extra prepare RET",
                )?;
            }
            require(opcode != 0xc2, "prepare RET with immediate is unsupported")?;
        }
    }
    Ok((transfers, edges))
}

fn qualify_prefix_data(
    elf: &Elf<'_>,
    bytes: &[u8],
    environ_slot: u64,
    selector: u64,
) -> Result<()> {
    let environ = extent_writers(elf, environ_slot, 8)?;
    require(
        environ.len() == 1
            && environ[0].r_offset == environ_slot
            && environ[0].r_type == reloc::R_X86_64_GLOB_DAT
            && environ[0].r_addend.unwrap_or(0) == 0
            && elf.dynsyms.get(environ[0].r_sym).is_some_and(|s| {
                elf.dynstrtab.get_at(s.st_name) == Some("environ")
                    && s.st_shndx == section_header::SHN_UNDEF as usize
            }),
        "standalone prefix does not use its sole actual dynamically relocated environ",
    )?;
    require(
        elf.program_headers.iter().any(|p| {
            p.p_type == program_header::PT_GNU_RELRO
                && environ_slot >= p.p_vaddr
                && environ_slot
                    .checked_add(8)
                    .is_some_and(|end| p.p_vaddr.checked_add(p.p_memsz).is_some_and(|r| end <= r))
        }),
        "standalone environ relocation slot is outside RELRO",
    )?;
    readonly_loaded_bytes(elf, bytes, environ_slot, 8)?;
    require(
        extent_writers(elf, selector, 22)?.is_empty(),
        "runtime relocation writes into standalone selector bytes",
    )?;
    require(
        readonly_loaded_bytes(elf, bytes, selector, 22)? == b"REVERIE_LITEINST_TOOL=",
        "standalone selector bytes differ",
    )?;
    Ok(())
}

fn qualify_standalone_constructor(
    elf: &Elf<'_>,
    bytes: &[u8],
    code: &BTreeMap<u64, Vec<u8>>,
    disassembly: &str,
    got: &BTreeMap<u64, u64>,
) -> Result<StandaloneConstructorEvidence> {
    let symbols = standalone_symbols(elf)?;
    let symbol = |name| symbol_evidence(name, &symbols[name]);
    let address = |name| symbols[name].st_value;
    let prefix = standalone_prefix(
        &code[&address(STANDALONE_ROOT)],
        address(STANDALONE_ROOT),
        address(STANDALONE_BODY),
        address(CONSTRUCTOR_BRIDGE),
        address(STANDALONE_RESOLVER),
    )?;
    qualify_prefix_data(elf, bytes, prefix.environ, prefix.selector)?;
    let (body_initializer_call, body_resolver_transfer) = standalone_body_order(
        &code[&address(STANDALONE_BODY)],
        address(STANDALONE_BODY),
        address(STANDALONE_INITIALIZER),
        address(STANDALONE_RESOLVER),
        got,
    )?;
    let gate_owner = &symbols[CONSTRUCTOR_GATE_OWNER];
    let gate_label = constructor_interior_label(elf, CONSTRUCTOR_GATE, gate_owner)?;
    let gate_return = constructor_interior_label(elf, CONSTRUCTOR_GATE_RETURN, gate_owner)?;
    constructor_gate_operands(
        &code[&gate_owner.st_value],
        gate_label.st_value - gate_owner.st_value,
        gate_return.st_value - gate_owner.st_value,
    )?;
    let fixed_native_gate = qualify_fixed_native_gate(elf, bytes, code, gate_label.st_value)?;
    let bridge_gate = native_bridge_gate_address(
        fixed_native_gate.as_ref(),
        &symbol_evidence(CONSTRUCTOR_GATE, &gate_label),
    )?;
    let preparation_helpers = preparation_symbols(elf)?;
    let initializing: Vec<_> = elf
        .syms
        .iter()
        .filter(|s| {
            s.st_type() == sym::STT_OBJECT
                && s.st_shndx != section_header::SHN_UNDEF as usize
                && s.st_size == 1
                && s.st_bind() == sym::STB_LOCAL
        })
        .filter(|s| {
            elf.strtab
                .get_at(s.st_name)
                .is_some_and(|name| name.contains("tool_region") && name.ends_with("INITIALIZING"))
        })
        .collect();
    require(
        initializing.len() == 1,
        "native constructor initializing guard is absent/ambiguous",
    )?;
    require(
        elf.program_headers.iter().any(|p| {
            p.p_type == program_header::PT_LOAD
                && p.p_flags & program_header::PF_W != 0
                && initializing[0].st_value >= p.p_vaddr
                && initializing[0]
                    .st_value
                    .checked_add(1)
                    .is_some_and(|end| end <= p.p_vaddr.saturating_add(p.p_memsz))
        }),
        "native constructor initializing guard is not loader-mapped writable data",
    )?;
    let route = constructor_native_bridge(
        &code[&address(CONSTRUCTOR_BRIDGE)],
        address(CONSTRUCTOR_BRIDGE),
        initializing[0].st_value,
        bridge_gate,
        address(CONSTRUCTOR_ADOPTION),
    )?;
    let prepare_instructions =
        constructor_instructions(disassembly, address(CONSTRUCTOR_ADOPTION))?;
    let (prepare_helper_transfers, prepare_helper_edges) = preparation_transfers(
        &prepare_instructions,
        got,
        &preparation_helpers.values().map(|s| s.st_value).collect(),
    )?;
    let preparation_helpers = preparation_helpers
        .iter()
        .map(|(name, s)| {
            (
                resolved_preparation_role(name).unwrap().to_owned(),
                symbol_evidence(name, s),
            )
        })
        .collect();
    let function_sha256 = symbols
        .iter()
        .map(|(name, s)| (name.clone(), sha256(&code[&s.st_value])))
        .collect();
    Ok(StandaloneConstructorEvidence {
        generic_initializer: symbol(GENERIC_INITIALIZER), body: symbol(STANDALONE_BODY),
        selected_initializer: symbol(STANDALONE_INITIALIZER), resolver: symbol(STANDALONE_RESOLVER),
        bridge: symbol(CONSTRUCTOR_BRIDGE), native_dispatch_version: NATIVE_DISPATCH_VERSION, prepare: symbol(CONSTRUCTOR_ADOPTION),
        native_gate: symbol_evidence(CONSTRUCTOR_GATE, &gate_label), native_gate_owner: symbol(CONSTRUCTOR_GATE_OWNER),
        native_gate_return: symbol_evidence(CONSTRUCTOR_GATE_RETURN, &gate_return),
        native_gate_offset: gate_label.st_value - gate_owner.st_value, fixed_native_gate, preparation_helpers, prepare_helper_transfers, prepare_helper_edges,
        function_sha256, environ_got_slot: prefix.environ, selector_address: prefix.selector,
        active_body_materialization: prefix.materialization, active_bridge_transfer: prefix.active,
        inert_resolver_transfer: prefix.inert, body_initializer_call, body_resolver_transfer,
        bridge_prepare_call: route.prepare, prepare_return: route.prepare_return,
        native_body_retain: route.body_retain, native_ready_gate: route.ready_gate,
        native_body_identity_check: route.body_identity_check,
        native_body_sample_store: route.body_sample_store,
        native_body_call: route.body_call, native_body_call_width: 3,
        native_body_return: route.body_return, native_returned_store: route.returned_store,
        native_restore: route.restore, native_return: route.native_return,
        bootstrap_record: CONSTRUCTOR_RECORD,
        bootstrap_bottom: CONSTRUCTOR_BOTTOM, bootstrap_top: CONSTRUCTOR_TOP,
        observation: "Complete actual function bytes; exact native missing/present selector branches, same-owner hidden body/bridge/prepare, native original-RDI/R15 lineage and supplied-body CALL recipe and explicit initializer-then-resolver order. Dynamic environ provider is not authenticated. Scalar ABI and source-bound typed Constructor adoption/publication helpers remain premises; this is not universal CFG/provider/protected-interior proof, execution, first-entire-DSO-Rust isolation or whole caller-window equality.".to_owned(),
    })
}

fn qualify_detcore_constructor_route(
    elf: &Elf<'_>,
    bytes: &[u8],
    code: &BTreeMap<u64, Vec<u8>>,
    disassembly: &str,
    got: &BTreeMap<u64, u64>,
) -> Result<DetcoreConstructorEvidence> {
    let symbols = detcore_symbols(elf)?;
    let symbol = |name| symbol_evidence(name, &symbols[name]);
    let address = |name| symbols[name].st_value;
    let (body_materialization, entry_bridge_transfer) = generic_entry_prefix(
        &code[&address(DETCORE_ROOT)],
        address(DETCORE_ROOT),
        address(DETCORE_BODY),
        address(CONSTRUCTOR_BRIDGE),
    )?;
    let gate_owner = &symbols[CONSTRUCTOR_GATE_OWNER];
    let gate_label = constructor_interior_label(elf, CONSTRUCTOR_GATE, gate_owner)?;
    let gate_return = constructor_interior_label(elf, CONSTRUCTOR_GATE_RETURN, gate_owner)?;
    constructor_gate_operands(
        &code[&gate_owner.st_value],
        gate_label.st_value - gate_owner.st_value,
        gate_return.st_value - gate_owner.st_value,
    )?;
    let fixed_native_gate = qualify_fixed_native_gate(elf, bytes, code, gate_label.st_value)?;
    let bridge_gate = native_bridge_gate_address(
        fixed_native_gate.as_ref(),
        &symbol_evidence(CONSTRUCTOR_GATE, &gate_label),
    )?;
    let preparation_helpers = preparation_symbols(elf)?;
    // The native election must use the same actual single-byte local guard;
    // an invented data address or a guard for a different region earns no proof.
    let initializing: Vec<_> = elf
        .syms
        .iter()
        .filter(|s| {
            s.st_type() == sym::STT_OBJECT
                && s.st_shndx != section_header::SHN_UNDEF as usize
                && s.st_size == 1
                && s.st_bind() == sym::STB_LOCAL
        })
        .filter(|s| {
            elf.strtab
                .get_at(s.st_name)
                .is_some_and(|name| name.contains("tool_region") && name.ends_with("INITIALIZING"))
        })
        .collect();
    require(
        initializing.len() == 1,
        "native Detcore initializing guard is absent/ambiguous",
    )?;
    let initializing_guard = initializing[0].st_value;
    require(
        elf.program_headers.iter().any(|p| {
            p.p_type == program_header::PT_LOAD
                && p.p_flags & program_header::PF_W != 0
                && initializing_guard >= p.p_vaddr
                && initializing_guard
                    .checked_add(1)
                    .is_some_and(|end| end <= p.p_vaddr.saturating_add(p.p_memsz))
        }),
        "native Detcore initializing guard is not loader-mapped writable data",
    )?;
    let route = constructor_native_bridge(
        &code[&address(CONSTRUCTOR_BRIDGE)],
        address(CONSTRUCTOR_BRIDGE),
        initializing_guard,
        bridge_gate,
        address(CONSTRUCTOR_ADOPTION),
    )?;
    let prepare_instructions =
        constructor_instructions(disassembly, address(CONSTRUCTOR_ADOPTION))?;
    let (prepare_helper_transfers, prepare_helper_edges) = preparation_transfers(
        &prepare_instructions,
        got,
        &preparation_helpers.values().map(|s| s.st_value).collect(),
    )?;
    let preparation_helpers = preparation_helpers
        .iter()
        .map(|(name, s)| {
            (
                resolved_preparation_role(name).unwrap().to_owned(),
                symbol_evidence(name, s),
            )
        })
        .collect();
    let function_sha256 = symbols
        .iter()
        .map(|(name, s)| (name.clone(), sha256(&code[&s.st_value])))
        .collect();
    Ok(DetcoreConstructorEvidence {
        protected_initializer: symbol(DETCORE_ROOT),
        body: symbol(DETCORE_BODY),
        bridge: symbol(CONSTRUCTOR_BRIDGE),
        native_dispatch_version: NATIVE_DISPATCH_VERSION,
        prepare: symbol(CONSTRUCTOR_ADOPTION),
        native_gate: symbol_evidence(CONSTRUCTOR_GATE, &gate_label),
        native_gate_owner: symbol(CONSTRUCTOR_GATE_OWNER),
        native_gate_return: symbol_evidence(CONSTRUCTOR_GATE_RETURN, &gate_return),
        native_gate_offset: gate_label.st_value - gate_owner.st_value, fixed_native_gate,
        initializing_guard,
        function_sha256,
        body_materialization,
        entry_bridge_transfer,
        bridge_prepare_call: route.prepare,
        prepare_return: route.prepare_return,
        native_body_retain: route.body_retain,
        native_ready_gate: route.ready_gate,
        native_body_identity_check: route.body_identity_check,
        native_body_sample_store: route.body_sample_store,
        native_body_call: route.body_call,
        native_body_call_width: 3,
        native_body_return: route.body_return,
        native_returned_store: route.returned_store,
        native_body_save: route.body_save,
        native_stack_switch: route.stack_switch,
        native_restore: route.restore,
        native_return: route.native_return,
        terminal_exit_transfer: route.terminal_exit,
        terminal_ud2: route.terminal_ud2,
        preparation_helpers,
        prepare_helper_transfers,
        prepare_helper_edges,
        bootstrap_record: CONSTRUCTOR_RECORD,
        bootstrap_bottom: CONSTRUCTOR_BOTTOM,
        bootstrap_top: CONSTRUCTOR_TOP,
        observation: "Exact protected Detcore ENDBR64/LEA/JMP into the Constructor-origin native bridge; complete actual code, gate, preparation and body identity are bound. The separate registration census rejects duplicate or bypass entries into these native roles. The body is supplied on its owned stack; arbitrary body effects, other DSO constructors, execution and protected interiors are not proved here.".to_owned(),
    })
}

fn qualify_generic_bootstrap(
    elf: &Elf<'_>,
    bytes: &[u8],
    code: &BTreeMap<u64, Vec<u8>>,
    disassembly: &str,
    got: &BTreeMap<u64, u64>,
) -> Result<GenericBootstrapEvidence> {
    let symbols = generic_symbols(elf)?;
    let symbol = |name| symbol_evidence(name, &symbols[name]);
    let address = |name| symbols[name].st_value;
    let mut registration_roles: BTreeSet<_> = [
        GENERIC_INITIALIZER,
        GENERIC_BODY,
        GENERIC_BRIDGE,
        GENERIC_ADOPTION,
    ]
    .map(&address)
    .into_iter()
    .collect();
    if let Some(selector) = fixed_native_selector_symbol(elf)? {
        registration_roles.extend(
            selector.st_value
                ..selector
                    .st_value
                    .checked_add(selector.st_size)
                    .ok_or("fixed selector range overflow")?,
        );
        for (canonical, size) in [
            (FIXED_NATIVE_OWNER, 56),
            (FIXED_NATIVE_RAW6, 92),
            (FIXED_NATIVE_RAW3, 60),
        ] {
            let function = fixed_native_function_symbol(elf, canonical, size)?;
            registration_roles.extend(
                function.st_value
                    ..function
                        .st_value
                        .checked_add(size)
                        .ok_or("fixed syscall registration range overflow")?,
            );
        }
    }
    generic_no_init_registration(elf, bytes, &registration_roles)?;
    let (body_materialization, entry_bridge_transfer) = generic_entry_prefix(
        &code[&address(GENERIC_INITIALIZER)],
        address(GENERIC_INITIALIZER),
        address(GENERIC_BODY),
        address(GENERIC_BRIDGE),
    )?;
    let gate_owner = &symbols[CONSTRUCTOR_GATE_OWNER];
    let gate_label = constructor_interior_label(elf, CONSTRUCTOR_GATE, gate_owner)?;
    let gate_return = constructor_interior_label(elf, CONSTRUCTOR_GATE_RETURN, gate_owner)?;
    constructor_gate_operands(
        &code[&gate_owner.st_value],
        gate_label.st_value - gate_owner.st_value,
        gate_return.st_value - gate_owner.st_value,
    )?;
    let fixed_native_gate = qualify_fixed_native_gate(elf, bytes, code, gate_label.st_value)?;
    let bridge_gate = native_bridge_gate_address(
        fixed_native_gate.as_ref(),
        &symbol_evidence(CONSTRUCTOR_GATE, &gate_label),
    )?;
    let preparation_helpers = preparation_symbols(elf)?;
    // The native election must use the same actual single-byte local guard;
    // an invented data address or a guard for a different region earns no proof.
    let initializing: Vec<_> = elf
        .syms
        .iter()
        .filter(|s| {
            s.st_type() == sym::STT_OBJECT
                && s.st_shndx != section_header::SHN_UNDEF as usize
                && s.st_size == 1
                && s.st_bind() == sym::STB_LOCAL
        })
        .filter(|s| {
            elf.strtab
                .get_at(s.st_name)
                .is_some_and(|name| name.contains("tool_region") && name.ends_with("INITIALIZING"))
        })
        .collect();
    require(
        initializing.len() == 1,
        "native generic initializing guard is absent/ambiguous",
    )?;
    let initializing_guard = initializing[0].st_value;
    require(
        elf.program_headers.iter().any(|p| {
            p.p_type == program_header::PT_LOAD
                && p.p_flags & program_header::PF_W != 0
                && initializing_guard >= p.p_vaddr
                && initializing_guard
                    .checked_add(1)
                    .is_some_and(|end| end <= p.p_vaddr.saturating_add(p.p_memsz))
        }),
        "native generic initializing guard is not loader-mapped writable data",
    )?;
    let route = generic_native_bridge(
        &code[&address(GENERIC_BRIDGE)],
        address(GENERIC_BRIDGE),
        initializing_guard,
        bridge_gate,
        address(GENERIC_ADOPTION),
    )?;
    let prepare_instructions = constructor_instructions(disassembly, address(GENERIC_ADOPTION))?;
    let (prepare_helper_transfers, prepare_helper_edges) = preparation_transfers(
        &prepare_instructions,
        got,
        &preparation_helpers.values().map(|s| s.st_value).collect(),
    )?;
    let preparation_helpers = preparation_helpers
        .iter()
        .map(|(name, s)| {
            (
                resolved_preparation_role(name).unwrap().to_owned(),
                symbol_evidence(name, s),
            )
        })
        .collect();
    let function_sha256 = symbols
        .iter()
        .map(|(name, s)| (name.clone(), sha256(&code[&s.st_value])))
        .collect();
    Ok(GenericBootstrapEvidence {
        public_initializer: symbol(GENERIC_INITIALIZER),
        body: symbol(GENERIC_BODY),
        bridge: symbol(GENERIC_BRIDGE),
        native_dispatch_version: NATIVE_DISPATCH_VERSION,
        prepare: symbol(GENERIC_ADOPTION),
        native_gate: symbol_evidence(CONSTRUCTOR_GATE, &gate_label),
        native_gate_owner: symbol(CONSTRUCTOR_GATE_OWNER),
        native_gate_return: symbol_evidence(CONSTRUCTOR_GATE_RETURN, &gate_return),
        native_gate_offset: gate_label.st_value - gate_owner.st_value, fixed_native_gate,
        initializing_guard,
        function_sha256,
        body_materialization,
        entry_bridge_transfer,
        bridge_prepare_call: route.prepare,
        prepare_return: route.prepare_return,
        native_body_retain: route.body_retain,
        native_ready_gate: route.ready_gate,
        native_body_identity_check: route.body_identity_check,
        native_body_sample_store: route.body_sample_store,
        native_body_call: route.body_call,
        native_body_call_width: 3,
        native_body_return: route.body_return,
        native_returned_store: route.returned_store,
        native_body_save: route.body_save,
        native_stack_switch: route.stack_switch,
        native_restore: route.restore,
        native_return: route.native_return,
        terminal_exit_transfer: route.terminal_exit,
        terminal_ud2: route.terminal_ud2,
        preparation_helpers,
        prepare_helper_transfers,
        prepare_helper_edges,
        bootstrap_record: GENERIC_RECORD,
        bootstrap_bottom: CONSTRUCTOR_BOTTOM,
        bootstrap_top: CONSTRUCTOR_TOP,
        observation: "Complete actual DEFAULT-visible public generic ENDBR64/LEA/JMP, hidden fresh native bridge and no-write exit127/UD2 terminal; original RDI retained in native R15 matches the owned Generic record+0x38 before its native width3 supplied-body CALL. All selected function bytes and trusted-gate labels are retained and independently requalified. Whole actual prepare/helper intervals and source-bound typed origin/publication/atomic/compiler-refusal roles are premises, not recursive imported-provider closure; runtime placement/None/repeat/allocator assertions remain separate; no execution or whole-memory-isolation credit.".to_owned(),
    })
}

fn disassembly_edges(
    text: &str,
    functions: &BTreeMap<u64, u64>,
    got_targets: &BTreeMap<u64, u64>,
) -> Result<(CallGraph, Vec<GotEdge>)> {
    let mut graph = BTreeMap::<u64, BTreeSet<u64>>::new();
    let mut got_edges = Vec::new();
    let mut current = None;
    let mut headers = 0usize;
    for line in text.lines() {
        let trimmed = line.trim();
        let header = trimmed
            .split_once(" <")
            .filter(|(_, suffix)| suffix.ends_with(">:"))
            .and_then(|(addr, _)| u64::from_str_radix(addr, 16).ok());
        if let Some(addr) = header {
            current = functions.contains_key(&addr).then_some(addr);
            headers += 1;
            continue;
        }
        let Some(source) = current else {
            continue;
        };
        let Some((addr, instruction)) = trimmed.split_once(':') else {
            continue;
        };
        let Ok(address) = u64::from_str_radix(addr.trim(), 16) else {
            continue;
        };
        // Objdump prints linker alignment padding between function ranges under
        // the preceding header. Padding contributes no call-path evidence.
        if address < source || address >= source.saturating_add(functions[&source]) {
            continue;
        }
        let mut words = instruction
            .split_whitespace()
            .skip_while(|word| raw_byte(word).is_some());
        let Some(opcode) = words.next() else {
            continue;
        };
        if !matches!(opcode, "call" | "callq" | "jmp" | "jmpq") {
            continue;
        }
        let Some(destination) = words.next() else {
            continue;
        };
        if destination.starts_with('*') {
            if !destination.ends_with("(%rip)") {
                continue;
            }
            let Some((_, comment)) = instruction.split_once('#') else {
                continue;
            };
            let Some(slot) = comment.split_whitespace().next() else {
                continue;
            };
            let Ok(slot) = u64::from_str_radix(slot, 16) else {
                continue;
            };
            let Some(target) = got_targets.get(&slot) else {
                continue;
            };
            graph.entry(source).or_default().insert(*target);
            got_edges.push(GotEdge {
                source_function: source,
                instruction: address,
                slot,
                target_function: *target,
            });
            continue;
        }
        let Ok(destination) = u64::from_str_radix(destination, 16) else {
            continue;
        };
        if functions.contains_key(&destination) {
            graph.entry(source).or_default().insert(destination);
        }
    }
    require(headers > 0, "objdump yielded no function disassembly")?;
    Ok((graph, got_edges))
}

fn shortest_path(graph: &BTreeMap<u64, BTreeSet<u64>>, from: u64, to: u64) -> Result<Vec<u64>> {
    let mut queue = VecDeque::from([from]);
    let mut predecessors = BTreeMap::from([(from, from)]);
    while let Some(current) = queue.pop_front() {
        if current == to {
            let mut path = vec![to];
            while *path.last().unwrap() != from {
                path.push(predecessors[path.last().unwrap()]);
            }
            path.reverse();
            return Ok(path);
        }
        if let Some(edges) = graph.get(&current) {
            for next in edges {
                if !predecessors.contains_key(next) {
                    predecessors.insert(*next, current);
                    queue.push_back(*next);
                }
            }
        }
    }
    Err(format!(
        "no direct locally resolved compiled call path from {from:#x} to {to:#x}; evidence incomplete"
    ))
}

struct CollectedProofEvidence {
    readelf_versions: FileIdentity,
    readelf_symbols_relocations: FileIdentity,
    objdump_disassembly: FileIdentity,
}

fn collect_proof_evidence(
    artifact: &FileIdentity,
    elf: &Elf<'_>,
    bytes: &[u8],
    initializer_name: &str,
    scope: &BTreeMap<u64, u64>,
    runner: &mut Runner,
) -> Result<CollectedProofEvidence> {
    let cwd = artifact.path.parent().ok_or("artifact has no parent")?;
    let path_string = artifact.path.to_str().ok_or("artifact path is not UTF-8")?;
    runner.text("readelf", &["--version-info", "--wide", path_string], cwd)?;
    let readelf_versions = runner.commands.last().unwrap().stdout.clone();
    let expected_bytes = proof_function_bytes(elf, bytes, scope)?;
    let mut disassembly = Vec::new();
    let mut emitted = 0usize;
    let limit = MAX_OBJDUMP_BYTES.min(runner.max_stream_bytes);
    for (&address, &size) in scope {
        // One aggregate budget covers all stdout/stderr from all intervals.
        // Reserve the separator before spawning; neither a per-range nor a
        // concatenated-output cap can silently grow with the function count.
        let remaining = limit
            .checked_sub(emitted)
            .and_then(|remaining| remaining.checked_sub(1))
            .filter(|remaining| *remaining > 0)
            .ok_or("objdump aggregate byte limit exhausted")?;
        let end = address.checked_add(size).ok_or("function range overflow")?;
        let arguments = vec![
            "--disassemble".to_owned(),
            "--show-raw-insn".to_owned(),
            "--disassemble-zeroes".to_owned(),
            "--insn-width=16".to_owned(),
            "--wide".to_owned(),
            format!("--start-address={address:#x}"),
            format!("--stop-address={end:#x}"),
            path_string.to_owned(),
        ];
        let stdout = runner.run_with_combined_limit("objdump", &arguments, cwd, Some(remaining))?;
        let stderr_bytes = fs::metadata(&runner.commands.last().unwrap().stderr.path)
            .map_err(|e| e.to_string())?
            .len();
        emitted = emitted
            .checked_add(stdout.len())
            .and_then(|n| n.checked_add(usize::try_from(stderr_bytes).ok()?))
            .and_then(|n| n.checked_add(1))
            .ok_or("objdump aggregate byte count overflow")?;
        require(
            emitted <= limit,
            "objdump aggregate output exceeds unchanged byte cap",
        )?;
        disassembly.extend_from_slice(&stdout);
        disassembly.push(b'\n');
    }
    let text = std::str::from_utf8(&disassembly)
        .map_err(|e| format!("objdump output is not UTF-8: {e}"))?;
    verify_constructor_complete_bytes(elf, initializer_name, text, &expected_bytes)?;
    let disassembly_path = runner
        .logs
        .join(format!("objdump-scope-{:04}.stdout", runner.serial));
    write_new(&disassembly_path, &disassembly)?;
    let objdump_disassembly = FileIdentity::read(&disassembly_path)?;
    runner.text(
        "readelf",
        &["--symbols", "--relocs", "--dynamic", "--wide", path_string],
        cwd,
    )?;
    let readelf_symbols_relocations = runner.commands.last().unwrap().stdout.clone();
    artifact.verify()?;
    Ok(CollectedProofEvidence {
        readelf_versions,
        readelf_symbols_relocations,
        objdump_disassembly,
    })
}

pub fn qualify_elf(
    path: &Path,
    initializer_name: &str,
    runner: &mut Runner,
) -> Result<ElfQualification> {
    qualify_elf_in_source_context(path, initializer_name, runner, None)
}
pub fn qualify_elf_with_sources(
    path: &Path,
    initializer_name: &str,
    runner: &mut Runner,
    sources: &VerifiedCompiledSources,
) -> Result<ElfQualification> {
    sources.verify_unchanged(runner)?;
    let result = qualify_elf_in_source_context(path, initializer_name, runner, Some(sources))?;
    sources.verify_unchanged(runner)?;
    Ok(result)
}
fn qualify_elf_in_source_context(
    path: &Path,
    initializer_name: &str,
    runner: &mut Runner,
    sources: Option<&VerifiedCompiledSources>,
) -> Result<ElfQualification> {
    if let Some(sources) = sources {
        sources.require_image(initializer_name)?;
    }

    let artifact = FileIdentity::read(path)?;
    let bytes = fs::read(&artifact.path).map_err(|e| e.to_string())?;
    let elf = Elf::parse(&bytes).map_err(|e| format!("parse actual runtime ELF: {e}"))?;
    authenticate_loader_metadata(&elf, &bytes)?;
    let scope = proof_functions(&elf, initializer_name)?;
    let evidence =
        collect_proof_evidence(&artifact, &elf, &bytes, initializer_name, &scope, runner)?;
    qualify_elf_from_evidence_in_source_context(
        path,
        initializer_name,
        evidence.readelf_versions,
        evidence.readelf_symbols_relocations,
        evidence.objdump_disassembly,
        sources,
    )
}

/// Qualify the exact standalone loader route, never diagnostic allocator work.
/// Uses the same complete-byte/tool/portability/constructor proof as the M1
/// interfaces, with an explicit constructor-only collection and result type.
pub fn qualify_constructor(path: &Path, runner: &mut Runner) -> Result<ConstructorQualification> {
    qualify_constructor_in_source_context(path, runner, None)
}
pub fn qualify_constructor_with_sources(
    path: &Path,
    runner: &mut Runner,
    sources: &VerifiedCompiledSources,
) -> Result<ConstructorQualification> {
    sources.verify_unchanged(runner)?;
    let result = qualify_constructor_in_source_context(path, runner, Some(sources))?;
    sources.verify_unchanged(runner)?;
    Ok(result)
}
fn qualify_constructor_in_source_context(
    path: &Path,
    runner: &mut Runner,
    sources: Option<&VerifiedCompiledSources>,
) -> Result<ConstructorQualification> {
    if let Some(sources) = sources {
        sources.require_image(STANDALONE_ROOT)?;
    }

    let artifact = FileIdentity::read(path)?;
    let bytes = fs::read(&artifact.path).map_err(|e| e.to_string())?;
    let elf = Elf::parse(&bytes).map_err(|e| format!("parse actual runtime ELF: {e}"))?;
    require_legacy_standalone_gate(&elf)?;
    authenticate_loader_metadata(&elf, &bytes)?;
    let scope = constructor_proof_functions(&elf)?;
    let evidence =
        collect_proof_evidence(&artifact, &elf, &bytes, STANDALONE_ROOT, &scope, runner)?;
    qualify_constructor_from_evidence_in_source_context(
        path,
        evidence.readelf_versions,
        evidence.readelf_symbols_relocations,
        evidence.objdump_disassembly,
        sources,
    )
}

