    fn fixed_normal_return_control_instructions(
        address: u64,
        bytes: &[u8],
        offsets: &[usize],
    ) -> Vec<EncodedConstructorInstruction> {
        offsets
            .iter()
            .enumerate()
            .map(|(i, &offset)| {
                let end = offsets.get(i + 1).copied().unwrap_or(bytes.len());
                EncodedConstructorInstruction {
                    address: address + offset as u64,
                    bytes: bytes[offset..end].to_vec(),
                }
            })
            .collect()
    }

    fn fixed_normal_return_contract_controls() {
        let got = BTreeMap::new();
        let readonly = BTreeMap::new();
        for sample in 0..2 {
            let graph = fixed_normal_return_control_graph(sample);
            let caller = fixed_wrapper_recipe(
                "fixed_native_from_native",
                graph.caller_address,
                &graph.caller,
                &graph.targets,
                &got,
                &readonly,
            )
            .expect("frozen normal caller whole recipe (new291 must fail first on old checker)");
            let setup = fixed_arena_recipe(
                "fixed_arena_setup",
                graph.setup_address,
                &graph.setup,
                &graph.targets,
                &got,
            )
            .expect("frozen canonical normal247 setup whole recipe");
            assert_eq!(
                caller
                    .iter()
                    .map(|e| (
                        e.instruction - graph.caller_address,
                        e.target,
                        e.local_got_slot
                    ))
                    .collect::<Vec<_>>(),
                [
                    (102, graph.targets["fixed_scalar_syscall"], None),
                    (152, graph.targets["fixed_region_publication_get"], None),
                    (230, graph.targets["fixed_native_bitmap_range"], None),
                    (269, graph.setup_address, None),
                ]
            );
            assert_eq!(
                setup
                    .iter()
                    .map(|e| (
                        e.instruction - graph.setup_address,
                        e.target,
                        e.local_got_slot
                    ))
                    .collect::<Vec<_>>(),
                [
                    (23, graph.targets["fixed_setup_bitmap_range"], None),
                    (62, graph.targets["fixed_setup_bitmap_range"], None),
                    (108, graph.targets["fixed_scalar_syscall"], None),
                    (141, graph.targets["fixed_scalar_syscall"], None),
                    (192, graph.targets["fixed_setup_bitmap_range"], None),
                    (215, graph.targets["fixed_setup_bitmap_range"], None),
                ]
            );
            for (role, address, bytes, offsets, edges) in [
                (
                    "fixed_native_from_native",
                    graph.caller_address,
                    &graph.caller,
                    graph.caller_offsets,
                    &caller,
                ),
                (
                    "fixed_arena_setup",
                    graph.setup_address,
                    &graph.setup,
                    graph.setup_offsets,
                    &setup,
                ),
            ] {
                let instructions =
                    fixed_normal_return_control_instructions(address, bytes, offsets);
                fixed_census_transfers(&instructions, address, bytes, edges, &got, false).unwrap();
                let check = |actual: &[u8], targets: &BTreeMap<String, u64>| {
                    if role == "fixed_native_from_native" {
                        fixed_wrapper_recipe(role, address, actual, targets, &got, &readonly)
                    } else {
                        fixed_arena_recipe(role, address, actual, targets, &got)
                    }
                };
                // Every byte/bit: saves, fixed receiver/payload, tags, full EAX/EDX
                // return, TEST mask/JE, shifted backbranches, stores and epilogue.
                for byte in 0..bytes.len() {
                    for bit in 0..8 {
                        let mut bad = bytes.clone();
                        bad[byte] ^= 1 << bit;
                        assert!(
                            check(&bad, &graph.targets).is_err(),
                            "normal sample{sample} {role}+{byte}/{bit}"
                        );
                    }
                }
                for end in 0..bytes.len() {
                    assert!(check(&bytes[..end], &graph.targets).is_err());
                }
                for extra in [
                    &[0x90][..],
                    &[0xc3][..],
                    &[0xe8, 0, 0, 0, 0][..],
                    &[0xff, 0xd0][..],
                ] {
                    let mut bad = bytes.clone();
                    bad.extend_from_slice(extra);
                    assert!(check(&bad, &graph.targets).is_err());
                }
                for index in 0..edges.len() {
                    let mut bad = edges.to_vec();
                    bad.remove(index);
                    assert!(
                        fixed_census_transfers(&instructions, address, bytes, &bad, &got, false)
                            .is_err()
                    );
                    let mut bad = edges.to_vec();
                    bad.push(edges[index].clone());
                    assert!(
                        fixed_census_transfers(&instructions, address, bytes, &bad, &got, false)
                            .is_err()
                    );
                    let mut bad = edges.to_vec();
                    bad[index].target += 1;
                    assert!(
                        fixed_census_transfers(&instructions, address, bytes, &bad, &got, false)
                            .is_err()
                    );
                }
                let mut bad = instructions.clone();
                bad.remove(0);
                assert!(fixed_census_transfers(&bad, address, bytes, edges, &got, false).is_err());
                let mut bad = instructions.clone();
                bad.insert(0, instructions[0].clone());
                assert!(fixed_census_transfers(&bad, address, bytes, edges, &got, false).is_err());
            }
            for key in [
                "fixed_initializing",
                "fixed_scalar_syscall",
                "fixed_region",
                "fixed_region_publication_get",
                "fixed_native_bitmap_range",
                "fixed_arena_setup",
            ] {
                let mut bad = graph.targets.clone();
                bad.remove(key);
                assert!(
                    fixed_wrapper_recipe(
                        "fixed_native_from_native",
                        graph.caller_address,
                        &graph.caller,
                        &bad,
                        &got,
                        &readonly
                    )
                    .is_err()
                );
                let mut bad = graph.targets.clone();
                bad.insert(key.into(), graph.targets[key] + 1);
                assert!(
                    fixed_wrapper_recipe(
                        "fixed_native_from_native",
                        graph.caller_address,
                        &graph.caller,
                        &bad,
                        &got,
                        &readonly
                    )
                    .is_err()
                );
            }
            for tag in [2u32, 3, 0x101, 0x80000001] {
                let mut bad = graph.setup.clone();
                bad[29..33].copy_from_slice(&tag.to_le_bytes());
                assert!(
                    fixed_arena_recipe(
                        "fixed_arena_setup",
                        graph.setup_address,
                        &bad,
                        &graph.targets,
                        &got
                    )
                    .is_err(),
                    "noncanonical EBX error tag {tag:#x}"
                );
            }
        }
        fixed_normal_return_join_controls();
    }

    struct FixedNormalReturnControlProof {
        witnesses: BTreeMap<String, AuthenticatedFixedNormalReturn>,
        transfers: BTreeMap<String, Vec<ConstructorTransfer>>,
        selected: BTreeMap<String, u64>,
    }

    // Same complete recipes, operands, actual instruction census and witness
    // factory as the production closure; no control constructs an identity enum.
    fn fixed_normal_return_control_proof(
        graph: &FixedNormalReturnControlGraph,
    ) -> Result<FixedNormalReturnControlProof> {
        let got = BTreeMap::new();
        let readonly = BTreeMap::new();
        let mut witnesses = BTreeMap::new();
        let mut transfers = BTreeMap::new();
        let mut selected = BTreeMap::new();
        for (role, address, bytes, offsets) in [
            (
                "fixed_native_from_native",
                graph.caller_address,
                &graph.caller,
                graph.caller_offsets,
            ),
            (
                "fixed_arena_setup",
                graph.setup_address,
                &graph.setup,
                graph.setup_offsets,
            ),
        ] {
            let edges = if role == "fixed_native_from_native" {
                fixed_wrapper_recipe(role, address, bytes, &graph.targets, &got, &readonly)?
            } else {
                fixed_arena_recipe(role, address, bytes, &graph.targets, &got)?
            };
            let instructions = fixed_normal_return_control_instructions(address, bytes, offsets);
            fixed_census_transfers(&instructions, address, bytes, &edges, &got, false)?;
            if let Some(witness) = fixed_normal_return_qualified_operation(
                role,
                address,
                (bytes, &instructions),
                &graph.targets,
                &got,
                &readonly,
            )? {
                assert_eq!(witness.edges, edges);
                witnesses.insert(role.into(), witness);
            }
            transfers.insert(role.into(), edges);
            selected.insert(role.into(), address);
        }
        Ok(FixedNormalReturnControlProof {
            witnesses,
            transfers,
            selected,
        })
    }

    fn fixed_normal_return_control_join(
        proof: &FixedNormalReturnControlProof,
        graph: &FixedNormalReturnControlGraph,
    ) -> Result<()> {
        fixed_normal_return_contract(
            &proof.witnesses,
            &proof.transfers,
            &proof.selected,
            &graph.targets,
        )
    }

    fn fixed_normal_return_rebind_caller(graph: &mut FixedNormalReturnControlGraph) {
        for (displacement, next, key) in [
            (53, 57, "fixed_initializing"),
            (103, 107, "fixed_scalar_syscall"),
            (148, 152, "fixed_region"),
            (153, 157, "fixed_region_publication_get"),
            (231, 235, "fixed_native_bitmap_range"),
            (270, 274, "fixed_arena_setup"),
        ] {
            let delta =
                i32::try_from(graph.targets[key] as i64 - (graph.caller_address + next) as i64)
                    .unwrap();
            graph.caller[displacement..displacement + 4].copy_from_slice(&delta.to_le_bytes());
        }
    }

    fn fixed_normal_return_join_controls() {
        for sample in 0..2 {
            let graph = fixed_normal_return_control_graph(sample);
            let proof = fixed_normal_return_control_proof(&graph).unwrap();
            if sample == 0 {
                assert!(!proof.witnesses.contains_key("fixed_native_from_native"));
            } else {
                let caller = proof.witnesses.get("fixed_native_from_native").expect(
                    "actual291 must produce a recipe/census witness through the full recipe union",
                );
                assert!(caller.identity == FixedNormalReturnIdentity::Caller291);
            }
            assert!(
                proof.witnesses["fixed_arena_setup"].identity
                    == FixedNormalReturnIdentity::Setup247
            );
            fixed_normal_return_control_join(&proof, &graph).unwrap();
        }
        // The two authentic247 bodies share one proved contract, not a chronology label.
        let mut compatible = fixed_normal_return_control_graph(1);
        let old = fixed_normal_return_control_graph(0);
        compatible.setup_address = old.setup_address;
        compatible.setup = old.setup;
        compatible.setup_offsets = old.setup_offsets;
        for key in [
            "fixed_arena_setup",
            "fixed_setup_bitmap_range",
            "fixed_scalar_syscall",
        ] {
            compatible.targets.insert(key.into(), old.targets[key]);
        }
        fixed_normal_return_rebind_caller(&mut compatible);
        let proof = fixed_normal_return_control_proof(&compatible).unwrap();
        fixed_normal_return_control_join(&proof, &compatible).unwrap();

        // Retained real DEV449 setup: individually whole-recipe/typed/census valid.
        // Rebind ALL caller operands, so only the finite247 return-contract join refuses.
        let mut outside = fixed_normal_return_control_graph(1);
        outside.setup_address = 0x1e5a20;
        outside.setup = fixed_hex(
            "",
        );
        outside.setup_offsets = &[
            0, 7, 12, 17, 22, 27, 29, 34, 36, 38, 46, 54, 56, 61, 66, 71, 73, 78, 80, 82, 84, 89,
            99, 104, 109, 114, 119, 124, 128, 130, 132, 136, 140, 147, 148, 153, 163, 168, 173,
            178, 183, 188, 192, 198, 200, 205, 210, 212, 215, 219, 227, 229, 239, 244, 254, 259,
            261, 263, 268, 273, 278, 283, 288, 293, 298, 303, 308, 313, 318, 328, 332, 337, 347,
            352, 356, 361, 366, 371, 376, 381, 386, 391, 396, 401, 409, 414, 419, 427, 429, 432,
            436, 444,
        ];
        for (key, address) in [
            ("fixed_arena_setup", 0x1e5a20),
            ("fixed_setup_bitmap_range", 0x1e55d0),
            ("fixed_scalar_syscall", 0x1f6750),
            ("fixed_heap_metadata_initialize", 0x1ec7b0),
            ("fixed_metadata_atomic_new_usize", 0x1ed6f0),
        ] {
            outside.targets.insert(key.into(), address);
        }
        fixed_normal_return_rebind_caller(&mut outside);
        let proof = fixed_normal_return_control_proof(&outside).expect(
            "wrong-contract graph must first pass both actual whole recipes and complete censuses",
        );
        assert!(
            proof.witnesses["fixed_native_from_native"].identity
                == FixedNormalReturnIdentity::Caller291
        );
        assert!(
            proof.witnesses["fixed_arena_setup"].identity == FixedNormalReturnIdentity::OtherSetup
        );
        assert_eq!(
            fixed_normal_return_control_join(&proof, &outside).unwrap_err(),
            "new normal caller lacks authenticated canonical normal247 setup"
        );

        // Still recipe/census valid: wrong same-size target and interior selected target.
        for shift in [1, 0x2000] {
            let mut graph = fixed_normal_return_control_graph(1);
            graph
                .targets
                .insert("fixed_arena_setup".into(), graph.setup_address + shift);
            fixed_normal_return_rebind_caller(&mut graph);
            let proof = fixed_normal_return_control_proof(&graph).unwrap();
            assert_eq!(
                fixed_normal_return_control_join(&proof, &graph).unwrap_err(),
                "normal return witness loses its actual role/address/transfers"
            );
        }
        // Typed receiver aliases must reach the join, not fail a malformed displacement.
        for (key, other) in [
            ("fixed_region", "fixed_initializing"),
            ("fixed_initializing", "fixed_region"),
        ] {
            let mut graph = fixed_normal_return_control_graph(1);
            graph.targets.insert(key.into(), graph.targets[other]);
            fixed_normal_return_rebind_caller(&mut graph);
            let proof = fixed_normal_return_control_proof(&graph).unwrap();
            assert_eq!(
                fixed_normal_return_control_join(&proof, &graph).unwrap_err(),
                "normal return receiver/function identities alias"
            );
        }
        let graph = fixed_normal_return_control_graph(1);
        let mut proof = fixed_normal_return_control_proof(&graph).unwrap();
        proof.witnesses.remove("fixed_arena_setup");
        assert_eq!(
            fixed_normal_return_control_join(&proof, &graph).unwrap_err(),
            "new normal caller lacks authenticated canonical normal247 setup"
        );
        let mut proof = fixed_normal_return_control_proof(&graph).unwrap();
        proof
            .selected
            .insert("fixed_arena_setup".into(), graph.setup_address + 1);
        assert_eq!(
            fixed_normal_return_control_join(&proof, &graph).unwrap_err(),
            "normal return witness loses its actual role/address/transfers"
        );
        for role in ["fixed_native_from_native", "fixed_arena_setup"] {
            for mutation in 0..4 {
                let mut proof = fixed_normal_return_control_proof(&graph).unwrap();
                let edges = proof.transfers.get_mut(role).unwrap();
                match mutation {
                    0 => {
                        edges.remove(0);
                    }
                    1 => {
                        edges.push(edges[0].clone());
                    }
                    2 => {
                        edges[0].instruction += 1;
                    }
                    3 => {
                        edges[0].local_got_slot = Some(0xdead);
                    }
                    _ => unreachable!(),
                }
                assert_eq!(
                    fixed_normal_return_control_join(&proof, &graph).unwrap_err(),
                    "normal return witness loses its actual role/address/transfers"
                );
            }
            let (address, bytes, offsets) = if role == "fixed_native_from_native" {
                (graph.caller_address, &graph.caller, graph.caller_offsets)
            } else {
                (graph.setup_address, &graph.setup, graph.setup_offsets)
            };
            let instructions = fixed_normal_return_control_instructions(address, bytes, offsets);
            for mutation in 0..3 {
                let mut bad = instructions.clone();
                match mutation {
                    0 => {
                        bad.remove(0);
                    }
                    1 => {
                        bad.insert(0, instructions[0].clone());
                    }
                    2 => {
                        bad[0].bytes[0] ^= 1;
                    }
                    _ => unreachable!(),
                }
                assert!(
                    fixed_normal_return_qualified_operation(
                        role,
                        address,
                        (bytes, &bad),
                        &graph.targets,
                        &BTreeMap::new(),
                        &BTreeMap::new()
                    )
                    .is_err()
                );
            }
        }
        let mut missing = fixed_normal_return_control_graph(1);
        missing.setup.clear();
        assert!(fixed_normal_return_control_proof(&missing).is_err());
        // Explicit full/partial EAX, EDX errno, success clear and branch/store mutations.
        for (offset, value) in [
            (220, 0x90),
            (230, 0x88),
            (231, 0xc8),
            (234, 0xea),
            (221, 0xc0),
            (41, 0x75),
        ] {
            let mut bad = fixed_normal_return_control_graph(1);
            bad.setup[offset] = value;
            assert!(fixed_normal_return_control_proof(&bad).is_err());
        }
        for (offset, value) in [(277, 0x90), (278, 2), (279, 0x75), (285, 0xda), (290, 0xd7)] {
            let mut bad = fixed_normal_return_control_graph(1);
            bad.caller[offset] = value;
            assert!(fixed_normal_return_control_proof(&bad).is_err());
        }
    }

    fn fixed_backing_schema_controls() {
        let function = |name: &str, address| SymbolEvidence {
            name: name.to_owned(),
            address,
            size: 16,
            binding: sym::STB_LOCAL,
            visibility: sym::STV_DEFAULT,
        };
        let mut functions = BTreeMap::new();
        for (index, role) in FIXED_REQUIRED_ROLES
            .iter()
            .copied()
            .chain(FIXED_PUBLICATION_REQUIRED_ROLES.iter().copied())
            .enumerate()
        {
            functions.insert(
                role.to_owned(),
                function(role, 0x3000 + index as u64 * 0x20),
            );
        }
        let mut compiler_routes = BTreeMap::new();
        for (index, (shim, role)) in [
            ("__rust_alloc", "fixed_patch_alloc"),
            ("__rust_alloc_zeroed", "fixed_patch_alloc_zeroed"),
            ("__rust_realloc", "fixed_patch_realloc"),
            ("__rust_dealloc", "fixed_patch_dealloc"),
        ]
        .into_iter()
        .enumerate()
        {
            let shim_symbol = function(shim, 0x2000 + index as u64 * 0x20);
            functions.insert(shim.to_owned(), shim_symbol.clone());
            let implementation = functions[role].clone();
            compiler_routes.insert(
                shim.to_owned(),
                FixedAllocatorRoute {
                    call_path: vec![shim_symbol.address, implementation.address],
                    shim: shim_symbol,
                    implementation,
                    local_got_edges: vec![],
                },
            );
        }
        let backing = AllocatorBackingEvidence {
            fixed_native_syscalls: None,
            fixed_arena_version: 1,
            descriptor: AllocatorDescriptorEvidence {
                symbol: SymbolEvidence {
                    name: ALLOCATOR_BACKING_SYMBOL.to_owned(),
                    address: 0x1200,
                    size: 16,
                    binding: sym::STB_GLOBAL,
                    visibility: sym::STV_HIDDEN,
                },
                version: 1,
                mode: AllocatorBackingMode::Fixed,
                payload_sha256: "0".repeat(64),
                file_offset: 0x200,
                section_index: 1,
                load_segment_index: 0,
            },
            compiler_global_type: "reverie_liteinst::patch_alloc::FixedPrivatePatchAllocator"
                .to_owned(),
            fixed_backing_record: ImmutableAllocatorObject {
                symbol: SymbolEvidence {
                    name: "_RNvNtNtNtCsk1nybVdH5QO_15reverie_inguest5guest11tool_region5arena13FIXED_BACKING".to_owned(),
                    address: 0x4000, size: 40, binding: sym::STB_LOCAL,
                    visibility: sym::STV_DEFAULT,
                },
                payload_sha256: sha256(&[FIXED_TOOL_BOTTOM, FIXED_TOOL_BOTTOM + FIXED_ARENA_BYTES,
                    FIXED_PATCH_BOTTOM, FIXED_PATCH_BOTTOM + FIXED_ARENA_BYTES, FIXED_METADATA + 24]
                    .into_iter().flat_map(u64::to_le_bytes).collect::<Vec<_>>()),
                file_offset: 0x800, section_index: 1, load_segment_index: 0,
            },
            tls_boundary: AllocatorTlsBoundary {
                dependency: "existing_installation_depth_tls".to_owned(),
                provider_symbol: "__tls_get_addr".to_owned(), provider_version: "GLIBC_2.3".to_owned(),
                provider_library: "ld-linux-x86-64.so.2".to_owned(),
                plt_address: 0x5000, got_slot: 0x6000, dynamic_symbol_index: 1,
                tls_cell: SymbolEvidence { name: "_RNvNCNKNvNtCsnMqmb1yYhM_16reverie_liteinst11patch_alloc18INSTALLATION_DEPTH0s_023___RUST_STD_INTERNAL_VAL".to_owned(), address: 0x48,
                    size: 8, binding: sym::STB_LOCAL, visibility: sym::STV_DEFAULT },
                tls_module_slot: 0x6100, tls_offset_slot: 0x6108,
                callsites: vec![ConstructorTransfer { instruction: 0x3010, target: 0x5000, local_got_slot: None }],
                local_key_object: None, local_key_transfer: None, local_key_resolution: None,
                unisolated: true, plt_sha256: "0".repeat(64),
                function_sha256: BTreeMap::from([("fixed_patch_alloc".to_owned(), "0".repeat(64))]),
                local_chain: BTreeMap::from([("fixed_patch_alloc".to_owned(), functions["fixed_patch_alloc"].clone())]),
                direct_allocation: None,
            },
            allocator_transfers: FIXED_REQUIRED_ROLES[..4]
                .iter()
                .chain(FIXED_PUBLICATION_REQUIRED_ROLES.iter())
                .map(|role| (role.to_string(), vec![]))
                .collect(),
            readonly_objects:BTreeMap::new(),
            selection_objects:[("fixed_initializing","_RNvNtNtCsTest_15reverie_inguest5guest11tool_region12INITIALIZING",1),("fixed_region","_RNvNtNtCsTest_15reverie_inguest5guest11tool_region6REGION",32),("fixed_compiler_global_marker","_RNvCsTest_24reverie_liteinst_preload26REVERIE_LITEINST_ALLOCATOR",0)].into_iter().enumerate().map(|(i,(key,name,size))|(key.into(),SymbolEvidence {name:name.into(),address:0x7000+32*i as u64,size,binding:sym::STB_LOCAL,visibility:sym::STV_DEFAULT})).collect(),
            guard_contract:FIXED_GUARD_CONTRACT.into(),guarded_terminal_edges:BTreeMap::new(),
            compiler_routes,
            function_sha256: functions
                .keys()
                .map(|role| (role.clone(), "0".repeat(64)))
                .collect(),
            functions,
            owned_setup_transfers: BTreeMap::from([("fixed_arena_setup".to_owned(), vec![])]),
            owned_setup_got_edges: vec![],
        };
        // Structural schema controls only; synthetic hashes never qualify ELF.
        validate_fixed_backing_evidence(&backing).unwrap();
        // Each new mandatory publication root needs its own structural
        // function/hash and transfer-map evidence. Synthetic hashes remain
        // schema controls only and never qualify a physical ELF.
        for &role in FIXED_PUBLICATION_REQUIRED_ROLES {
            let mut missing_function = backing.clone();
            missing_function.functions.remove(role);
            missing_function.function_sha256.remove(role);
            missing_function.allocator_transfers.remove(role);
            assert!(
                validate_fixed_backing_evidence(&missing_function).is_err(),
                "accepted missing publication function {role}"
            );
            let mut missing_transfers = backing.clone();
            missing_transfers.allocator_transfers.remove(role);
            assert!(
                validate_fixed_backing_evidence(&missing_transfers).is_err(),
                "accepted missing publication transfer map {role}"
            );
        }
        // Structural receipt controls for exactly the three physically proven
        // guarded edges. Synthetic receipts do not qualify ELF or panic bodies.
        for (caller, address, size, call) in [
            (
                "_RNvNvMNtNtCs_4core5alloc6layoutNtB4_6Layout29from_size_alignment_unchecked18precondition_checkCs_24reverie_liteinst_preload",
                0x16a0a0,
                86,
                0x16a0eb,
            ),
            (
                "_RNvNvMNtNtCs_4core3mem9alignmentNtB4_9Alignment13new_unchecked18precondition_checkCs_16reverie_liteinst",
                0x191280,
                162,
                0x191317,
            ),
            (
                "_RNvNvMNtNtCs_4core3mem9alignmentNtB4_9Alignment13new_unchecked18precondition_checkCs_15reverie_inguest",
                0x1f3740,
                162,
                0x1f37d7,
            ),
        ] {
            let mut proved = backing.clone();
            let mut caller_symbol = function(caller, address);
            caller_symbol.size = size;
            proved.functions.insert(caller.into(), caller_symbol);
            proved.function_sha256.insert(caller.into(), "0".repeat(64));
            proved.functions.insert(
                "fixed_panic_nounwind_fmt".into(),
                function("fixed_panic_nounwind_fmt", 0x35ff40),
            );
            proved
                .function_sha256
                .insert("fixed_panic_nounwind_fmt".into(), "0".repeat(64));
            let transfer = ConstructorTransfer {
                instruction: call,
                target: 0x35ff40,
                local_got_slot: Some(0x39af00),
            };
            proved
                .allocator_transfers
                .insert(caller.into(), vec![transfer.clone()]);
            proved.guarded_terminal_edges.insert(
                "guard".into(),
                FixedGuardedTerminal {
                    caller_role: caller.into(),
                    terminal_role: "fixed_panic_nounwind_fmt".into(),
                    premise: "valid_globalalloc_layout".into(),
                    transfer,
                },
            );
            validate_fixed_backing_evidence(&proved).unwrap();
            for (label, wrong_caller, wrong_terminal, wrong_premise) in [
                (
                    "wrong caller",
                    "fixed_patch_alloc",
                    "fixed_panic_nounwind_fmt",
                    "valid_globalalloc_layout",
                ),
                (
                    "wrong terminal",
                    caller,
                    "fixed_heap_panic_null",
                    "valid_globalalloc_layout",
                ),
                (
                    "wrong premise",
                    caller,
                    "fixed_panic_nounwind_fmt",
                    "constant_atomic_order",
                ),
            ] {
                let mut bad = proved.clone();
                let guard = bad.guarded_terminal_edges.get_mut("guard").unwrap();
                guard.caller_role = wrong_caller.into();
                guard.terminal_role = wrong_terminal.into();
                guard.premise = wrong_premise.into();
                let edge = guard.transfer.clone();
                // Supply consistent edge/symbol/hash evidence so rejection
                // specifically requires the finite caller/terminal/premise join.
                bad.allocator_transfers
                    .insert(wrong_caller.into(), vec![edge.clone()]);
                bad.functions
                    .entry(wrong_terminal.into())
                    .or_insert_with(|| function(wrong_terminal, edge.target));
                bad.function_sha256
                    .entry(wrong_terminal.into())
                    .or_insert_with(|| "0".repeat(64));
                assert!(
                    validate_fixed_backing_evidence(&bad).is_err(),
                    "accepted {caller} {label}"
                );
            }
            let mut wrong_target = proved.clone();
            wrong_target
                .guarded_terminal_edges
                .get_mut("guard")
                .unwrap()
                .transfer
                .target += 1;
            assert!(validate_fixed_backing_evidence(&wrong_target).is_err());
            // Even a matching transfer list cannot substitute another target
            // for the independently selected exact terminal symbol.
            wrong_target.allocator_transfers.insert(
                caller.into(),
                vec![
                    wrong_target.guarded_terminal_edges["guard"]
                        .transfer
                        .clone(),
                ],
            );
            assert!(validate_fixed_backing_evidence(&wrong_target).is_err());
            let mut missing_edge = proved.clone();
            missing_edge
                .allocator_transfers
                .get_mut(caller)
                .unwrap()
                .clear();
            assert!(validate_fixed_backing_evidence(&missing_edge).is_err());
            let mut wrong_call = proved.clone();
            wrong_call
                .guarded_terminal_edges
                .get_mut("guard")
                .unwrap()
                .transfer
                .instruction += 1;
            assert!(validate_fixed_backing_evidence(&wrong_call).is_err());
            let mut wrong_got = proved.clone();
            wrong_got
                .guarded_terminal_edges
                .get_mut("guard")
                .unwrap()
                .transfer
                .local_got_slot = None;
            assert!(validate_fixed_backing_evidence(&wrong_got).is_err());
        }
        // Real symbol spelling is required; canonical pseudo spellings are not actual identities.
        for key in [
            "fixed_initializing",
            "fixed_region",
            "fixed_compiler_global_marker",
        ] {
            let mut empty_disambiguator = backing.clone();
            let object = empty_disambiguator.selection_objects.get_mut(key).unwrap();
            object.name = object.name.replace("CsTest_", "Cs_");
            assert!(validate_fixed_backing_evidence(&empty_disambiguator).is_err());
            let mut wrong_source = backing.clone();
            let object = wrong_source.selection_objects.get_mut(key).unwrap();
            object.name.push_str("_foreign");
            assert!(validate_fixed_backing_evidence(&wrong_source).is_err());
        }
        let mut diagnostic_tls = backing.clone();
        diagnostic_tls.tls_boundary.tls_cell.address = 0x88;
        validate_fixed_backing_evidence(&diagnostic_tls).unwrap();
        fixed_tls_offset_schema_controls(&backing);
        fixed_tls_direct_schema_controls(&backing);
        fixed_tls_direct_census_controls();
        let value = serde_json::to_value(&backing).unwrap();
        assert!(value.get("fixed_native_syscalls").is_none());
        for field in [
            "fixed_arena_version",
            "descriptor",
            "compiler_global_type",
            "fixed_backing_record",
            "tls_boundary",
            "allocator_transfers",
            "readonly_objects",
            "selection_objects",
            "guard_contract",
            "guarded_terminal_edges",
            "compiler_routes",
            "functions",
            "function_sha256",
            "owned_setup_transfers",
            "owned_setup_got_edges",
        ] {
            let mut missing = value.clone();
            missing.as_object_mut().unwrap().remove(field);
            assert!(serde_json::from_value::<AllocatorBackingEvidence>(missing).is_err());
        }
        for (field, replacement) in [
            ("fixed_arena_version", serde_json::json!(2)),
            ("compiler_global_type", serde_json::json!("SharedToolHeap")),
            ("compiler_routes", serde_json::json!({})),
            ("function_sha256", serde_json::json!({})),
            ("owned_setup_transfers", serde_json::json!({})),
            ("allocator_transfers", serde_json::json!({})),
            ("selection_objects", serde_json::json!({})),
            (
                "guard_contract",
                serde_json::json!("unqualified_or_hostile_memory"),
            ),
        ] {
            let mut bad = value.clone();
            bad[field] = replacement;
            assert!(
                validate_fixed_backing_evidence(&serde_json::from_value(bad).unwrap()).is_err()
            );
        }
        for (field, replacement) in [
            ("dependency", serde_json::json!("complete_isolated_tls")),
            ("provider_symbol", serde_json::json!("malloc")),
            ("provider_version", serde_json::json!("GLIBC_2.4")),
            ("provider_library", serde_json::json!("libc.so.6")),
            ("unisolated", serde_json::json!(false)),
            ("tls_offset_slot", serde_json::json!(0x6109)),
            ("callsites", serde_json::json!([])),
            ("function_sha256", serde_json::json!({})),
        ] {
            let mut bad = value.clone();
            bad["tls_boundary"][field] = replacement;
            assert!(
                validate_fixed_backing_evidence(&serde_json::from_value(bad).unwrap()).is_err()
            );
        }
        let mut wrong_tls_argument = backing.clone();
        wrong_tls_argument.tls_boundary.tls_cell.address += 8;
        assert!(validate_fixed_backing_evidence(&wrong_tls_argument).is_err());
        let mut wrong_tls_call = backing.clone();
        wrong_tls_call.tls_boundary.callsites[0].target += 1;
        assert!(validate_fixed_backing_evidence(&wrong_tls_call).is_err());
        let mut guessed_tls_pointer_origin = backing.clone();
        guessed_tls_pointer_origin.tls_boundary.callsites[0].local_got_slot = Some(0x6000);
        assert!(validate_fixed_backing_evidence(&guessed_tls_pointer_origin).is_err());
        for unproved_owner in ["7detcore", "16detcore_liteinst"] {
            let mut wrong_owner = backing.clone();
            wrong_owner
                .selection_objects
                .get_mut("fixed_compiler_global_marker")
                .unwrap()
                .name = format!("_RNvCsTest_{unproved_owner}26REVERIE_LITEINST_ALLOCATOR");
            assert!(validate_fixed_backing_evidence(&wrong_owner).is_err());
        }
        let mut legacy = backing.clone();
        legacy.descriptor.mode = AllocatorBackingMode::Legacy;
        assert!(validate_fixed_backing_evidence(&legacy).is_err());
        let mut route = backing.clone();
        route
            .compiler_routes
            .get_mut("__rust_alloc")
            .unwrap()
            .implementation = function("fixed_tool_alloc", 0x6000);
        assert!(validate_fixed_backing_evidence(&route).is_err());
        let mut collapsed = backing.clone();
        collapsed
            .compiler_routes
            .get_mut("__rust_alloc")
            .unwrap()
            .call_path
            .truncate(1);
        assert!(validate_fixed_backing_evidence(&collapsed).is_err());
        let mut unknown = value;
        unknown["legacy_exemption"] = serde_json::json!(true);
        assert!(serde_json::from_value::<AllocatorBackingEvidence>(unknown).is_err());
        fixed_native_syscall_controls(&backing);
    }

    // Physical mini-ELF census controls only: no verified-source fabrication,
    // whole constructor qualification, or allocator-execution credit.
    fn fixed_tls_direct_census_controls() {
        fn put(bytes: &mut [u8], at: usize, width: usize, value: u64) {
            bytes[at..at + width].copy_from_slice(&value.to_le_bytes()[..width]);
        }
        fn rip(code: &mut [u8], address: u64, field: usize, next: usize, target: u64) {
            let value = i32::try_from(target as i64 - (address + next as u64) as i64).unwrap();
            code[field..next].copy_from_slice(&value.to_le_bytes());
        }
        fn getter() -> Vec<u8> {
            let mut code = fixed_hex(FIXED_OPTIMIZED_TLS_THUNK_EVENT_ARGUMENT_HEX);
            rip(&mut code, 0x1500, 4, 8, 0x3300);
            rip(&mut code, 0x1500, 9, 13, 0x1800);
            code
        }
        let getter_name = FIXED_EMITTED_ROLE_SYMBOLS
            .iter()
            .find(|&&(role, _)| role == "fixed_tls_fn_once")
            .unwrap()
            .1
            .replace("Cs_", "Cs1_");
        let cell_name = FIXED_TLS_CELL_ROLE.replace("Cs_", "Cs1_");
        let mut base = vec![0_u8; 0x7000];
        base[..7].copy_from_slice(b"\x7fELF\x02\x01\x01");
        for (at, width, value) in [
            (16, 2, 3),
            (18, 2, 62),
            (20, 4, 1),
            (32, 8, 64),
            (40, 8, 0x6000),
            (52, 2, 64),
            (54, 2, 56),
            (56, 2, 5),
            (58, 2, 64),
            (60, 2, 9),
            (62, 2, 8),
        ] {
            put(&mut base, at, width, value);
        }
        for (index, kind, flags, address, size) in [
            (0, 1, 4, 0, 0x1000),
            (1, 1, 5, 0x1000, 0x1000),
            (2, 1, 6, 0x3000, 0x1000),
            (3, 1, 4, 0x4000, 0x3000),
            (4, 2, 6, 0x3800, 0x100),
        ] {
            let at = 64 + index * 56;
            for (offset, width, value) in [
                (0, 4, kind),
                (4, 4, flags),
                (8, 8, address),
                (16, 8, address),
                (24, 8, address),
                (32, 8, size),
                (40, 8, size),
                (48, 8, 4096),
            ] {
                put(&mut base, at + offset, width, value);
            }
        }
        let static_names = format!("\0{cell_name}\0{getter_name}\0");
        let getter_name_offset = cell_name.len() + 2;
        let dynamic_names = format!("\0{getter_name}\0");
        assert!(static_names.len() < 0x200 && dynamic_names.len() < 0x200);
        base[0x4200..0x4200 + static_names.len()].copy_from_slice(static_names.as_bytes());
        base[0x4600..0x4600 + dynamic_names.len()].copy_from_slice(dynamic_names.as_bytes());
        for (offset, width, value) in [
            (0, 4, 1),
            (4, 1, u64::from(sym::STT_TLS)),
            (6, 2, 7),
            (8, 8, 0x40),
            (16, 8, 8),
        ] {
            put(&mut base, 0x4018 + offset, width, value);
        }
        for (index, (tag, value)) in [
            (goblin::elf::dynamic::DT_STRTAB, 0x4600),
            (goblin::elf::dynamic::DT_STRSZ, dynamic_names.len() as u64),
            (goblin::elf::dynamic::DT_SYMTAB, 0x4400),
            (goblin::elf::dynamic::DT_SYMENT, 24),
            (goblin::elf::dynamic::DT_HASH, 0x5000),
            (goblin::elf::dynamic::DT_RELA, 0x4800),
            (goblin::elf::dynamic::DT_RELASZ, 24),
            (goblin::elf::dynamic::DT_RELAENT, 24),
            (goblin::elf::dynamic::DT_NULL, 0),
        ]
        .into_iter()
        .enumerate()
        {
            put(&mut base, 0x3800 + index * 16, 8, tag);
            put(&mut base, 0x3808 + index * 16, 8, value);
        }
        for (i, value) in [1, 2, 1, 0, 0].into_iter().enumerate() {
            put(&mut base, 0x5000 + i * 4, 4, value);
        }
        for (index, kind, flags, address, size, link, entry) in [
            (1, 1, 6, 0x1000, 0x100, 0, 0),
            (2, 2, 0, 0x4000, 72, 3, 24),
            (3, 3, 0, 0x4200, static_names.len() as u64, 0, 0),
            (4, 11, 0, 0x4400, 48, 5, 24),
            (5, 3, 0, 0x4600, dynamic_names.len() as u64, 0, 0),
            (6, 4, 0, 0x4800, 24, 4, 24),
            (7, 8, 0x403, 0, 8, 0, 0),
            (8, 3, 0, 0x5100, 1, 0, 0),
        ] {
            let at = 0x6000 + index * 64;
            for (offset, width, value) in [
                (4, 4, kind),
                (8, 8, flags),
                (16, 8, address),
                (24, 8, address),
                (32, 8, size),
                (40, 4, link),
                (48, 8, 8),
                (56, 8, entry),
            ] {
                put(&mut base, at + offset, width, value);
            }
        }
        let cell = SymbolEvidence {
            name: cell_name,
            address: 0x40,
            size: 8,
            binding: sym::STB_LOCAL,
            visibility: sym::STV_HIDDEN,
        };
        let census = |bytes: &[u8]| {
            direct_tls_getter_census(&Elf::parse(bytes).unwrap(), bytes, &cell, 0x3300, 0x1800)
        };
        let good = census(&base).unwrap();
        assert!(
            good.named_getters.is_empty()
                && good.recipe_getters.is_empty()
                && good.getter_pointer_slots.is_empty()
        );
        assert_eq!(good.mappings.len(), 1);
        assert_eq!(good.mappings[0].file_size, 0x1000);
        assert!(direct_tls_source_context(None).is_err());
        let elf = Elf::parse(&base).unwrap();
        assert!(
            derive_direct_allocation_tls_evidence(&elf, &base, &cell, 0x3300, 0x1800, &[], None)
                .is_err()
        );
        let mut unnamed = base.clone();
        unnamed[0x1500..0x1516].copy_from_slice(&getter());
        // The recipe is outside the only executable section's 0x100-byte
        // extent and has no symbol: PT_LOAD bytes remain part of the census.
        let found = census(&unnamed).unwrap();
        assert_eq!(found.recipe_getters, [0x1500]);
        let mut pointer = unnamed.clone();
        for (offset, value) in [
            (0, 0x3400),
            (8, u64::from(reloc::R_X86_64_RELATIVE)),
            (16, 0x1500),
        ] {
            put(&mut pointer, 0x4800 + offset, 8, value);
        }
        // Writable/unprotected destination and unnamed target must not be
        // dropped by the RELRO/local-symbol GOT map used for other proofs.
        assert_eq!(census(&pointer).unwrap().getter_pointer_slots, [0x3400]);
        for (field, next, target) in [(4, 8, 0x3308), (9, 13, 0x1801)] {
            let mut bad = unnamed.clone();
            rip(&mut bad[0x1500..0x1516], 0x1500, field, next, target);
            assert!(
                census(&bad).is_err(),
                "unnamed getter wrong descriptor/provider operand"
            );
        }
        for (size, binding, dynamic, unknown) in [
            (0, sym::STB_LOCAL, false, false),
            (22, sym::STB_GLOBAL, false, false),
            (22, sym::STB_LOCAL, true, false),
            (22, sym::STB_LOCAL, false, true),
        ] {
            let mut bad = base.clone();
            let row = if dynamic { 0x4418 } else { 0x4030 };
            let name = if dynamic {
                1
            } else {
                getter_name_offset as u64
            };
            for (offset, width, value) in [
                (0, 4, name),
                (4, 1, u64::from((binding << 4) | sym::STT_FUNC)),
                (6, 2, 1),
                (8, 8, 0x1500),
                (16, 8, size),
            ] {
                put(&mut bad, row + offset, width, value);
            }
            if unknown {
                let end = 0x4200 + getter_name_offset + getter_name.len();
                bad[end] = b'X';
                bad[end + 1] = 0;
                put(
                    &mut bad,
                    0x6000 + 3 * 64 + 32,
                    8,
                    (static_names.len() + 1) as u64,
                );
            }
            assert!(
                census(&bad).is_err(),
                "raw getter is not pruned before validation"
            );
        }
        let mut named = unnamed.clone();
        for (offset, width, value) in [
            (0, 4, getter_name_offset as u64),
            (4, 1, u64::from(sym::STT_FUNC)),
            (6, 2, 1),
            (8, 8, 0x1500),
            (16, 8, 22),
        ] {
            put(&mut named, 0x4030 + offset, width, value);
        }
        assert_eq!(census(&named).unwrap().named_getters, [0x1500]);
        named[0x1500] ^= 1;
        assert!(
            census(&named).is_err(),
            "named getter whole body must be exact"
        );
        let mut allocation = fixed_hex(FIXED_OPTIMIZED_PATCH_ALLOC_EVENT_ARGUMENT_HEX);
        let operands = [
            (16, 20, 0x3310),
            (40, 44, 0x3300),
            (45, 49, 0x1800),
            (182, 186, 0x3318),
        ];
        for &(field, next, target) in &operands {
            rip(&mut allocation, 0x1100, field, next, target);
        }
        fixed_tls_cell_access_recipe("fixed_patch_alloc", 0x1100, &allocation, &cell, &operands)
            .unwrap();
        for field in [0, 16, 40, 45, 52, 182] {
            let mut bad = allocation.clone();
            bad[field] ^= 1;
            assert!(
                fixed_tls_cell_access_recipe("fixed_patch_alloc", 0x1100, &bad, &cell, &operands)
                    .is_err()
            );
        }
        // Actual mapping bytes participate in the record join even when a
        // change does not create a getter. An old census cannot be replayed.
        let mut changed = base.clone();
        changed[0x1700] = 0x90;
        assert_ne!(good.mappings, census(&changed).unwrap().mappings);
    }

    // Synthetic direct-schema positive. The old checker must refuse this
    // additive route before implementation; hashes here do not qualify an ELF.
    fn fixed_tls_direct_schema_controls(backing: &AllocatorBackingEvidence) {
        let mut direct = backing.clone();
        let tls = &mut direct.tls_boundary;
        tls.tls_cell.address = 0x40;
        let allocation = tls.local_chain.get_mut("fixed_patch_alloc").unwrap();
        allocation.size = 186;
        allocation.name = FIXED_EMITTED_ROLE_SYMBOLS
            .iter()
            .find(|&&(role, _)| role == "fixed_patch_alloc")
            .unwrap()
            .1
            .replace("Cs_", "Cs1_");
        let address = allocation.address;
        tls.callsites = vec![ConstructorTransfer {
            instruction: address + 0x2c,
            target: tls.plt_address,
            local_got_slot: None,
        }];
        let allocation_sha256 = tls.function_sha256["fixed_patch_alloc"].clone();
        let mut value = serde_json::to_value(&direct).unwrap();
        value["tls_boundary"]["direct_allocation"] = serde_json::json!({
            "version": 1,
            "policy": "installation_depth_named_getter_pt_load22_raw_loader_pointers_v1",
            "elf_sha256": "0".repeat(64),
            "compiled_sources_sha256": "1".repeat(64),
            "reverie_pin": "2".repeat(40),
            "allocation_sha256": allocation_sha256,
            "mappings": [{"program_header_index": 1, "file_offset": 0x1000,
                "virtual_address": 0x1000, "file_size": 0x1000, "memory_size": 0x1000,
                "flags": 5, "sha256": "0".repeat(64)}],
            "static_symbol_count": 1, "dynamic_symbol_count": 1,
            "raw_names_sha256": "0".repeat(64),
            "loader_writer_count": 0, "loader_writers_sha256": "0".repeat(64),
            "named_getters": [], "recipe_getters": [], "getter_pointer_slots": []
        });
        let decoded: AllocatorBackingEvidence = serde_json::from_value(value.clone()).unwrap();
        validate_fixed_backing_evidence(&decoded).unwrap();
        assert_eq!(serde_json::to_value(&decoded).unwrap(), value);
        for (field, replacement) in [
            ("version", serde_json::json!(2)),
            ("policy", serde_json::json!("empty_role_map")),
            ("elf_sha256", serde_json::json!("")),
            ("compiled_sources_sha256", serde_json::json!("")),
            ("reverie_pin", serde_json::json!("")),
            ("allocation_sha256", serde_json::json!("3".repeat(64))),
            ("mappings", serde_json::json!([])),
            ("static_symbol_count", serde_json::json!(0)),
            ("named_getters", serde_json::json!([0x1500])),
            ("recipe_getters", serde_json::json!([0x1500])),
            ("getter_pointer_slots", serde_json::json!([0x3400])),
        ] {
            let mut bad = value.clone();
            bad["tls_boundary"]["direct_allocation"][field] = replacement;
            assert!(
                validate_fixed_backing_evidence(&serde_json::from_value(bad).unwrap()).is_err(),
                "synthetic direct provenance mutation {field}"
            );
        }
        for field in [
            "elf_sha256",
            "compiled_sources_sha256",
            "raw_names_sha256",
            "loader_writers_sha256",
        ] {
            let mut stale = value.clone();
            stale["tls_boundary"]["direct_allocation"][field] = serde_json::json!("3".repeat(64));
            let stale: AllocatorBackingEvidence = serde_json::from_value(stale).unwrap();
            // Structural hash spelling is not authority. Complete record Eq
            // at the real independently re-extracting consumer must see this.
            assert_ne!(
                stale, decoded,
                "direct record join excludes no provenance field"
            );
        }
        for mutation in 0..7 {
            let mut bad = decoded.clone();
            let tls = &mut bad.tls_boundary;
            match mutation {
                0 => tls.callsites.clear(),
                1 => tls.callsites.push(tls.callsites[0].clone()),
                2 => tls.callsites[0].instruction += 1,
                3 => tls.callsites[0].target += 1,
                4 => tls.tls_cell.address = 0x48,
                5 => tls.local_key_object = Some(1),
                6 => tls
                    .function_sha256
                    .remove("fixed_patch_alloc")
                    .map(|_| ())
                    .unwrap(),
                _ => unreachable!(),
            }
            assert!(
                validate_fixed_backing_evidence(&bad).is_err(),
                "direct role/edge/tuple mutation{mutation}"
            );
        }
        let mut unknown = value.clone();
        unknown["tls_boundary"]["direct_allocation"]["absent"] = serde_json::json!(true);
        assert!(serde_json::from_value::<AllocatorBackingEvidence>(unknown).is_err());
        let mut old = value;
        old["tls_boundary"]
            .as_object_mut()
            .unwrap()
            .remove("direct_allocation");
        let old: AllocatorBackingEvidence = serde_json::from_value(old).unwrap();
        assert!(
            validate_fixed_backing_evidence(&old).is_err(),
            "missing direct provenance cannot erase the old required FnOnce chain"
        );
    }

